window.ROAR_COURSE_DATA = {"project": {"name": "ASU ROAR 2026 — Autonomous Mars Rover", "competition": "European Rover Challenge (ERC) 2026", "ros_distro": "ROS 2 Jazzy", "simulator": "Gazebo Harmonic (gz sim)", "workspace_root": "/home/abdalrhmanzakaria/ROAR-27-Simulation-Testing"}, "erc_scoring_rules": {"max_total_points": 300, "rover_radius_m": 0.5, "waypoint_acceptance_radius_m": 1.0, "settled_speed_threshold_m_s": 0.05, "timeout_sec": 1200.0, "rules": [{"code": "O/NAV-010", "label": "Waypoint Reached", "formula": "max(0, round(30 - 6 * max(0, d_center - 0.5)))", "max_points": 120}, {"code": "O/NAV-020", "label": "Autonomy Bonus", "formula": "25 pts per autonomous waypoint", "max_points": 100}, {"code": "O/NAV-030", "label": "Back to Start", "formula": "25 pts if d_center <= 1.0m and >=1 WP reached", "max_points": 25}, {"code": "O/NAV-040", "label": "Back to Start Autonomy", "formula": "25 pts if return leg autonomous", "max_points": 25}, {"code": "O/NAV-050", "label": "Traversal Plan Execution", "formula": "6 pts per completed leg (5 legs)", "max_points": 30}, {"code": "O/NAV-060", "label": "Return Penalty", "formula": "-5 pts per return request", "max_points": 0}, {"code": "O/NAV-110", "label": "GNSS-Only Penalty", "formula": "-20% total traverse deduction", "max_points": 0}]}, "tf_tree": [{"parent": "map", "child": "odom", "type": "static (identity)", "broadcaster": "ieskf_node", "source": "src/navstack/slam/roar_localization/src/ieskf_node.cpp:560-576"}, {"parent": "odom", "child": "base_footprint", "type": "dynamic (100 Hz)", "broadcaster": "ieskf_node", "source": "src/navstack/slam/roar_localization/src/ieskf_node.cpp:528-546"}, {"parent": "base_footprint", "child": "base_link", "type": "fixed (rpy: 0, 0, -pi/2)", "broadcaster": "robot_state_publisher", "source": "src/roar2026/dev_environment/rover/roar_simulation_full/urdf/base/rover.xacro:10-14"}, {"parent": "base_link", "child": "zed2i_link", "type": "fixed (xyz: 0, 0.35, 0.25; yaw: +pi/2)", "broadcaster": "robot_state_publisher", "source": "src/roar2026/dev_environment/rover/roar_simulation_full/urdf/base/rover_simulation.urdf.xacro:18-21"}, {"parent": "zed2i_link", "child": "zed2i_depth_optical_frame", "type": "fixed (rpy: -pi/2, 0, -pi/2)", "broadcaster": "robot_state_publisher", "source": "src/roar2026/dev_environment/rover/roar_simulation_full/urdf/modules/sensors.xacro:40-48"}, {"parent": "base_link", "child": "bno055_link", "type": "fixed (xyz: 0, 0, 0.1)", "broadcaster": "robot_state_publisher", "source": "src/roar2026/dev_environment/rover/roar_simulation_full/urdf/base/rover_simulation.urdf.xacro:24-26"}], "voice": {"primary": "mp3", "mp3_voice": "en-US-AndrewNeural", "fallback": "browser_speech_synthesis", "lang": "en-US", "asu_pronunciation": "A S U (Ain Shams University)"}, "pronunciation_dictionary": [{"pattern": "\\bA-S-U\\s+ROAR\\b", "spoken": "A S U Roar", "note": "Project name spoken as three letters A-S-U plus Roar"}, {"pattern": "\\bASU\\s+ROAR\\b", "spoken": "A S U Roar", "note": "Project name spoken as three letters A-S-U plus Roar"}, {"pattern": "\\bA-S-U\\b", "spoken": "A S U", "note": "Ain Shams University initialism"}, {"pattern": "\\bASU\\b", "spoken": "A S U", "note": "Ain Shams University initialism"}, {"pattern": "\\bROAR\\b", "spoken": "Roar", "note": "Rover team name spoken as word"}, {"pattern": "\\bERC\\b", "spoken": "E R C", "note": "European Rover Challenge"}, {"pattern": "\\bROS\\s*2\\b", "spoken": "Ross 2", "note": "Robot Operating System 2"}, {"pattern": "\\bROS\\b", "spoken": "Ross", "note": "Robot Operating System"}, {"pattern": "\\bNav2\\b", "spoken": "Nav 2", "note": "Navigation2 stack"}, {"pattern": "\\bIESKF\\b", "spoken": "I E S K F", "note": "Iterated Error-State Kalman Filter"}, {"pattern": "\\bMPPI\\b", "spoken": "M P P I", "note": "Model Predictive Path Integral"}, {"pattern": "\\bZUPT\\b", "spoken": "Z U P T", "note": "Zero-Velocity Update"}, {"pattern": "\\bTF2\\b", "spoken": "T F 2", "note": "Transform library v2"}, {"pattern": "\\bTF\\b", "spoken": "T F", "note": "Transform tree"}, {"pattern": "\\bQoS\\b", "spoken": "Q O S", "note": "Quality of Service"}, {"pattern": "D\\*\\s*Lite", "spoken": "D-star Lite", "note": "Incremental heuristic path planner"}, {"pattern": "\\bA\\*", "spoken": "A-star", "note": "Graph search"}, {"pattern": "\\bWIO\\b", "spoken": "W I O", "note": "Wheel-Inertial Odometry"}, {"pattern": "\\bWVO\\b", "spoken": "W V O", "note": "Wheel-Visual Odometry"}, {"pattern": "\\bWO-FIS\\b", "spoken": "W O F I S", "note": "Wheel Odometry Fuzzy Inference System"}, {"pattern": "\\bVO-FIS\\b", "spoken": "V O F I S", "note": "Visual Odometry Fuzzy Inference System"}, {"pattern": "\\bFIS\\b", "spoken": "F I S", "note": "Fuzzy Inference System"}, {"pattern": "\\bIMU\\b", "spoken": "I M U", "note": "Inertial Measurement Unit"}, {"pattern": "\\bBNO055\\b", "spoken": "B N O zero five five", "note": "Bosch 9-axis IMU"}, {"pattern": "\\bZED2i\\b", "spoken": "Zed 2 i", "note": "Stereolabs stereo camera"}, {"pattern": "\\bXYZRGB\\b", "spoken": "X Y Z R G B", "note": "Colored 3D point cloud"}, {"pattern": "\\bRGB-D\\b", "spoken": "R G B D", "note": "Color and depth"}, {"pattern": "\\bRGB\\b", "spoken": "R G B", "note": "Color image"}, {"pattern": "\\bURDF\\b", "spoken": "U R D F", "note": "Unified Robot Description Format"}, {"pattern": "\\b[Xx]acro\\b", "spoken": "zack-roh", "note": "XML macro"}, {"pattern": "\\bSDF\\b", "spoken": "S D F", "note": "Simulation Description Format"}, {"pattern": "\\bSOR\\b", "spoken": "S O R", "note": "Statistical Outlier Removal"}, {"pattern": "\\bROR\\b", "spoken": "R O R", "note": "Radius Outlier Removal"}, {"pattern": "\\bROI\\b", "spoken": "R O I", "note": "Region of Interest"}, {"pattern": "\\bPCA\\b", "spoken": "P C A", "note": "Principal Component Analysis"}, {"pattern": "\\bRANSAC\\b", "spoken": "ran-sack", "note": "Random Sample Consensus"}, {"pattern": "\\bDBSCAN\\b", "spoken": "D B scan", "note": "Density-Based Spatial Clustering"}, {"pattern": "\\bEMA\\b", "spoken": "E M A", "note": "Exponential Moving Average"}, {"pattern": "\\bArUco\\b", "spoken": "ah-roo-koh", "note": "Square fiducial marker"}, {"pattern": "\\bSolvePnP\\b", "spoken": "Solve P N P", "note": "Perspective-n-Point pose solver"}, {"pattern": "\\bIPPE\\b", "spoken": "I P P E", "note": "Infinitesimal Plane-Based Pose Estimation"}, {"pattern": "\\b6-DOF\\b", "spoken": "six D O F", "note": "Six degrees of freedom"}, {"pattern": "\\b12D\\b", "spoken": "twelve D", "note": "Twelve-dimensional"}, {"pattern": "\\b2\\.5D\\b", "spoken": "two point five D", "note": "Elevation grid"}, {"pattern": "\\b3D\\b", "spoken": "three D", "note": "Three-dimensional"}, {"pattern": "\\bBFS\\b", "spoken": "B F S", "note": "Breadth-First Search"}, {"pattern": "\\bCUDA\\b", "spoken": "koo-dah", "note": "NVIDIA GPU compute"}, {"pattern": "\\bGPU\\b", "spoken": "G P U", "note": "Graphics Processing Unit"}, {"pattern": "\\bIoU\\b", "spoken": "I O U", "note": "Intersection over Union"}, {"pattern": "\\bSLAM\\b", "spoken": "slam", "note": "Simultaneous Localization and Mapping"}, {"pattern": "\\bBT\\b", "spoken": "B T", "note": "Behavior Tree"}, {"pattern": "\\bGUI\\b", "spoken": "G U I", "note": "Graphical User Interface"}, {"pattern": "\\bHTML\\b", "spoken": "H T M L", "note": "HyperText Markup Language"}, {"pattern": "\\bYAML\\b", "spoken": "yam-ul", "note": "YAML configuration"}, {"pattern": "\\bJSON\\b", "spoken": "jay-son", "note": "JSON payload"}, {"pattern": "\\bNumPy\\b", "spoken": "num-pie", "note": "NumPy array"}, {"pattern": "\\bk_Q\\b", "spoken": "k Q", "note": "Process noise factor k_Q"}, {"pattern": "\\bk_V\\b", "spoken": "k V", "note": "Visual noise factor k_V"}, {"pattern": "\\bd_edge\\b", "spoken": "d edge", "note": "Chassis edge distance"}, {"pattern": "Z²", "spoken": "Z squared", "note": "Quadratic depth factor"}, {"pattern": "\\bHz\\b", "spoken": "hertz", "note": "Frequency in hertz"}, {"pattern": "\\bm/s\\b", "spoken": "meters per second", "note": "Linear speed"}], "featured_intro": {"id": "featured_intro", "number": "00", "title": "Meet the Autonomous Mars Rover", "subtitle": "How ASU ROAR 2026 senses, plans, and scores 300 points in simulation.", "thumbnail_kind": "intro", "scenes": [{"scene_id": "intro_s1", "title": "Digital Twin on Mars", "visual_mode": "rover_loop", "components": ["rover_twin", "gazebo_sim", "zed_degradation"], "flows": [{"from": "gazebo_sim", "to": "rover_twin", "channel": "gz_bridge_bus"}, {"from": "rover_twin", "to": "zed_degradation", "channel": "points_updated"}], "narration": "In the ASU ROAR autonomy stack—where ASU stands for Ain Shams University—our six-wheel rocker-bogie rover runs inside a physics-accurate Gazebo Harmonic Marsyard. The simulation bridges wheel mechanics, chassis contact sensors, and atmospherically degraded ZED2i stereo clouds directly into our ROS 2 pipeline.", "captions": ["ASU ROAR (Ain Shams University) 6-wheel rover in Gazebo Harmonic.", "Bridges mechanics, contacts, and degraded ZED2i clouds into ROS 2."], "source_refs": [{"file": "src/roar2026/dev_environment/rover/roar_simulation_full/urdf/base/rover_simulation.urdf.xacro", "lines": "13-31", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/urdf/base/rover_simulation.urdf.xacro:13-31"}], "narration_spoken": "In the A S U Roar autonomy stack—where A S U stands for Ain Shams University—our six-wheel rocker-bogie rover runs inside a physics-accurate Gazebo Harmonic Marsyard. The simulation bridges wheel mechanics, chassis contact sensors, and atmospherically degraded Zed 2 i stereo clouds directly into our Ross 2 pipeline.", "audio_file": "assets/audio/intro_s1.mp3", "audio_duration_sec": 19.99, "duration_sec": 20.84, "caption_split_sec": 11.69}, {"scene_id": "intro_s2", "title": "From 3D Vision to 2,000 Rollouts", "visual_mode": "mppi_rollouts", "components": ["lidar_cluster", "ieskf_core", "dstar_planner", "mppi_controller"], "flows": [{"from": "lidar_cluster", "to": "dstar_planner", "channel": "unified_costmap"}, {"from": "ieskf_core", "to": "mppi_controller", "channel": "odom_tf"}, {"from": "dstar_planner", "to": "mppi_controller", "channel": "global_plan"}], "narration": "Our perception and terrain-mapping nodes isolate non-traversable boulders into a unified costmap while a 100 Hz IESKF fuses wheel encoders, IMU, and visual pose. Downstream, our D* Lite global planner and 20 Hz MPPI controller evaluate two thousand candidate rollouts to drive the six wheels safely.", "captions": ["3D rock perception builds /unified_costmap alongside 100 Hz IESKF odometry.", "D* Lite global paths guide 2,000-rollout MPPI control at 20 Hz."], "source_refs": [{"file": "src/navstack/navstack_nav2/launch/roar_nav2_only.launch.py", "lines": "65-261", "snippet_key": "src/navstack/navstack_nav2/launch/roar_nav2_only.launch.py:65-261"}], "narration_spoken": "Our perception and terrain-mapping nodes isolate non-traversable boulders into a unified costmap while a 100 hertz I E S K F fuses wheel encoders, I M U, and visual pose. Downstream, our D-star Lite global planner and 20 hertz M P P I controller evaluate two thousand candidate rollouts to drive the six wheels safely.", "audio_file": "assets/audio/intro_s2.mp3", "audio_duration_sec": 21.19, "duration_sec": 22.04, "caption_split_sec": 12.99}, {"scene_id": "intro_s3", "title": "Autonomous Mission & 300-Point Judge", "visual_mode": "erc_score_bar", "components": ["mission_gui", "wp_follower", "referee_core", "report_gen"], "flows": [{"from": "mission_gui", "to": "wp_follower", "channel": "yaml_injection"}, {"from": "wp_follower", "to": "referee_core", "channel": "odom_tf"}, {"from": "referee_core", "to": "report_gen", "channel": "referee_score"}], "narration": "Mission Control synchronizes metric waypoint targets across Nav2 and an automated ERC referee that audits collisions, settled stops, and timing on a 300-point scale. Select any lesson below, and click any animated node or packet on stage to pause and inspect the underlying source code.", "captions": ["Mission Control syncs goals with a live 300-point ERC referee engine.", "Click any node or packet during playback to inspect live source code."], "source_refs": [{"file": "src/navigation/referee_engine/referee_engine/score_calculator.py", "lines": "23-51", "snippet_key": "src/navigation/referee_engine/referee_engine/score_calculator.py:23-51"}], "narration_spoken": "Mission Control synchronizes metric waypoint targets across Nav 2 and an automated E R C referee that audits collisions, settled stops, and timing on a 300-point scale. Select any lesson below, and click any animated node or packet on stage to pause and inspect the underlying source code.", "audio_file": "assets/audio/intro_s3.mp3", "audio_duration_sec": 17.9, "duration_sec": 18.75, "caption_split_sec": 11.29}], "duration_sec": 61.6}, "lessons": [{"id": "lesson_01", "number": "01", "title": "The Big Picture", "subtitle": "Closed-loop autonomy, readiness gates, and parallel ROS 2 pipelines.", "thumbnail_kind": "big_picture", "scenes": [{"scene_id": "01_s1", "title": "The Closed-Loop Rover Cycle", "visual_mode": "rover_loop", "components": ["rover_twin", "lidar_cluster", "dstar_planner", "ros2_control"], "flows": [{"from": "rover_twin", "to": "lidar_cluster", "channel": "sense_stream"}, {"from": "lidar_cluster", "to": "dstar_planner", "channel": "unified_costmap"}, {"from": "dstar_planner", "to": "ros2_control", "channel": "cmd_vel_stamped"}], "narration": "Across an ASU ROAR mission, the rover autonomously traverses four Marsyard waypoints and returns to the origin without operator intervention. At runtime, stereo point clouds and inertial measurements feed perception and mapping, which drive path planning and stamped six-wheel velocity control.", "captions": ["Autonomous 4-waypoint traverse plus return-to-origin (0, 0).", "Closed loop: stereo & IMU sensing → costmap & pose → 6-wheel velocity."], "source_refs": [{"file": "src/start_gui.sh", "lines": "15-27", "snippet_key": "src/start_gui.sh:15-27"}, {"file": "src/navigation/scripts/asu_roar_gui.py", "lines": "82-89", "snippet_key": "src/navigation/scripts/asu_roar_gui.py:82-89"}], "narration_spoken": "Across an A S U Roar mission, the rover autonomously traverses four Marsyard waypoints and returns to the origin without operator intervention. At runtime, stereo point clouds and inertial measurements feed perception and mapping, which drive path planning and stamped six-wheel velocity control.", "audio_file": "assets/audio/01_s1.mp3", "audio_duration_sec": 17.23, "duration_sec": 18.08, "caption_split_sec": 8.39}, {"scene_id": "01_s2", "title": "Readiness-Gated Startup", "visual_mode": "readiness_gates", "components": ["mission_gui", "gazebo_sim", "bt_navigator", "referee_core"], "flows": [{"from": "gazebo_sim", "to": "mission_gui", "channel": "gate_sim_ready"}, {"from": "bt_navigator", "to": "mission_gui", "channel": "gate_nav_ready"}, {"from": "mission_gui", "to": "referee_core", "channel": "yaml_injection"}], "narration": "Instead of launching every subsystem blindly, our PyQt5 Mission Control orchestrates four readiness-gated stages. It waits for the differential-drive odometry topic from Gazebo before starting Nav2, then verifies the navigate-to-pose action server is live before releasing the referee and waypoint follower.", "captions": ["Gate 1 polls /diff_drive_controller/odom before launching Nav2 & SLAM.", "Gate 2 verifies /navigate_to_pose before starting Referee & Follower."], "source_refs": [{"file": "src/navigation/scripts/asu_roar_gui.py", "lines": "1124-1223", "snippet_key": "src/navigation/scripts/asu_roar_gui.py:1124-1223"}, {"file": "src/navigation/scripts/asu_roar_gui.py", "lines": "1451-1457", "snippet_key": "src/navigation/scripts/asu_roar_gui.py:1451-1457"}], "narration_spoken": "Instead of launching every subsystem blindly, our PyQt5 Mission Control orchestrates four readiness-gated stages. It waits for the differential-drive odometry topic from Gazebo before starting Nav 2, then verifies the navigate-to-pose action server is live before releasing the referee and waypoint follower.", "audio_file": "assets/audio/01_s2.mp3", "audio_duration_sec": 18.65, "duration_sec": 19.5, "caption_split_sec": 7.56}, {"scene_id": "01_s3", "title": "Two Parallel Data Highways", "visual_mode": "dual_highway", "components": ["zed_degradation", "costmap_fuser", "ieskf_core", "mppi_controller", "ros2_control"], "flows": [{"from": "zed_degradation", "to": "costmap_fuser", "channel": "points_updated"}, {"from": "costmap_fuser", "to": "mppi_controller", "channel": "unified_costmap"}, {"from": "ieskf_core", "to": "mppi_controller", "channel": "odom_tf"}, {"from": "mppi_controller", "to": "ros2_control", "channel": "cmd_vel_stamped"}], "narration": "Inside ROS 2, sensor traffic splits into two parallel real-time pipelines: a spatial perception stream that converts 5 Hz stereo clouds into a unified traversability costmap, and a 100 Hz localization stream that publishes fused odometry and TF transforms. Both streams converge inside the navigation stack to compute collision-free wheel commands.", "captions": ["Spatial pipeline: 5 Hz stereo point clouds → /unified_costmap.", "State pipeline: 100 Hz IMU & encoders → /odom + TF → MPPI control."], "source_refs": [{"file": "src/navstack/navstack_nav2/launch/roar_nav2_only.launch.py", "lines": "65-261", "snippet_key": "src/navstack/navstack_nav2/launch/roar_nav2_only.launch.py:65-261"}], "narration_spoken": "Inside Ross 2, sensor traffic splits into two parallel real-time pipelines: a spatial perception stream that converts 5 hertz stereo clouds into a unified traversability costmap, and a 100 hertz localization stream that publishes fused odometry and T F transforms. Both streams converge inside the navigation stack to compute collision-free wheel commands.", "audio_file": "assets/audio/01_s3.mp3", "audio_duration_sec": 22.49, "duration_sec": 23.34, "caption_split_sec": 17.57}, {"scene_id": "01_s4", "title": "Four Waypoints, Home & 300 Points", "visual_mode": "mission_tour", "components": ["wp_follower", "rover_twin", "referee_core", "report_gen"], "flows": [{"from": "wp_follower", "to": "rover_twin", "channel": "nav_to_pose_action"}, {"from": "rover_twin", "to": "referee_core", "channel": "odom_tf"}, {"from": "referee_core", "to": "report_gen", "channel": "referee_score"}], "narration": "During execution, the waypoint action client sequences four target goals followed by a fifth return-to-start leg at zero-zero. In parallel, the referee core audits every meter of motion and every contact event at 10 Hz, compiling live and final 300-point HTML scorecards.", "captions": ["Sequential NavigateToPose dispatch across WP1..WP4 and Start (0, 0).", "10 Hz referee audits collisions and stop accuracy for 300-pt HTML reports."], "source_refs": [{"file": "src/navstack/path-planning/globalPlanner/scripts/batch_waypoint_follower.py", "lines": "136-162", "snippet_key": "src/navstack/path-planning/globalPlanner/scripts/batch_waypoint_follower.py:136-162"}, {"file": "src/navigation/referee_engine/referee_engine/score_calculator.py", "lines": "23-36", "snippet_key": "src/navigation/referee_engine/referee_engine/score_calculator.py:23-36"}], "narration_spoken": "During execution, the waypoint action client sequences four target goals followed by a fifth return-to-start leg at zero-zero. In parallel, the referee core audits every meter of motion and every contact event at 10 hertz, compiling live and final 300-point H T M L scorecards.", "audio_file": "assets/audio/01_s4.mp3", "audio_duration_sec": 18.22, "duration_sec": 19.07, "caption_split_sec": 8.66}], "duration_sec": 80.0}, {"id": "lesson_02", "number": "02", "title": "Simulation & Gazebo", "subtitle": "Procedural Marsyard worlds, ROS-Gazebo bridging, and realistic sensor noise.", "thumbnail_kind": "simulation", "scenes": [{"scene_id": "02_s1", "title": "Offline Marsyard & Waypoint Synthesis", "visual_mode": "world_synthesis", "components": ["marsyard_gen", "wp_sampler", "mission_gui"], "flows": [{"from": "marsyard_gen", "to": "wp_sampler", "channel": "offline_bake"}, {"from": "wp_sampler", "to": "mission_gui", "channel": "yaml_injection"}], "narration": "Before Gazebo starts, our offline synthesis pipeline builds three Marsyard worlds from the competition terrain mesh, populating eight, fifty, and ninety procedural rocks alongside ArUco landmarks. It then bakes ground-truth elevation grids and uses Poisson-disk sampling to generate three hundred obstacle-cleared waypoint routes per world.", "captions": ["Synthesizes 3 Marsyard worlds with 8, 50, and 90 procedural rocks.", "Bakes heightmap.npz and 300 Poisson-sampled waypoint routes per world."], "source_refs": [{"file": "src/roar2026/navMission_setup/master_pipeline.sh", "lines": "13-61", "snippet_key": "src/roar2026/navMission_setup/master_pipeline.sh:13-61"}, {"file": "src/roar2026/navMission_setup/generate_worlds.py", "lines": "33-64", "snippet_key": "src/roar2026/navMission_setup/generate_worlds.py:33-64"}], "narration_spoken": "Before Gazebo starts, our offline synthesis pipeline builds three Marsyard worlds from the competition terrain mesh, populating eight, fifty, and ninety procedural rocks alongside ah-roo-koh landmarks. It then bakes ground-truth elevation grids and uses Poisson-disk sampling to generate three hundred obstacle-cleared waypoint routes per world.", "audio_file": "assets/audio/02_s1.mp3", "audio_duration_sec": 20.28, "duration_sec": 21.13, "caption_split_sec": 12.97}, {"scene_id": "02_s2", "title": "Rover Variants & Chained Controllers", "visual_mode": "rover_variants", "components": ["gazebo_sim", "rover_twin", "ros2_control"], "flows": [{"from": "rover_twin", "to": "gazebo_sim", "channel": "spawn_chain"}, {"from": "gazebo_sim", "to": "ros2_control", "channel": "gate_sim_ready"}], "narration": "Our launch script compiles one of three Xacro configurations: clean pass-through sensors, realistic Mars sensor noise, or full noise with the 6-DOF manipulator arm. After spawning the rover into Gazebo, a twelve-second settle timer triggers chained spawners that activate the joint-state broadcaster, differential-drive controller, and arm controller in strict sequence.", "captions": ["Three Xacro builds: Clean, Noisy, and Full with 6-DOF manipulator.", "12s settle timer chains joint_state_broadcaster → diff_drive → arm."], "source_refs": [{"file": "src/roar2026/dev_environment/launch_test.sh", "lines": "20-29", "snippet_key": "src/roar2026/dev_environment/launch_test.sh:20-29"}, {"file": "src/roar2026/dev_environment/rover/roar_simulation_full/launch/basic_rover.launch.py", "lines": "281-306", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/launch/basic_rover.launch.py:281-306"}], "narration_spoken": "Our launch script compiles one of three zack-roh configurations: clean pass-through sensors, realistic Mars sensor noise, or full noise with the six D O F manipulator arm. After spawning the rover into Gazebo, a twelve-second settle timer triggers chained spawners that activate the joint-state broadcaster, differential-drive controller, and arm controller in strict sequence.", "audio_file": "assets/audio/02_s2.mp3", "audio_duration_sec": 22.2, "duration_sec": 23.05, "caption_split_sec": 11.28}, {"scene_id": "02_s3", "title": "The ROS ↔ Gazebo Parameter Bridge", "visual_mode": "gz_bridge", "components": ["gazebo_sim", "ros_gz_bridge", "collision_alarm"], "flows": [{"from": "gazebo_sim", "to": "ros_gz_bridge", "channel": "gz_bridge_bus"}, {"from": "ros_gz_bridge", "to": "collision_alarm", "channel": "rover_contact"}], "narration": "A single ROS-Gazebo parameter bridge translates internal physics transport streams into ROS 2 topics, forwarding the simulation clock, 100 Hz BNO055 IMU data, and 5 Hz ZED2i RGB-D frames. It also multiplexes seven Gazebo contact sensors mounted across the chassis and all six rocker-bogie wheels onto the rover-contact topic.", "captions": ["parameter_bridge maps Gazebo clock, 100 Hz IMU, and 5 Hz RGB-D to ROS 2.", "Aggregates 7 chassis and wheel contact sensors onto /rover_contact."], "source_refs": [{"file": "src/roar2026/dev_environment/rover/roar_simulation_full/launch/basic_rover.launch.py", "lines": "166-199", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/launch/basic_rover.launch.py:166-199"}, {"file": "src/roar2026/dev_environment/rover/roar_simulation_full/urdf/modules/rover_gazebo.xacro", "lines": "20-189", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/urdf/modules/rover_gazebo.xacro:20-189"}], "narration_spoken": "A single Ross-Gazebo parameter bridge translates internal physics transport streams into Ross 2 topics, forwarding the simulation clock, 100 hertz B N O zero five five I M U data, and 5 hertz Zed 2 i R G B D frames. It also multiplexes seven Gazebo contact sensors mounted across the chassis and all six rocker-bogie wheels onto the rover-contact topic.", "audio_file": "assets/audio/02_s3.mp3", "audio_duration_sec": 23.74, "duration_sec": 24.59, "caption_split_sec": 15.6}, {"scene_id": "02_s4", "title": "Mars Dust, Solar Glare & Z² Depth Noise", "visual_mode": "solar_degradation", "components": ["ros_gz_bridge", "zed_degradation", "lidar_cluster"], "flows": [{"from": "ros_gz_bridge", "to": "zed_degradation", "channel": "raw_camera"}, {"from": "zed_degradation", "to": "lidar_cluster", "channel": "points_updated"}], "narration": "To prevent overfitting to clean synthetic images, our ZED2i degradation node projects the 3D sun position through the camera intrinsics to synthesize lens glare and depth washout holes. It injects particulate dust and quadratic stereo range noise proportional to Z² before unprojecting pixels into a colored 3D point cloud.", "captions": ["Projects 3D sun into camera intrinsics for glare bloom and NaN depth holes.", "Applies dust + quadratic stereo noise (σ = 0.003·Z²) → XYZRGB PointCloud2."], "source_refs": [{"file": "src/roar2026/dev_environment/rover/roar_simulation_full/src/zed_degradation_node.py", "lines": "154-336", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/src/zed_degradation_node.py:154-336"}], "narration_spoken": "To prevent overfitting to clean synthetic images, our Zed 2 i degradation node projects the three D sun position through the camera intrinsics to synthesize lens glare and depth washout holes. It injects particulate dust and quadratic stereo range noise proportional to Z squared before unprojecting pixels into a colored three D point cloud.", "audio_file": "assets/audio/02_s4.mp3", "audio_duration_sec": 20.16, "duration_sec": 21.01, "caption_split_sec": 11.09}, {"scene_id": "02_s5", "title": "Digital Encoder Pulses & Ground Contact Filter", "visual_mode": "encoder_pulses", "components": ["ros2_control", "encoder_sim", "ieskf_core", "ros_gz_bridge", "collision_alarm"], "flows": [{"from": "ros2_control", "to": "encoder_sim", "channel": "joint_pulses"}, {"from": "encoder_sim", "to": "ieskf_core", "channel": "joint_pulses"}, {"from": "ros_gz_bridge", "to": "collision_alarm", "channel": "rover_contact"}], "narration": "On the drivetrain side, our encoder simulator converts continuous middle-wheel joint angles into quantized integer ticks at two hundred and one thousand, five hundred and fifty-four pulses per revolution, matching physical rover hardware. Meanwhile, the simulation collision alarm strips benign terrain-mesh touches so only non-ground impacts trigger alerts.", "captions": ["Quantizes middle-wheel angles to integer ticks (201,554 pulses/rev).", "Filters normal Marsyard ground contacts out of /collision_alarm."], "source_refs": [{"file": "src/roar2026/dev_environment/rover/roar_simulation_full/src/encoder_sim_node.py", "lines": "31-75", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/src/encoder_sim_node.py:31-75"}, {"file": "src/roar2026/dev_environment/rover/roar_simulation_full/src/collision_alarm_node.py", "lines": "20-49", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/src/collision_alarm_node.py:20-49"}], "narration_spoken": "On the drivetrain side, our encoder simulator converts continuous middle-wheel joint angles into quantized integer ticks at two hundred and one thousand, five hundred and fifty-four pulses per revolution, matching physical rover hardware. Meanwhile, the simulation collision alarm strips benign terrain-mesh touches so only non-ground impacts trigger alerts.", "audio_file": "assets/audio/02_s5.mp3", "audio_duration_sec": 20.88, "duration_sec": 21.73, "caption_split_sec": 14.5}], "duration_sec": 111.5}, {"id": "lesson_03", "number": "03", "title": "Sensor Processing & Perception", "subtitle": "GPU point-cloud filtering, slope-aware RANSAC, DBSCAN, and ArUco.", "thumbnail_kind": "perception", "scenes": [{"scene_id": "03_s1", "title": "GPU Range Crop, Voxel Grid & Outlier Removal", "visual_mode": "pointcloud_clean", "components": ["zed_degradation", "lidar_cluster", "ransac_roughness"], "flows": [{"from": "zed_degradation", "to": "lidar_cluster", "channel": "points_updated"}, {"from": "lidar_cluster", "to": "ransac_roughness", "channel": "points_filtered"}], "narration": "Our point-cloud clustering node subscribes with Best-Effort depth-one QoS so perception always processes the freshest stereo frame without queue lag. On arrival, it crops points beyond six meters on the GPU, downsamples into six-centimeter voxels, and runs both Statistical and Radius Outlier Removal to strip dust artifacts.", "captions": ["Best-Effort (depth 1) intake + GPU ROI crop (< 6.0m) + 6cm voxel grid.", "Sequential SOR and ROR filters remove airborne dust and stereo outliers."], "source_refs": [{"file": "src/navstack/perception/perception_module/lidar_cluster_node.py", "lines": "152-203", "snippet_key": "src/navstack/perception/perception_module/lidar_cluster_node.py:152-203"}, {"file": "src/navstack/perception/config/perception_params.yaml", "lines": "31-58", "snippet_key": "src/navstack/perception/config/perception_params.yaml:31-58"}], "narration_spoken": "Our point-cloud clustering node subscribes with Best-Effort depth-one Q O S so perception always processes the freshest stereo frame without queue lag. On arrival, it crops points beyond six meters on the G P U, downsamples into six-centimeter voxels, and runs both Statistical and Radius Outlier Removal to strip dust artifacts.", "audio_file": "assets/audio/03_s1.mp3", "audio_duration_sec": 20.26, "duration_sec": 21.11, "caption_split_sec": 9.78}, {"scene_id": "03_s2", "title": "Slope-Aware RANSAC & Surface Roughness", "visual_mode": "ransac_slope", "components": ["lidar_cluster", "ransac_roughness", "dbscan_gate"], "flows": [{"from": "lidar_cluster", "to": "ransac_roughness", "channel": "points_filtered"}, {"from": "ransac_roughness", "to": "dbscan_gate", "channel": "points_no_ground"}], "narration": "Standard flat-plane removal would misclassify climbable Marsyard ramps as obstacles, so our iterative RANSAC strips planes tilted up to forty-five degrees while keeping steep boulder faces intact. A PCA surface-normal variance filter then discards smooth slope remnants so only sharp, high-roughness rock geometry survives.", "captions": ["Iterative RANSAC strips ground and traversable ramps up to 45° tilt.", "PCA normal-variance roughness check preserves sharp boulder geometry."], "source_refs": [{"file": "src/navstack/perception/perception_module/lidar_cluster_node.py", "lines": "336-486", "snippet_key": "src/navstack/perception/perception_module/lidar_cluster_node.py:336-486"}], "narration_spoken": "Standard flat-plane removal would misclassify climbable Marsyard ramps as obstacles, so our iterative ran-sack strips planes tilted up to forty-five degrees while keeping steep boulder faces intact. A P C A surface-normal variance filter then discards smooth slope remnants so only sharp, high-roughness rock geometry survives.", "audio_file": "assets/audio/03_s2.mp3", "audio_duration_sec": 19.51, "duration_sec": 20.36, "caption_split_sec": 12.39}, {"scene_id": "03_s3", "title": "DBSCAN Rock Clustering & 3D Shape Gate", "visual_mode": "dbscan_boxes", "components": ["ransac_roughness", "dbscan_gate", "terrain_mapper", "obstacle_pub"], "flows": [{"from": "ransac_roughness", "to": "dbscan_gate", "channel": "points_no_ground"}, {"from": "dbscan_gate", "to": "terrain_mapper", "channel": "detections_obstacles"}, {"from": "dbscan_gate", "to": "obstacle_pub", "channel": "lidar_clusters"}], "narration": "Remaining non-ground points are grouped via DBSCAN with a twenty-five-centimeter neighborhood radius and fitted with axis-aligned 3D bounding boxes. Each candidate must pass minimum height, footprint, and depth-to-height aspect gates—rejecting flat ground slabs before publishing confirmed rocks to terrain mapping and obstacle tracking.", "captions": ["DBSCAN (eps = 0.25m) groups rock clusters into 3D bounding boxes.", "3D shape & aspect-ratio gates reject flat slabs before publishing."], "source_refs": [{"file": "src/navstack/perception/perception_module/lidar_cluster_node.py", "lines": "220-293", "snippet_key": "src/navstack/perception/perception_module/lidar_cluster_node.py:220-293"}, {"file": "src/navstack/perception/config/perception_params.yaml", "lines": "120-155", "snippet_key": "src/navstack/perception/config/perception_params.yaml:120-155"}], "narration_spoken": "Remaining non-ground points are grouped via D B scan with a twenty-five-centimeter neighborhood radius and fitted with axis-aligned three D bounding boxes. Each candidate must pass minimum height, footprint, and depth-to-height aspect gates—rejecting flat ground slabs before publishing confirmed rocks to terrain mapping and obstacle tracking.", "audio_file": "assets/audio/03_s3.mp3", "audio_duration_sec": 20.11, "duration_sec": 20.96, "caption_split_sec": 10.4}, {"scene_id": "03_s4", "title": "TF2 World Projection & EMA Obstacle Memory", "visual_mode": "ema_memory", "components": ["lidar_cluster", "ieskf_core", "obstacle_pub"], "flows": [{"from": "lidar_cluster", "to": "obstacle_pub", "channel": "lidar_clusters"}, {"from": "ieskf_core", "to": "obstacle_pub", "channel": "odom_tf"}], "narration": "Because raw clusters are expressed in the moving camera frame, our obstacle publisher queries TF2 to project each 3D box into the fixed odom frame. It associates repeat sightings within half a meter using exponential moving-average smoothing and retains occluded rocks for four seconds to prevent costmap flicker.", "captions": ["TF2 transforms camera-frame detections into persistent odom coordinates.", "EMA smoothing (α = 0.35) and 4s retention prevent obstacle flicker."], "source_refs": [{"file": "src/navstack/perception/perception_module/obstacle_publisher_node.py", "lines": "83-220", "snippet_key": "src/navstack/perception/perception_module/obstacle_publisher_node.py:83-220"}], "narration_spoken": "Because raw clusters are expressed in the moving camera frame, our obstacle publisher queries T F 2 to project each three D box into the fixed odom frame. It associates repeat sightings within half a meter using exponential moving-average smoothing and retains occluded rocks for four seconds to prevent costmap flicker.", "audio_file": "assets/audio/03_s4.mp3", "audio_duration_sec": 18.38, "duration_sec": 19.23, "caption_split_sec": 9.14}, {"scene_id": "03_s5", "title": "ArUco 6-DOF Landmark Pose Estimation", "visual_mode": "aruco_pnp", "components": ["zed_degradation", "aruco_detector", "ieskf_core"], "flows": [{"from": "zed_degradation", "to": "aruco_detector", "channel": "rgb_updated"}, {"from": "aruco_detector", "to": "ieskf_core", "channel": "aruco_detections"}], "narration": "In parallel with rock segmentation, our ArUco detector scans degraded RGB frames across multiple fiducial dictionaries to locate surveyed Marsyard markers. When corners are detected, OpenCV's IPPE-Square SolvePnP solver computes a 6-DOF camera-to-marker pose for absolute drift correction inside the localization filter.", "captions": ["Multi-dictionary fiducial detection + IPPE-Square SolvePnP 6-DOF pose.", "Publishes camera-frame landmark observations to IESKF localization."], "optional_insight_id": "aruco_import_mismatch", "source_refs": [{"file": "src/navstack/perception/perception_module/aruco_detector_node.py", "lines": "76-117", "snippet_key": "src/navstack/perception/perception_module/aruco_detector_node.py:76-117"}, {"file": "src/navstack/perception/perception_module/aruco_detector_node.py", "lines": "210-266", "snippet_key": "src/navstack/perception/perception_module/aruco_detector_node.py:210-266"}], "narration_spoken": "In parallel with rock segmentation, our ah-roo-koh detector scans degraded R G B frames across multiple fiducial dictionaries to locate surveyed Marsyard markers. When corners are detected, OpenCV's I P P E-Square Solve P N P solver computes a six D O F camera-to-marker pose for absolute drift correction inside the localization filter.", "audio_file": "assets/audio/03_s5.mp3", "audio_duration_sec": 21.05, "duration_sec": 21.9, "caption_split_sec": 10.49}], "duration_sec": 103.6}, {"id": "lesson_04", "number": "04", "title": "Localization & Mapping", "subtitle": "12D IESKF fusion, Sugeno fuzzy trust weighting, ZUPT, and 2.5D costmaps.", "thumbnail_kind": "localization", "scenes": [{"scene_id": "04_s1", "title": "100 Hz Wheel-Inertial Prediction (WIO + IESKF)", "visual_mode": "ieskf_predict", "components": ["ros_gz_bridge", "encoder_sim", "wio_module", "ieskf_core"], "flows": [{"from": "ros_gz_bridge", "to": "wio_module", "channel": "imu_data"}, {"from": "encoder_sim", "to": "wio_module", "channel": "joint_pulses"}, {"from": "wio_module", "to": "ieskf_core", "channel": "odom_tf"}], "narration": "At 100 Hz, our localization node rotates incoming BNO055 IMU measurements by minus ninety degrees in yaw to align the sensor frame, then combines pitch and midpoint yaw with quantized wheel encoder deltas inside WIO. Those dead-reckoning increments drive a 12D Iterated Error-State Kalman Filter tracking 3D position, velocity, and accelerometer and gyroscope biases.", "captions": ["100 Hz WIO combines yaw-aligned BNO055 orientation with encoder pulses.", "12D IESKF tracks [p, v, b_a, b_w] with Joseph-form covariance updates."], "source_refs": [{"file": "src/navstack/slam/roar_localization/src/wio.cpp", "lines": "41-155", "snippet_key": "src/navstack/slam/roar_localization/src/wio.cpp:41-155"}, {"file": "src/navstack/slam/roar_localization/src/ieskf.cpp", "lines": "105-140", "snippet_key": "src/navstack/slam/roar_localization/src/ieskf.cpp:105-140"}], "narration_spoken": "At 100 hertz, our localization node rotates incoming B N O zero five five I M U measurements by minus ninety degrees in yaw to align the sensor frame, then combines pitch and midpoint yaw with quantized wheel encoder deltas inside W I O. Those dead-reckoning increments drive a twelve D Iterated Error-State Kalman Filter tracking three D position, velocity, and accelerometer and gyroscope biases.", "audio_file": "assets/audio/04_s1.mp3", "audio_duration_sec": 25.15, "duration_sec": 26.0, "caption_split_sec": 15.31}, {"scene_id": "04_s2", "title": "Sugeno Fuzzy Logic Trust Balancing (WO-FIS & VO-FIS)", "visual_mode": "fuzzy_balance", "components": ["wio_module", "gt_bridge", "fuzzy_fis", "ieskf_core"], "flows": [{"from": "wio_module", "to": "fuzzy_fis", "channel": "joint_pulses"}, {"from": "gt_bridge", "to": "fuzzy_fis", "channel": "zed_pose_cov"}, {"from": "fuzzy_fis", "to": "ieskf_core", "channel": "odom_tf"}], "narration": "Because loose regolith causes wheel slip while solar glare degrades visual odometry, two zero-order Sugeno fuzzy systems continuously adapt filter covariances. When IMU acceleration disagrees with wheel speed, WO-FIS inflates process noise k_Q up to tenfold; when visual pose jumps or stalls, VO-FIS scales measurement noise k_V up to twenty-fivefold.", "captions": ["Sugeno WO-FIS inflates process noise k_Q (up to 10×) during wheel slip.", "Sugeno VO-FIS scales visual noise k_V (up to 25×) on camera tracking jumps."], "source_refs": [{"file": "src/navstack/slam/roar_localization/include/roar_localization/fuzzy_utils.hpp", "lines": "304-538", "snippet_key": "src/navstack/slam/roar_localization/include/roar_localization/fuzzy_utils.hpp:304-538"}, {"file": "src/navstack/slam/roar_localization/src/wvo.cpp", "lines": "43-108", "snippet_key": "src/navstack/slam/roar_localization/src/wvo.cpp:43-108"}], "narration_spoken": "Because loose regolith causes wheel slip while solar glare degrades visual odometry, two zero-order Sugeno fuzzy systems continuously adapt filter covariances. When I M U acceleration disagrees with wheel speed, W O F I S inflates process noise k Q up to tenfold; when visual pose jumps or stalls, V O F I S scales measurement noise k V up to twenty-fivefold.", "audio_file": "assets/audio/04_s2.mp3", "audio_duration_sec": 23.21, "duration_sec": 24.06, "caption_split_sec": 10.18}, {"scene_id": "04_s3", "title": "Zero-Velocity Updates (ZUPT) & TF Tree", "visual_mode": "zupt_lock", "components": ["zupt_detector", "aruco_detector", "ieskf_core", "bt_navigator"], "flows": [{"from": "zupt_detector", "to": "ieskf_core", "channel": "imu_data"}, {"from": "aruco_detector", "to": "ieskf_core", "channel": "aruco_detections"}, {"from": "ieskf_core", "to": "bt_navigator", "channel": "odom_tf"}], "narration": "Whenever the rover pauses for half a second and passes four stationary gates across encoder speed, gyro rate, and accelerometer variance, our ZUPT detector injects a hard zero-velocity pseudo-measurement. That update collapses accumulated velocity drift and refines IMU biases while the node broadcasts 100 Hz odometry and the dynamic odom-to-base-footprint TF transform.", "captions": ["4-gate ZUPT triggers after 0.5s stationary pause to zero velocity drift.", "Broadcasts 100 Hz /odom and dynamic odom → base_footprint TF."], "source_refs": [{"file": "src/navstack/slam/roar_localization/include/roar_localization/zupt.hpp", "lines": "125-164", "snippet_key": "src/navstack/slam/roar_localization/include/roar_localization/zupt.hpp:125-164"}, {"file": "src/navstack/slam/roar_localization/src/ieskf_node.cpp", "lines": "345-360", "snippet_key": "src/navstack/slam/roar_localization/src/ieskf_node.cpp:345-360"}], "narration_spoken": "Whenever the rover pauses for half a second and passes four stationary gates across encoder speed, gyro rate, and accelerometer variance, our Z U P T detector injects a hard zero-velocity pseudo-measurement. That update collapses accumulated velocity drift and refines I M U biases while the node broadcasts 100 hertz odometry and the dynamic odom-to-base-footprint T F transform.", "audio_file": "assets/audio/04_s3.mp3", "audio_duration_sec": 23.42, "duration_sec": 24.27, "caption_split_sec": 13.46}, {"scene_id": "04_s4", "title": "Kalman-Verified 2.5D Terrain Mapping", "visual_mode": "kalman_heightmap", "components": ["dbscan_gate", "ieskf_core", "terrain_mapper", "costmap_fuser"], "flows": [{"from": "dbscan_gate", "to": "terrain_mapper", "channel": "detections_obstacles"}, {"from": "ieskf_core", "to": "terrain_mapper", "channel": "odom_tf"}, {"from": "terrain_mapper", "to": "costmap_fuser", "channel": "active_heightmap"}], "narration": "Our terrain mapping node initializes a 2.5D grid from the static Marsyard heightmap and projects incoming 3D rock detections into map coordinates via TF. Each candidate must pass a ground-contact elevation gate and converge through a per-obstacle Kalman tracker with three-sigma Mahalanobis association before its height is permanently stamped onto the map.", "captions": ["Seeds 2.5D grid from static terrain + gates floating false positives.", "3σ Mahalanobis + Kalman variance convergence stamps confirmed boulders."], "source_refs": [{"file": "src/navstack/slam/terrain_mapping/terrain_mapping/terrain_mapping_node.py", "lines": "308-398", "snippet_key": "src/navstack/slam/terrain_mapping/terrain_mapping/terrain_mapping_node.py:308-398"}], "narration_spoken": "Our terrain mapping node initializes a two point five D grid from the static Marsyard heightmap and projects incoming three D rock detections into map coordinates via T F. Each candidate must pass a ground-contact elevation gate and converge through a per-obstacle Kalman tracker with three-sigma Mahalanobis association before its height is permanently stamped onto the map.", "audio_file": "assets/audio/04_s4.mp3", "audio_duration_sec": 21.34, "duration_sec": 22.19, "caption_split_sec": 10.59}, {"scene_id": "04_s5", "title": "Unified Costmap: Slope, Roughness & Inflation", "visual_mode": "costmap_fusion", "components": ["terrain_mapper", "costmap_fuser", "dstar_planner", "mppi_controller"], "flows": [{"from": "terrain_mapper", "to": "costmap_fuser", "channel": "active_heightmap"}, {"from": "costmap_fuser", "to": "dstar_planner", "channel": "unified_costmap"}, {"from": "costmap_fuser", "to": "mppi_controller", "channel": "unified_costmap"}], "narration": "The heightmap-to-costmap node reconstructs metric elevations, computing Sobel gradient magnitude for terrain slope and Laplacian magnitude for surface roughness to score traversable cells from zero to ninety-nine. Step heights above forty-five centimeters become lethal cost one hundred and receive an L2 distance-transform inflation halo before publishing on unified-costmap.", "captions": ["Sobel slope + Laplacian roughness score traversable terrain (0–99).", "Steps > 0.45m become lethal (100) with L2 safety inflation on /unified_costmap."], "source_refs": [{"file": "src/navstack/path-planning/globalPlanner/scripts/heightmap_to_costmap.py", "lines": "144-229", "snippet_key": "src/navstack/path-planning/globalPlanner/scripts/heightmap_to_costmap.py:144-229"}, {"file": "src/navstack/navstack_nav2/config/roar_nav2_sim.yaml", "lines": "46-63", "snippet_key": "src/navstack/navstack_nav2/config/roar_nav2_sim.yaml:46-63"}], "narration_spoken": "The heightmap-to-costmap node reconstructs metric elevations, computing Sobel gradient magnitude for terrain slope and Laplacian magnitude for surface roughness to score traversable cells from zero to ninety-nine. Step heights above forty-five centimeters become lethal cost one hundred and receive an L2 distance-transform inflation halo before publishing on unified-costmap.", "audio_file": "assets/audio/04_s5.mp3", "audio_duration_sec": 21.7, "duration_sec": 22.55, "caption_split_sec": 13.44}], "duration_sec": 119.1}, {"id": "lesson_05", "number": "05", "title": "Navigation & Path Planning", "subtitle": "Nav2 Behavior Trees, incremental D* Lite, and 2,000-rollout MPPI.", "thumbnail_kind": "navigation", "scenes": [{"scene_id": "05_s1", "title": "Nav2 Lifecycle & Behavior Tree Brain", "visual_mode": "bt_orchestration", "components": ["bt_navigator", "dstar_planner", "mppi_controller"], "flows": [{"from": "bt_navigator", "to": "dstar_planner", "channel": "nav_to_pose_action"}, {"from": "dstar_planner", "to": "mppi_controller", "channel": "global_plan"}], "narration": "Our Nav2 bringup uses the lifecycle manager to transition the planner, controller, behavior server, and BT Navigator into active state automatically. When a navigate-to-pose goal arrives, the Behavior Tree ticks global D* Lite replanning at 1 Hz alongside 20 Hz MPPI trajectory tracking, backed by spin, backup, and wait recovery actions.", "captions": ["Lifecycle Manager autostarts Planner, Controller, Behaviors, and BT Navigator.", "Behavior Tree coordinates 1 Hz D* Lite replanning, 20 Hz MPPI, and recoveries."], "source_refs": [{"file": "src/navstack/navstack_nav2/launch/roar_nav2_only.launch.py", "lines": "219-289", "snippet_key": "src/navstack/navstack_nav2/launch/roar_nav2_only.launch.py:219-289"}, {"file": "src/navstack/navstack_nav2/config/roar_nav2_sim.yaml", "lines": "1-14", "snippet_key": "src/navstack/navstack_nav2/config/roar_nav2_sim.yaml:1-14"}], "narration_spoken": "Our Nav 2 bringup uses the lifecycle manager to transition the planner, controller, behavior server, and B T Navigator into active state automatically. When a navigate-to-pose goal arrives, the Behavior Tree ticks global D-star Lite replanning at 1 hertz alongside 20 hertz M P P I trajectory tracking, backed by spin, backup, and wait recovery actions.", "audio_file": "assets/audio/05_s1.mp3", "audio_duration_sec": 22.32, "duration_sec": 23.17, "caption_split_sec": 9.49}, {"scene_id": "05_s2", "title": "D* Lite Backward Search, Clearance & Smoothing", "visual_mode": "dstar_wave", "components": ["costmap_fuser", "dstar_planner", "mppi_controller"], "flows": [{"from": "costmap_fuser", "to": "dstar_planner", "channel": "unified_costmap"}, {"from": "dstar_planner", "to": "mppi_controller", "channel": "global_plan"}], "narration": "Inside our custom C++ D* Lite planner plugin, if a requested goal lands on an inflated rock cell, a BFS snap relocates it to the nearest safe cell within five meters. The search then propagates backward from goal to rover—penalizing Euclidean step length, a Dijkstra obstacle-clearance field, and squared costmap difficulty—before applying three-pass path smoothing.", "captions": ["BFS snaps blocked goals (≤ 5m) before backward D* Lite search.", "Combines step distance, obstacle clearance, and squared terrain cost + smoothing."], "source_refs": [{"file": "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp", "lines": "203-281", "snippet_key": "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp:203-281"}, {"file": "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp", "lines": "698-717", "snippet_key": "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp:698-717"}], "narration_spoken": "Inside our custom C++ D-star Lite planner plugin, if a requested goal lands on an inflated rock cell, a B F S snap relocates it to the nearest safe cell within five meters. The search then propagates backward from goal to rover—penalizing Euclidean step length, a Dijkstra obstacle-clearance field, and squared costmap difficulty—before applying three-pass path smoothing.", "audio_file": "assets/audio/05_s2.mp3", "audio_duration_sec": 22.82, "duration_sec": 23.67, "caption_split_sec": 11.25}, {"scene_id": "05_s3", "title": "Incremental Path Repair in Milliseconds", "visual_mode": "dstar_incremental", "components": ["costmap_fuser", "dstar_planner", "rover_twin"], "flows": [{"from": "costmap_fuser", "to": "dstar_planner", "channel": "unified_costmap"}, {"from": "dstar_planner", "to": "rover_twin", "channel": "global_plan"}], "narration": "As newly detected boulders stamp onto unified-costmap mid-traverse, our D* Lite plugin diffs the incoming occupancy grid against its cached grid. Instead of replanning across the full Marsyard from scratch, it updates edge keys only around modified cells and repairs the affected path segment in milliseconds.", "captions": ["Diffs incoming /unified_costmap updates against the cached planner grid.", "Locally repairs priority-queue vertices around new boulders in milliseconds."], "source_refs": [{"file": "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp", "lines": "282-300", "snippet_key": "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp:282-300"}, {"file": "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp", "lines": "574-639", "snippet_key": "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp:574-639"}], "narration_spoken": "As newly detected boulders stamp onto unified-costmap mid-traverse, our D-star Lite plugin diffs the incoming occupancy grid against its cached grid. Instead of replanning across the full Marsyard from scratch, it updates edge keys only around modified cells and repairs the affected path segment in milliseconds.", "audio_file": "assets/audio/05_s3.mp3", "audio_duration_sec": 18.17, "duration_sec": 19.02, "caption_split_sec": 9.9}, {"scene_id": "05_s4", "title": "MPPI: 2,000 Trajectory Rollouts & 8 Critics", "visual_mode": "mppi_rollouts", "components": ["dstar_planner", "costmap_fuser", "mppi_controller"], "flows": [{"from": "dstar_planner", "to": "mppi_controller", "channel": "global_plan"}, {"from": "costmap_fuser", "to": "mppi_controller", "channel": "unified_costmap"}], "narration": "In our implementation, the MPPI controller receives an eight-by-eight-meter rolling local costmap and the rover's current motion state at 20 Hz, forward-simulating two thousand perturbed differential-drive rollouts over a 2.8-second horizon. Eight configured critics score each candidate on obstacle cost, path alignment, goal angle, and forward preference to synthesize one optimal control sequence.", "captions": ["Simulates 2,000 DiffDrive rollouts (2.8s horizon) at 20 Hz on an 8×8m window.", "8 critics weight obstacle clearance, path alignment, and forward motion."], "source_refs": [{"file": "src/navstack/navstack_nav2/config/roar_nav2_sim.yaml", "lines": "82-180", "snippet_key": "src/navstack/navstack_nav2/config/roar_nav2_sim.yaml:82-180"}, {"file": "src/navstack/control/nav2_mppi_controller/src/optimizer.cpp", "lines": "134-162", "snippet_key": "src/navstack/control/nav2_mppi_controller/src/optimizer.cpp:134-162"}], "narration_spoken": "In our implementation, the M P P I controller receives an eight-by-eight-meter rolling local costmap and the rover's current motion state at 20 hertz, forward-simulating two thousand perturbed differential-drive rollouts over a 2.8-second horizon. Eight configured critics score each candidate on obstacle cost, path alignment, goal angle, and forward preference to synthesize one optimal control sequence.", "audio_file": "assets/audio/05_s4.mp3", "audio_duration_sec": 24.12, "duration_sec": 24.97, "caption_split_sec": 17.74}, {"scene_id": "05_s5", "title": "Savitzky-Golay Smoothing to 6-Wheel Kinematics", "visual_mode": "six_wheel_drive", "components": ["mppi_controller", "ros2_control", "rover_twin"], "flows": [{"from": "mppi_controller", "to": "ros2_control", "channel": "cmd_vel_stamped"}, {"from": "ros2_control", "to": "rover_twin", "channel": "joint_pulses"}], "narration": "Before commands leave Nav2, a Savitzky-Golay velocity smoother filters high-frequency control jitter and remaps stamped Twist messages directly onto the differential-drive controller topic. Inside ros2_control, left and right angular velocities drive three synchronized rocker-bogie wheels per side while raw controller TF remains disabled to preserve IESKF authority.", "captions": ["Savitzky-Golay smoother publishes TwistStamped to /diff_drive_controller/cmd_vel.", "Drives 3 wheels per side (enable_odom_tf: false preserves IESKF TF)."], "source_refs": [{"file": "src/navstack/navstack_nav2/launch/roar_nav2_only.launch.py", "lines": "241-248", "snippet_key": "src/navstack/navstack_nav2/launch/roar_nav2_only.launch.py:241-248"}, {"file": "src/roar2026/dev_environment/rover/roar_simulation_full/configs/diff_controller.yaml", "lines": "18-43", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/configs/diff_controller.yaml:18-43"}], "narration_spoken": "Before commands leave Nav 2, a Savitzky-Golay velocity smoother filters high-frequency control jitter and remaps stamped Twist messages directly onto the differential-drive controller topic. Inside ros2_control, left and right angular velocities drive three synchronized rocker-bogie wheels per side while raw controller T F remains disabled to preserve I E S K F authority.", "audio_file": "assets/audio/05_s5.mp3", "audio_duration_sec": 23.11, "duration_sec": 23.96, "caption_split_sec": 13.49}], "duration_sec": 114.8}, {"id": "lesson_06", "number": "06", "title": "Mission Execution", "subtitle": "Grid-to-metric coordinate injection, NavigateToPose loops, and batch queues.", "thumbnail_kind": "mission", "scenes": [{"scene_id": "06_s1", "title": "Map Preview & Grid-to-Metric Injection", "visual_mode": "coord_injection", "components": ["wp_sampler", "mission_gui", "dstar_planner", "referee_core"], "flows": [{"from": "wp_sampler", "to": "mission_gui", "channel": "offline_bake"}, {"from": "mission_gui", "to": "dstar_planner", "channel": "yaml_injection"}, {"from": "mission_gui", "to": "referee_core", "channel": "yaml_injection"}], "narration": "When an operator selects a world and route ID in Mission Control, the GUI reads the NumPy waypoint indices and converts grid columns and rows into metric world coordinates using the heightmap origin and resolution. It writes those exact coordinates into both the Nav2 YAML configuration and the referee inputs directory so planning and scoring share a single ground truth.", "captions": ["Converts NumPy grid (col, row) indices into metric (x, y) world meters.", "Injects identical targets into roar_nav2_sim.yaml and referee inputs."], "source_refs": [{"file": "src/navigation/scripts/asu_roar_gui.py", "lines": "928-1007", "snippet_key": "src/navigation/scripts/asu_roar_gui.py:928-1007"}], "narration_spoken": "When an operator selects a world and route ID in Mission Control, the G U I reads the num-pie waypoint indices and converts grid columns and rows into metric world coordinates using the heightmap origin and resolution. It writes those exact coordinates into both the Nav 2 yam-ul configuration and the referee inputs directory so planning and scoring share a single ground truth.", "audio_file": "assets/audio/06_s1.mp3", "audio_duration_sec": 22.01, "duration_sec": 22.86, "caption_split_sec": 12.97}, {"scene_id": "06_s2", "title": "Sequential NavigateToPose Action Loop", "visual_mode": "waypoint_sequence", "components": ["wp_follower", "bt_navigator", "ieskf_core"], "flows": [{"from": "wp_follower", "to": "bt_navigator", "channel": "nav_to_pose_action"}, {"from": "ieskf_core", "to": "wp_follower", "channel": "odom_tf"}], "narration": "Once Gate 2 unlocks, our waypoint follower sends each target sequentially over the navigate-to-pose action interface while monitoring continuous action feedback. Nav2's goal checker marks a leg succeeded once the rover enters a 0.45-meter XY tolerance radius, immediately triggering dispatch of the next mission waypoint.", "captions": ["Dispatches sequential goals via /navigate_to_pose action client.", "Goal checker confirms arrival within 0.45m XY tolerance before advancing."], "source_refs": [{"file": "src/navstack/path-planning/globalPlanner/scripts/batch_waypoint_follower.py", "lines": "26-68", "snippet_key": "src/navstack/path-planning/globalPlanner/scripts/batch_waypoint_follower.py:26-68"}, {"file": "src/navstack/navstack_nav2/config/roar_nav2_sim.yaml", "lines": "77-81", "snippet_key": "src/navstack/navstack_nav2/config/roar_nav2_sim.yaml:77-81"}], "narration_spoken": "Once Gate 2 unlocks, our waypoint follower sends each target sequentially over the navigate-to-pose action interface while monitoring continuous action feedback. Nav 2's goal checker marks a leg succeeded once the rover enters a 0.45-meter XY tolerance radius, immediately triggering dispatch of the next mission waypoint.", "audio_file": "assets/audio/06_s2.mp3", "audio_duration_sec": 19.25, "duration_sec": 20.1, "caption_split_sec": 9.55}, {"scene_id": "06_s3", "title": "Competition Judge Mode vs. Batch Queue", "visual_mode": "judge_vs_batch", "components": ["mission_gui", "wp_follower", "referee_core"], "flows": [{"from": "mission_gui", "to": "wp_follower", "channel": "nav_to_pose_action"}, {"from": "wp_follower", "to": "referee_core", "channel": "odom_tf"}], "narration": "Our execution layer supports two follower nodes: an interactive ERC competition client that pauses at each reached waypoint for judge clearance or retry commands, and an unattended batch client for multi-world regression queues. In batch mode, a twenty-minute watchdog timer guards every run against deadlocks so overnight test campaigns never stall.", "captions": ["ERC mode pauses for judge clearance; Batch mode runs unattended queues.", "20-minute watchdog timer protects multi-world regression runs from hangs."], "source_refs": [{"file": "src/navstack/path-planning/globalPlanner/scripts/erc_waypoint_follower.py", "lines": "151-166", "snippet_key": "src/navstack/path-planning/globalPlanner/scripts/erc_waypoint_follower.py:151-166"}, {"file": "src/navigation/scripts/asu_roar_gui.py", "lines": "77-81", "snippet_key": "src/navigation/scripts/asu_roar_gui.py:77-81"}], "narration_spoken": "Our execution layer supports two follower nodes: an interactive E R C competition client that pauses at each reached waypoint for judge clearance or retry commands, and an unattended batch client for multi-world regression queues. In batch mode, a twenty-minute watchdog timer guards every run against deadlocks so overnight test campaigns never stall.", "audio_file": "assets/audio/06_s3.mp3", "audio_duration_sec": 19.97, "duration_sec": 20.82, "caption_split_sec": 13.32}, {"scene_id": "06_s4", "title": "Return to Start (0,0) & Graceful Teardown", "visual_mode": "return_home", "components": ["wp_follower", "rover_twin", "referee_core", "mission_gui"], "flows": [{"from": "wp_follower", "to": "rover_twin", "channel": "nav_to_pose_action"}, {"from": "referee_core", "to": "mission_gui", "channel": "referee_score"}], "narration": "After clearing the fourth waypoint, the follower appends a fifth navigation leg back to origin zero-zero to earn the fifty-point autonomous return bonus. As soon as the rover settles at home and the referee writes run-summary NumPy artifacts, Mission Control cleanly terminates all process groups and advances the queue.", "captions": ["Leg 5 navigates back to Start (0, 0) for the 50-pt return bonus.", "Persists run_summary.npy and cleanly tears down all ROS 2 & Gazebo processes."], "source_refs": [{"file": "src/navstack/path-planning/globalPlanner/scripts/batch_waypoint_follower.py", "lines": "136-163", "snippet_key": "src/navstack/path-planning/globalPlanner/scripts/batch_waypoint_follower.py:136-163"}, {"file": "src/navigation/scripts/asu_roar_gui.py", "lines": "1212-1231", "snippet_key": "src/navigation/scripts/asu_roar_gui.py:1212-1231"}], "narration_spoken": "After clearing the fourth waypoint, the follower appends a fifth navigation leg back to origin zero-zero to earn the fifty-point autonomous return bonus. As soon as the rover settles at home and the referee writes run-summary num-pie artifacts, Mission Control cleanly terminates all process groups and advances the queue.", "audio_file": "assets/audio/06_s4.mp3", "audio_duration_sec": 18.43, "duration_sec": 19.28, "caption_split_sec": 9.4}], "duration_sec": 83.1}, {"id": "lesson_07", "number": "07", "title": "Referee & Evaluation", "subtitle": "Mesh-aware collision rules, 300-point ERC math, and HTML scorecards.", "thumbnail_kind": "referee", "scenes": [{"scene_id": "07_s1", "title": "Mesh-Aware Collision Monitoring", "visual_mode": "pebble_vs_boulder", "components": ["gazebo_sim", "marsyard_gen", "collision_monitor", "referee_core"], "flows": [{"from": "gazebo_sim", "to": "collision_monitor", "channel": "rover_contact"}, {"from": "marsyard_gen", "to": "collision_monitor", "channel": "offline_bake"}, {"from": "collision_monitor", "to": "referee_core", "channel": "collision_flag"}], "narration": "Not every rock contact on the Marsyard is a penalty—rovers are permitted to roll over small pebbles while solid boulders are strictly forbidden. Our collision monitor cross-references incoming Gazebo contact names against ground-truth obstacle metadata, whitelisting pebble mesh IDs five through nine and publishing an immediate collision flag on any larger rock hit.", "captions": ["Cross-references 7 link contact streams against obstacle_data.npy.", "Whitelists safe pebble meshes {5..9}; flags solid boulder hits immediately."], "source_refs": [{"file": "src/navigation/referee_engine/referee_engine/collision_monitor_node.py", "lines": "24-95", "snippet_key": "src/navigation/referee_engine/referee_engine/collision_monitor_node.py:24-95"}], "narration_spoken": "Not every rock contact on the Marsyard is a penalty—rovers are permitted to roll over small pebbles while solid boulders are strictly forbidden. Our collision monitor cross-references incoming Gazebo contact names against ground-truth obstacle metadata, whitelisting pebble mesh IDs five through nine and publishing an immediate collision flag on any larger rock hit.", "audio_file": "assets/audio/07_s1.mp3", "audio_duration_sec": 20.59, "duration_sec": 21.44, "caption_split_sec": 8.09}, {"scene_id": "07_s2", "title": "Critical Rules: Instant KILL vs. 20-Minute Timeout", "visual_mode": "kill_vs_timeout", "components": ["collision_monitor", "ros_gz_bridge", "referee_core"], "flows": [{"from": "collision_monitor", "to": "referee_core", "channel": "collision_flag"}, {"from": "ros_gz_bridge", "to": "referee_core", "channel": "gz_bridge_bus"}], "narration": "At 10 Hz, the critical rule enforcer checks two terminal conditions: any boulder collision or Marsyard boundary breach triggers an instant KILL that zeroes the entire run score. Conversely, exceeding twenty minutes of active driving triggers a TIMEOUT that preserves all earned points, while judge-hold pauses are excluded from the mission clock.", "captions": ["Boulder hit or boundary breach → instant KILL and 0 total points.", "20-min active clock limit → TIMEOUT (retains earned points; pauses excluded)."], "source_refs": [{"file": "src/navigation/referee_engine/referee_engine/critical_rule_enforcer.py", "lines": "28-45", "snippet_key": "src/navigation/referee_engine/referee_engine/critical_rule_enforcer.py:28-45"}, {"file": "src/navigation/referee_engine/referee_engine/referee_core_node.py", "lines": "175-187", "snippet_key": "src/navigation/referee_engine/referee_engine/referee_core_node.py:175-187"}], "narration_spoken": "At 10 hertz, the critical rule enforcer checks two terminal conditions: any boulder collision or Marsyard boundary breach triggers an instant KILL that zeroes the entire run score. Conversely, exceeding twenty minutes of active driving triggers a TIMEOUT that preserves all earned points, while judge-hold pauses are excluded from the mission clock.", "audio_file": "assets/audio/07_s2.mp3", "audio_duration_sec": 19.97, "duration_sec": 20.82, "caption_split_sec": 10.61}, {"scene_id": "07_s3", "title": "Settled Stop & Edge-Distance Precision Formula", "visual_mode": "edge_caliper", "components": ["ieskf_core", "rover_twin", "referee_core"], "flows": [{"from": "ieskf_core", "to": "referee_core", "channel": "odom_tf"}, {"from": "rover_twin", "to": "referee_core", "channel": "odom_tf"}], "narration": "Driving past a waypoint does not count—our waypoint tracker requires the rover center to enter a one-meter capture radius and settle below 0.05 m/s linear speed. Once settled, the score calculator subtracts the half-meter rover radius to obtain chassis edge distance d_edge and awards thirty minus six times d_edge precision points.", "captions": ["Requires settled stop: center distance ≤ 1.0m and speed < 0.05 m/s.", "Edge-distance precision formula: max(0, round(30 - 6 × d_edge)) pts."], "source_refs": [{"file": "src/navigation/referee_engine/referee_engine/waypoint_tracker.py", "lines": "141-174", "snippet_key": "src/navigation/referee_engine/referee_engine/waypoint_tracker.py:141-174"}, {"file": "src/navigation/referee_engine/referee_engine/score_calculator.py", "lines": "40-51", "snippet_key": "src/navigation/referee_engine/referee_engine/score_calculator.py:40-51"}], "narration_spoken": "Driving past a waypoint does not count—our waypoint tracker requires the rover center to enter a one-meter capture radius and settle below 0.05 meters per second linear speed. Once settled, the score calculator subtracts the half-meter rover radius to obtain chassis edge distance d edge and awards thirty minus six times d edge precision points.", "audio_file": "assets/audio/07_s3.mp3", "audio_duration_sec": 21.46, "duration_sec": 22.31, "caption_split_sec": 12.14}, {"scene_id": "07_s4", "title": "The Official 300-Point ERC Score Breakdown", "visual_mode": "erc_score_bar", "components": ["referee_core", "report_gen"], "flows": [{"from": "referee_core", "to": "report_gen", "channel": "referee_score"}], "narration": "Our score calculator implements the full 300-point ERC Traverse rubric: up to one hundred twenty points across four waypoints, one hundred points for autonomous leg transitions, fifty points for autonomous return to start, and thirty points for strict waypoint ordering. Any manual return-to-start intervention deducts five penalty points while streaming live JSON breakdowns at 10 Hz.", "captions": ["300 pts: 120 WP precision + 100 autonomy + 50 return + 30 route adherence.", "Streams live 10 Hz JSON rule breakdowns on /referee/score."], "source_refs": [{"file": "src/navigation/referee_engine/referee_engine/score_calculator.py", "lines": "86-183", "snippet_key": "src/navigation/referee_engine/referee_engine/score_calculator.py:86-183"}], "narration_spoken": "Our score calculator implements the full 300-point E R C Traverse rubric: up to one hundred twenty points across four waypoints, one hundred points for autonomous leg transitions, fifty points for autonomous return to start, and thirty points for strict waypoint ordering. Any manual return-to-start intervention deducts five penalty points while streaming live jay-son breakdowns at 10 hertz.", "audio_file": "assets/audio/07_s4.mp3", "audio_duration_sec": 23.5, "duration_sec": 24.35, "caption_split_sec": 16.77}, {"scene_id": "07_s5", "title": "Subsystem Benchmarks & Master HTML Scorecards", "visual_mode": "html_dashboards", "components": ["referee_core", "report_gen", "mission_gui"], "flows": [{"from": "referee_core", "to": "report_gen", "channel": "referee_score"}, {"from": "report_gen", "to": "mission_gui", "channel": "referee_score"}], "narration": "Alongside competition scoring, dedicated evaluation nodes benchmark SLAM trajectory RMSE, 3D bounding-box IoU for perception, and path-tracking cross-track error against Gazebo ground truth. At run completion, the report generator compiles per-mission HTML dashboards and aggregates multi-world batch runs into a master leaderboard.", "captions": ["Benchmarks SLAM RMSE, 3D perception IoU, and path-tracking error vs. truth.", "Compiles per-run HTML scorecards plus multi-world Master Batch reports."], "source_refs": [{"file": "src/navigation/referee_engine/launch/roar_full_evaluation.launch.py", "lines": "160-284", "snippet_key": "src/navigation/referee_engine/launch/roar_full_evaluation.launch.py:160-284"}, {"file": "src/navigation/scripts/asu_roar_gui.py", "lines": "1263-1358", "snippet_key": "src/navigation/scripts/asu_roar_gui.py:1263-1358"}], "narration_spoken": "Alongside competition scoring, dedicated evaluation nodes benchmark slam trajectory RMSE, three D bounding-box I O U for perception, and path-tracking cross-track error against Gazebo ground truth. At run completion, the report generator compiles per-mission H T M L dashboards and aggregates multi-world batch runs into a master leaderboard.", "audio_file": "assets/audio/07_s5.mp3", "audio_duration_sec": 21.26, "duration_sec": 22.11, "caption_split_sec": 13.76}], "duration_sec": 111.0}], "scenarios": [{"id": "sc_sim_init", "number": "S1", "title": "Simulation Initialization", "subtitle": "Gazebo spawn → 12s settle → chained controllers → Gate 1.", "scenes": [{"scene_id": "sc1_s1", "title": "Launch Gazebo & Spawn Rover", "visual_mode": "rover_variants", "components": ["mission_gui", "gazebo_sim", "rover_twin"], "flows": [{"from": "mission_gui", "to": "gazebo_sim", "channel": "spawn_chain"}, {"from": "rover_twin", "to": "gazebo_sim", "channel": "spawn_chain"}], "narration": "Simulation bringup starts when ASU ROAR Mission Control invokes launch-test with the selected world ID and rover sensor profile. Gazebo Harmonic loads the Marsyard SDF terrain, spawns the compiled Xacro rover model, and starts the clock and sensor parameter bridge.", "captions": ["Mission Control invokes launch_test.sh with selected world & rover profile.", "Gazebo Harmonic loads Marsyard SDF, spawns rover, and starts clock bridge."], "source_refs": [{"file": "src/roar2026/dev_environment/launch_test.sh", "lines": "116-121", "snippet_key": "src/roar2026/dev_environment/launch_test.sh:116-121"}], "narration_spoken": "Simulation bringup starts when A S U Roar Mission Control invokes launch-test with the selected world ID and rover sensor profile. Gazebo Harmonic loads the Marsyard S D F terrain, spawns the compiled zack-roh rover model, and starts the clock and sensor parameter bridge.", "audio_file": "assets/audio/sc1_s1.mp3", "audio_duration_sec": 16.61, "duration_sec": 17.46, "caption_split_sec": 8.38}, {"scene_id": "sc1_s2", "title": "Chained ros2_control Activation", "visual_mode": "six_wheel_drive", "components": ["gazebo_sim", "ros2_control", "rover_twin"], "flows": [{"from": "gazebo_sim", "to": "ros2_control", "channel": "spawn_chain"}, {"from": "ros2_control", "to": "rover_twin", "channel": "gate_sim_ready"}], "narration": "Once entity spawn exits, a twelve-second timer lets the rocker-bogie suspension settle onto the terrain mesh before loading controllers. Launch event handlers then chain the joint-state broadcaster into the six-wheel differential-drive controller and optional arm controller.", "captions": ["12s post-spawn timer lets rocker-bogie suspension settle on terrain.", "OnProcessExit handlers chain joint_state_broadcaster → diff_drive → arm."], "source_refs": [{"file": "src/roar2026/dev_environment/rover/roar_simulation_full/launch/basic_rover.launch.py", "lines": "281-306", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/launch/basic_rover.launch.py:281-306"}], "narration_spoken": "Once entity spawn exits, a twelve-second timer lets the rocker-bogie suspension settle onto the terrain mesh before loading controllers. Launch event handlers then chain the joint-state broadcaster into the six-wheel differential-drive controller and optional arm controller.", "audio_file": "assets/audio/sc1_s2.mp3", "audio_duration_sec": 14.98, "duration_sec": 15.83, "caption_split_sec": 8.1}, {"scene_id": "sc1_s3", "title": "Readiness Gate 1 Unlocked", "visual_mode": "readiness_gates", "components": ["ros2_control", "mission_gui"], "flows": [{"from": "ros2_control", "to": "mission_gui", "channel": "gate_sim_ready"}], "narration": "Mission Control polls the ROS 2 graph every 1.5 seconds waiting for the differential-drive odometry topic to appear. As soon as that topic goes live, Readiness Gate 1 unlocks and triggers the SLAM, perception, and Nav2 launch sequence.", "captions": ["Polls ROS 2 topic graph every 1.5s for /diff_drive_controller/odom.", "Gate 1 unlocks and triggers SLAM, Perception, and Nav2 bringup."], "source_refs": [{"file": "src/navigation/scripts/asu_roar_gui.py", "lines": "1133-1148", "snippet_key": "src/navigation/scripts/asu_roar_gui.py:1133-1148"}, {"file": "src/navigation/scripts/asu_roar_gui.py", "lines": "1451-1457", "snippet_key": "src/navigation/scripts/asu_roar_gui.py:1451-1457"}], "narration_spoken": "Mission Control polls the Ross 2 graph every 1.5 seconds waiting for the differential-drive odometry topic to appear. As soon as that topic goes live, Readiness Gate 1 unlocks and triggers the slam, perception, and Nav 2 launch sequence.", "audio_file": "assets/audio/sc1_s3.mp3", "audio_duration_sec": 15.12, "duration_sec": 15.97, "caption_split_sec": 7.92}], "duration_sec": 49.3}, {"id": "sc_sensor_proc", "number": "S2", "title": "Sensor Processing", "subtitle": "Raw Gazebo streams → Mars dust & glare → quantized pulses.", "scenes": [{"scene_id": "sc2_s1", "title": "Gazebo Physics to ROS 2 Sensor Streams", "visual_mode": "gz_bridge", "components": ["gazebo_sim", "ros_gz_bridge"], "flows": [{"from": "gazebo_sim", "to": "ros_gz_bridge", "channel": "gz_bridge_bus"}], "narration": "During active operation, the ROS-Gazebo bridge streams 5 Hz ZED2i RGB and float32 depth frames, 100 Hz BNO055 inertial measurements, and 50 Hz link contact arrays. Every message carries synchronized simulation timestamps driven by the bridged Gazebo clock topic.", "captions": ["Bridges 5 Hz RGB-D, 100 Hz BNO055 IMU, and 50 Hz contact streams.", "All sensor headers share simulation time via bridged /clock."], "source_refs": [{"file": "src/roar2026/dev_environment/rover/roar_simulation_full/launch/basic_rover.launch.py", "lines": "166-199", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/launch/basic_rover.launch.py:166-199"}], "narration_spoken": "During active operation, the Ross-Gazebo bridge streams 5 hertz Zed 2 i R G B and float32 depth frames, 100 hertz B N O zero five five inertial measurements, and 50 hertz link contact arrays. Every message carries synchronized simulation timestamps driven by the bridged Gazebo clock topic.", "audio_file": "assets/audio/sc2_s1.mp3", "audio_duration_sec": 19.46, "duration_sec": 20.31, "caption_split_sec": 14.15}, {"scene_id": "sc2_s2", "title": "Atmospheric Degradation & 3D Unprojection", "visual_mode": "solar_degradation", "components": ["ros_gz_bridge", "zed_degradation", "lidar_cluster"], "flows": [{"from": "ros_gz_bridge", "to": "zed_degradation", "channel": "raw_camera"}, {"from": "zed_degradation", "to": "lidar_cluster", "channel": "points_updated"}], "narration": "Our ZED2i degradation node projects the sun into image space to inject glare washout, Mars dust attenuation, and quadratic stereo depth noise. It then back-projects degraded depth and RGB pixels through the camera intrinsics into a colored XYZRGB point cloud.", "captions": ["Injects solar glare NaN holes, dust, and 0.003·Z² depth noise.", "Back-projects degraded RGB-D frames onto /zed2i/points_updated."], "source_refs": [{"file": "src/roar2026/dev_environment/rover/roar_simulation_full/src/zed_degradation_node.py", "lines": "255-337", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/src/zed_degradation_node.py:255-337"}], "narration_spoken": "Our Zed 2 i degradation node projects the sun into image space to inject glare washout, Mars dust attenuation, and quadratic stereo depth noise. It then back-projects degraded depth and R G B pixels through the camera intrinsics into a colored X Y Z R G B point cloud.", "audio_file": "assets/audio/sc2_s2.mp3", "audio_duration_sec": 16.78, "duration_sec": 17.63, "caption_split_sec": 8.8}, {"scene_id": "sc2_s3", "title": "Encoder Pulse Quantization", "visual_mode": "encoder_pulses", "components": ["ros2_control", "encoder_sim", "wio_module"], "flows": [{"from": "ros2_control", "to": "encoder_sim", "channel": "joint_pulses"}, {"from": "encoder_sim", "to": "wio_module", "channel": "joint_pulses"}], "narration": "Simultaneously, the encoder simulator reads continuous left and right middle-wheel joint angles and quantizes them into rounded integer pulse counts. Publishing those discrete ticks at 50 Hz ensures our localization filter experiences exact hardware encoder resolution.", "captions": ["Converts continuous middle-wheel radians into integer encoder counts.", "Publishes quantized ticks at 50 Hz on /joint_states_updated."], "source_refs": [{"file": "src/roar2026/dev_environment/rover/roar_simulation_full/src/encoder_sim_node.py", "lines": "50-75", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/src/encoder_sim_node.py:50-75"}], "narration_spoken": "Simultaneously, the encoder simulator reads continuous left and right middle-wheel joint angles and quantizes them into rounded integer pulse counts. Publishing those discrete ticks at 50 hertz ensures our localization filter experiences exact hardware encoder resolution.", "audio_file": "assets/audio/sc2_s3.mp3", "audio_duration_sec": 16.06, "duration_sec": 16.91, "caption_split_sec": 9.46}], "duration_sec": 54.8}, {"id": "sc_perception", "number": "S3", "title": "Perception", "subtitle": "PointCloud2 → RANSAC & Roughness → DBSCAN → World EMA map.", "scenes": [{"scene_id": "sc3_s1", "title": "ROI, Voxel & Outlier Rejection", "visual_mode": "pointcloud_clean", "components": ["zed_degradation", "lidar_cluster", "ransac_roughness"], "flows": [{"from": "zed_degradation", "to": "lidar_cluster", "channel": "points_updated"}, {"from": "lidar_cluster", "to": "ransac_roughness", "channel": "points_filtered"}], "narration": "Incoming stereo clouds enter the clustering node with Best-Effort depth-one QoS so stale frames are dropped automatically under load. CUDA range cropping within six meters, six-centimeter voxel downsampling, and dual SOR and ROR filters produce a clean obstacle candidate cloud.", "captions": ["Best-Effort (depth 1) drops stale clouds; GPU crops range < 6.0m.", "6cm voxel grid + SOR/ROR outlier rejection publish /lidar/points_filtered."], "source_refs": [{"file": "src/navstack/perception/perception_module/lidar_cluster_node.py", "lines": "148-203", "snippet_key": "src/navstack/perception/perception_module/lidar_cluster_node.py:148-203"}], "narration_spoken": "Incoming stereo clouds enter the clustering node with Best-Effort depth-one Q O S so stale frames are dropped automatically under load. koo-dah range cropping within six meters, six-centimeter voxel downsampling, and dual S O R and R O R filters produce a clean obstacle candidate cloud.", "audio_file": "assets/audio/sc3_s1.mp3", "audio_duration_sec": 17.71, "duration_sec": 18.56, "caption_split_sec": 8.62}, {"scene_id": "sc3_s2", "title": "Ramp Preservation & Rock Clustering", "visual_mode": "ransac_slope", "components": ["ransac_roughness", "dbscan_gate", "terrain_mapper"], "flows": [{"from": "ransac_roughness", "to": "dbscan_gate", "channel": "points_no_ground"}, {"from": "dbscan_gate", "to": "terrain_mapper", "channel": "detections_obstacles"}], "narration": "Iterative slope-aware RANSAC strips ground and traversable ramps up to forty-five degrees, while PCA roughness filtering removes smooth slope remnants. DBSCAN and 3D bounding-box shape gates then isolate true boulders and publish validated detections to the terrain mapper.", "captions": ["Slope-aware RANSAC (≤ 45°) + PCA roughness isolate jagged rock surfaces.", "DBSCAN + 3D shape gates publish boulders to /detections/obstacles."], "source_refs": [{"file": "src/navstack/perception/perception_module/lidar_cluster_node.py", "lines": "205-293", "snippet_key": "src/navstack/perception/perception_module/lidar_cluster_node.py:205-293"}], "narration_spoken": "Iterative slope-aware ran-sack strips ground and traversable ramps up to forty-five degrees, while P C A roughness filtering removes smooth slope remnants. D B scan and three D bounding-box shape gates then isolate true boulders and publish validated detections to the terrain mapper.", "audio_file": "assets/audio/sc3_s2.mp3", "audio_duration_sec": 16.7, "duration_sec": 17.55, "caption_split_sec": 10.34}, {"scene_id": "sc3_s3", "title": "World-Frame EMA Stabilization", "visual_mode": "ema_memory", "components": ["lidar_cluster", "ieskf_core", "obstacle_pub"], "flows": [{"from": "lidar_cluster", "to": "obstacle_pub", "channel": "lidar_clusters"}, {"from": "ieskf_core", "to": "obstacle_pub", "channel": "odom_tf"}], "optional_insight_id": "aruco_import_mismatch", "narration": "Using the live TF tree from IESKF, our obstacle publisher transforms camera-frame bounding boxes into persistent odom coordinates. Exponential moving-average updates smooth centroid jitter across frames and hold obstacles in memory for four seconds during brief occlusions.", "captions": ["Transforms 3D rock boxes from camera optical frame into odom via TF2.", "EMA centroid smoothing + 4s persistence stabilize /planning/obstacles."], "source_refs": [{"file": "src/navstack/perception/perception_module/obstacle_publisher_node.py", "lines": "130-201", "snippet_key": "src/navstack/perception/perception_module/obstacle_publisher_node.py:130-201"}], "narration_spoken": "Using the live T F tree from I E S K F, our obstacle publisher transforms camera-frame bounding boxes into persistent odom coordinates. Exponential moving-average updates smooth centroid jitter across frames and hold obstacles in memory for four seconds during brief occlusions.", "audio_file": "assets/audio/sc3_s3.mp3", "audio_duration_sec": 16.75, "duration_sec": 17.6, "caption_split_sec": 9.56}], "duration_sec": 53.7}, {"id": "sc_map_loc", "number": "S4", "title": "Mapping and Localization", "subtitle": "100 Hz IESKF + Fuzzy + ZUPT → 2.5D Kalman map → Costmap.", "scenes": [{"scene_id": "sc4_s1", "title": "IESKF + Sugeno Fuzzy + ZUPT", "visual_mode": "fuzzy_balance", "components": ["wio_module", "fuzzy_fis", "zupt_detector", "ieskf_core"], "flows": [{"from": "wio_module", "to": "ieskf_core", "channel": "joint_pulses"}, {"from": "fuzzy_fis", "to": "ieskf_core", "channel": "zed_pose_cov"}, {"from": "zupt_detector", "to": "ieskf_core", "channel": "odom_tf"}], "narration": "Inside ASU ROAR localization, the 12D IESKF fuses 100 Hz wheel-inertial predictions with visual pose observations weighted dynamically by Sugeno WO-FIS and VO-FIS. Stationary ZUPT updates clamp velocity drift to zero while the filter broadcasts fused odometry and TF transforms.", "captions": ["12D IESKF fuses 100 Hz WIO + visual pose weighted by Sugeno Fuzzy FIS.", "Stationary ZUPT resets velocity drift; publishes /odom + dynamic TF."], "source_refs": [{"file": "src/navstack/slam/roar_localization/src/ieskf_node.cpp", "lines": "295-360", "snippet_key": "src/navstack/slam/roar_localization/src/ieskf_node.cpp:295-360"}], "narration_spoken": "Inside A S U Roar localization, the twelve D I E S K F fuses 100 hertz wheel-inertial predictions with visual pose observations weighted dynamically by Sugeno W O F I S and V O F I S. Stationary Z U P T updates clamp velocity drift to zero while the filter broadcasts fused odometry and T F transforms.", "audio_file": "assets/audio/sc4_s1.mp3", "audio_duration_sec": 21.72, "duration_sec": 22.57, "caption_split_sec": 14.55}, {"scene_id": "sc4_s2", "title": "Mahalanobis & Kalman Obstacle Stamping", "visual_mode": "kalman_heightmap", "components": ["dbscan_gate", "ieskf_core", "terrain_mapper", "costmap_fuser"], "flows": [{"from": "dbscan_gate", "to": "terrain_mapper", "channel": "detections_obstacles"}, {"from": "ieskf_core", "to": "terrain_mapper", "channel": "odom_tf"}, {"from": "terrain_mapper", "to": "costmap_fuser", "channel": "active_heightmap"}], "narration": "Anchored by that TF tree, the terrain mapper associates world-frame rock detections using three-sigma Mahalanobis gating and updates per-obstacle Kalman trackers. Once positional variance drops below 0.025 square meters, the boulder elevation is stamped onto the active 2.5D heightmap.", "captions": ["3σ Mahalanobis association updates per-obstacle Kalman trackers.", "Stamps rock elevation onto /active_map/heightmap once variance < 0.025 m²."], "source_refs": [{"file": "src/navstack/slam/terrain_mapping/terrain_mapping/terrain_mapping_node.py", "lines": "308-398", "snippet_key": "src/navstack/slam/terrain_mapping/terrain_mapping/terrain_mapping_node.py:308-398"}], "narration_spoken": "Anchored by that T F tree, the terrain mapper associates world-frame rock detections using three-sigma Mahalanobis gating and updates per-obstacle Kalman trackers. Once positional variance drops below 0.025 square meters, the boulder elevation is stamped onto the active two point five D heightmap.", "audio_file": "assets/audio/sc4_s2.mp3", "audio_duration_sec": 18.82, "duration_sec": 19.67, "caption_split_sec": 10.79}, {"scene_id": "sc4_s3", "title": "Heightmap Derivatives to Unified Costmap", "visual_mode": "costmap_fusion", "components": ["terrain_mapper", "costmap_fuser", "dstar_planner"], "flows": [{"from": "terrain_mapper", "to": "costmap_fuser", "channel": "active_heightmap"}, {"from": "costmap_fuser", "to": "dstar_planner", "channel": "unified_costmap"}], "narration": "The costmap fuser denormalizes the heightmap back into physical meters, combining Sobel slope, Laplacian roughness, lethal step masks, and L2 inflation into a single occupancy grid. Publishing with Transient-Local QoS guarantees both D* Lite and MPPI receive the latest terrain map immediately.", "captions": ["Combines Sobel slope, Laplacian roughness, lethal cliffs, and L2 inflation.", "Publishes /unified_costmap with Transient-Local QoS to Nav2."], "source_refs": [{"file": "src/navstack/path-planning/globalPlanner/scripts/heightmap_to_costmap.py", "lines": "122-229", "snippet_key": "src/navstack/path-planning/globalPlanner/scripts/heightmap_to_costmap.py:122-229"}], "narration_spoken": "The costmap fuser denormalizes the heightmap back into physical meters, combining Sobel slope, Laplacian roughness, lethal step masks, and L2 inflation into a single occupancy grid. Publishing with Transient-Local Q O S guarantees both D-star Lite and M P P I receive the latest terrain map immediately.", "audio_file": "assets/audio/sc4_s3.mp3", "audio_duration_sec": 19.37, "duration_sec": 20.22, "caption_split_sec": 11.71}], "duration_sec": 62.5}, {"id": "sc_nav_init", "number": "S5", "title": "Navigation Initialization", "subtitle": "Lifecycle bringup → Gate 2 → D* Lite path → MPPI cmd_vel.", "scenes": [{"scene_id": "sc5_s1", "title": "Lifecycle Manager Autostart", "visual_mode": "bt_orchestration", "components": ["mission_gui", "bt_navigator", "dstar_planner", "mppi_controller"], "flows": [{"from": "mission_gui", "to": "bt_navigator", "channel": "gate_nav_ready"}, {"from": "bt_navigator", "to": "dstar_planner", "channel": "nav_to_pose_action"}], "narration": "During navigation bringup, the Nav2 lifecycle manager configures and activates the planner server, controller server, recovery behaviors, and BT Navigator in sequence. Once BT Navigator advertises the navigate-to-pose action server, Mission Control unlocks Readiness Gate 2.", "captions": ["Lifecycle Manager transitions Planner, Controller, and BT Navigator to Active.", "Advertising /navigate_to_pose unlocks Mission Control Readiness Gate 2."], "source_refs": [{"file": "src/navstack/navstack_nav2/launch/roar_nav2_only.launch.py", "lines": "272-290", "snippet_key": "src/navstack/navstack_nav2/launch/roar_nav2_only.launch.py:272-290"}], "narration_spoken": "During navigation bringup, the Nav 2 lifecycle manager configures and activates the planner server, controller server, recovery behaviors, and B T Navigator in sequence. Once B T Navigator advertises the navigate-to-pose action server, Mission Control unlocks Readiness Gate 2.", "audio_file": "assets/audio/sc5_s1.mp3", "audio_duration_sec": 17.76, "duration_sec": 18.61, "caption_split_sec": 10.85}, {"scene_id": "sc5_s2", "title": "Initial D* Lite Global Plan", "visual_mode": "dstar_wave", "components": ["costmap_fuser", "dstar_planner", "mppi_controller"], "flows": [{"from": "costmap_fuser", "to": "dstar_planner", "channel": "unified_costmap"}, {"from": "dstar_planner", "to": "mppi_controller", "channel": "global_plan"}], "narration": "When the first waypoint goal arrives, our D* Lite plugin builds a Dijkstra clearance field over unified-costmap and computes an obstacle-safe path from goal back to the rover. Three-pass smoothing refines the trajectory before publishing PoseStamped waypoints onto the global plan topic.", "captions": ["Builds Dijkstra clearance field and runs backward D* Lite search.", "Publishes 3-pass smoothed PoseStamped trajectory onto /plan."], "source_refs": [{"file": "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp", "lines": "261-312", "snippet_key": "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp:261-312"}], "narration_spoken": "When the first waypoint goal arrives, our D-star Lite plugin builds a Dijkstra clearance field over unified-costmap and computes an obstacle-safe path from goal back to the rover. Three-pass smoothing refines the trajectory before publishing PoseStamped waypoints onto the global plan topic.", "audio_file": "assets/audio/sc5_s2.mp3", "audio_duration_sec": 16.68, "duration_sec": 17.53, "caption_split_sec": 11.81}, {"scene_id": "sc5_s3", "title": "20 Hz MPPI Rollout Loop Begins", "visual_mode": "mppi_rollouts", "components": ["mppi_controller", "ros2_control", "rover_twin"], "flows": [{"from": "mppi_controller", "to": "ros2_control", "channel": "cmd_vel_stamped"}, {"from": "ros2_control", "to": "rover_twin", "channel": "joint_pulses"}], "narration": "Tracking that global plan, the MPPI controller samples two thousand noisy rollouts every fifty milliseconds across its rolling eight-by-eight-meter local costmap. Smoothed TwistStamped commands stream at 20 Hz into the six-wheel differential-drive controller to initiate motion.", "captions": ["20 Hz MPPI evaluates 2,000 rollouts over an 8×8m rolling local costmap.", "Streams smoothed TwistStamped commands to /diff_drive_controller/cmd_vel."], "source_refs": [{"file": "src/navstack/navstack_nav2/config/roar_nav2_sim.yaml", "lines": "65-106", "snippet_key": "src/navstack/navstack_nav2/config/roar_nav2_sim.yaml:65-106"}], "narration_spoken": "Tracking that global plan, the M P P I controller samples two thousand noisy rollouts every fifty milliseconds across its rolling eight-by-eight-meter local costmap. Smoothed TwistStamped commands stream at 20 hertz into the six-wheel differential-drive controller to initiate motion.", "audio_file": "assets/audio/sc5_s3.mp3", "audio_duration_sec": 16.2, "duration_sec": 17.05, "caption_split_sec": 11.21}], "duration_sec": 53.2}, {"id": "sc_wp_exec", "number": "S6", "title": "Waypoint Execution", "subtitle": "YAML coordinate sync → WP1..WP4 goals → Return Home (0,0).", "scenes": [{"scene_id": "sc6_s1", "title": "Metric Coordinate Sync", "visual_mode": "coord_injection", "components": ["mission_gui", "wp_follower", "referee_core"], "flows": [{"from": "mission_gui", "to": "wp_follower", "channel": "yaml_injection"}, {"from": "mission_gui", "to": "referee_core", "channel": "yaml_injection"}], "narration": "Prior to dispatch, Mission Control transforms the selected four-waypoint tour from heightmap grid cells into metric Marsyard coordinates. Writing identical target arrays into Nav2 YAML parameters and the referee input file guarantees zero coordinate mismatch during scoring.", "captions": ["Transforms selected 4-waypoint route from grid indices to metric meters.", "Synchronizes identical coordinates across Nav2 YAML and Referee inputs."], "source_refs": [{"file": "src/navigation/scripts/asu_roar_gui.py", "lines": "928-988", "snippet_key": "src/navigation/scripts/asu_roar_gui.py:928-988"}], "narration_spoken": "Prior to dispatch, Mission Control transforms the selected four-waypoint tour from heightmap grid cells into metric Marsyard coordinates. Writing identical target arrays into Nav 2 yam-ul parameters and the referee input file guarantees zero coordinate mismatch during scoring.", "audio_file": "assets/audio/sc6_s1.mp3", "audio_duration_sec": 16.32, "duration_sec": 17.17, "caption_split_sec": 8.41}, {"scene_id": "sc6_s2", "title": "Visiting WP1 through WP4", "visual_mode": "waypoint_sequence", "components": ["wp_follower", "bt_navigator", "dstar_planner"], "flows": [{"from": "wp_follower", "to": "bt_navigator", "channel": "nav_to_pose_action"}, {"from": "bt_navigator", "to": "dstar_planner", "channel": "global_plan"}], "narration": "The waypoint follower dispatches Waypoint 1 through Waypoint 4 one at a time over navigate-to-pose and awaits GoalStatus SUCCEEDED within the 0.45-meter goal tolerance. Along each leg, D* Lite incrementally repairs the global path whenever perception stamps newly revealed rocks.", "captions": ["Sequentially dispatches WP1..WP4 and awaits STATUS_SUCCEEDED (0.45m tol).", "D* Lite incrementally repairs paths around newly stamped boulders."], "source_refs": [{"file": "src/navstack/path-planning/globalPlanner/scripts/batch_waypoint_follower.py", "lines": "136-163", "snippet_key": "src/navstack/path-planning/globalPlanner/scripts/batch_waypoint_follower.py:136-163"}], "narration_spoken": "The waypoint follower dispatches Waypoint 1 through Waypoint 4 one at a time over navigate-to-pose and awaits GoalStatus SUCCEEDED within the 0.45-meter goal tolerance. Along each leg, D-star Lite incrementally repairs the global path whenever perception stamps newly revealed rocks.", "audio_file": "assets/audio/sc6_s2.mp3", "audio_duration_sec": 17.52, "duration_sec": 18.37, "caption_split_sec": 12.09}, {"scene_id": "sc6_s3", "title": "Return-to-Start & Clean Shutdown", "visual_mode": "return_home", "components": ["wp_follower", "rover_twin", "mission_gui"], "flows": [{"from": "wp_follower", "to": "rover_twin", "channel": "nav_to_pose_action"}, {"from": "rover_twin", "to": "mission_gui", "channel": "odom_tf"}], "narration": "Once Waypoint 4 succeeds, the follower automatically dispatches a fifth goal back to origin zero-zero to complete the competition loop. After settling at start and flushing run-summary artifacts, Mission Control tears down the simulation cleanly for the next run.", "captions": ["Dispatches fifth NavigateToPose goal back to Start (0, 0).", "Flushes run_summary.npy and triggers clean process-group teardown."], "source_refs": [{"file": "src/navigation/scripts/asu_roar_gui.py", "lines": "1210-1231", "snippet_key": "src/navigation/scripts/asu_roar_gui.py:1210-1231"}], "narration_spoken": "Once Waypoint 4 succeeds, the follower automatically dispatches a fifth goal back to origin zero-zero to complete the competition loop. After settling at start and flushing run-summary artifacts, Mission Control tears down the simulation cleanly for the next run.", "audio_file": "assets/audio/sc6_s3.mp3", "audio_duration_sec": 15.41, "duration_sec": 16.26, "caption_split_sec": 8.51}], "duration_sec": 51.8}, {"id": "sc_mission_eval", "number": "S7", "title": "Mission Evaluation", "subtitle": "Contact mesh check → settled stop math → 300-pt HTML report.", "scenes": [{"scene_id": "sc7_s1", "title": "Live Collision & Boundary Guard", "visual_mode": "pebble_vs_boulder", "components": ["gazebo_sim", "collision_monitor", "referee_core"], "flows": [{"from": "gazebo_sim", "to": "collision_monitor", "channel": "rover_contact"}, {"from": "collision_monitor", "to": "referee_core", "channel": "collision_flag"}], "narration": "Throughout the mission, the collision monitor filters seven link contact streams against obstacle metadata—ignoring safe pebble meshes five through nine while flagging solid rock hits. At 10 Hz, the referee core enforces instant KILL on collisions or boundary exits and TIMEOUT at twenty active minutes.", "captions": ["Ignores safe pebble meshes {5..9}; flags solid boulder contacts.", "10 Hz referee enforces instant KILL on impact/out-of-bounds or 20m TIMEOUT."], "source_refs": [{"file": "src/navigation/referee_engine/referee_engine/collision_monitor_node.py", "lines": "65-95", "snippet_key": "src/navigation/referee_engine/referee_engine/collision_monitor_node.py:65-95"}, {"file": "src/navigation/referee_engine/referee_engine/referee_core_node.py", "lines": "260-299", "snippet_key": "src/navigation/referee_engine/referee_engine/referee_core_node.py:260-299"}], "narration_spoken": "Throughout the mission, the collision monitor filters seven link contact streams against obstacle metadata—ignoring safe pebble meshes five through nine while flagging solid rock hits. At 10 hertz, the referee core enforces instant KILL on collisions or boundary exits and TIMEOUT at twenty active minutes.", "audio_file": "assets/audio/sc7_s1.mp3", "audio_duration_sec": 17.52, "duration_sec": 18.37, "caption_split_sec": 10.18}, {"scene_id": "sc7_s2", "title": "Waypoint Settling & 300-Point Scoring", "visual_mode": "edge_caliper", "components": ["ieskf_core", "referee_core", "report_gen"], "flows": [{"from": "ieskf_core", "to": "referee_core", "channel": "odom_tf"}, {"from": "referee_core", "to": "report_gen", "channel": "referee_score"}], "narration": "When the rover settles below 0.05 m/s inside a one-meter waypoint radius, the referee records chassis edge distance and evaluates the ERC precision formula. It sums waypoint accuracy, autonomous navigation bonuses, route adherence, and return-to-start credits up to 300 points.", "captions": ["Verifies settled stop (< 0.05 m/s within 1.0m) and computes d_edge score.", "Totals O/NAV-010..110 rubric items up to 300 maximum points."], "source_refs": [{"file": "src/navigation/referee_engine/referee_engine/waypoint_tracker.py", "lines": "140-194", "snippet_key": "src/navigation/referee_engine/referee_engine/waypoint_tracker.py:140-194"}, {"file": "src/navigation/referee_engine/referee_engine/score_calculator.py", "lines": "86-166", "snippet_key": "src/navigation/referee_engine/referee_engine/score_calculator.py:86-166"}], "narration_spoken": "When the rover settles below 0.05 meters per second inside a one-meter waypoint radius, the referee records chassis edge distance and evaluates the E R C precision formula. It sums waypoint accuracy, autonomous navigation bonuses, route adherence, and return-to-start credits up to 300 points.", "audio_file": "assets/audio/sc7_s2.mp3", "audio_duration_sec": 19.58, "duration_sec": 20.43, "caption_split_sec": 11.84}, {"scene_id": "sc7_s3", "title": "Live & Master HTML Report Compilation", "visual_mode": "html_dashboards", "components": ["referee_core", "report_gen", "mission_gui"], "flows": [{"from": "referee_core", "to": "report_gen", "channel": "referee_score"}, {"from": "report_gen", "to": "mission_gui", "channel": "referee_score"}], "narration": "Every score update refreshes a live ERC HTML scorecard on disk, and mission termination writes a timestamped final report alongside SLAM and perception benchmarks. Across batch campaigns, Mission Control aggregates every run summary into a master multi-world HTML dashboard.", "captions": ["Updates ERC_Report_Live.html in real time + writes final run scorecard.", "Aggregates SLAM, Perception, and ERC metrics into a Master Batch report."], "source_refs": [{"file": "src/navigation/referee_engine/referee_engine/report_generator_node.py", "lines": "31-45", "snippet_key": "src/navigation/referee_engine/referee_engine/report_generator_node.py:31-45"}, {"file": "src/navigation/scripts/asu_roar_gui.py", "lines": "1263-1358", "snippet_key": "src/navigation/scripts/asu_roar_gui.py:1263-1358"}], "narration_spoken": "Every score update refreshes a live E R C H T M L scorecard on disk, and mission termination writes a timestamped final report alongside slam and perception benchmarks. Across batch campaigns, Mission Control aggregates every run summary into a master multi-world H T M L dashboard.", "audio_file": "assets/audio/sc7_s3.mp3", "audio_duration_sec": 18.22, "duration_sec": 19.07, "caption_split_sec": 10.84}], "duration_sec": 57.9}], "components": {"rover_twin": {"id": "rover_twin", "name": "ROAR 6-Wheel Rover", "badge": "URDF · Rocker-Bogie", "category": "simulation", "one_sentence": "Six-wheel rocker-bogie Mars rover digital twin equipped with a ZED2i stereo camera, BNO055 IMU, 7 contact sensors, and an optional 6-DOF arm.", "package_name": "roar_simulation_full", "source_file": "src/roar2026/dev_environment/rover/roar_simulation_full/urdf/base/rover_simulation.urdf.xacro", "lines": "13-31", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/urdf/base/rover_simulation.urdf.xacro:13-31"}, "marsyard_gen": {"id": "marsyard_gen", "name": "Marsyard World Synthesis", "badge": "Offline Pipeline", "category": "simulation", "one_sentence": "Generates three ERC 2026 Marsyard worlds with 8, 50, and 90 rocks, ArUco landmarks, and 2.5D ground-truth heightmaps.", "package_name": "roar2026/navMission_setup", "source_file": "src/roar2026/navMission_setup/generate_worlds.py", "lines": "33-64", "snippet_key": "src/roar2026/navMission_setup/generate_worlds.py:33-64"}, "wp_sampler": {"id": "wp_sampler", "name": "Poisson Waypoint Generator", "badge": "300 Routes / World", "category": "simulation", "one_sentence": "Samples 300 obstacle-cleared 4-waypoint mission tours per world using Poisson-disk sampling and rover clearance masks.", "package_name": "roar2026/navMission_setup", "source_file": "src/roar2026/navMission_setup/waypoints_setup/wayPoint_generator/wp_generator.py", "lines": "29-62", "snippet_key": "src/roar2026/navMission_setup/waypoints_setup/wayPoint_generator/wp_generator.py:29-62"}, "gazebo_sim": {"id": "gazebo_sim", "name": "Gazebo Harmonic Server", "badge": "gz sim -s -r", "category": "simulation", "one_sentence": "Executes rigid-body Marsyard physics, 7 link contact sensors, 100 Hz BNO055 IMU, and 5 Hz ZED2i RGB-D rendering.", "package_name": "roar_simulation_full", "source_file": "src/roar2026/dev_environment/rover/roar_simulation_full/urdf/modules/rover_gazebo.xacro", "lines": "4-78", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/urdf/modules/rover_gazebo.xacro:4-78"}, "ros_gz_bridge": {"id": "ros_gz_bridge", "name": "ROS ↔ Gazebo Bridge", "badge": "parameter_bridge", "category": "simulation", "one_sentence": "Translates Gazebo Harmonic clock, IMU, camera, ground-truth pose, and 7 link contact streams into typed ROS 2 Jazzy topics.", "package_name": "ros_gz_bridge (launched by roar_simulation_full)", "source_file": "src/roar2026/dev_environment/rover/roar_simulation_full/launch/basic_rover.launch.py", "lines": "166-199", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/launch/basic_rover.launch.py:166-199"}, "ros2_control": {"id": "ros2_control", "name": "6-Wheel DiffDrive & Arm Control", "badge": "controller_manager", "category": "simulation", "one_sentence": "Converts TwistStamped velocity commands into left and right 6-wheel angular speeds while disabling raw odom TF to avoid conflicting with IESKF.", "package_name": "roar_simulation_full", "source_file": "src/roar2026/dev_environment/rover/roar_simulation_full/configs/diff_controller.yaml", "lines": "18-43", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/configs/diff_controller.yaml:18-43"}, "zed_degradation": {"id": "zed_degradation", "name": "ZED2i Mars Degradation Node", "badge": "Dust · Glare · Z²", "category": "simulation", "one_sentence": "Projects the 3D sun into camera pixels to inject Mars dust, solar washout, quadratic stereo depth noise (0.003·Z²), and unprojects XYZRGB PointCloud2.", "package_name": "roar_simulation_full", "source_file": "src/roar2026/dev_environment/rover/roar_simulation_full/src/zed_degradation_node.py", "lines": "255-337", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/src/zed_degradation_node.py:255-337"}, "encoder_sim": {"id": "encoder_sim", "name": "Wheel Encoder Simulator", "badge": "201,554 pulses/rev", "category": "simulation", "one_sentence": "Quantizes continuous middle-wheel joint angles from radians into integer hardware encoder pulse counts on /joint_states_updated.", "package_name": "roar_simulation_full", "source_file": "src/roar2026/dev_environment/rover/roar_simulation_full/src/encoder_sim_node.py", "lines": "25-76", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/src/encoder_sim_node.py:25-76"}, "collision_alarm": {"id": "collision_alarm", "name": "Sim Collision Alarm Node", "badge": "/collision_alarm", "category": "simulation", "one_sentence": "Filters benign Marsyard ground contacts out of /rover_contact and raises a boolean alarm only when the rover touches non-terrain objects.", "package_name": "roar_simulation_full", "source_file": "src/roar2026/dev_environment/rover/roar_simulation_full/src/collision_alarm_node.py", "lines": "20-50", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/src/collision_alarm_node.py:20-50"}, "lidar_cluster": {"id": "lidar_cluster", "name": "3D Point-Cloud Cluster Node", "badge": "Open3D + CUDA", "category": "perception", "one_sentence": "Runs GPU ROI cropping, 6cm voxel downsampling, SOR/ROR outlier removal, slope-aware RANSAC, PCA roughness filtering, and DBSCAN rock clustering.", "package_name": "perception_module", "source_file": "src/navstack/perception/perception_module/lidar_cluster_node.py", "lines": "148-294", "snippet_key": "src/navstack/perception/perception_module/lidar_cluster_node.py:148-294"}, "ransac_roughness": {"id": "ransac_roughness", "name": "Slope-Aware RANSAC & Roughness", "badge": "Tilt ≤ 45° · PCA", "category": "perception", "one_sentence": "Strips flat ground and traversable ramps up to 45° while preserving steep boulder faces and high-curvature rock edges.", "package_name": "perception_module", "source_file": "src/navstack/perception/perception_module/lidar_cluster_node.py", "lines": "336-402", "snippet_key": "src/navstack/perception/perception_module/lidar_cluster_node.py:336-402"}, "dbscan_gate": {"id": "dbscan_gate", "name": "DBSCAN & 3D Shape Gate", "badge": "eps=0.25m · BBox", "category": "perception", "one_sentence": "Groups non-ground rock points with DBSCAN and rejects flat ramp remnants using bounding-box dimensions and depth-to-height aspect ratios.", "package_name": "perception_module", "source_file": "src/navstack/perception/perception_module/lidar_cluster_node.py", "lines": "220-293", "snippet_key": "src/navstack/perception/perception_module/lidar_cluster_node.py:220-293"}, "obstacle_pub": {"id": "obstacle_pub", "name": "Persistent Obstacle Publisher", "badge": "TF2 + EMA Memory", "category": "perception", "one_sentence": "Transforms camera-frame 3D rock detections into the odom frame via TF2, merges sightings with EMA smoothing, and prunes stale obstacles after 4s.", "package_name": "perception_module", "source_file": "src/navstack/perception/perception_module/obstacle_publisher_node.py", "lines": "83-201", "snippet_key": "src/navstack/perception/perception_module/obstacle_publisher_node.py:83-201"}, "aruco_detector": {"id": "aruco_detector", "name": "ArUco 6-DOF Detector Node", "badge": "SolvePnP IPPE", "category": "perception", "one_sentence": "Auto-detects ArUco and AprilTag dictionaries in RGB frames and computes 6-DOF marker poses using OpenCV's SOLVEPNP_IPPE_SQUARE.", "package_name": "perception_module", "source_file": "src/navstack/perception/perception_module/aruco_detector_node.py", "lines": "76-117", "snippet_key": "src/navstack/perception/perception_module/aruco_detector_node.py:76-117"}, "gt_bridge": {"id": "gt_bridge", "name": "Ground-Truth Pose Bridge", "badge": "Sim ZED Pose", "category": "localization", "one_sentence": "Converts Gazebo's 50 Hz ground-truth rover TF into PoseWithCovarianceStamped on /zed2i/zed_node/pose_with_covariance for simulation fusion.", "package_name": "roar_localization", "source_file": "src/navstack/slam/roar_localization/src/ground_truth_bridge.cpp", "lines": "52-79", "snippet_key": "src/navstack/slam/roar_localization/src/ground_truth_bridge.cpp:52-79"}, "wio_module": {"id": "wio_module", "name": "Wheel-Inertial Odometry (WIO)", "badge": "100 Hz Dead-Reckoning", "category": "localization", "one_sentence": "Combines quantized left/right encoder pulse deltas with BNO055 pitch and midpoint yaw to compute 3D dead-reckoning displacements and wheel speeds.", "package_name": "roar_localization", "source_file": "src/navstack/slam/roar_localization/src/wio.cpp", "lines": "89-155", "snippet_key": "src/navstack/slam/roar_localization/src/wio.cpp:89-155"}, "ieskf_core": {"id": "ieskf_core", "name": "12D IESKF State Estimator", "badge": "C++17 Eigen Filter", "category": "localization", "one_sentence": "Tracks 12 error-state variables [p, v, b_a, b_w] at 100 Hz using iterated Gauss-Newton updates and Joseph-form covariance stabilization.", "package_name": "roar_localization", "source_file": "src/navstack/slam/roar_localization/include/roar_localization/ieskf.hpp", "lines": "210-255", "snippet_key": "src/navstack/slam/roar_localization/include/roar_localization/ieskf.hpp:210-255"}, "fuzzy_fis": {"id": "fuzzy_fis", "name": "Sugeno WO-FIS & VO-FIS", "badge": "Adaptive Noise k_Q / k_V", "category": "localization", "one_sentence": "Zero-order Sugeno fuzzy inference systems that inflate process noise k_Q on wheel slip and inflate visual noise k_V when camera tracking jumps.", "package_name": "roar_localization", "source_file": "src/navstack/slam/roar_localization/include/roar_localization/fuzzy_utils.hpp", "lines": "304-331", "snippet_key": "src/navstack/slam/roar_localization/include/roar_localization/fuzzy_utils.hpp:304-331"}, "zupt_detector": {"id": "zupt_detector", "name": "Zero-Velocity Update (ZUPT)", "badge": "4-Gate Drift Reset", "category": "localization", "one_sentence": "Detects 0.5s stationary pauses across encoders, gyro, and accel variance to inject v=[0,0,0], collapsing velocity drift and accelerometer bias.", "package_name": "roar_localization", "source_file": "src/navstack/slam/roar_localization/include/roar_localization/zupt.hpp", "lines": "125-164", "snippet_key": "src/navstack/slam/roar_localization/include/roar_localization/zupt.hpp:125-164"}, "terrain_mapper": {"id": "terrain_mapper", "name": "2.5D Kalman Terrain Mapper", "badge": "Mahalanobis + Kalman", "category": "mapping", "one_sentence": "Loads the static Marsyard heightmap and stamps live 3D rock detections only after terrain-consistency gating and Kalman variance convergence.", "package_name": "terrain_mapping", "source_file": "src/navstack/slam/terrain_mapping/terrain_mapping/terrain_mapping_node.py", "lines": "308-398", "snippet_key": "src/navstack/slam/terrain_mapping/terrain_mapping/terrain_mapping_node.py:308-398"}, "costmap_fuser": {"id": "costmap_fuser", "name": "Unified Costmap Fuser", "badge": "Sobel · Laplacian · L2", "category": "mapping", "one_sentence": "Derives 0–99 slope and roughness costs, marks cliffs >0.45m as lethal (100), and applies L2 distance-transform safety inflation onto /unified_costmap.", "package_name": "dstar_navigation", "source_file": "src/navstack/path-planning/globalPlanner/scripts/heightmap_to_costmap.py", "lines": "144-216", "snippet_key": "src/navstack/path-planning/globalPlanner/scripts/heightmap_to_costmap.py:144-216"}, "bt_navigator": {"id": "bt_navigator", "name": "Nav2 BT Navigator & Lifecycle", "badge": "/navigate_to_pose", "category": "navigation", "one_sentence": "Autostarts the Nav2 lifecycle stack and ticks the replanning-and-recovery Behavior Tree to coordinate global D* Lite planning with local MPPI control.", "package_name": "navstack_nav2", "source_file": "src/navstack/navstack_nav2/launch/roar_nav2_only.launch.py", "lines": "263-290", "snippet_key": "src/navstack/navstack_nav2/launch/roar_nav2_only.launch.py:263-290"}, "dstar_planner": {"id": "dstar_planner", "name": "D* Lite Global Planner", "badge": "Incremental C++ Plugin", "category": "navigation", "one_sentence": "Searches backward from BFS-snapped goals using Dijkstra obstacle clearance + squared terrain cost, repairing changed cells incrementally and smoothing paths.", "package_name": "dstar_navigation", "source_file": "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp", "lines": "265-312", "snippet_key": "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp:265-312"}, "mppi_controller": {"id": "mppi_controller", "name": "MPPI Trajectory Controller", "badge": "2,000 Rollouts @ 20 Hz", "category": "navigation", "one_sentence": "Samples 2,000 noisy 2.8s DiffDrive trajectories at 20 Hz, scores them across 8 critics on an 8×8m rolling costmap, and smooths TwistStamped outputs.", "package_name": "nav2_mppi_controller (configured in navstack_nav2)", "source_file": "src/navstack/navstack_nav2/config/roar_nav2_sim.yaml", "lines": "82-156", "snippet_key": "src/navstack/navstack_nav2/config/roar_nav2_sim.yaml:82-156"}, "mission_gui": {"id": "mission_gui", "name": "ASU ROAR Mission Control", "badge": "Readiness Orchestrator", "category": "mission", "one_sentence": "PyQt5 mission orchestrator that previews Marsyard maps, injects metric waypoints into YAML, and gates Sim → Nav2 → Referee → Follower startup.", "package_name": "navigation/scripts", "source_file": "src/navigation/scripts/asu_roar_gui.py", "lines": "1124-1223", "snippet_key": "src/navigation/scripts/asu_roar_gui.py:1124-1223"}, "wp_follower": {"id": "wp_follower", "name": "ERC Waypoint Action Client", "badge": "WP1..WP4 → Start(0,0)", "category": "mission", "one_sentence": "Dispatches sequential NavigateToPose goals across four mission waypoints plus return-to-start (0,0) in either autonomous batch or interactive judge mode.", "package_name": "dstar_navigation", "source_file": "src/navstack/path-planning/globalPlanner/scripts/batch_waypoint_follower.py", "lines": "26-68", "snippet_key": "src/navstack/path-planning/globalPlanner/scripts/batch_waypoint_follower.py:26-68"}, "collision_monitor": {"id": "collision_monitor", "name": "Mesh-Aware Collision Monitor", "badge": "Safe Pebbles {5..9}", "category": "evaluation", "one_sentence": "Monitors 7 Gazebo contact topics against obstacle_data.npy, ignoring safe pebble meshes {5..9} while flagging solid boulder hits immediately.", "package_name": "referee_engine", "source_file": "src/navigation/referee_engine/referee_engine/collision_monitor_node.py", "lines": "35-95", "snippet_key": "src/navigation/referee_engine/referee_engine/collision_monitor_node.py:35-95"}, "referee_core": {"id": "referee_core", "name": "ERC Automated Referee Core", "badge": "10 Hz Rules & 300 Pts", "category": "evaluation", "one_sentence": "Evaluates critical KILL/TIMEOUT rules, verifies settled waypoint stops (<0.05 m/s within 1.0m), and computes official 300-point ERC Traverse scores.", "package_name": "referee_engine", "source_file": "src/navigation/referee_engine/referee_engine/score_calculator.py", "lines": "23-166", "snippet_key": "src/navigation/referee_engine/referee_engine/score_calculator.py:23-166"}, "report_gen": {"id": "report_gen", "name": "HTML Report & Benchmark Suite", "badge": "ERC · SLAM · Perception", "category": "evaluation", "one_sentence": "Generates live and final ERC HTML scorecards alongside SLAM trajectory drift, 3D IoU perception dashboards, and multi-world batch summaries.", "package_name": "referee_engine", "source_file": "src/navigation/referee_engine/referee_engine/report_generator_node.py", "lines": "31-45", "snippet_key": "src/navigation/referee_engine/referee_engine/report_generator_node.py:31-45"}}, "channels": {"sense_stream": {"id": "sense_stream", "label": "/zed2i/* + /bno055/data", "kind": "ROS 2 Sensor Streams", "msg_type": "sensor_msgs/Image, PointCloud2, Imu, JointState", "rate_qos": "5 Hz Camera · 100 Hz IMU · 50 Hz Encoders", "one_sentence": "Raw and degraded Mars sensor measurements flowing from Gazebo and hardware adapters into perception and localization.", "source_file": "src/roar2026/dev_environment/rover/roar_simulation_full/launch/basic_rover.launch.py", "lines": "166-199", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/launch/basic_rover.launch.py:166-199"}, "gate_sim_ready": {"id": "gate_sim_ready", "label": "/diff_drive_controller/odom", "kind": "Readiness Gate 1", "msg_type": "nav_msgs/msg/Odometry", "rate_qos": "50 Hz · Polled every 1.5s (90s timeout)", "one_sentence": "Mission Control waits until /diff_drive_controller/odom appears in `ros2 topic list` before launching Nav2 and SLAM.", "source_file": "src/navigation/scripts/asu_roar_gui.py", "lines": "1451-1457", "snippet_key": "src/navigation/scripts/asu_roar_gui.py:1451-1457"}, "gate_nav_ready": {"id": "gate_nav_ready", "label": "/navigate_to_pose (Ready)", "kind": "Readiness Gate 2", "msg_type": "nav2_msgs/action/NavigateToPose", "rate_qos": "Action Server · Polled every 1.5s (120s timeout)", "one_sentence": "Mission Control confirms /navigate_to_pose is active in `ros2 action list` before starting the Referee and Waypoint Follower.", "source_file": "src/navigation/scripts/asu_roar_gui.py", "lines": "1166-1185", "snippet_key": "src/navigation/scripts/asu_roar_gui.py:1166-1185"}, "offline_bake": {"id": "offline_bake", "label": "heightmap.npz + obstacle_data.npy", "kind": "Offline Asset Pipeline", "msg_type": "NumPy .npz / .npy + SDF .world", "rate_qos": "Pre-mission synthesis (Worlds 1..3)", "one_sentence": "Bakes collision-mesh elevation grids, rock metadata, ArUco coordinates, and 300 safe waypoint tours per world.", "source_file": "src/roar2026/navMission_setup/master_pipeline.sh", "lines": "13-61", "snippet_key": "src/roar2026/navMission_setup/master_pipeline.sh:13-61"}, "spawn_chain": {"id": "spawn_chain", "label": "spawn_entity → spawners", "kind": "ROS 2 Launch Event Chain", "msg_type": "OnProcessExit + TimerAction(12.0s)", "rate_qos": "Sequential Controller Activation", "one_sentence": "Spawns roar_rover in Gazebo, waits 12s, then chains joint_state_broadcaster → diff_drive_controller → arm_controller.", "source_file": "src/roar2026/dev_environment/rover/roar_simulation_full/launch/basic_rover.launch.py", "lines": "281-306", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/launch/basic_rover.launch.py:281-306"}, "gz_bridge_bus": {"id": "gz_bridge_bus", "label": "gz.msgs ↔ ROS 2 Topics", "kind": "ROS ↔ Gazebo Bridge", "msg_type": "Clock, Imu, Image, CameraInfo, TFMessage, Contacts", "rate_qos": "5–100 Hz · Bidirectional Bridge", "one_sentence": "Maps internal Gazebo transport topics into ROS 2 topics, remapping all 7 contact sensors onto /rover_contact and pose onto /world/rover_world/pose/info.", "source_file": "src/roar2026/dev_environment/rover/roar_simulation_full/launch/basic_rover.launch.py", "lines": "166-199", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/launch/basic_rover.launch.py:166-199"}, "raw_camera": {"id": "raw_camera", "label": "/zed2i/image_raw + /zed2i/depth", "kind": "ROS 2 Topic", "msg_type": "sensor_msgs/msg/Image (bgr8 & 32FC1)", "rate_qos": "5 Hz · SENSOR_DATA (Best Effort)", "one_sentence": "Raw 640×360 RGB and 32-bit float depth images rendered by Gazebo's ZED2i camera sensor before atmospheric degradation.", "source_file": "src/roar2026/dev_environment/rover/roar_simulation_full/src/zed_degradation_node.py", "lines": "89-106", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/src/zed_degradation_node.py:89-106"}, "points_updated": {"id": "points_updated", "label": "/zed2i/points_updated", "kind": "ROS 2 Topic", "msg_type": "sensor_msgs/msg/PointCloud2 (XYZRGB)", "rate_qos": "5 Hz · RELIABLE pub → BEST_EFFORT sub", "one_sentence": "Degraded 3D XYZRGB stereo point cloud containing Mars dust dropouts, solar glare NaN holes, and 0.003·Z² depth noise.", "source_file": "src/roar2026/dev_environment/rover/roar_simulation_full/src/zed_degradation_node.py", "lines": "300-337", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/src/zed_degradation_node.py:300-337"}, "joint_pulses": {"id": "joint_pulses", "label": "/joint_states_updated", "kind": "ROS 2 Topic", "msg_type": "sensor_msgs/msg/JointState", "rate_qos": "50 Hz · RELIABLE", "one_sentence": "Quantized integer encoder pulse counts (201,554 pulses/rev) for wheel_lhs_mid_joint and wheel_rhs_mid_joint.", "source_file": "src/roar2026/dev_environment/rover/roar_simulation_full/src/encoder_sim_node.py", "lines": "50-75", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/src/encoder_sim_node.py:50-75"}, "rover_contact": {"id": "rover_contact", "label": "/rover_contact", "kind": "ROS 2 Topic", "msg_type": "ros_gz_interfaces/msg/Contacts", "rate_qos": "50 Hz · 7 Link Contact Sensors", "one_sentence": " physics collision pairs reported by Gazebo across base_footprint and all six rocker-bogie wheels.", "source_file": "src/roar2026/dev_environment/rover/roar_simulation_full/src/collision_alarm_node.py", "lines": "20-49", "snippet_key": "src/roar2026/dev_environment/rover/roar_simulation_full/src/collision_alarm_node.py:20-49"}, "points_filtered": {"id": "points_filtered", "label": "/lidar/points_filtered", "kind": "ROS 2 Topic", "msg_type": "sensor_msgs/msg/PointCloud2", "rate_qos": "5 Hz · RELIABLE", "one_sentence": "Denoised 3D point cloud after <6.0m GPU ROI crop, 6cm voxel downsampling, Statistical Outlier Removal, and Radius Outlier Removal.", "source_file": "src/navstack/perception/perception_module/lidar_cluster_node.py", "lines": "152-203", "snippet_key": "src/navstack/perception/perception_module/lidar_cluster_node.py:152-203"}, "points_no_ground": {"id": "points_no_ground", "label": "/lidar/points_no_ground", "kind": "ROS 2 Topic", "msg_type": "sensor_msgs/msg/PointCloud2", "rate_qos": "5 Hz · RELIABLE", "one_sentence": "Obstacle-only point cloud remaining after slope-aware RANSAC strips ground/ramps (≤45°) and PCA normal variance removes smooth slopes.", "source_file": "src/navstack/perception/perception_module/lidar_cluster_node.py", "lines": "205-218", "snippet_key": "src/navstack/perception/perception_module/lidar_cluster_node.py:205-218"}, "detections_obstacles": {"id": "detections_obstacles", "label": "/detections/obstacles", "kind": "ROS 2 Topic", "msg_type": "active_mapping_msgs/msg/ObstacleDetectionArray", "rate_qos": "5 Hz · RELIABLE", "one_sentence": "Validated 3D rock centroids and bounding-box dimensions sent from DBSCAN + Shape Gate into the 2.5D Kalman Terrain Mapper.", "source_file": "src/navstack/perception/perception_module/lidar_cluster_node.py", "lines": "281-293", "snippet_key": "src/navstack/perception/perception_module/lidar_cluster_node.py:281-293"}, "lidar_clusters": {"id": "lidar_clusters", "label": "/detection/lidar_clusters", "kind": "ROS 2 Topic", "msg_type": "vision_msgs/msg/Detection3DArray", "rate_qos": "5 Hz · RELIABLE", "one_sentence": "3D bounding-box detections consumed by obstacle_publisher_node and the perception IoU benchmark.", "source_file": "src/navstack/perception/perception_module/obstacle_publisher_node.py", "lines": "53-55", "snippet_key": "src/navstack/perception/perception_module/obstacle_publisher_node.py:53-55"}, "planning_obstacles": {"id": "planning_obstacles", "label": "/planning/obstacles", "kind": "ROS 2 Topic", "msg_type": "vision_msgs/msg/Detection3DArray", "rate_qos": "5 Hz · EMA α=0.35 · 4s expiry", "one_sentence": "Persistent world-frame obstacle map maintained via TF2 transforms and exponential moving-average position smoothing.", "source_file": "src/navstack/perception/perception_module/obstacle_publisher_node.py", "lines": "204-223", "snippet_key": "src/navstack/perception/perception_module/obstacle_publisher_node.py:204-223"}, "rgb_updated": {"id": "rgb_updated", "label": "/zed2i/image_raw_updated", "kind": "ROS 2 Topic", "msg_type": "sensor_msgs/msg/Image (bgr8)", "rate_qos": "5 Hz · RELIABLE", "one_sentence": "Atmosphere-degraded RGB camera stream scanned by aruco_detector_node for square fiducial markers.", "source_file": "src/navstack/perception/perception_module/aruco_detector_node.py", "lines": "152-167", "snippet_key": "src/navstack/perception/perception_module/aruco_detector_node.py:152-167"}, "aruco_detections": {"id": "aruco_detections", "label": "/aruco/detections", "kind": "ROS 2 Topic", "msg_type": "roar_msgs/msg/ArucoDetectionArray", "rate_qos": "5 Hz · RELIABLE", "one_sentence": "6-DOF marker poses in the camera optical frame consumed by ieskf_node::arucoCallback for absolute landmark drift correction.", "source_file": "src/navstack/slam/roar_localization/src/ieskf_node.cpp", "lines": "421-474", "snippet_key": "src/navstack/slam/roar_localization/src/ieskf_node.cpp:421-474"}, "imu_data": {"id": "imu_data", "label": "/bno055/data", "kind": "ROS 2 Topic", "msg_type": "sensor_msgs/msg/Imu", "rate_qos": "100 Hz · Remapped from /imu/data", "one_sentence": "100 Hz BNO055 NDOF quaternion, angular velocity, and linear acceleration (rotated -90° yaw in ieskf_node to align base_link with base_footprint).", "source_file": "src/navstack/slam/roar_localization/src/ieskf_node.cpp", "lines": "258-294", "snippet_key": "src/navstack/slam/roar_localization/src/ieskf_node.cpp:258-294"}, "zed_pose_cov": {"id": "zed_pose_cov", "label": "/zed2i/zed_node/pose_with_covariance", "kind": "ROS 2 Topic", "msg_type": "geometry_msgs/msg/PoseWithCovarianceStamped", "rate_qos": "50 Hz Sim / 30 Hz Real · RELIABLE", "one_sentence": "Visual pose observation blended with wheel odometry in WVO and weighted by Sugeno VO-FIS before updating the 12D IESKF.", "source_file": "src/navstack/slam/roar_localization/src/ieskf_node.cpp", "lines": "380-416", "snippet_key": "src/navstack/slam/roar_localization/src/ieskf_node.cpp:380-416"}, "odom_tf": {"id": "odom_tf", "label": "/odom + TF (odom → base_footprint)", "kind": "ROS 2 Topic & Dynamic TF", "msg_type": "nav_msgs/msg/Odometry + TransformStamped", "rate_qos": "100 Hz · RELIABLE + Static map→odom", "one_sentence": "Fused 100 Hz rover pose, body-frame velocity, and dynamic TF tree broadcast by ieskf_node to Nav2, Mapping, Waypoint Follower, and Referee.", "source_file": "src/navstack/slam/roar_localization/src/ieskf_node.cpp", "lines": "479-546", "snippet_key": "src/navstack/slam/roar_localization/src/ieskf_node.cpp:479-546"}, "active_heightmap": {"id": "active_heightmap", "label": "/active_map/heightmap + range", "kind": "ROS 2 Topic Pair", "msg_type": "nav_msgs/OccupancyGrid + Float32MultiArray", "rate_qos": "2 Hz · TRANSIENT_LOCAL", "one_sentence": "Normalized 0–100 elevation grid plus [h_min, h_range] physical scale combining static Marsyard terrain with Kalman-verified boulders.", "source_file": "src/navstack/slam/terrain_mapping/terrain_mapping/terrain_mapping_node.py", "lines": "520-553", "snippet_key": "src/navstack/slam/terrain_mapping/terrain_mapping/terrain_mapping_node.py:520-553"}, "unified_costmap": {"id": "unified_costmap", "label": "/unified_costmap", "kind": "ROS 2 Topic", "msg_type": "nav_msgs/msg/OccupancyGrid", "rate_qos": "1 Hz · TRANSIENT_LOCAL", "one_sentence": "Single traversability grid encoding free space (0), slope/roughness/inflation cost (1–99), lethal cliffs/rocks (100), and unknown (-1).", "source_file": "src/navstack/path-planning/globalPlanner/scripts/heightmap_to_costmap.py", "lines": "196-229", "snippet_key": "src/navstack/path-planning/globalPlanner/scripts/heightmap_to_costmap.py:196-229"}, "global_plan": {"id": "global_plan", "label": "/plan", "kind": "ROS 2 Topic", "msg_type": "nav_msgs/msg/Path", "rate_qos": "1 Hz / On-Change · RELIABLE", "one_sentence": "3-pass smoothed global PoseStamped path computed by DStarPlanner and tracked by MPPIController.", "source_file": "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp", "lines": "453-461", "snippet_key": "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp:453-461"}, "cmd_vel_stamped": {"id": "cmd_vel_stamped", "label": "/diff_drive_controller/cmd_vel", "kind": "ROS 2 Topic", "msg_type": "geometry_msgs/msg/TwistStamped", "rate_qos": "20 Hz · Remapped from /cmd_vel", "one_sentence": "Savitzky-Golay-smoothed linear and angular velocity commands sent at 20 Hz from MPPIController to the 6-wheel DiffDriveController.", "source_file": "src/navstack/navstack_nav2/launch/roar_nav2_only.launch.py", "lines": "241-248", "snippet_key": "src/navstack/navstack_nav2/launch/roar_nav2_only.launch.py:241-248"}, "yaml_injection": {"id": "yaml_injection", "label": "waypoints: [...] + wp_gui.npy", "kind": "Mission Config Sync", "msg_type": "YAML + NumPy Mission Assets", "rate_qos": "Pre-Launch Injection", "one_sentence": "Converts selected grid (col, row) waypoints into metric (x, y) meters and writes them into both roar_nav2_sim.yaml and referee_engine/inputs/.", "source_file": "src/navigation/scripts/asu_roar_gui.py", "lines": "967-1008", "snippet_key": "src/navigation/scripts/asu_roar_gui.py:967-1008"}, "nav_to_pose_action": {"id": "nav_to_pose_action", "label": "/navigate_to_pose", "kind": "ROS 2 Action", "msg_type": "nav2_msgs/action/NavigateToPose", "rate_qos": "Sequential Goal → Feedback → Result (0.45m tol)", "one_sentence": "Action interface sending each mission waypoint (WP1..WP4 and Start 0,0) to bt_navigator and awaiting GoalStatus.STATUS_SUCCEEDED.", "source_file": "src/navstack/path-planning/globalPlanner/scripts/batch_waypoint_follower.py", "lines": "26-68", "snippet_key": "src/navstack/path-planning/globalPlanner/scripts/batch_waypoint_follower.py:26-68"}, "collision_flag": {"id": "collision_flag", "label": "/rover/collision_flag", "kind": "ROS 2 Topic", "msg_type": "std_msgs/msg/Bool", "rate_qos": "Event-Driven + 2 Hz Reset · RELIABLE", "one_sentence": "Fatal collision signal published when any of the 7 rover links contacts a rock outside the safe pebble mesh set {5, 6, 7, 8, 9}.", "source_file": "src/navigation/referee_engine/referee_engine/collision_monitor_node.py", "lines": "65-95", "snippet_key": "src/navigation/referee_engine/referee_engine/collision_monitor_node.py:65-95"}, "referee_score": {"id": "referee_score", "label": "/referee/score + run_summary.npy", "kind": "ROS 2 Topic & Summary Artifact", "msg_type": "std_msgs/msg/String (JSON) + NumPy Dict", "rate_qos": "10 Hz Live Evaluation", "one_sentence": "Streams the live 300-point ERC rule breakdown (O/NAV-010..110), terminal status (RUNNING/SUCCESS/KILL/TIMEOUT), and writes HTML scorecards.", "source_file": "src/navigation/referee_engine/referee_engine/referee_core_node.py", "lines": "276-308", "snippet_key": "src/navigation/referee_engine/referee_engine/referee_core_node.py:276-308"}}, "code_insights": {"aruco_import_mismatch": {"id": "aruco_import_mismatch", "badge": "Code Insight · Verified Runtime Impact", "title": "ArUco Message Import Mismatch (Line 40)", "summary": "aruco_detector_node.py imports ArucoDetection & ArucoDetectionArray from active_mapping_msgs.msg, whereas those IDL interfaces are compiled inside roar_msgs.", "runtime_impact": ["Process Isolation: perception.launch.py spawns aruco_detector_node as a separate OS process without an OnProcessExit shutdown hook, so lidar_cluster_node and obstacle_publisher_node keep running normally.", "Topic Impact: aruco_detector_node exits at startup with ImportError, leaving /aruco/detections at 0 messages (diag_aruco_received_ = 0 in ieskf_node).", "Why Missions Still Succeed in Sim: roar_nav2_only.launch.py runs ground_truth_bridge → /zed2i/zed_node/pose_with_covariance (50 Hz) alongside 100 Hz WIO and ZUPT, sustaining accurate /odom without ArUco resets."], "source_file": "src/navstack/perception/perception_module/aruco_detector_node.py", "lines": "35-43", "secondary_file": "src/navstack/slam/roar_msgs/CMakeLists.txt", "secondary_lines": "9-14", "snippet_key": "src/navstack/perception/perception_module/aruco_detector_node.py:35-43", "secondary_snippet_key": "src/navstack/slam/roar_msgs/CMakeLists.txt:9-14"}}, "snippets": {"src/roar2026/dev_environment/rover/roar_simulation_full/urdf/base/rover_simulation.urdf.xacro:13-31": {"file": "src/roar2026/dev_environment/rover/roar_simulation_full/urdf/base/rover_simulation.urdf.xacro", "lines": "13-31", "start_line": 13, "end_line": 31, "language": "xacro", "code": "  <xacro:rover_base />\n  <xacro:robotic_arm prefix=\"arm_\" parent_link=\"arm_mount_point\">\n    <origin xyz=\"0.0 0 0\" rpy=\"0 0 0\"/>\n  </xacro:robotic_arm>\n\n  <xacro:depth_camera name=\"zed2i\" parent_link=\"base_link\">\n    <!-- Rover forward is +Y, so we yaw 90 deg (pi/2) to make camera +X point forward -->\n    <origin xyz=\"0.0 0.35 0.25\" rpy=\"0 0 1.5707963267949\" />\n  </xacro:depth_camera>\n  <xacro:depth_camera_gazebo name=\"zed2i\" />\n\n  <xacro:bno055_imu name=\"bno055\" parent_link=\"base_link\">\n     <origin xyz=\"0 0 0.1\" rpy=\"0 0 0\"/>\n  </xacro:bno055_imu>\n  <xacro:bno055_imu_gazebo name=\"bno055\" />\n\n  <xacro:rover_gazebo controllers_yaml=\"$(find roar_simulation_full)/configs/diff_controller.yaml\"/>\n  <xacro:arm_gazebo prefix=\"arm_\" />\n"}, "src/roar2026/navMission_setup/generate_worlds.py:33-64": {"file": "src/roar2026/navMission_setup/generate_worlds.py", "lines": "33-64", "start_line": 33, "end_line": 64, "language": "py", "code": "WORLDS = [\n    {\n        \"name\":             \"world_1\",\n        \"label\":            \"LOW density\",\n        \"density\":          0.005,   # ~7 rocks  across ~1456 m²\n        \"num_rocks\":        8,\n        \"collidable_ratio\": 0.50,    # 50 % solid\n        \"heightmap_resolution\": 0.25,\n        \"gradient_scale\":   150.0,\n        \"stability_scale\":  90.0,\n    },\n    {\n        \"name\":             \"world_2\",\n        \"label\":            \"MODERATE density\",\n        \"density\":          0.035,   # ~51 rocks  across ~1456 m²\n        \"num_rocks\":        50,\n        \"collidable_ratio\": 0.60,    # 60 % solid\n        \"heightmap_resolution\": 0.25,\n        \"gradient_scale\":   150.0,\n        \"stability_scale\":  90.0,\n    },\n    {\n        \"name\":             \"world_3\",\n        \"label\":            \"HIGH density\",\n        \"density\":          0.075,   # ~109 rocks across ~1456 m²\n        \"num_rocks\":        90,\n        \"collidable_ratio\": 0.70,    # 70 % solid\n        \"heightmap_resolution\": 0.25,\n        \"gradient_scale\":   150.0,\n        \"stability_scale\":  90.0,\n    },\n]"}, "src/roar2026/navMission_setup/waypoints_setup/wayPoint_generator/wp_generator.py:29-62": {"file": "src/roar2026/navMission_setup/waypoints_setup/wayPoint_generator/wp_generator.py", "lines": "29-62", "start_line": 29, "end_line": 62, "language": "py", "code": "@dataclass\nclass RoverConfig:\n    rover_length_m: float\n    rover_width_m: float\n    clearance_margin_m: float\n    grid_resolution_m: float\n\n    @property\n    def clearance_radius_cells(self) -> int:\n        radius_m = math.sqrt((self.rover_length_m / 2) ** 2 + (self.rover_width_m / 2) ** 2) + self.clearance_margin_m\n        return int(math.ceil(radius_m / self.grid_resolution_m))\n\n\n@dataclass\nclass Constraints:\n    candidate_count: int\n    min_spacing_cells: float\n    max_spacing_cells: float\n    boundary_margin_cells: int\n    duplicate_distance_threshold: float\n    # New semantic fields\n    points_per_mission: int = 5\n    target_mission_count: int = 300\n    # Backward‑compatible field (deprecated but kept for older pipelines)\n    target_wp_count: int = 5\n    max_attempts: int = 1000\n    seed: Optional[int] = None\n    # Optional ratios (preserve historic behavior)\n    boundary_margin_ratio: Optional[float] = 0.05\n    min_spacing_ratio: Optional[float] = 0.10\n    max_spacing_ratio: Optional[float] = 0.40\n    max_turn_angle_deg: Optional[float] = 80.0\n    min_start_end_dist: Optional[float] = 0.0\n"}, "src/roar2026/dev_environment/rover/roar_simulation_full/urdf/modules/rover_gazebo.xacro:4-78": {"file": "src/roar2026/dev_environment/rover/roar_simulation_full/urdf/modules/rover_gazebo.xacro", "lines": "4-78", "start_line": 4, "end_line": 78, "language": "xacro", "code": "  <xacro:macro name=\"rover_gazebo\" params=\"controllers_yaml\">\n    <gazebo>\n      <plugin filename=\"gz_ros2_control-system\" name=\"gz_ros2_control::GazeboSimROS2ControlPlugin\">\n        <parameters>${controllers_yaml}</parameters>\n      </plugin>\n\n          <plugin filename=\"gz-sim-pose-publisher-system\" name=\"gz::sim::systems::PosePublisher\">\n        <publish_link_pose>false</publish_link_pose>\n        <publish_collision_pose>false</publish_collision_pose>\n        <publish_visual_pose>false</publish_visual_pose>\n        <publish_nested_model_pose>true</publish_nested_model_pose>\n        <use_pose_vector_msg>true</use_pose_vector_msg>\n        <update_frequency>50</update_frequency>\n      </plugin>\n    </gazebo>\n\n    <xacro:contact_sensor_gazebo name=\"base_link\" />\n    <xacro:contact_sensor_gazebo name=\"wheel_rhs_front\" />\n    <xacro:contact_sensor_gazebo name=\"wheel_rhs_mid\" />\n    <xacro:contact_sensor_gazebo name=\"wheel_rhs_rear\" />\n    <xacro:contact_sensor_gazebo name=\"wheel_lhs_front\" />\n    <xacro:contact_sensor_gazebo name=\"wheel_lhs_mid\" />\n    <xacro:contact_sensor_gazebo name=\"wheel_lhs_rear\" />\n  </xacro:macro>\n\n  <xacro:macro name=\"contact_sensor_gazebo\" params=\"name\">\n    <gazebo reference=\"${name}\">\n      <sensor name=\"${name}_contact\" type=\"contact\">\n        <always_on>true</always_on>\n        <topic>/rover_contact</topic>\n        <update_rate>50</update_rate>\n        <contact>\n          <collision>${name}_collision</collision>\n        </contact>\n      </sensor>\n    </gazebo>\n  </xacro:macro>\n\n  <xacro:macro name=\"depth_camera_gazebo\" params=\"name\">\n    <gazebo reference=\"${name}_link\">\n      \n      <sensor name=\"${name}_rgb\" type=\"camera\">\n        <always_on>1</always_on>\n        <visualize>false</visualize>\n        <update_rate>5</update_rate>\n        <topic>${name}/image_raw</topic>\n        <camera>\n          <horizontal_fov>1.91986</horizontal_fov> <image><width>640</width><height>360</height></image>\n          <clip><near>0.2</near><far>300</far></clip>\n          <noise>\n            <type>gaussian</type>\n            <mean>0.0</mean>\n            <stddev>0.007</stddev> \n          </noise>\n        </camera>\n      </sensor>\n\n      <sensor name=\"${name}_depth\" type=\"depth_camera\">\n        <always_on>1</always_on>\n        <visualize>false</visualize>\n        <update_rate>5</update_rate>\n        <topic>${name}/depth</topic>\n        <camera>\n          <horizontal_fov>1.91986</horizontal_fov> <image><width>640</width><height>360</height></image>\n          <clip><near>0.2</near><far>20</far></clip>\n          <noise>\n            <type>gaussian</type>\n            <mean>0.0</mean>\n            <stddev>0.01</stddev> \n          </noise>\n        </camera>\n      </sensor>\n      \n    </gazebo>\n  </xacro:macro>"}, "src/roar2026/dev_environment/rover/roar_simulation_full/launch/basic_rover.launch.py:166-199": {"file": "src/roar2026/dev_environment/rover/roar_simulation_full/launch/basic_rover.launch.py", "lines": "166-199", "start_line": 166, "end_line": 199, "language": "py", "code": "    bridge = Node(\n        package='ros_gz_bridge',\n        executable='parameter_bridge',\n        arguments=[\n            '/clock@rosgraph_msgs/msg/Clock[gz.msgs.Clock',\n            '/bno055/data@sensor_msgs/msg/Imu[gz.msgs.IMU',\n            '/bno055/mag@sensor_msgs/msg/MagneticField[gz.msgs.Magnetometer',\n            '/zed2i/image_raw@sensor_msgs/msg/Image[gz.msgs.Image',\n            '/zed2i/depth@sensor_msgs/msg/Image[gz.msgs.Image',\n            '/zed2i/camera_info@sensor_msgs/msg/CameraInfo[gz.msgs.CameraInfo',\n            '/cmd_vel@geometry_msgs/msg/Twist]gz.msgs.Twist',\n            '/chassis/contact_sensors@ros_gz_interfaces/msg/Contacts[gz.msgs.Contacts',\n            '/model/roar_rover/pose@tf2_msgs/msg/TFMessage[gz.msgs.Pose_V',\n                        '/world/rover_world/model/roar_rover/link/base_footprint/sensor/base_link_contact/contact@ros_gz_interfaces/msg/Contacts[gz.msgs.Contacts',\n            '/world/rover_world/model/roar_rover/link/wheel_lhs_front/sensor/wheel_lhs_front_contact/contact@ros_gz_interfaces/msg/Contacts[gz.msgs.Contacts',\n            '/world/rover_world/model/roar_rover/link/wheel_lhs_mid/sensor/wheel_lhs_mid_contact/contact@ros_gz_interfaces/msg/Contacts[gz.msgs.Contacts',\n            '/world/rover_world/model/roar_rover/link/wheel_lhs_rear/sensor/wheel_lhs_rear_contact/contact@ros_gz_interfaces/msg/Contacts[gz.msgs.Contacts',\n            '/world/rover_world/model/roar_rover/link/wheel_rhs_front/sensor/wheel_rhs_front_contact/contact@ros_gz_interfaces/msg/Contacts[gz.msgs.Contacts',\n            '/world/rover_world/model/roar_rover/link/wheel_rhs_mid/sensor/wheel_rhs_mid_contact/contact@ros_gz_interfaces/msg/Contacts[gz.msgs.Contacts',\n            '/world/rover_world/model/roar_rover/link/wheel_rhs_rear/sensor/wheel_rhs_rear_contact/contact@ros_gz_interfaces/msg/Contacts[gz.msgs.Contacts',\n        ],\n        output='screen',\n                remappings=[\n            ('/model/roar_rover/pose', '/world/rover_world/pose/info'),\n            ('/world/rover_world/model/roar_rover/link/base_footprint/sensor/base_link_contact/contact', '/rover_contact'),\n            ('/world/rover_world/model/roar_rover/link/wheel_lhs_front/sensor/wheel_lhs_front_contact/contact', '/rover_contact'),\n            ('/world/rover_world/model/roar_rover/link/wheel_lhs_mid/sensor/wheel_lhs_mid_contact/contact', '/rover_contact'),\n            ('/world/rover_world/model/roar_rover/link/wheel_lhs_rear/sensor/wheel_lhs_rear_contact/contact', '/rover_contact'),\n            ('/world/rover_world/model/roar_rover/link/wheel_rhs_front/sensor/wheel_rhs_front_contact/contact', '/rover_contact'),\n            ('/world/rover_world/model/roar_rover/link/wheel_rhs_mid/sensor/wheel_rhs_mid_contact/contact', '/rover_contact'),\n            ('/world/rover_world/model/roar_rover/link/wheel_rhs_rear/sensor/wheel_rhs_rear_contact/contact', '/rover_contact'),\n        ],\n        parameters=[{'use_sim_time': use_sim_time}]\n    )"}, "src/roar2026/dev_environment/rover/roar_simulation_full/configs/diff_controller.yaml:18-43": {"file": "src/roar2026/dev_environment/rover/roar_simulation_full/configs/diff_controller.yaml", "lines": "18-43", "start_line": 18, "end_line": 43, "language": "yaml", "code": "diff_drive_controller:\n  ros__parameters:\n    left_wheel_names:\n      - wheel_lhs_front_joint\n      - wheel_lhs_mid_joint\n      - wheel_lhs_rear_joint\n    right_wheel_names:\n      - wheel_rhs_front_joint\n      - wheel_rhs_mid_joint\n      - wheel_rhs_rear_joint\n\n    base_frame_id: base_footprint\n\n\n    wheel_separation: 0.61  # Distance between left and right wheels (meters)\n    wheel_radius: 0.125     # Radius of your wheels (meters)\n\n    use_stamped_vel: true   # Matches Nav2's stamped cmd_vel output on Jazzy\n\n    enable_odom_tf: false   # IESKF owns odom→base_footprint; prevent TF conflict\n\n    linear.x.has_velocity_limits: true\n    linear.x.max_velocity: 1.0\n    angular.z.has_velocity_limits: true\n    angular.z.max_velocity: 2.0\n"}, "src/roar2026/dev_environment/rover/roar_simulation_full/src/zed_degradation_node.py:255-337": {"file": "src/roar2026/dev_environment/rover/roar_simulation_full/src/zed_degradation_node.py", "lines": "255-337", "start_line": 255, "end_line": 337, "language": "py", "code": "    def depth_callback(self, depth_msg: Image):\n        try:\n            cv_depth = self.bridge.imgmsg_to_cv2(depth_msg, desired_encoding='32FC1').copy()\n            h, w = cv_depth.shape\n\n            if self.X_factor is None or self.X_factor.shape != (h, w):\n                self._set_intrinsics(w, h, self.fx, self.fy, w / 2.0, h / 2.0)\n\n            valid_mask = np.isfinite(cv_depth) & (cv_depth > 0.2)\n\n            # Distance-quadratic stereo depth noise\n            z_values = cv_depth[valid_mask]\n            stddev = 0.003 * (z_values ** 2)\n            cv_depth[valid_mask] += np.random.normal(loc=0.0, scale=stddev).astype(np.float32)\n\n            # Mars dust depth dropouts\n            if self.latest_dust_mask is not None and self.latest_dust_mask.shape == (h, w):\n                dust_mask_depth = valid_mask & self.latest_dust_mask\n            else:\n                dust_mask_depth = valid_mask & (np.random.uniform(0.0, 1.0, size=(h, w)) < 0.015)\n            cv_depth[dust_mask_depth] = 0.4\n\n            # Sun glare stereo depth blindness\n            u, v = self.get_sun_pixel()\n            if u is not None and v is not None:\n                glare_radius_depth = 80.0\n                if -glare_radius_depth < u < w + glare_radius_depth and -glare_radius_depth < v < h + glare_radius_depth:\n                    Y, X = np.ogrid[:h, :w]\n                    dist_from_sun = np.sqrt((X - u) ** 2 + (Y - v) ** 2)\n                    cv_depth[dist_from_sun < glare_radius_depth] = np.nan\n\n            degraded_depth_msg = self.bridge.cv2_to_imgmsg(cv_depth, encoding='32FC1')\n            degraded_depth_msg.header.stamp = depth_msg.header.stamp\n            degraded_depth_msg.header.frame_id = 'zed2i_depth_optical_frame'\n            self.depth_pub.publish(degraded_depth_msg)\n\n            vis_img = np.copy(cv_depth)\n            vis_img[~np.isfinite(vis_img)] = 15.0\n            vis_img = np.clip(vis_img, 0.0, 15.0)\n            vis_norm = cv2.normalize(vis_img, None, 0, 255, cv2.NORM_MINMAX, dtype=cv2.CV_8U)\n            colorized_depth = cv2.applyColorMap(vis_norm, cv2.COLORMAP_JET)\n            vis_msg = self.bridge.cv2_to_imgmsg(colorized_depth, encoding='bgr8')\n            vis_msg.header = degraded_depth_msg.header\n            self.depth_vis_pub.publish(vis_msg)\n\n            # Generate PointCloud2\n            X = self.X_factor * cv_depth\n            Y = self.Y_factor * cv_depth\n\n            if self.latest_rgb is not None and self.latest_rgb.shape[:2] == (h, w):\n                rgb_src = self.latest_rgb\n                R_chan = rgb_src[..., 2].astype(np.uint32)\n                G_chan = rgb_src[..., 1].astype(np.uint32)\n                B_chan = rgb_src[..., 0].astype(np.uint32)\n                rgb_packed = ((R_chan << 16) | (G_chan << 8) | B_chan).view(np.float32)\n            else:\n                neutral = np.uint32((200 << 16) | (200 << 8) | 200).view(np.float32)\n                rgb_packed = np.full((h, w), neutral, dtype=np.float32)\n\n            pc_valid = np.isfinite(cv_depth) & (cv_depth > 0.0)\n            points = np.stack(\n                (X[pc_valid], Y[pc_valid], cv_depth[pc_valid], rgb_packed[pc_valid]),\n                axis=-1\n            ).astype(np.float32)\n\n            pc2 = PointCloud2()\n            pc2.header = degraded_depth_msg.header\n            pc2.height = 1\n            pc2.width = len(points)\n            pc2.is_dense = False\n            pc2.is_bigendian = False\n            pc2.fields = [\n                PointField(name='x', offset=0, datatype=PointField.FLOAT32, count=1),\n                PointField(name='y', offset=4, datatype=PointField.FLOAT32, count=1),\n                PointField(name='z', offset=8, datatype=PointField.FLOAT32, count=1),\n                PointField(name='rgb', offset=12, datatype=PointField.FLOAT32, count=1),\n            ]\n            pc2.point_step = 16\n            pc2.row_step = 16 * len(points)\n            pc2.data = points.tobytes()\n\n            self.pc_pub.publish(pc2)\n        except Exception as e:"}, "src/roar2026/dev_environment/rover/roar_simulation_full/src/encoder_sim_node.py:25-76": {"file": "src/roar2026/dev_environment/rover/roar_simulation_full/src/encoder_sim_node.py", "lines": "25-76", "start_line": 25, "end_line": 76, "language": "py", "code": "class EncoderSimNode(Node):\n    def __init__(self):\n        super().__init__('encoder_sim_node')\n\n        # Pick the representative wheel per side. Mid wheels for now —\n        # swap to averaging all three per side later if needed.\n        self.left_joint  = self.declare_parameter('left_joint',  'wheel_lhs_mid_joint').value\n        self.right_joint = self.declare_parameter('right_joint', 'wheel_rhs_mid_joint').value\n\n        # Matches WIOParams::pulses_per_rev default in ieskf_node.cpp (2000.0).\n        # Swap to the real 3531_0-derived value (~201554) once you're ready\n        # to tune for hardware accuracy — keeping the default for now so the\n        # sim matches what the filter already expects out of the box.\n        self.pulses_per_rev = self.declare_parameter('pulses_per_rev', 201554.0).value\n\n        self.sub = self.create_subscription(\n            JointState, '/joint_states', self.joint_state_cb, 10)\n        self.pub = self.create_publisher(\n            JointState, '/joint_states_updated', 10)\n\n        self.get_logger().info(\n            f\"encoder_sim_node up. left={self.left_joint} right={self.right_joint} \"\n            f\"pulses_per_rev={self.pulses_per_rev}\"\n        )\n\n    def joint_state_cb(self, msg: JointState):\n        left_pos = None\n        right_pos = None\n        for name, pos in zip(msg.name, msg.position):\n            if name == self.left_joint:\n                left_pos = pos\n            elif name == self.right_joint:\n                right_pos = pos\n\n        if left_pos is None or right_pos is None:\n            self.get_logger().warn(\n                \"left/right joint not found in /joint_states yet — skipping\",\n                throttle_duration_sec=3.0,\n            )\n            return\n\n        # radians -> simulated pulse count (rounded, so it actually quantizes\n        # like a real encoder instead of passing through a perfect float)\n        left_pulses  = round(left_pos  / (2.0 * math.pi) * self.pulses_per_rev)\n        right_pulses = round(right_pos / (2.0 * math.pi) * self.pulses_per_rev)\n\n        out = JointState()\n        out.header = msg.header\n        out.name = [self.left_joint, self.right_joint]\n        out.position = [float(left_pulses), float(right_pulses)]\n        self.pub.publish(out)\n"}, "src/roar2026/dev_environment/rover/roar_simulation_full/src/collision_alarm_node.py:20-50": {"file": "src/roar2026/dev_environment/rover/roar_simulation_full/src/collision_alarm_node.py", "lines": "20-50", "start_line": 20, "end_line": 50, "language": "py", "code": "    def contact_callback(self, msg):\n        alarm_msg = Bool()\n        \n        current_collision = False\n        hit_details = \"\"\n        \n        for contact in msg.contacts:\n            c1 = contact.collision1.name.lower() if hasattr(contact.collision1, 'name') else str(contact.collision1)\n            c2 = contact.collision2.name.lower() if hasattr(contact.collision2, 'name') else str(contact.collision2)\n            \n            # Ignore the ground / mars_yard terrain\n            if 'mars_yard' not in c1 and 'mars_yard' not in c2 and 'ground' not in c1 and 'ground' not in c2 and 'terrain' not in c1 and 'terrain' not in c2:\n                current_collision = True\n                hit_details = f\"{c1} <-> {c2}\"\n                break\n        \n        if current_collision:\n            alarm_msg.data = True\n            self.publisher.publish(alarm_msg)\n            \n            if not self.is_colliding:\n                self.get_logger().warn(f'OBSTACLE COLLISION DETECTED! Details: {hit_details}')\n                self.is_colliding = True\n        else:\n            alarm_msg.data = False\n            self.publisher.publish(alarm_msg)\n            \n            if self.is_colliding:\n                self.get_logger().info('Rover is clear of obstacles.')\n                self.is_colliding = False\n"}, "src/navstack/perception/perception_module/lidar_cluster_node.py:148-294": {"file": "src/navstack/perception/perception_module/lidar_cluster_node.py", "lines": "148-294", "start_line": 148, "end_line": 294, "language": "py", "code": "    def listener_callback(self, msg: PointCloud2):\n        # Read all params fresh each call → ros2 param set takes effect live\n        p = self._read_params()\n\n        # ── Stage 0: GPU-accelerated ROI distance mask ───────────────────\n        points, colors = self._pc2_to_numpy_rgb(msg)\n        if points.shape[0] == 0:\n            return\n\n        if self._use_gpu:\n            # Upload to GPU, compute squared norms, threshold, download mask\n            pts_t  = o3c.Tensor(points, dtype=o3c.float32, device=self._gpu_device)\n            sq     = (pts_t * pts_t).sum(1)                     # Nx1 squared distances\n            mask_t = sq < float(p['max_dist'] ** 2)             # boolean mask on GPU\n            mask   = mask_t.cpu().numpy().astype(bool)\n        else:\n            mask = np.linalg.norm(points, axis=1) < p['max_dist']\n\n        points = points[mask]\n        colors = colors[mask]\n        if points.shape[0] == 0:\n            return\n\n        # Wrap in Open3D legacy PointCloud for the rest of the pipeline\n        pcd = o3d.geometry.PointCloud()\n        pcd.points = o3d.utility.Vector3dVector(points)\n        pcd.colors = o3d.utility.Vector3dVector(colors)\n\n        # ── Stage 1: Voxel-grid downsampling ────────────────────────────\n        pcd = pcd.voxel_down_sample(voxel_size=p['voxel_size'])\n        if len(pcd.points) < 10:\n            return\n\n        # ── Stage 2: Statistical Outlier Removal (SOR) ──────────────────\n        # Removes per-point speckle by comparing each point's mean\n        # neighbour distance to the global mean±σ across all points.\n        if p['sor_en'] and len(pcd.points) >= p['sor_k']:\n            pcd, _ = pcd.remove_statistical_outlier(\n                nb_neighbors=int(p['sor_k']),\n                std_ratio=float(p['sor_std'])\n            )\n            if len(pcd.points) < 5:\n                return\n\n        # ── Stage 3: Radius Outlier Removal (ROR) ───────────────────────\n        # Removes isolated points (sensor reflections) that survive SOR.\n        if p['ror_en'] and len(pcd.points) >= p['ror_n']:\n            pcd, _ = pcd.remove_radius_outlier(\n                nb_points=int(p['ror_n']),\n                radius=float(p['ror_r'])\n            )\n            if len(pcd.points) < 5:\n                return\n\n        # Publish clean cloud (with ground, for debugging in RViz)\n        self.filtered_pub.publish(self._pcd_to_pc2_rgb(pcd, msg.header))\n\n        # ── Stage 4: Slope-aware iterative RANSAC plane removal ─────────\n        # Strips ground + ramps while PRESERVING steep rock faces.\n        pcd_ng = self._remove_planes_slope_aware(pcd, p)\n        if pcd_ng is None or len(pcd_ng.points) == 0:\n            return\n\n        # ── Stage 4b: Surface-normal roughness filter ────────────────────\n        # Removes any remaining smooth-slope points; keeps only rough/sharp rock points.\n        if p['roughness_en']:\n            pcd_ng = self._roughness_filter(pcd_ng, p)\n            if pcd_ng is None or len(pcd_ng.points) < 5:\n                return\n\n        self.no_ground_pub.publish(self._pcd_to_pc2_rgb(pcd_ng, msg.header))\n\n        # ── Stage 5: DBSCAN clustering ───────────────────────────────────\n        # Groups surviving points into candidate obstacle clusters.\n        labels = np.array(\n            pcd_ng.cluster_dbscan(\n                eps=p['cluster_tol'],\n                min_points=p['min_cluster'],\n                print_progress=False\n            )\n        )\n\n        # Build message containers\n        detections     = Detection3DArray(header=msg.header)\n        raw_detections = Detection3DArray(header=msg.header)\n        slam_detections = ObstacleDetectionArray(header=msg.header)\n\n        max_label = int(labels.max()) if labels.size > 0 else -1\n\n        for i in range(max_label + 1):\n            idx = np.where(labels == i)[0]\n            if len(idx) < p['min_cluster'] or len(idx) > p['max_cluster']:\n                continue  # DBSCAN already filters by min, but max is our extra gate\n\n            cluster_pcd = pcd_ng.select_by_index(idx)\n            aabb   = cluster_pcd.get_axis_aligned_bounding_box()\n            center = aabb.get_center()\n            extent = aabb.get_extent()\n            sx, sy, sz = float(extent[0]), float(extent[1]), float(extent[2])\n            cx, cy, cz = float(center[0]), float(center[1]), float(center[2])\n\n            # Assemble Detection3D (shared by raw + filtered arrays)\n            det = self._make_detection3d(msg.header, center, extent, i)\n            raw_detections.detections.append(det)\n\n            # ── Stage 6: Bounding-box shape filter ──────────────────────\n            if not (p['min_bx'] <= sx <= p['max_bx'] and\n                    p['min_by'] <= sy <= p['max_by'] and\n                    p['min_bz'] <= sz <= p['max_bz']):\n                self.get_logger().debug(\n                    f'Cluster {i} rejected by bbox: x={sx:.2f} y={sy:.2f} z={sz:.2f}'\n                )\n                continue\n\n            # ── Stage 6: Aspect-ratio filter (flat slab rejection) ───────\n            # A ramp remnant is wide+deep but not tall.  Rocks are chunkier.\n            if p['max_dr'] > 0 and sy > 1e-3 and (sz / sy) > p['max_dr']:\n                self.get_logger().debug(\n                    f'Cluster {i} rejected by depth/height={sz/sy:.1f} > {p[\"max_dr\"]}'\n                )\n                continue\n\n            # ── Stage 6: Distance filter ─────────────────────────────────\n            cl_dist = float(np.linalg.norm([cx, cy, cz]))\n            if cl_dist < p['min_cdist'] or cl_dist > p['max_cdist']:\n                continue\n\n            # ── Stage 6: Centre-height (Y-axis) filter ───────────────────\n            # ZED Y=down; positive Y = below camera (on ground level).\n            # Rocks sit near Y=0..+0.5; reject clusters above or far below.\n            if cy < p['min_cy'] or cy > p['max_cy']:\n                continue\n\n            detections.detections.append(det)\n\n            # Build SLAM-format obstacle\n            slam_obs = ObstacleDetection()\n            slam_obs.position   = Point(x=cx, y=cy, z=cz)\n            slam_obs.dimensions = Vector3(x=sx, y=sy, z=sz)\n            slam_detections.detections.append(slam_obs)\n\n        # Publish\n        self.raw_cluster_pub.publish(raw_detections)\n        self.cluster_pub.publish(detections)\n        self.slam_pub.publish(slam_detections)\n        self._publish_markers(detections, msg.header)\n"}, "src/navstack/perception/perception_module/lidar_cluster_node.py:336-402": {"file": "src/navstack/perception/perception_module/lidar_cluster_node.py", "lines": "336-402", "start_line": 336, "end_line": 402, "language": "py", "code": "    def _remove_planes_slope_aware(self, pcd, p) -> o3d.geometry.PointCloud:\n        \"\"\"\n        Iteratively finds and removes dominant planes, but ONLY if the plane:\n          (a) has >= plane_min_inliers points (small planes = rock faces → keep)\n          (b) its normal tilts <= ground_max_tilt_deg from vertical (ZED Y axis)\n              → near-vertical walls / rock faces are NEVER removed\n          (c) its centroid depth (Z) is within [gnd_min_z, gnd_max_z]\n              → prevents accidentally removing a floating rock cluster\n\n        This is the key improvement over the old all-planes-stripped approach:\n        a ramp at 30° is removed; a near-vertical boulder face at 80° is kept.\n        \"\"\"\n        cos_limit = math.cos(math.radians(float(p['gnd_tilt'])))\n        current   = pcd\n\n        for i in range(int(p['plane_iters'])):\n            if len(current.points) < 20:\n                break\n\n            try:\n                plane_model, inliers = current.segment_plane(\n                    distance_threshold=float(p['gnd_thresh']),\n                    ransac_n=3,\n                    num_iterations=200\n                )\n            except Exception:\n                break\n\n            if len(inliers) < int(p['plane_inliers']):\n                # Too few inliers → this is a small feature (rock), not ground. Stop.\n                self.get_logger().debug(\n                    f'RANSAC iter {i}: {len(inliers)} inliers < {p[\"plane_inliers\"]}, stopping.'\n                )\n                break\n\n            # Compute cosine between plane normal and gravity (Y axis)\n            normal = np.array(plane_model[:3], dtype=np.float64)\n            normal /= np.linalg.norm(normal) + 1e-9\n            cos_with_gravity = abs(float(np.dot(normal, _GRAVITY)))\n\n            # Compute centroid depth (Z = forward in ZED frame)\n            pts_arr = np.asarray(current.points)\n            centroid_z = float(np.mean(pts_arr[inliers, 2]))\n\n            # Check centroid depth is in valid ground range\n            depth_ok = p['gnd_min_z'] <= centroid_z <= p['gnd_max_z']\n\n            # Remove the plane only if it is \"ground-like\"\n            if cos_with_gravity >= cos_limit and depth_ok:\n                axis = ['X', 'Y', 'Z'][int(np.argmax(np.abs(normal)))]\n                self.get_logger().debug(\n                    f'RANSAC iter {i}: removed {len(inliers)} pts  '\n                    f'normal≈{normal.round(2)}  dominant={axis}  '\n                    f'tilt_ok  centroid_z={centroid_z:.2f}'\n                )\n                current = current.select_by_index(inliers, invert=True)\n            else:\n                # This plane is too steep (rock face) or at wrong depth — stop.\n                self.get_logger().debug(\n                    f'RANSAC iter {i}: KEPT {len(inliers)} pts  '\n                    f'cos_grav={cos_with_gravity:.2f} < {cos_limit:.2f} '\n                    f'or depth_ok={depth_ok}. Stopping.'\n                )\n                break\n\n        return current\n"}, "src/navstack/perception/perception_module/lidar_cluster_node.py:220-293": {"file": "src/navstack/perception/perception_module/lidar_cluster_node.py", "lines": "220-293", "start_line": 220, "end_line": 293, "language": "py", "code": "        # ── Stage 5: DBSCAN clustering ───────────────────────────────────\n        # Groups surviving points into candidate obstacle clusters.\n        labels = np.array(\n            pcd_ng.cluster_dbscan(\n                eps=p['cluster_tol'],\n                min_points=p['min_cluster'],\n                print_progress=False\n            )\n        )\n\n        # Build message containers\n        detections     = Detection3DArray(header=msg.header)\n        raw_detections = Detection3DArray(header=msg.header)\n        slam_detections = ObstacleDetectionArray(header=msg.header)\n\n        max_label = int(labels.max()) if labels.size > 0 else -1\n\n        for i in range(max_label + 1):\n            idx = np.where(labels == i)[0]\n            if len(idx) < p['min_cluster'] or len(idx) > p['max_cluster']:\n                continue  # DBSCAN already filters by min, but max is our extra gate\n\n            cluster_pcd = pcd_ng.select_by_index(idx)\n            aabb   = cluster_pcd.get_axis_aligned_bounding_box()\n            center = aabb.get_center()\n            extent = aabb.get_extent()\n            sx, sy, sz = float(extent[0]), float(extent[1]), float(extent[2])\n            cx, cy, cz = float(center[0]), float(center[1]), float(center[2])\n\n            # Assemble Detection3D (shared by raw + filtered arrays)\n            det = self._make_detection3d(msg.header, center, extent, i)\n            raw_detections.detections.append(det)\n\n            # ── Stage 6: Bounding-box shape filter ──────────────────────\n            if not (p['min_bx'] <= sx <= p['max_bx'] and\n                    p['min_by'] <= sy <= p['max_by'] and\n                    p['min_bz'] <= sz <= p['max_bz']):\n                self.get_logger().debug(\n                    f'Cluster {i} rejected by bbox: x={sx:.2f} y={sy:.2f} z={sz:.2f}'\n                )\n                continue\n\n            # ── Stage 6: Aspect-ratio filter (flat slab rejection) ───────\n            # A ramp remnant is wide+deep but not tall.  Rocks are chunkier.\n            if p['max_dr'] > 0 and sy > 1e-3 and (sz / sy) > p['max_dr']:\n                self.get_logger().debug(\n                    f'Cluster {i} rejected by depth/height={sz/sy:.1f} > {p[\"max_dr\"]}'\n                )\n                continue\n\n            # ── Stage 6: Distance filter ─────────────────────────────────\n            cl_dist = float(np.linalg.norm([cx, cy, cz]))\n            if cl_dist < p['min_cdist'] or cl_dist > p['max_cdist']:\n                continue\n\n            # ── Stage 6: Centre-height (Y-axis) filter ───────────────────\n            # ZED Y=down; positive Y = below camera (on ground level).\n            # Rocks sit near Y=0..+0.5; reject clusters above or far below.\n            if cy < p['min_cy'] or cy > p['max_cy']:\n                continue\n\n            detections.detections.append(det)\n\n            # Build SLAM-format obstacle\n            slam_obs = ObstacleDetection()\n            slam_obs.position   = Point(x=cx, y=cy, z=cz)\n            slam_obs.dimensions = Vector3(x=sx, y=sy, z=sz)\n            slam_detections.detections.append(slam_obs)\n\n        # Publish\n        self.raw_cluster_pub.publish(raw_detections)\n        self.cluster_pub.publish(detections)\n        self.slam_pub.publish(slam_detections)\n        self._publish_markers(detections, msg.header)"}, "src/navstack/perception/perception_module/obstacle_publisher_node.py:83-201": {"file": "src/navstack/perception/perception_module/obstacle_publisher_node.py", "lines": "83-201", "start_line": 83, "end_line": 201, "language": "py", "code": "    def callback(self, msg: Detection3DArray):\n        max_base_h   = self.get_parameter('max_obstacle_base_height').value\n        min_conf     = self.get_parameter('min_confidence').value\n        source_frame = self.get_parameter('source_frame').value\n        merge_radius = self.get_parameter('merge_radius').value\n        ema_alpha    = self.get_parameter('ema_alpha').value\n\n        world_frame  = self.get_parameter('world_frame').value\n\n        # Use native TF2 to perfectly resolve the 6-frame tree offsets\n        try:\n            tf_stamped = self.tf_buffer.lookup_transform(\n                world_frame,   # target frame\n                source_frame,  # source frame (where the detections are)\n                rclpy.time.Time(), # get the latest available\n                timeout=rclpy.duration.Duration(seconds=0.2)\n            )\n        except Exception as e:\n            self.get_logger().warn(\n                f'Waiting for TF tree to link {source_frame} to {world_frame}...',\n                throttle_duration_sec=5.0,\n            )\n            return\n\n        now = time.time()\n        self.latest_stamp = msg.header.stamp\n\n        for det in msg.detections:\n            # Confidence filter (min_conf=0.0 by default — accept all LiDAR clusters)\n            score    = det.results[0].hypothesis.score    if det.results else 1.0\n            class_id = det.results[0].hypothesis.class_id if det.results else 'obstacle'\n            if score < min_conf:\n                continue\n\n            # Height filter — evaluated in camera frame (Z is UP)\n            bottom_z_cam = det.bbox.center.position.z - det.bbox.size.z / 2.0\n            if bottom_z_cam > max_base_h:\n                continue\n\n            # Distance filter — 3D distance from camera origin in camera frame\n            cx = det.bbox.center.position.x\n            cy = det.bbox.center.position.y\n            cz = det.bbox.center.position.z\n            dist_cam = math.sqrt(cx*cx + cy*cy + cz*cz)\n            if dist_cam > self.get_parameter('max_detection_distance').value:\n                continue\n\n            # Transform obstacle centre to world frame\n            pt_cam        = PointStamped()\n            pt_cam.header = msg.header\n            pt_cam.point  = det.bbox.center.position\n            try:\n                pt_world = tf2_geometry_msgs.do_transform_point(pt_cam, tf_stamped)\n            except Exception as e:\n                self.get_logger().warn(f'Transform failed: {e}')\n                continue\n\n            # Build world-frame detection\n            out_det = Detection3D()\n            out_det.header.frame_id       = world_frame\n            out_det.header.stamp          = msg.header.stamp\n            out_det.bbox.center.position.x = pt_world.point.x\n            out_det.bbox.center.position.y = pt_world.point.y\n            out_det.bbox.center.position.z = pt_world.point.z\n            out_det.bbox.center.orientation.w = 1.0\n            out_det.bbox.size.x = det.bbox.size.x\n            out_det.bbox.size.y = det.bbox.size.y\n            out_det.bbox.size.z = det.bbox.size.z\n            hyp = ObjectHypothesisWithPose()\n            hyp.hypothesis.class_id = class_id\n            hyp.hypothesis.score    = score\n            out_det.results.append(hyp)\n\n            # Merge into obstacle map: if a known obstacle is within merge_radius, update it;\n            # otherwise add a new entry\n            merged = False\n            for entry in self.obstacle_map.values():\n                existing = entry['detection']\n                dx = existing.bbox.center.position.x - pt_world.point.x\n                dy = existing.bbox.center.position.y - pt_world.point.y\n                dz = existing.bbox.center.position.z - pt_world.point.z\n                if math.sqrt(dx*dx + dy*dy + dz*dz) < merge_radius:\n                    # Update in place with EMA (Exponential Moving Average) to eliminate jitter\n                    existing.bbox.center.position.x = (1 - ema_alpha) * existing.bbox.center.position.x + ema_alpha * out_det.bbox.center.position.x\n                    existing.bbox.center.position.y = (1 - ema_alpha) * existing.bbox.center.position.y + ema_alpha * out_det.bbox.center.position.y\n                    existing.bbox.center.position.z = (1 - ema_alpha) * existing.bbox.center.position.z + ema_alpha * out_det.bbox.center.position.z\n                    \n                    existing.bbox.size.x = (1 - ema_alpha) * existing.bbox.size.x + ema_alpha * out_det.bbox.size.x\n                    existing.bbox.size.y = (1 - ema_alpha) * existing.bbox.size.y + ema_alpha * out_det.bbox.size.y\n                    existing.bbox.size.z = (1 - ema_alpha) * existing.bbox.size.z + ema_alpha * out_det.bbox.size.z\n                    \n                    # Keep highest confidence score\n                    if out_det.results and existing.results:\n                        existing.results[0].hypothesis.score = max(existing.results[0].hypothesis.score, out_det.results[0].hypothesis.score)\n\n                    entry['last_seen']  = now\n                    merged = True\n                    break\n\n            if not merged:\n                if len(self.obstacle_map) >= self.get_parameter('max_obstacles').value:\n                    # Map is full — drop the lowest-confidence entry to make room\n                    oldest_key = min(\n                        self.obstacle_map,\n                        key=lambda k: self.obstacle_map[k]['detection'].results[0].hypothesis.score\n                        if self.obstacle_map[k]['detection'].results else 0.0\n                    )\n                    del self.obstacle_map[oldest_key]\n\n                self.obstacle_map[self._next_id] = {\n                    'detection':  out_det,\n                    'last_seen':  now,\n                    'color_idx':  self._next_id,  # fixed forever — colour won't change\n                }\n                self._next_id += 1\n\n        # Forget stale obstacles\n        self._forget_old(now)\n"}, "src/navstack/perception/perception_module/aruco_detector_node.py:76-117": {"file": "src/navstack/perception/perception_module/aruco_detector_node.py", "lines": "76-117", "start_line": 76, "end_line": 117, "language": "py", "code": "    def detect(self, image: np.ndarray):\n        \"\"\"Return (corners, ids, rejected) from the first dictionary that hits.\"\"\"\n        for d in self._DICTS:\n            adict = cv2.aruco.getPredefinedDictionary(d)\n            if self._use_new_api:\n                det = cv2.aruco.ArucoDetector(adict, self._params)\n                corners, ids, rejected = det.detectMarkers(image)\n            else:\n                corners, ids, rejected = cv2.aruco.detectMarkers(\n                    image, adict, parameters=self._params)\n            if ids is not None and len(ids) > 0:\n                return corners, ids, rejected\n        return None, None, None\n\n    def estimate_poses(self, corners, marker_size: float, K, dist):\n        \"\"\"\n        Returns rvecs, tvecs as lists (one entry per detected marker).\n        Uses SOLVEPNP_IPPE_SQUARE — the most accurate method for square targets.\n        \"\"\"\n        if not corners:\n            return [], []\n        half = marker_size / 2.0\n        obj_pts = np.array([\n            [-half,  half, 0.0],\n            [ half,  half, 0.0],\n            [ half, -half, 0.0],\n            [-half, -half, 0.0],\n        ], dtype=np.float32)\n\n        rvecs, tvecs = [], []\n        for corner in corners:\n            ok, rvec, tvec = cv2.solvePnP(\n                obj_pts,\n                corner.reshape(-1, 2).astype(np.float32),\n                K, dist,\n                flags=cv2.SOLVEPNP_IPPE_SQUARE\n            )\n            if ok:\n                rvecs.append(rvec)\n                tvecs.append(tvec)\n        return rvecs, tvecs\n"}, "src/navstack/slam/roar_localization/src/ground_truth_bridge.cpp:52-79": {"file": "src/navstack/slam/roar_localization/src/ground_truth_bridge.cpp", "lines": "52-79", "start_line": 52, "end_line": 79, "language": "cpp", "code": "    void callback(const tf2_msgs::msg::TFMessage::SharedPtr msg)\n    {\n        for (const auto& t : msg->transforms) {\n            if (t.child_frame_id == rover_frame_) {\n                geometry_msgs::msg::PoseWithCovarianceStamped out;\n                out.header.stamp = now();\n                out.header.frame_id = \"odom\";\n                out.pose.pose.position.x = t.transform.translation.x;\n                out.pose.pose.position.y = t.transform.translation.y;\n                out.pose.pose.position.z = t.transform.translation.z;\n                out.pose.pose.orientation = t.transform.rotation;\n\n                for (auto& c : out.pose.covariance) c = 0.0;\n                out.pose.covariance[0]  = position_var_;\n                out.pose.covariance[7]  = position_var_;\n                out.pose.covariance[14] = position_var_;\n                out.pose.covariance[21] = 1e-6;\n                out.pose.covariance[28] = 1e-6;\n                out.pose.covariance[35] = 1e-6;\n\n                pub_->publish(out);\n                return;\n            }\n        }\n        RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,\n            \"Rover frame '%s' not found in TFMessage (%zu transforms)\",\n            rover_frame_.c_str(), msg->transforms.size());\n    }"}, "src/navstack/slam/roar_localization/src/wio.cpp:89-155": {"file": "src/navstack/slam/roar_localization/src/wio.cpp", "lines": "89-155", "start_line": 89, "end_line": 155, "language": "cpp", "code": "    // ── Step 3: Pulses → individual wheel speeds ──────────────────────────────\n    //   one full revolution = pulses_per_rev counts = 2π × wheel_radius metres\n    //\n    // NOTE on encoder format:\n    //   - If your driver publishes RADIANS: set pulses_per_rev = 2π (6.2832).\n    //     Then metres_per_pulse = 2π×r / 2π = r, and\n    //     speed = delta_rad × r / dt — exactly correct.\n    //   - If your driver publishes RAW COUNTS: set pulses_per_rev to your\n    //     encoder's actual PPR × quadrature_factor.\n    const double metres_per_pulse = (2.0 * M_PI * params_.wheel_radius)\n                                    / params_.pulses_per_rev;\n\n    const double v_L = (delta_L * metres_per_pulse) / dt;\n    const double v_R = (delta_R * metres_per_pulse) / dt;\n\n    // Average forward speed — yaw comes from BNO055, not from the differential\n    // (v_R - v_L), because differential speed is unreliable on rough terrain.\n    const double vx = 0.5 * (v_L + v_R);\n\n    // Speed sanity check: reject if above physical maximum.\n    if (std::abs(vx) > params_.max_vx) {\n        out.valid    = false;\n        out.R        = quat_to_rot(q_imu);\n        out.vx       = 0.0;\n        out.dp_world = Vec3::Zero();\n        Vec3 euler   = quat_to_euler(q_imu);\n        out.yaw      = euler(2);\n        out.pitch    = euler(1);\n        prev_pulses_L_ = pulses_L;\n        prev_pulses_R_ = pulses_R;\n        return out;\n    }\n\n    // Reading was valid. Update stored counts.\n    prev_pulses_L_ = pulses_L;\n    prev_pulses_R_ = pulses_R;\n\n    // ── Step 4: BNO055 quaternion → R, Euler ─────────────────────────────────\n    const Mat3 R     = quat_to_rot(q_imu);\n    const Vec3 euler = rot_to_euler(R);\n    const double pitch = euler(1);\n    const double yaw   = euler(2);\n\n    // ── Step 5: Mid-point yaw integration ────────────────────────────────────\n    // Halves the integration error when the rover is turning.\n    const double d_yaw   = wrap_angle(yaw - prev_yaw_);\n    const double avg_yaw = prev_yaw_ + 0.5 * d_yaw;\n    prev_yaw_ = yaw;\n\n    // ── Step 6: Dead-reckoning dp in world frame ──────────────────────────────\n    // dp_z is non-zero on slopes.\n    const double dp_x = vx * std::cos(avg_yaw) * dt;\n    const double dp_y = vx * std::sin(avg_yaw) * dt;\n    const double dp_z = vx * std::sin(pitch)   * dt;\n\n    // ── Pack output ───────────────────────────────────────────────────────────\n    out.R        = R;\n    out.vx       = vx;\n    out.v_L      = v_L;   // ← NEW: left wheel speed for slip ratio\n    out.v_R      = v_R;   // ← NEW: right wheel speed for slip ratio\n    out.dp_world = Vec3(dp_x, dp_y, dp_z);\n    out.yaw      = yaw;\n    out.pitch    = pitch;\n    out.valid    = true;\n\n    return out;\n}"}, "src/navstack/slam/roar_localization/include/roar_localization/ieskf.hpp:210-255": {"file": "src/navstack/slam/roar_localization/include/roar_localization/ieskf.hpp", "lines": "210-255", "start_line": 210, "end_line": 255, "language": "hpp", "code": "    template<typename PredictFn, typename DxFn>\n    void applyUpdate(const ObsVec& z,\n                     const ObsMat& H,\n                     const ObsCov& V,\n                     PredictFn     predict_h,\n                     DxFn          add_dx_to_h)\n    {\n        // Innovation covariance S = H·P·H' + V  [3×3]\n        const Eigen::Matrix3d S = H * P_ * H.transpose() + V;\n\n        // Kalman gain K = P·H'·S⁻¹  [12×3]  (LDLT for symmetric PD solve)\n        const KalmanGain K =\n            P_ * H.transpose() * S.ldlt().solve(Eigen::Matrix3d::Identity());\n\n        // Iterated update loop — standard IEKF (Bell & Cathey) form:\n        //\n        //   δx_{i+1} = K · ( z − h(x ⊕ δx_i) + H·δx_i )\n        //\n        // (algebraically equivalent to δx_{i+1} = K·(z − h(x⊕δx_i)) − (I−K·H)·δx_i)\n        //\n        // The +H·δx_i term is essential: it re-expresses the residual around\n        // the ORIGINAL linearization point. For linear h this collapses to\n        // z − h(x) and the loop converges in exactly one iteration with the\n        // full Kalman step. For future nonlinear observations, the loop\n        // performs proper Gauss-Newton iterations.\n        StateVec dx_iter = StateVec::Zero();\n        const ObsVec h_at_x = predict_h();\n\n        for (int i = 0; i < params_.max_iterations; ++i)\n        {\n            const ObsVec h_x_dx   = add_dx_to_h(h_at_x, dx_iter);\n            const ObsVec residual = z - h_x_dx + H * dx_iter;\n            const StateVec dx_new = K * residual;\n\n            const bool converged = (dx_new - dx_iter).norm() < params_.epsilon;\n            dx_iter = dx_new;\n            if (converged) break;\n        }\n\n        injectErrorState(dx_iter);\n\n        // Joseph-form covariance update — keeps P symmetric positive-definite\n        const StateMat I_KH = StateMat::Identity() - K * H;\n        P_ = I_KH * P_ * I_KH.transpose() + K * V * K.transpose();\n        P_ = 0.5 * (P_ + P_.transpose());\n    }"}, "src/navstack/slam/roar_localization/include/roar_localization/fuzzy_utils.hpp:304-331": {"file": "src/navstack/slam/roar_localization/include/roar_localization/fuzzy_utils.hpp", "lines": "304-331", "start_line": 304, "end_line": 331, "language": "hpp", "code": "class WOFIS\n{\npublic:\n    explicit WOFIS(const WOFISParams& params = WOFISParams{})\n        : params_(params)\n    {\n        buildFIS();\n    }\n\n    // Evaluate k_Q.\n    // slip_ratio   ∈ [0, 1]  — clamped internally\n    // omega_z_norm ∈ [0, 1]  — |ω_z| / max_omega_z\n    // vx_norm      ∈ [0, 1]  — vx / max_vx\n    double evaluate(double slip_ratio,\n                    double omega_z_norm,\n                    double vx_norm) const\n    {\n        slip_ratio   = std::clamp(slip_ratio,   0.0, 1.0);\n        omega_z_norm = std::clamp(omega_z_norm, 0.0, 1.0);\n        vx_norm      = std::clamp(vx_norm,      0.0, 1.0);\n\n        return fis_.evaluate({slip_ratio, omega_z_norm, vx_norm},\n                             params_.k_Q_min);\n    }\n\n    const WOFISParams& getParams() const { return params_; }\n    const SugenoFIS&   getFIS()    const { return fis_; }\n"}, "src/navstack/slam/roar_localization/include/roar_localization/zupt.hpp:125-164": {"file": "src/navstack/slam/roar_localization/include/roar_localization/zupt.hpp", "lines": "125-164", "start_line": 125, "end_line": 164, "language": "hpp", "code": "    void update(double v_L, double v_R,\n                double omega_z,\n                const Vec3& a_m,\n                double now_sec)\n    {\n        // ── Update accel ring buffer ─────────────────────────────────────────\n        accel_buffer_.push_back(a_m);\n        while (static_cast<int>(accel_buffer_.size()) > params_.accel_buffer_size) {\n            accel_buffer_.pop_front();\n        }\n\n        // ── Evaluate all four conditions ─────────────────────────────────────\n        const bool wheels_quiet =\n            std::abs(v_L) < params_.encoder_speed_threshold &&\n            std::abs(v_R) < params_.encoder_speed_threshold;\n\n        const bool gyro_quiet =\n            std::abs(omega_z) < params_.angular_velocity_threshold;\n\n        const bool accel_quiet =\n            (static_cast<int>(accel_buffer_.size()) >= params_.accel_buffer_size) &&\n            (computeAccelVariance() < params_.accel_variance_threshold);\n\n        const bool all_satisfied = wheels_quiet && gyro_quiet && accel_quiet;\n\n        // ── Update timer ─────────────────────────────────────────────────────\n        // If all conditions just became true, remember when. If they remain\n        // true for `min_stationary_duration`, declare stationary.\n        if (all_satisfied) {\n            if (!satisfied_now_) {\n                first_satisfied_time_ = now_sec;\n                satisfied_now_        = true;\n            }\n            const double elapsed = now_sec - first_satisfied_time_;\n            currently_stationary_ = (elapsed >= params_.min_stationary_duration);\n        } else {\n            satisfied_now_        = false;\n            currently_stationary_ = false;\n        }\n    }"}, "src/navstack/slam/terrain_mapping/terrain_mapping/terrain_mapping_node.py:308-398": {"file": "src/navstack/slam/terrain_mapping/terrain_mapping/terrain_mapping_node.py", "lines": "308-398", "start_line": 308, "end_line": 398, "language": "py", "code": "    def _on_detections(self, msg: ObstacleDetectionArray):\n        updated = 0\n        created = 0\n        rejected = 0\n\n        for det in msg.detections:\n            world_pt = self._transform_to_map_frame(det.position, msg.header)\n            if world_pt is None:\n                continue  # transform failed — skip this detection\n\n            wx, wy, wz = world_pt\n\n            # 1. Associate with the nearest existing track (Mahalanobis gate).\n            best = None\n            best_d_sq = self._assoc_gate_sq\n            for track in self._tracks:\n                d_sq = track.mahalanobis_sq(wx, wy, wz, self._r_xy, self._r_z)\n                if d_sq < best_d_sq:\n                    best_d_sq = d_sq\n                    best = track\n\n            if best is not None:\n                best.update(\n                    wx, wy, wz,\n                    det.dimensions.x, det.dimensions.y, det.dimensions.z,\n                    self._r_xy, self._r_z,\n                )\n                updated += 1\n                continue\n\n            # 2. New obstacle — verify it against the trusted terrain before\n            #    a track is born: its bbox bottom must sit on the base map.\n            if not self._terrain_consistent(wx, wy, wz - det.dimensions.z / 2.0):\n                rejected += 1\n                continue\n\n            self._tracks.append(\n                _ObstacleTrack(\n                    x=wx, y=wy, z=wz,\n                    var_x=self._r_xy, var_y=self._r_xy, var_z=self._r_z,\n                    dim_x=det.dimensions.x,\n                    dim_y=det.dimensions.y,\n                    dim_z=det.dimensions.z,\n                    class_id=det.class_id,\n                )\n            )\n            created += 1\n\n        if updated or created:\n            self._rebuild_height_map()\n\n        if updated or created or rejected:\n            self.get_logger().debug(\n                f\"Detections — track updates: {updated}  new tracks: {created}  \"\n                f\"terrain-rejected: {rejected}  tracks total: {len(self._tracks)}\"\n            )\n\n    def _terrain_consistent(self, wx: float, wy: float, bottom_z: float) -> bool:\n        \"\"\"Gate a prospective obstacle's bbox bottom against the trusted base\n        terrain height at (wx, wy). Base cells carry initial_height_variance\n        (tiny — the map is respected); unmapped NaN cells carry\n        unknown_height_variance, which makes the gate pass automatically\n        there. Out-of-grid detections are likewise unverifiable but allowed.\"\"\"\n        col = int((wx - self._origin_x) / self._resolution)\n        row = int((wy - self._origin_y) / self._resolution)\n        if not (0 <= row < self._rows and 0 <= col < self._cols):\n            return True\n\n        terrain = float(self._base_height_map[row, col])\n        var_terrain = self._unknown_variance if np.isnan(terrain) else self._base_variance\n        if np.isnan(terrain):\n            terrain = 0.0\n\n        innovation_sq = (bottom_z - terrain) ** 2\n        return innovation_sq / (var_terrain + self._r_z) < self._terrain_gate_sq\n\n    def _rebuild_height_map(self):\n        \"\"\"Recompute the published height map: the immutable base terrain\n        plus every VERIFIED track's bbox top stamped over its footprint at\n        the track's current filtered position. Rebuilding from scratch means\n        a track whose estimate shifts cells between sightings never leaves a\n        stale stamp behind.\"\"\"\n        hm = self._base_height_map.copy()\n        for track in self._tracks:\n            if track.mean_variance() > self._commit_variance:\n                continue  # not yet verified — stays out of the published maps\n            top = track.z + track.dim_z / 2.0\n            for row, col in self._bbox_to_cells(track.x, track.y, track.dim_x, track.dim_y):\n                hm[row, col] = np.fmax(hm[row, col], top)\n        self._height_map = hm\n"}, "src/navstack/path-planning/globalPlanner/scripts/heightmap_to_costmap.py:144-216": {"file": "src/navstack/path-planning/globalPlanner/scripts/heightmap_to_costmap.py", "lines": "144-216", "start_line": 144, "end_line": 216, "language": "py", "code": "        # ─── Step 2: Compute terrain derivatives ────────────────────────\n        h_blur = cv2.GaussianBlur(h_meters, (3, 3), 0)\n\n        # 1st derivative (steepness) via Sobel\n        sobel_x = cv2.Sobel(h_blur, cv2.CV_32F, 1, 0, ksize=3)\n        sobel_y = cv2.Sobel(h_blur, cv2.CV_32F, 0, 1, ksize=3)\n        steepness = np.sqrt(sobel_x ** 2 + sobel_y ** 2)\n\n        # 2nd derivative (roughness) via Laplacian\n        roughness = np.abs(cv2.Laplacian(h_blur, cv2.CV_32F))\n\n        # Normalize to 0-99 (100 is reserved for lethal)\n        norm_steep = np.clip((steepness / self.max_slope) * 99.0, 0, 99)\n        norm_rough = np.clip((roughness / self.max_roughness) * 99.0, 0, 99)\n\n        # Merge with configurable weights\n        terrain_cost = np.clip(\n            norm_steep * self.steep_w + norm_rough * self.rough_w, 0, 99)\n\n        # ─── Step 3: Detect lethal cells from heightmap ─────────────────\n        # Steep slopes → lethal\n        steep_lethal = steepness > self.max_slope\n\n        # Height diffs (cliffs) → lethal (3x3 max-min filter)\n        kernel_3x3 = np.ones((3, 3), np.uint8)\n        max_h = cv2.dilate(h_blur, kernel_3x3)\n        min_h = cv2.erode(h_blur, kernel_3x3)\n        diff_lethal = (max_h - min_h) > self.max_h_diff\n\n        lethal_mask = (steep_lethal | diff_lethal) & valid_hm\n\n        # ─── Step 4: Inflation layer ────────────────────────────────────\n        # Build binary lethal image for distance transform\n        lethal_binary = lethal_mask.astype(np.uint8)  # 1 = lethal, 0 = free\n\n        # Distance transform: compute distance from each cell to nearest lethal\n        # cv2.distanceTransform needs inverted input (0 = obstacle)\n        dist_map = cv2.distanceTransform(\n            (1 - lethal_binary), cv2.DIST_L2, 5) * res  # convert to meters\n\n        # Inscribed inflation: cells within inscribed_radius → also lethal\n        inscribed_mask = dist_map < self.inscribed_radius\n\n        # Gradual inflation: exponential decay between inscribed and inflation radius\n        # inflation_cost = 99 * exp(-scaling * (dist - inscribed_radius) / (inflation_radius - inscribed_radius))\n        inflation_cost = np.zeros_like(dist_map, dtype=np.float64)\n        inflation_band = (dist_map >= self.inscribed_radius) & (dist_map < self.inflation_radius)\n        if self.inflation_radius > self.inscribed_radius:\n            normalized_dist = (dist_map[inflation_band] - self.inscribed_radius) / \\\n                              (self.inflation_radius - self.inscribed_radius)\n            inflation_cost[inflation_band] = 99.0 * np.exp(-self.inflation_scaling * normalized_dist)\n\n        # ─── Step 5: Combine everything ─────────────────────────────────\n        # Start with terrain cost as base\n        out = terrain_cost.copy()\n\n        # Overlay inflation cost (take max of terrain and inflation)\n        out = np.maximum(out, inflation_cost)\n\n        # Mark lethal cells (original + inscribed inflation)\n        all_lethal = lethal_mask | inscribed_mask\n        out[all_lethal] = 100\n\n        # Mark unknown cells\n        hm_unknown = ~valid_hm\n        out[hm_unknown] = -1\n\n        # Clamp non-lethal, non-unknown to [0, 99]\n        free_mask = ~all_lethal & valid_hm\n        out[free_mask] = np.clip(out[free_mask], 0, 99)\n\n        out = out.astype(np.int8)\n"}, "src/navstack/navstack_nav2/launch/roar_nav2_only.launch.py:263-290": {"file": "src/navstack/navstack_nav2/launch/roar_nav2_only.launch.py", "lines": "263-290", "start_line": 263, "end_line": 290, "language": "py", "code": "    # Behavior tree orchestrator — exposes the /navigate_to_pose action\n    bt_navigator = Node(\n        package='nav2_bt_navigator',\n        executable='bt_navigator',\n        name='bt_navigator',\n        output='screen',\n        parameters=[nav_params, {'use_sim_time': True}]\n    )\n\n    lifecycle = Node(\n        package='nav2_lifecycle_manager',\n        executable='lifecycle_manager',\n        name='lifecycle_manager_navigation',\n        output='screen',\n        parameters=[{\n            'use_sim_time': True,\n            'autostart': True,\n            'bond_timeout': 0.0,\n            'node_names': [\n                'map_server',\n                'planner_server',\n                'controller_server',\n                'behavior_server',\n                'bt_navigator',\n            ]\n        }]\n    )\n"}, "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp:265-312": {"file": "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp", "lines": "265-312", "start_line": 265, "end_line": 312, "language": "cpp", "code": "    if (enable_clearance_field_ && clearance_m_.size() == current_map_size)\n      computeClearanceField(current_costs, current_map_size);\n\n    const bool goal_changed = (new_goal != goal_idx_);\n    const bool start_changed = (new_start != start_idx_);\n    const bool can_incremental = enable_incremental_updates_ &&\n                                 !goal_changed &&\n                                 last_costs_.size() == current_map_size;\n\n    if (goal_changed) {\n      // Goal changed: full re-initialization required\n      start_idx_ = new_start;\n      goal_idx_  = new_goal;\n      last_start_idx_ = start_idx_;\n      initializePlannerState();\n      computeShortestPath();\n    }\n    else if (can_incremental) {\n      // D* Lite km_ accumulation: compensate for robot movement\n      if (start_changed) {\n        km_ += heuristic(last_start_idx_, new_start);\n        start_idx_ = new_start;\n        last_start_idx_ = start_idx_;\n      }\n\n      // Diff costmap and update changed vertices\n      for (size_t i = 0; i < current_map_size; ++i) {\n        if (last_costs_[i] == current_costs[i]) continue;\n        const unsigned int idx = static_cast<unsigned int>(i);\n        updateVertex(idx);\n        const NeighborList nbrs = getNeighbors(idx);\n        for (int k = 0; k < nbrs.count; ++k)\n          updateVertex(nbrs.indices[k]);\n      }\n      computeShortestPath();\n    }\n    else {\n      start_idx_ = new_start;\n      goal_idx_  = new_goal;\n      last_start_idx_ = start_idx_;\n      initializePlannerState();\n      computeShortestPath();\n    }\n\n    if (!std::isfinite(g_[start_idx_])) {\n      RCLCPP_WARN(logger_, \"No D* Lite path found to goal\");\n      return plan;\n    }"}, "src/navstack/navstack_nav2/config/roar_nav2_sim.yaml:82-156": {"file": "src/navstack/navstack_nav2/config/roar_nav2_sim.yaml", "lines": "82-156", "start_line": 82, "end_line": 156, "language": "yaml", "code": "    FollowPath:\n      plugin: \"nav2_mppi_controller::MPPIController\"\n      time_steps: 56\n      model_dt: 0.05\n      batch_size: 2000\n      vx_std: 0.35\n      vy_std: 0.0\n      wz_std: 0.6\n      vx_max: 0.7\n      vx_min: 0.0\n      wz_max: 1.2\n      iteration_count: 2\n      prune_distance: 3.5\n      transform_tolerance: 0.35\n      temperature: 0.25\n      gamma: 0.015\n      motion_model: \"DiffDrive\"\n      visualize: true\n      reset_period: 1.0\n      regenerate_noises: false\n      TrajectoryVisualizer:\n        trajectory_step: 5\n        time_step: 3\n      critics: [\"ConstraintCritic\", \"GoalCritic\", \"GoalAngleCritic\", \"ObstaclesCritic\", \"PathAlignCritic\", \"PathFollowCritic\", \"PathAngleCritic\", \"PreferForwardCritic\"]\n      ConstraintCritic:\n        enabled: true\n        cost_power: 1\n        cost_weight: 4.0\n      GoalCritic:\n        enabled: true\n        cost_power: 1\n        cost_weight: 8.0\n        threshold_to_consider: 1.0\n      GoalAngleCritic:\n        enabled: true\n        cost_power: 1\n        cost_weight: 4.0\n        threshold_to_consider: 0.5\n      PreferForwardCritic:\n        enabled: true\n        cost_power: 1\n        cost_weight: 15.0\n        threshold_to_consider: 0.5\n      ObstaclesCritic:\n        enabled: true\n        cost_power: 1\n        repulsion_weight: 5.0\n        critical_weight: 50.0\n        consider_footprint: true\n        collision_cost: 100000.0\n        collision_margin_distance: 0.5\n        near_goal_distance: 0.8\n      PathAlignCritic:\n        enabled: true\n        cost_power: 1\n        cost_weight: 3.0\n        max_path_occupancy_ratio: 0.95\n        trajectory_point_step: 4\n        threshold_to_consider: 0.5\n        offset_from_furthest: 15\n        use_path_orientations: false\n      PathFollowCritic:\n        enabled: true\n        cost_power: 1\n        cost_weight: 10.0\n        offset_from_furthest: 15\n        threshold_to_consider: 1.0\n      PathAngleCritic:\n        enabled: true\n        cost_power: 1\n        cost_weight: 2.0\n        offset_from_furthest: 4\n        threshold_to_consider: 0.35\n        max_angle_to_furthest: 1.5\n"}, "src/navigation/scripts/asu_roar_gui.py:1124-1223": {"file": "src/navigation/scripts/asu_roar_gui.py", "lines": "1124-1223", "start_line": 1124, "end_line": 1223, "language": "py", "code": "        # 1. Launch simulation — same command as the \"1. LAUNCH SIM\" button.\n        world_name = f\"world{world_num}\"\n        sim_cmd = (f\"cd {self.ws_root} && source /opt/ros/jazzy/setup.bash && \" \\\n                   f\"source install/setup.bash && \" \\\n                   f\"cd src/roar2026/dev_environment && ROAR_HEADLESS={'true' if hasattr(self, 'cb_headless') and self.cb_headless.isChecked() else 'false'} bash launch_test.sh {rover_cfg} {world_name}\")\n        self._open_in_terminal(sim_cmd, f\"BATCH SIM: {mission_id}\", keep_open=False)\n\n        self._batch_wait_for_sim_ready(generation, elapsed=0)\n\n    def _batch_wait_for_sim_ready(self, generation, elapsed):\n        if generation != self._batch_generation:\n            return  # item was aborted/skipped while waiting\n\n        if self.sim_ready:\n            self._batch_launch_nav(generation)\n            return\n\n        if elapsed >= self.SIM_READY_TIMEOUT_S:\n            self._batch_abort_item(\"simulation never became ready\")\n            return\n\n        QTimer.singleShot(\n            self.BATCH_READY_POLL_MS,\n            lambda: self._batch_wait_for_sim_ready(generation, elapsed + self.BATCH_READY_POLL_MS / 1000)\n        )\n\n    def _batch_launch_nav(self, generation):\n        if generation != self._batch_generation:\n            return\n\n        ctx = self._batch_item_ctx\n        # 2. Launch Nav2 — same command as the \"2. LAUNCH NAV2\" button, plus the\n        # rviz/enable_slam args master_evaluation.launch.py already passes it today.\n        nav_cmd = (f\"cd {self.ws_root} && source /opt/ros/jazzy/setup.bash && \" \\\n                   f\"source install/setup.bash && \" \\\n                   f\"ros2 launch navstack_nav2 roar_nav2_only.launch.py \"\n                   f\"rviz:={ctx['rviz_val']} enable_slam:={ctx.get('slam_val', 'true')}\")\n        self._open_in_terminal(nav_cmd, f\"BATCH NAV2: {ctx['mission_id']}\", keep_open=False)\n\n        self._nav_ready = False\n        self._batch_wait_for_nav_ready(generation, elapsed=0)\n\n    def _check_nav_ready_worker(self):\n        try:\n            cmd = \"source /opt/ros/jazzy/setup.bash && ros2 action list\"\n            result = subprocess.run([\"bash\", \"-c\", cmd], capture_output=True, text=True, timeout=1.5)\n            self._nav_ready = (\"/navigate_to_pose\" in result.stdout)\n        except Exception:\n            pass\n\n    def _batch_wait_for_nav_ready(self, generation, elapsed):\n        if generation != self._batch_generation:\n            return  # item was aborted/skipped while waiting\n\n        if self._nav_ready:\n            self._batch_launch_referee_and_waypoints(generation)\n            return\n\n        if elapsed >= self.NAV_READY_TIMEOUT_S:\n            self._batch_abort_item(\"nav2 never became ready\")\n            return\n\n        threading.Thread(target=self._check_nav_ready_worker, daemon=True).start()\n        QTimer.singleShot(\n            self.BATCH_READY_POLL_MS,\n            lambda: self._batch_wait_for_nav_ready(generation, elapsed + self.BATCH_READY_POLL_MS / 1000)\n        )\n\n    def _batch_launch_referee_and_waypoints(self, generation):\n        if generation != self._batch_generation:\n            return\n\n        ctx = self._batch_item_ctx\n        mission_id = ctx[\"mission_id\"]\n\n        # 3. Launch the referee/evaluators — mirrors the eval_launch include inside\n        # master_evaluation.launch.py, now fired only once Nav2 is confirmed ready.\n        referee_cmd = (\\\n            f\"cd {self.ws_root} && source /opt/ros/jazzy/setup.bash && \" \\\n            f\"source install/setup.bash && \" \\\n            f\"ros2 launch referee_engine roar_full_evaluation.launch.py \"\n            f\"mission:={mission_id} world_num:={ctx['world_num']} run_mock:=false \"\n            f\"enable_slam:={ctx.get('slam_val', 'false')} enable_perception:={ctx.get('perc_val', 'true')} enable_pursuit:={ctx.get('pursuit_val', 'true')}\"\n        )\n        self._open_in_terminal(referee_cmd, f\"BATCH REFEREE: {mission_id}\", keep_open=False)\n\n        # 4. Send waypoints — same follower invocation as the \"3. SEND WPTS\" button,\n        # with the same graceful teardown, tracked so we know when the item is done.\n        kills = \"pkill -2 -f ros2; pkill -2 -f gz; pkill -2 -f ruby; pkill -2 -f rviz2; pkill -2 -f nav2\"\n        wp_cmd = (\\\n            f\"cd {self.ws_root} && source /opt/ros/jazzy/setup.bash && \" \\\n            f\"source install/setup.bash && \" \\\n            f\"python3 {self.nav_ws}/path-planning/globalPlanner/scripts/batch_waypoint_follower.py --params {self.yaml_path} ; \"\n            f\"echo 'Waypoints finished. Tearing down batch item...' ; sleep 2 ; {kills}\"\n        )\n\n        self.batch_process = QProcess(self)\n        self.batch_process.finished.connect(lambda: self._on_batch_process_finished(generation))\n        self.batch_process.start(\"gnome-terminal\", [\"--wait\", \"--title\", f\"BATCH WPTS: {mission_id}\", \"--\", \"bash\", \"-c\", wp_cmd])\n"}, "src/navstack/path-planning/globalPlanner/scripts/batch_waypoint_follower.py:26-68": {"file": "src/navstack/path-planning/globalPlanner/scripts/batch_waypoint_follower.py", "lines": "26-68", "start_line": 26, "end_line": 68, "language": "py", "code": "    def navigate_to_waypoint(self, x, y):\n        self.get_logger().info(f\"\\n---> Connecting to '/navigate_to_pose' Action Server...\")\n        if not self.client.wait_for_server(timeout_sec=120.0):\n            self.get_logger().error(\"Action server '/navigate_to_pose' not available.\")\n            return False\n\n        goal_msg = NavigateToPose.Goal()\n        goal_msg.pose.header.frame_id = 'map'\n        goal_msg.pose.header.stamp = self.get_clock().now().to_msg()\n        goal_msg.pose.pose.position.x = x\n        goal_msg.pose.pose.position.y = y\n        goal_msg.pose.pose.orientation.w = 1.0\n\n        self.get_logger().info(f\"Sending waypoint goal: ({x:.2f}, {y:.2f})\")\n        send_goal_future = self.client.send_goal_async(goal_msg)\n        \n        # Wait for goal acceptance\n        rclpy.spin_until_future_complete(self, send_goal_future)\n        goal_handle = send_goal_future.result()\n\n        if not goal_handle.accepted:\n            self.get_logger().error(\"Goal was rejected by the action server.\")\n            return False\n\n        self.get_logger().info(\"Goal accepted. Moving to waypoint...\")\n        get_result_future = goal_handle.get_result_async()\n        \n        # Wait for execution result\n        rclpy.spin_until_future_complete(self, get_result_future)\n        result = get_result_future.result()\n        \n        if result.status == GoalStatus.STATUS_SUCCEEDED:\n            self.get_logger().info(\"Target waypoint reached!\")\n            if self.current_pose is not None:\n                rx = self.current_pose.position.x\n                ry = self.current_pose.position.y\n                dist = math.hypot(rx - x, ry - y)\n                self.get_logger().info(f\"Final Pose: ({rx:.2f}, {ry:.2f}) | Distance error: {dist:.3f}m\")\n            return True\n        else:\n            self.get_logger().error(f\"Failed to reach waypoint. Goal status: {result.status}\")\n            return False\n"}, "src/navigation/referee_engine/referee_engine/collision_monitor_node.py:35-95": {"file": "src/navigation/referee_engine/referee_engine/collision_monitor_node.py", "lines": "35-95", "start_line": 35, "end_line": 95, "language": "py", "code": "        # Non-collidable meshes as requested by the user\n        self.safe_meshes = {5, 6, 7, 8, 9}\n\n        sensors = [\n            ('base_footprint', 'base_link_contact'),\n            ('wheel_rhs_front', 'wheel_rhs_front_contact'),\n            ('wheel_rhs_mid', 'wheel_rhs_mid_contact'),\n            ('wheel_rhs_rear', 'wheel_rhs_rear_contact'),\n            ('wheel_lhs_front', 'wheel_lhs_front_contact'),\n            ('wheel_lhs_mid', 'wheel_lhs_mid_contact'),\n            ('wheel_lhs_rear', 'wheel_lhs_rear_contact'),\n        ]\n\n        self.subs = []\n        for link, sensor in sensors:\n            topic = f'/world/{world_name}/model/{model_name}/link/{link}/sensor/{sensor}/contact'\n            sub = self.create_subscription(\n                Contacts,\n                topic,\n                self.contact_callback,\n                10\n            )\n            self.subs.append(sub)\n            self.get_logger().info(f\"Subscribed to contact topic: {topic}\")\n\n        # Timer to reset the flag if no contacts have been received recently\n        self.timer = self.create_timer(0.5, self.timer_callback)\n        self.last_contact_time = self.get_clock().now()\n        self.is_colliding = False\n\n    def contact_callback(self, msg: Contacts):\n        if not msg.contacts:\n            return\n\n        for contact in msg.contacts:\n            c1 = contact.collision1.name\n            c2 = contact.collision2.name\n            \n            # Find the obstacle name (e.g., \"Rock_5::link::collision\")\n            obstacle_name = c2 if \"roar_rover\" in c1 else c1\n            \n            if \"Rock_\" in obstacle_name:\n                # Extract the base entity name (e.g., \"Rock_5\")\n                entity_name = obstacle_name.split(\"::\")[0]\n                \n                # Look up the mesh_id for this entity\n                mesh_id = self.entity_to_mesh.get(entity_name, -1)\n                \n                if mesh_id in self.safe_meshes:\n                    # It's one of the non-collidable meshes (4,5,6,7,9), ignore it!\n                    continue\n\n            # If we get here, it's a valid fatal collision (collidable rock, wall, etc.)\n            self.is_colliding = True\n            self.last_contact_time = self.get_clock().now()\n            \n            flag_msg = Bool()\n            flag_msg.data = True\n            self.pub.publish(flag_msg)\n            return  # Trigger alarm immediately\n"}, "src/navigation/referee_engine/referee_engine/score_calculator.py:23-166": {"file": "src/navigation/referee_engine/referee_engine/score_calculator.py", "lines": "23-166", "start_line": 23, "end_line": 166, "language": "py", "code": "class ScoreCalculator:\n    \"\"\"\n    ERC Navigation Task Score Calculator (TRAVERSE SUB-TASK: MAX 300 POINTS)\n\n    Rules Implemented:\n    1. O/NAV-010: Waypoint reached -> MAX(0, round(30 - 6 * d)) where d is edge distance (Max 120 pts total, 30 per wp)\n    2. O/NAV-020: Autonomy bonus -> 25 pts per waypoint reached in autonomous mode (Max 100 pts)\n    3. O/NAV-030: Back to start -> 25 pts if rover center is within 1m of start at finish (requires >=1 wp reached)\n    4. O/NAV-040: Back to start autonomy bonus -> 25 pts if back to start done in autonomous mode\n    5. O/NAV-050: Execution of Traversal Plan -> 6 pts per completed leg following plan (Max 30 pts for 5 legs)\n    6. O/NAV-060: Penalty points return -> -5 per return request\n    7. O/NAV-070 to O/NAV-100: Ignored\n    8. O/NAV-110: Penalty points - only GNSS feed used -> -20% deduction on traverse points\n    \"\"\"\n    def __init__(self, config: ScoreCalculatorConfig = ScoreCalculatorConfig()):\n        self.config = config\n\n    def calculate_edge_distance(self, center_distance: float) -> float:\n        \"\"\"Calculate distance in meters from the edge of the rover's body to the target waypoint.\"\"\"\n        return max(0.0, center_distance - self.config.rover_radius)\n\n    def score_waypoint_reached(self, d_edge: float) -> float:\n        \"\"\"\n        O/NAV-010: Waypoint reached score.\n        MAX(0, round(30 - (6 * d))) where d is edge distance in meters.\n        \"\"\"\n        raw_score = round(30.0 - (6.0 * d_edge))\n        return max(0.0, min(self.config.max_pts_per_waypoint, float(raw_score)))\n\n    def final_score(\n        self,\n        waypoint_details: List[Dict[str, Any]],\n        back_to_start_detail: Optional[Dict[str, Any]] = None,\n        num_return_requests: int = 0,\n        only_gnss_used: bool = False,\n        elapsed_time: float = 0.0,\n        is_fatal: bool = False,\n    ) -> Dict[str, Any]:\n        \"\"\"\n        Compute the official ERC Navigation Task score.\n        If is_fatal is True (crash, collision, out of boundaries), score is immediately 0.\n        If mission is timed out, the accumulated score up to timeout is preserved and returned.\n        \"\"\"\n        if is_fatal:\n            return {\n                \"traverse_score\": 0.0,\n                \"droning_score\": 0.0,\n                \"final_score\": 0.0,\n                \"max_possible_score\": 300.0,\n                \"nav_010_waypoint_reached\": 0.0,\n                \"nav_020_autonomy_bonus\": 0.0,\n                \"nav_030_back_to_start\": 0.0,\n                \"nav_040_back_to_start_autonomy\": 0.0,\n                \"nav_050_traversal_plan\": 0.0,\n                \"nav_060_return_penalty\": 0.0,\n                \"nav_110_gnss_penalty_applied\": False,\n                \"waypoint_details\": waypoint_details,\n                \"back_to_start_detail\": back_to_start_detail,\n                \"is_fatal\": True,\n                \"fatal_reason\": \"Collision or Out of Boundaries\",\n                \"elapsed_time_sec\": elapsed_time,\n            }\n\n        # 1. O/NAV-010 & O/NAV-020: Waypoint Scores\n        nav_010_total = 0.0\n        nav_020_total = 0.0\n        successful_waypoints_count = 0\n\n        processed_wp_details = []\n        for wp in waypoint_details:\n            d_center = wp.get(\"d_center\", wp.get(\"dmin\", 0.0))\n            d_edge = self.calculate_edge_distance(d_center)\n            is_auto = wp.get(\"is_autonomous\", True)\n            is_reached = wp.get(\"reached\", True) and wp.get(\"status\", \"REACHED\") != \"FAILED\"\n\n            if is_reached:\n                wp_score_010 = self.score_waypoint_reached(d_edge)\n                wp_score_020 = self.config.autonomy_bonus_per_waypoint if is_auto else 0.0\n                successful_waypoints_count += 1\n            else:\n                wp_score_010 = 0.0\n                wp_score_020 = 0.0\n\n            nav_010_total += wp_score_010\n            nav_020_total += wp_score_020\n\n            processed_wp_details.append({\n                \"id\": wp.get(\"id\", \"WP\"),\n                \"timestamp\": wp.get(\"timestamp\", 0.0),\n                \"d_center\": d_center,\n                \"d_edge\": d_edge,\n                \"positional_error\": d_center,\n                \"score_010\": wp_score_010,\n                \"score_020\": wp_score_020,\n                \"total_score\": wp_score_010 + wp_score_020,\n                \"is_autonomous\": is_auto,\n                \"reached\": is_reached,\n                \"status\": wp.get(\"status\", \"REACHED\" if is_reached else \"FAILED\"),\n                \"stop_pose\": wp.get(\"stop_pose\", (0.0, 0.0)),\n            })\n\n        # Cap sub-totals according to ERC rules\n        nav_010_total = min(120.0, nav_010_total)\n        nav_020_total = min(100.0, nav_020_total)\n\n        # 2. O/NAV-030 & O/NAV-040: Back to Start Scores\n        nav_030_total = 0.0\n        nav_040_total = 0.0\n\n        if back_to_start_detail is not None and successful_waypoints_count >= 1:\n            dist_start = back_to_start_detail.get(\"d_center\", back_to_start_detail.get(\"dist_to_start\", 999.0))\n            is_auto_start = back_to_start_detail.get(\"is_autonomous\", True)\n\n            if dist_start <= 1.0:\n                nav_030_total = self.config.back_to_start_reward\n                if is_auto_start:\n                    nav_040_total = self.config.back_to_start_autonomy_reward\n\n        # 3. O/NAV-050: Execution of Traversal Plan (6 pts per completed leg, max 30 pts for 5 legs)\n        legs_completed = successful_waypoints_count\n        if back_to_start_detail is not None and back_to_start_detail.get(\"d_center\", 999.0) <= 1.0:\n            legs_completed += 1\n        nav_050_total = min(30.0, legs_completed * self.config.traversal_plan_score_per_leg)\n\n        # 4. O/NAV-060: Return Penalties (-5 per return request)\n        nav_060_total = -1.0 * (num_return_requests * self.config.return_penalty_per_req)\n\n        # Raw traverse score sum\n        raw_traverse_score = (\n            nav_010_total\n            + nav_020_total\n            + nav_030_total\n            + nav_040_total\n            + nav_050_total\n            + nav_060_total\n        )\n\n        # 5. O/NAV-110: Only GNSS feed used -> 20% penalty on total traverse score\n        traverse_score = max(0.0, raw_traverse_score)\n        if only_gnss_used:\n            traverse_score *= 0.80\n\n        traverse_score = min(300.0, max(0.0, traverse_score))\n"}, "src/navigation/referee_engine/referee_engine/report_generator_node.py:31-45": {"file": "src/navigation/referee_engine/referee_engine/report_generator_node.py", "lines": "31-45", "start_line": 31, "end_line": 45, "language": "py", "code": "    def score_callback(self, msg: String):\n        try:\n            self.latest_score = json.loads(msg.data)\n            if isinstance(self.latest_score, dict):\n                status = self.latest_score.get(\"terminal_status\", \"RUNNING\")\n                # Always generate live report file\n                self.generate_terminal_report(status, is_live=True)\n\n                if self.latest_score.get(\"is_final\", False) and not self.report_generated:\n                    self.get_logger().info(f\"Final score payload received for status '{status}'. Saving final HTML report...\")\n                    self.generate_terminal_report(status, is_live=False)\n                    self.report_generated = True\n        except json.JSONDecodeError:\n            self.latest_score = msg.data\n"}, "src/navigation/scripts/asu_roar_gui.py:1451-1457": {"file": "src/navigation/scripts/asu_roar_gui.py", "lines": "1451-1457", "start_line": 1451, "end_line": 1457, "language": "py", "code": "    def _check_sim_ready_worker(self):\n        try:\n            cmd = \"source /opt/ros/jazzy/setup.bash && ros2 topic list\"\n            result = subprocess.run([\"bash\", \"-c\", cmd], capture_output=True, text=True, timeout=3.0)\n            self.sim_ready = (\"/diff_drive_controller/odom\" in [t.strip() for t in result.stdout.splitlines()])\n        except Exception:\n            pass"}, "src/navigation/scripts/asu_roar_gui.py:1166-1185": {"file": "src/navigation/scripts/asu_roar_gui.py", "lines": "1166-1185", "start_line": 1166, "end_line": 1185, "language": "py", "code": "    def _check_nav_ready_worker(self):\n        try:\n            cmd = \"source /opt/ros/jazzy/setup.bash && ros2 action list\"\n            result = subprocess.run([\"bash\", \"-c\", cmd], capture_output=True, text=True, timeout=1.5)\n            self._nav_ready = (\"/navigate_to_pose\" in result.stdout)\n        except Exception:\n            pass\n\n    def _batch_wait_for_nav_ready(self, generation, elapsed):\n        if generation != self._batch_generation:\n            return  # item was aborted/skipped while waiting\n\n        if self._nav_ready:\n            self._batch_launch_referee_and_waypoints(generation)\n            return\n\n        if elapsed >= self.NAV_READY_TIMEOUT_S:\n            self._batch_abort_item(\"nav2 never became ready\")\n            return\n"}, "src/roar2026/navMission_setup/master_pipeline.sh:13-61": {"file": "src/roar2026/navMission_setup/master_pipeline.sh", "lines": "13-61", "start_line": 13, "end_line": 61, "language": "sh", "code": "echo \"[1/4] Building Worlds (1, 2, 3) and applying NavMission setup...\"\ncd \"${SCRIPT_DIR}\"\n./build_full_worlds.sh\n\n# 2. Waypoint Generation & Mission Sync\necho \"[2/4] Fusing Waypoints and Syncing to Mission Workspace...\"\ncd \"${SCRIPT_DIR}/waypoints_setup/wayPoint_generator\"\n\nfor w in 1 2 3; do\n    echo \"  -> Processing waypoints for World $w...\"\n    \n    rm -f inputs/heightmap.npz inputs/obstacle_data*.npy\n    DEV_WORLD=\"${SIM_DIR}/dev_environment/worlds/world$w\"\n    \n    if [ -f \"$DEV_WORLD/heightmap.npz\" ]; then\n        cp \"$DEV_WORLD/heightmap.npz\" inputs/heightmap.npz\n    fi\n    if [ -f \"$DEV_WORLD/obstacle_data.npy\" ]; then\n        cp \"$DEV_WORLD/obstacle_data.npy\" inputs/obstacle_data.npy\n    fi\n    \n    python3 wp_generator.py\n    \n    # Sync to Mission Workspace\n    MISSION_DIR=\"${WS_ROOT}/src/navigation/missions/mission_$w/waypoints\"\n    mkdir -p \"$MISSION_DIR\"\n    \n    for wp_file in outputs/wp*.npy; do\n        if [ -f \"$wp_file\" ]; then\n            wp_name=$(basename \"$wp_file\" .npy)\n            mkdir -p \"$MISSION_DIR/$wp_name\"\n            cp \"$wp_file\" \"$MISSION_DIR/$wp_name/$wp_name.npy\"\n        fi\n    done\n    \n    # Sync costmap, obstacle_data, and aruco_data to mission assets\n    ASSETS_DIR=\"${WS_ROOT}/src/navigation/missions/mission_$w/assets\"\n    mkdir -p \"$ASSETS_DIR\"\n    if [ -f \"$DEV_WORLD/costmap.npz\" ]; then\n        cp \"$DEV_WORLD/costmap.npz\" \"$ASSETS_DIR/costmap.npz\"\n    fi\n    if [ -f \"$DEV_WORLD/obstacle_data.npy\" ]; then\n        cp \"$DEV_WORLD/obstacle_data.npy\" \"$ASSETS_DIR/obstacle_data.npy\"\n    fi\n    ARUCO_MAP=\"${WS_ROOT}/src/navstack/slam/roar_localization/config/aruco_map.yaml\"\n    if [ -f \"$ARUCO_MAP\" ]; then\n        cp \"$ARUCO_MAP\" \"$ASSETS_DIR/aruco_data.yaml\"\n    fi\ndone"}, "src/roar2026/dev_environment/rover/roar_simulation_full/launch/basic_rover.launch.py:281-306": {"file": "src/roar2026/dev_environment/rover/roar_simulation_full/launch/basic_rover.launch.py", "lines": "281-306", "start_line": 281, "end_line": 306, "language": "py", "code": "        # Wait for spawn → wait 12 s → start joint state broadcaster\n        RegisterEventHandler(\n            event_handler=OnProcessExit(\n                target_action=spawn_entity,\n                on_exit=[TimerAction(\n                    period=12.0,\n                    actions=[joint_state_broadcaster_spawner]\n                )]\n            )\n        ),\n\n        # Joint broadcaster done → start diff_drive controller\n        RegisterEventHandler(\n            event_handler=OnProcessExit(\n                target_action=joint_state_broadcaster_spawner,\n                on_exit=[diff_drive_controller_spawner]\n            )\n        ),\n\n        # Diff drive done → start arm controller (activates arm hardware, fixes arm TF in RViz)\n        RegisterEventHandler(\n            event_handler=OnProcessExit(\n                target_action=diff_drive_controller_spawner,\n                on_exit=[arm_controller_spawner]\n            )\n        ),"}, "src/roar2026/dev_environment/rover/roar_simulation_full/src/zed_degradation_node.py:89-106": {"file": "src/roar2026/dev_environment/rover/roar_simulation_full/src/zed_degradation_node.py", "lines": "89-106", "start_line": 89, "end_line": 106, "language": "py", "code": "        self.camera_info_sub = self.create_subscription(\n            CameraInfo,\n            '/zed2i/camera_info',\n            self.camera_info_callback,\n            qos_profile_sensor_data\n        )\n        self.rgb_sub = self.create_subscription(\n            Image,\n            '/zed2i/image_raw',\n            self.rgb_callback,\n            qos_profile_sensor_data\n        )\n        self.depth_sub = self.create_subscription(\n            Image,\n            '/zed2i/depth',\n            self.depth_callback,\n            qos_profile_sensor_data\n        )"}, "src/roar2026/dev_environment/rover/roar_simulation_full/src/zed_degradation_node.py:300-337": {"file": "src/roar2026/dev_environment/rover/roar_simulation_full/src/zed_degradation_node.py", "lines": "300-337", "start_line": 300, "end_line": 337, "language": "py", "code": "            # Generate PointCloud2\n            X = self.X_factor * cv_depth\n            Y = self.Y_factor * cv_depth\n\n            if self.latest_rgb is not None and self.latest_rgb.shape[:2] == (h, w):\n                rgb_src = self.latest_rgb\n                R_chan = rgb_src[..., 2].astype(np.uint32)\n                G_chan = rgb_src[..., 1].astype(np.uint32)\n                B_chan = rgb_src[..., 0].astype(np.uint32)\n                rgb_packed = ((R_chan << 16) | (G_chan << 8) | B_chan).view(np.float32)\n            else:\n                neutral = np.uint32((200 << 16) | (200 << 8) | 200).view(np.float32)\n                rgb_packed = np.full((h, w), neutral, dtype=np.float32)\n\n            pc_valid = np.isfinite(cv_depth) & (cv_depth > 0.0)\n            points = np.stack(\n                (X[pc_valid], Y[pc_valid], cv_depth[pc_valid], rgb_packed[pc_valid]),\n                axis=-1\n            ).astype(np.float32)\n\n            pc2 = PointCloud2()\n            pc2.header = degraded_depth_msg.header\n            pc2.height = 1\n            pc2.width = len(points)\n            pc2.is_dense = False\n            pc2.is_bigendian = False\n            pc2.fields = [\n                PointField(name='x', offset=0, datatype=PointField.FLOAT32, count=1),\n                PointField(name='y', offset=4, datatype=PointField.FLOAT32, count=1),\n                PointField(name='z', offset=8, datatype=PointField.FLOAT32, count=1),\n                PointField(name='rgb', offset=12, datatype=PointField.FLOAT32, count=1),\n            ]\n            pc2.point_step = 16\n            pc2.row_step = 16 * len(points)\n            pc2.data = points.tobytes()\n\n            self.pc_pub.publish(pc2)\n        except Exception as e:"}, "src/roar2026/dev_environment/rover/roar_simulation_full/src/encoder_sim_node.py:50-75": {"file": "src/roar2026/dev_environment/rover/roar_simulation_full/src/encoder_sim_node.py", "lines": "50-75", "start_line": 50, "end_line": 75, "language": "py", "code": "    def joint_state_cb(self, msg: JointState):\n        left_pos = None\n        right_pos = None\n        for name, pos in zip(msg.name, msg.position):\n            if name == self.left_joint:\n                left_pos = pos\n            elif name == self.right_joint:\n                right_pos = pos\n\n        if left_pos is None or right_pos is None:\n            self.get_logger().warn(\n                \"left/right joint not found in /joint_states yet — skipping\",\n                throttle_duration_sec=3.0,\n            )\n            return\n\n        # radians -> simulated pulse count (rounded, so it actually quantizes\n        # like a real encoder instead of passing through a perfect float)\n        left_pulses  = round(left_pos  / (2.0 * math.pi) * self.pulses_per_rev)\n        right_pulses = round(right_pos / (2.0 * math.pi) * self.pulses_per_rev)\n\n        out = JointState()\n        out.header = msg.header\n        out.name = [self.left_joint, self.right_joint]\n        out.position = [float(left_pulses), float(right_pulses)]\n        self.pub.publish(out)"}, "src/roar2026/dev_environment/rover/roar_simulation_full/src/collision_alarm_node.py:20-49": {"file": "src/roar2026/dev_environment/rover/roar_simulation_full/src/collision_alarm_node.py", "lines": "20-49", "start_line": 20, "end_line": 49, "language": "py", "code": "    def contact_callback(self, msg):\n        alarm_msg = Bool()\n        \n        current_collision = False\n        hit_details = \"\"\n        \n        for contact in msg.contacts:\n            c1 = contact.collision1.name.lower() if hasattr(contact.collision1, 'name') else str(contact.collision1)\n            c2 = contact.collision2.name.lower() if hasattr(contact.collision2, 'name') else str(contact.collision2)\n            \n            # Ignore the ground / mars_yard terrain\n            if 'mars_yard' not in c1 and 'mars_yard' not in c2 and 'ground' not in c1 and 'ground' not in c2 and 'terrain' not in c1 and 'terrain' not in c2:\n                current_collision = True\n                hit_details = f\"{c1} <-> {c2}\"\n                break\n        \n        if current_collision:\n            alarm_msg.data = True\n            self.publisher.publish(alarm_msg)\n            \n            if not self.is_colliding:\n                self.get_logger().warn(f'OBSTACLE COLLISION DETECTED! Details: {hit_details}')\n                self.is_colliding = True\n        else:\n            alarm_msg.data = False\n            self.publisher.publish(alarm_msg)\n            \n            if self.is_colliding:\n                self.get_logger().info('Rover is clear of obstacles.')\n                self.is_colliding = False"}, "src/navstack/perception/perception_module/lidar_cluster_node.py:152-203": {"file": "src/navstack/perception/perception_module/lidar_cluster_node.py", "lines": "152-203", "start_line": 152, "end_line": 203, "language": "py", "code": "        # ── Stage 0: GPU-accelerated ROI distance mask ───────────────────\n        points, colors = self._pc2_to_numpy_rgb(msg)\n        if points.shape[0] == 0:\n            return\n\n        if self._use_gpu:\n            # Upload to GPU, compute squared norms, threshold, download mask\n            pts_t  = o3c.Tensor(points, dtype=o3c.float32, device=self._gpu_device)\n            sq     = (pts_t * pts_t).sum(1)                     # Nx1 squared distances\n            mask_t = sq < float(p['max_dist'] ** 2)             # boolean mask on GPU\n            mask   = mask_t.cpu().numpy().astype(bool)\n        else:\n            mask = np.linalg.norm(points, axis=1) < p['max_dist']\n\n        points = points[mask]\n        colors = colors[mask]\n        if points.shape[0] == 0:\n            return\n\n        # Wrap in Open3D legacy PointCloud for the rest of the pipeline\n        pcd = o3d.geometry.PointCloud()\n        pcd.points = o3d.utility.Vector3dVector(points)\n        pcd.colors = o3d.utility.Vector3dVector(colors)\n\n        # ── Stage 1: Voxel-grid downsampling ────────────────────────────\n        pcd = pcd.voxel_down_sample(voxel_size=p['voxel_size'])\n        if len(pcd.points) < 10:\n            return\n\n        # ── Stage 2: Statistical Outlier Removal (SOR) ──────────────────\n        # Removes per-point speckle by comparing each point's mean\n        # neighbour distance to the global mean±σ across all points.\n        if p['sor_en'] and len(pcd.points) >= p['sor_k']:\n            pcd, _ = pcd.remove_statistical_outlier(\n                nb_neighbors=int(p['sor_k']),\n                std_ratio=float(p['sor_std'])\n            )\n            if len(pcd.points) < 5:\n                return\n\n        # ── Stage 3: Radius Outlier Removal (ROR) ───────────────────────\n        # Removes isolated points (sensor reflections) that survive SOR.\n        if p['ror_en'] and len(pcd.points) >= p['ror_n']:\n            pcd, _ = pcd.remove_radius_outlier(\n                nb_points=int(p['ror_n']),\n                radius=float(p['ror_r'])\n            )\n            if len(pcd.points) < 5:\n                return\n\n        # Publish clean cloud (with ground, for debugging in RViz)\n        self.filtered_pub.publish(self._pcd_to_pc2_rgb(pcd, msg.header))"}, "src/navstack/perception/perception_module/lidar_cluster_node.py:205-218": {"file": "src/navstack/perception/perception_module/lidar_cluster_node.py", "lines": "205-218", "start_line": 205, "end_line": 218, "language": "py", "code": "        # ── Stage 4: Slope-aware iterative RANSAC plane removal ─────────\n        # Strips ground + ramps while PRESERVING steep rock faces.\n        pcd_ng = self._remove_planes_slope_aware(pcd, p)\n        if pcd_ng is None or len(pcd_ng.points) == 0:\n            return\n\n        # ── Stage 4b: Surface-normal roughness filter ────────────────────\n        # Removes any remaining smooth-slope points; keeps only rough/sharp rock points.\n        if p['roughness_en']:\n            pcd_ng = self._roughness_filter(pcd_ng, p)\n            if pcd_ng is None or len(pcd_ng.points) < 5:\n                return\n\n        self.no_ground_pub.publish(self._pcd_to_pc2_rgb(pcd_ng, msg.header))"}, "src/navstack/perception/perception_module/lidar_cluster_node.py:281-293": {"file": "src/navstack/perception/perception_module/lidar_cluster_node.py", "lines": "281-293", "start_line": 281, "end_line": 293, "language": "py", "code": "            detections.detections.append(det)\n\n            # Build SLAM-format obstacle\n            slam_obs = ObstacleDetection()\n            slam_obs.position   = Point(x=cx, y=cy, z=cz)\n            slam_obs.dimensions = Vector3(x=sx, y=sy, z=sz)\n            slam_detections.detections.append(slam_obs)\n\n        # Publish\n        self.raw_cluster_pub.publish(raw_detections)\n        self.cluster_pub.publish(detections)\n        self.slam_pub.publish(slam_detections)\n        self._publish_markers(detections, msg.header)"}, "src/navstack/perception/perception_module/obstacle_publisher_node.py:53-55": {"file": "src/navstack/perception/perception_module/obstacle_publisher_node.py", "lines": "53-55", "start_line": 53, "end_line": 55, "language": "py", "code": "        self.sub = self.create_subscription(\n            Detection3DArray, '/detection/lidar_clusters', self.callback, 10)\n"}, "src/navstack/perception/perception_module/obstacle_publisher_node.py:204-223": {"file": "src/navstack/perception/perception_module/obstacle_publisher_node.py", "lines": "204-223", "start_line": 204, "end_line": 223, "language": "py", "code": "    def _publish_map(self):\n        \"\"\"Called by timer — publishes the full accumulated obstacle array.\"\"\"\n        if not self.obstacle_map:\n            return\n\n        world_frame = next(iter(self.obstacle_map.values()))['detection'].header.frame_id\n\n        out = Detection3DArray()\n        out.header.stamp    = self.latest_stamp if self.latest_stamp else self.get_clock().now().to_msg()\n        out.header.frame_id = world_frame\n\n        for entry in self.obstacle_map.values():\n            out.detections.append(entry['detection'])\n\n        self.obstacle_pub.publish(out)\n        # Pass the full map (with color info) to the marker builder\n        self._publish_markers(self.obstacle_map)\n\n        self.get_logger().debug(f'Map published: {len(out.detections)} obstacle(s) in \"{world_frame}\"')\n"}, "src/navstack/perception/perception_module/aruco_detector_node.py:152-167": {"file": "src/navstack/perception/perception_module/aruco_detector_node.py", "lines": "152-167", "start_line": 152, "end_line": 167, "language": "py", "code": "        # ── Subscribers ──────────────────────────────────────────────────\n        self.create_subscription(Image,      self.camera_topic, self._image_cb, qos_profile_sensor_data)\n        self.create_subscription(CameraInfo, self.info_topic,   self._info_cb,  10)\n\n        # ── Publishers ───────────────────────────────────────────────────\n        # Full 3-D detections (ID + 6-DOF pose + bbox size)\n        self.det3d_pub   = self.create_publisher(Detection3DArray, '/detection/aruco_3d',     10)\n        # Flat PoseArray for convenience (same order as Detection3DArray)\n        self.poses_pub   = self.create_publisher(PoseArray,         '/detection/aruco_poses',  10)\n        # Custom message format for SLAM\n        self.slam_pub    = self.create_publisher(ArucoDetectionArray, '/aruco/detections', 10)\n        # RViz markers\n        self.marker_pub  = self.create_publisher(MarkerArray,       '/visualization/aruco_markers', 10)\n        # Debug image with axes drawn\n        self.debug_pub   = self.create_publisher(Image,             '/detection/aruco_image',  10)\n"}, "src/navstack/slam/roar_localization/src/ieskf_node.cpp:421-474": {"file": "src/navstack/slam/roar_localization/src/ieskf_node.cpp", "lines": "421-474", "start_line": 421, "end_line": 474, "language": "cpp", "code": "void IESKFNode::arucoCallback(\n    const roar_msgs::msg::ArucoDetectionArray::SharedPtr msg)\n{\n    if (!aruco_enabled_ || aruco_map_.size() == 0) return;\n\n    const Mat3 R_body_to_world = quat_to_rot(current_orientation_);\n    const IESKFParams& fp      = filter_->getParams();\n\n    int applied = 0;\n\n    for (const auto& det : msg->detections)\n    {\n        diag_aruco_received_++;\n\n        // ── Distance filter ──────────────────────────────────────────────────\n        if (det.distance > aruco_max_distance_) continue;\n\n        // ── Look up marker world position ────────────────────────────────────\n        auto marker_world_opt = aruco_map_.getMarkerPosition(det.id);\n        if (!marker_world_opt) {\n            RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,\n                \"ArUco id=%d not in map — ignoring\", det.id);\n            continue;\n        }\n\n        // ── Extract marker position in camera optical frame ──────────────────\n        const Vec3 p_marker_camera(\n            det.pose_in_camera.position.x,\n            det.pose_in_camera.position.y,\n            det.pose_in_camera.position.z);\n\n        // ── Distance-scaled noise ────────────────────────────────────────────\n        // sigma_aruco grows linearly with distance — pixel error projects\n        // to larger world error as the marker is farther away.\n        const double sigma_aruco =\n            fp.sigma_aruco_base + fp.sigma_aruco_per_m * det.distance;\n\n        // ── Apply update ─────────────────────────────────────────────────────\n        filter_->updateAruco(\n            *marker_world_opt,\n            p_marker_camera,\n            R_body_to_world,\n            t_cam_in_body_,\n            R_cam_to_body_,\n            sigma_aruco);\n\n        ++applied;\n        diag_aruco_applied_++;\n    }\n\n    if (applied > 0) {\n        RCLCPP_DEBUG(get_logger(), \"Applied %d ArUco updates\", applied);\n    }\n}"}, "src/navstack/slam/roar_localization/src/ieskf_node.cpp:258-294": {"file": "src/navstack/slam/roar_localization/src/ieskf_node.cpp", "lines": "258-294", "start_line": 258, "end_line": 294, "language": "cpp", "code": "void IESKFNode::imuCallback(const sensor_msgs::msg::Imu::SharedPtr msg)\n{\n    const rclcpp::Time now = this->get_clock()->now();\n\n    // ── dt ────────────────────────────────────────────────────────────────────\n    if (first_imu_) {\n        last_imu_time_ = now;\n        first_imu_     = false;\n        return;\n    }\n    const double dt = (now - last_imu_time_).seconds();\n    last_imu_time_  = now;\n\n    if (dt <= 0.0 || dt > 0.5) {\n        RCLCPP_WARN(get_logger(), \"Skipping IMU step: dt=%.4f s\", dt);\n        return;\n    }\n\n    // ── Raw IMU data (still in IMU frame) ────────────────────────────────────\n    const Vec3 a_m_imu(msg->linear_acceleration.x,\n                       msg->linear_acceleration.y,\n                       msg->linear_acceleration.z);\n    const Vec3 omega_m_imu(msg->angular_velocity.x,\n                           msg->angular_velocity.y,\n                           msg->angular_velocity.z);\n    const Quat q_imu_raw(msg->orientation.w,\n                         msg->orientation.x,\n                         msg->orientation.y,\n                         msg->orientation.z);\n\n    // ── IMU mounting correction → body frame ─────────────────────────────────\n    const Vec3 a_m     = R_imu_to_body_ * a_m_imu;\n    const Vec3 omega_m = R_imu_to_body_ * omega_m_imu;\n    const Quat q_body  = (q_imu_raw * Quat(R_imu_to_body_.transpose())).normalized();\n    current_orientation_ = q_body;\n    current_angular_velocity_ = omega_m;\n"}, "src/navstack/slam/roar_localization/src/ieskf_node.cpp:380-416": {"file": "src/navstack/slam/roar_localization/src/ieskf_node.cpp", "lines": "380-416", "start_line": 380, "end_line": 416, "language": "cpp", "code": "void IESKFNode::zedPoseCallback(\n    const geometry_msgs::msg::PoseWithCovarianceStamped::SharedPtr msg)\n{\n    const Vec3 p_zed_raw(msg->pose.pose.position.x,\n                         msg->pose.pose.position.y,\n                         msg->pose.pose.position.z);\n\n    // ── ZED extrinsic correction: convert camera pose → base_link pose ───────\n    // p_base = p_zed_world − R_body_to_world × t_cam_in_body\n    const Mat3 R_cur  = quat_to_rot(current_orientation_);\n    const Vec3 p_base = p_zed_raw - R_cur * t_cam_in_body_;\n\n    // ── ZED confidence from covariance ───────────────────────────────────────\n    const double cov_trace =\n        msg->pose.covariance[0]  +\n        msg->pose.covariance[7]  +\n        msg->pose.covariance[14];\n    const double zed_confidence =\n        std::clamp(100.0 * std::exp(-cov_trace / zed_cov_scale_), 0.0, 100.0);\n\n    // ── WVO ──────────────────────────────────────────────────────────────────\n    WVOOutput wvo_out = wvo_->compute(p_base, accumulated_dp_wo_);\n    accumulated_dp_wo_ = Vec3::Zero();\n\n    // ── VO-FIS → k_V ─────────────────────────────────────────────────────────\n    const double k_V = vo_fis_.evaluate(zed_confidence, wvo_out.jump_ratio);\n    diag_last_k_V_ = k_V;\n\n    // ── IESKF update ─────────────────────────────────────────────────────────\n    if (wvo_out.valid && wvo_out.ready) {\n        filter_->update(wvo_out.z, k_V);\n    } else if (!wvo_out.valid) {\n        RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 2000,\n            \"WVO: ZED tracking lost (jump_ratio=%.2f, confidence=%.1f) — skipping update\",\n            wvo_out.jump_ratio, zed_confidence);\n    }\n}"}, "src/navstack/slam/roar_localization/src/ieskf_node.cpp:479-546": {"file": "src/navstack/slam/roar_localization/src/ieskf_node.cpp", "lines": "479-546", "start_line": 479, "end_line": 546, "language": "cpp", "code": "void IESKFNode::publishOdometry(const rclcpp::Time& stamp)\n{\n    const IESKFState& state = filter_->getState();\n    const auto&       P     = filter_->getCovariance();\n\n    nav_msgs::msg::Odometry odom;\n    odom.header.stamp    = stamp;\n    odom.header.frame_id = frame_id_;\n    odom.child_frame_id  = child_frame_id_;\n\n    odom.pose.pose.position.x = state.p.x();\n    odom.pose.pose.position.y = state.p.y();\n    odom.pose.pose.position.z = state.p.z();\n\n    odom.pose.pose.orientation.x = current_orientation_.x();\n    odom.pose.pose.orientation.y = current_orientation_.y();\n    odom.pose.pose.orientation.z = current_orientation_.z();\n    odom.pose.pose.orientation.w = current_orientation_.w();\n\n    const Vec3 velocity_body = quat_to_rot(current_orientation_).transpose() * state.v;\n    odom.twist.twist.linear.x = velocity_body.x();\n    odom.twist.twist.linear.y = velocity_body.y();\n    odom.twist.twist.linear.z = velocity_body.z();\n    odom.twist.twist.angular.x = current_angular_velocity_.x();\n    odom.twist.twist.angular.y = current_angular_velocity_.y();\n    odom.twist.twist.angular.z = current_angular_velocity_.z();\n\n    // 3×3 position covariance block\n    for (int i = 0; i < 3; ++i)\n        for (int j = 0; j < 3; ++j)\n            odom.pose.covariance[i * 6 + j] = P(i, j);\n\n    // Small fixed orientation covariance (BNO055 NDOF ≈ 1°)\n    const double ori_var = 0.017 * 0.017;\n    odom.pose.covariance[3*6+3] = ori_var;\n    odom.pose.covariance[4*6+4] = ori_var;\n    odom.pose.covariance[5*6+5] = ori_var;\n\n    // Velocity covariance\n    for (int i = 0; i < 3; ++i)\n        for (int j = 0; j < 3; ++j)\n            odom.twist.covariance[i * 6 + j] = P(3+i, 3+j);\n\n    pub_odom_->publish(odom);\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// publishTF — broadcast odom → base_link\n// ─────────────────────────────────────────────────────────────────────────────\nvoid IESKFNode::publishTF(const rclcpp::Time& stamp)\n{\n    const IESKFState& state = filter_->getState();\n\n    geometry_msgs::msg::TransformStamped tf_msg;\n    tf_msg.header.stamp    = stamp;\n    tf_msg.header.frame_id = frame_id_;\n    tf_msg.child_frame_id  = child_frame_id_;\n\n    tf_msg.transform.translation.x = state.p.x();\n    tf_msg.transform.translation.y = state.p.y();\n    tf_msg.transform.translation.z = state.p.z();\n    tf_msg.transform.rotation.x = current_orientation_.x();\n    tf_msg.transform.rotation.y = current_orientation_.y();\n    tf_msg.transform.rotation.z = current_orientation_.z();\n    tf_msg.transform.rotation.w = current_orientation_.w();\n\n    tf_broadcaster_->sendTransform(tf_msg);\n}"}, "src/navstack/slam/terrain_mapping/terrain_mapping/terrain_mapping_node.py:520-553": {"file": "src/navstack/slam/terrain_mapping/terrain_mapping/terrain_mapping_node.py", "lines": "520-553", "start_line": 520, "end_line": 553, "language": "py", "code": "    def _publish_heightmap(self, stamp):\n        \"\"\"Publish the height map as an OccupancyGrid, min-max normalized to\n        [0, 100] over the map's valid (non-NaN) cells. Unscanned/NaN cells\n        are marked unknown (-1), matching the semantics of _publish_occupancy_grid.\"\"\"\n        grid = OccupancyGrid()\n        grid.header.stamp = stamp\n        grid.header.frame_id = self._map_frame\n\n        grid.info.map_load_time = stamp\n        grid.info.resolution = self._resolution\n        grid.info.width  = self._cols\n        grid.info.height = self._rows\n        grid.info.origin.position.x = self._origin_x\n        grid.info.origin.position.y = self._origin_y\n        grid.info.origin.position.z = 0.0\n        grid.info.origin.orientation.w = 1.0\n\n        unmapped = np.isnan(self._height_map)\n        valid = self._height_map[~unmapped]\n        h_min = float(valid.min()) if valid.size > 0 else 0.0\n        h_range = float(valid.max()) - h_min if valid.size > 0 else 0.0\n\n        if h_range > 1e-6:\n            normalized = (self._height_map - h_min) / h_range * 100.0\n        else:\n            normalized = np.zeros_like(self._height_map)\n\n        flat = np.clip(np.nan_to_num(normalized, nan=0.0), 0, 100).astype(np.int8)\n        flat[unmapped] = -1\n        grid.data = flat.flatten().tolist()\n\n        self._pub_heightmap.publish(grid)\n        self._pub_heightmap_range.publish(Float32MultiArray(data=[h_min, h_range]))\n"}, "src/navstack/path-planning/globalPlanner/scripts/heightmap_to_costmap.py:196-229": {"file": "src/navstack/path-planning/globalPlanner/scripts/heightmap_to_costmap.py", "lines": "196-229", "start_line": 196, "end_line": 229, "language": "py", "code": "        # ─── Step 5: Combine everything ─────────────────────────────────\n        # Start with terrain cost as base\n        out = terrain_cost.copy()\n\n        # Overlay inflation cost (take max of terrain and inflation)\n        out = np.maximum(out, inflation_cost)\n\n        # Mark lethal cells (original + inscribed inflation)\n        all_lethal = lethal_mask | inscribed_mask\n        out[all_lethal] = 100\n\n        # Mark unknown cells\n        hm_unknown = ~valid_hm\n        out[hm_unknown] = -1\n\n        # Clamp non-lethal, non-unknown to [0, 99]\n        free_mask = ~all_lethal & valid_hm\n        out[free_mask] = np.clip(out[free_mask], 0, 99)\n\n        out = out.astype(np.int8)\n\n        # ─── Step 6: Dilate unknown regions ─────────────────────────────\n        unknown_mask = (out == -1).astype(np.uint8)\n        if np.any(unknown_mask):\n            dilated = cv2.dilate(unknown_mask, kernel_3x3, iterations=2).astype(bool)\n            out[dilated] = -1\n\n        # ─── Step 7: Publish ────────────────────────────────────────────\n        out_msg = OccupancyGrid()\n        out_msg.header = hm_msg.header\n        out_msg.info = hm_msg.info\n        out_msg.data = out.flatten().tolist()\n        self.pub.publish(out_msg)\n"}, "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp:453-461": {"file": "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp", "lines": "453-461", "start_line": 453, "end_line": 461, "language": "cpp", "code": "    plan.poses = poses;\n\n    // Smooth the path — 3 passes with a 5-point window\n    for (int pass = 0; pass < 3; ++pass) {\n      plan.poses = smoothPath(plan.poses, 5);\n    }\n\n    std::copy(current_costs, current_costs + current_map_size, last_costs_.begin());\n    return plan;"}, "src/navstack/navstack_nav2/launch/roar_nav2_only.launch.py:241-248": {"file": "src/navstack/navstack_nav2/launch/roar_nav2_only.launch.py", "lines": "241-248", "start_line": 241, "end_line": 248, "language": "py", "code": "    controller = Node(\n        package='nav2_controller',\n        executable='controller_server',\n        name='controller_server',\n        output='screen',\n        parameters=[nav_params, {'use_sim_time': True}],\n        remappings=[('/cmd_vel', '/diff_drive_controller/cmd_vel')]\n    )"}, "src/navigation/scripts/asu_roar_gui.py:967-1008": {"file": "src/navigation/scripts/asu_roar_gui.py", "lines": "967-1008", "start_line": 967, "end_line": 1008, "language": "py", "code": "    def _save_gui_mission(self, waypoints_m, override_dir=None):\n        try:\n            target_name = override_dir if override_dir else \"gui_mission\"\n            mission_dir = os.path.join(self.referee_inputs_dir, target_name)\n            os.makedirs(mission_dir, exist_ok=True)\n\n            pairs = [(waypoints_m[i], waypoints_m[i + 1]) for i in range(0, len(waypoints_m), 2)]\n            wp_array = np.array([[x, y, 1.0] for x, y in pairs], dtype=float)\n            np.save(os.path.join(mission_dir, \"wp_gui.npy\"), wp_array)\n\n            all_pts = [(0.0, 0.0)] + pairs\n            segments = []\n            for i in range(len(pairs)):\n                seg_start = all_pts[i]\n                seg_end   = all_pts[i + 1]\n                segments.append([list(seg_start), list(seg_end)])\n            path_array = np.array(segments, dtype=float)\n            np.save(os.path.join(mission_dir, \"optimal_path.npy\"), path_array)\n\n            self.current_gui_mission = target_name\n\n        except Exception as e:\n            QMessageBox.warning(self, \"Warning\", f\"<font color='white'>Could not save mission array:<br>{str(e)}</font>\")\n\n    def update_yaml(self, waypoints_list):\n        with open(self.yaml_path, 'r') as f:\n            lines = f.readlines()\n        new_lines = []\n        in_waypoints_block = False\n        for line in lines:\n            if line.strip().startswith(\"waypoints: [\"):\n                new_lines.append(f\"      waypoints: [{', '.join(map(str, waypoints_list))}]\\n\")\n                if \"]\" not in line:\n                    in_waypoints_block = True\n            elif in_waypoints_block:\n                if \"]\" in line:\n                    in_waypoints_block = False\n            else:\n                new_lines.append(line)\n        with open(self.yaml_path, 'w') as f:\n            f.writelines(new_lines)\n"}, "src/navigation/referee_engine/referee_engine/collision_monitor_node.py:65-95": {"file": "src/navigation/referee_engine/referee_engine/collision_monitor_node.py", "lines": "65-95", "start_line": 65, "end_line": 95, "language": "py", "code": "    def contact_callback(self, msg: Contacts):\n        if not msg.contacts:\n            return\n\n        for contact in msg.contacts:\n            c1 = contact.collision1.name\n            c2 = contact.collision2.name\n            \n            # Find the obstacle name (e.g., \"Rock_5::link::collision\")\n            obstacle_name = c2 if \"roar_rover\" in c1 else c1\n            \n            if \"Rock_\" in obstacle_name:\n                # Extract the base entity name (e.g., \"Rock_5\")\n                entity_name = obstacle_name.split(\"::\")[0]\n                \n                # Look up the mesh_id for this entity\n                mesh_id = self.entity_to_mesh.get(entity_name, -1)\n                \n                if mesh_id in self.safe_meshes:\n                    # It's one of the non-collidable meshes (4,5,6,7,9), ignore it!\n                    continue\n\n            # If we get here, it's a valid fatal collision (collidable rock, wall, etc.)\n            self.is_colliding = True\n            self.last_contact_time = self.get_clock().now()\n            \n            flag_msg = Bool()\n            flag_msg.data = True\n            self.pub.publish(flag_msg)\n            return  # Trigger alarm immediately\n"}, "src/navigation/referee_engine/referee_engine/referee_core_node.py:276-308": {"file": "src/navigation/referee_engine/referee_engine/referee_core_node.py", "lines": "276-308", "start_line": 276, "end_line": 308, "language": "py", "code": "        score_dict = self.score_engine.final_score(\n            waypoint_details=self.tracker.waypoint_records,\n            back_to_start_detail=self.tracker.back_to_start_record,\n            num_return_requests=self.tracker.num_returns,\n            only_gnss_used=self.only_gnss_used,\n            elapsed_time=self.current_sim_time,\n            is_fatal=is_fatal\n        )\n        score_dict[\"terminal_status\"] = status\n        score_dict[\"is_final\"] = is_completed or is_fatal or (status in [\"KILL\", \"TIMEOUT\", \"SUCCESS\"])\n        score_dict[\"t_min_computed_sec\"] = float(self.t_min_computed)\n        score_dict[\"t_max_computed_sec\"] = float(self.t_max_computed)\n        score_dict[\"minimum_time_sec\"] = float(self.minimum_time)\n        score_dict[\"maximum_time_sec\"] = float(self.maximum_time)\n        score_dict[\"ideal_distance_m\"] = float(self.total_ideal_distance)\n        score_dict[\"actual_distance_m\"] = float(self.tracker.actual_distance)\n\n        # Save summary continuously so file exists at all times\n        self._save_summary_file(score_dict)\n\n        if is_fatal or status in [\"KILL\", \"TIMEOUT\", \"SUCCESS\"] or is_completed:\n            self._conclude_run(status=status, is_fatal=is_fatal)\n            return\n\n        score_msg = String()\n        score_msg.data = json.dumps(score_dict)\n        self.score_pub.publish(score_msg)\n\n        status_msg = String()\n        status_str = \"WAITING FOR COMMAND\" if self.tracker.state.name == \"WAITING_FOR_COMMAND\" else \"RUNNING\"\n        status_msg.data = f\"{status_str} | Waypoints: {self.tracker.waypoints_completed}/{len(self.tracker.waypoints)}\"\n        self.status_pub.publish(status_msg)\n"}, "src/navstack/perception/perception_module/aruco_detector_node.py:35-43": {"file": "src/navstack/perception/perception_module/aruco_detector_node.py", "lines": "35-43", "start_line": 35, "end_line": 43, "language": "py", "code": "from sensor_msgs.msg import Image, CameraInfo\nfrom geometry_msgs.msg import PoseStamped, PoseArray, Pose, Point\nfrom std_msgs.msg import ColorRGBA\nfrom vision_msgs.msg import Detection3DArray, Detection3D, ObjectHypothesisWithPose\nfrom visualization_msgs.msg import Marker, MarkerArray\nfrom active_mapping_msgs.msg import ArucoDetection, ArucoDetectionArray\n\nfrom cv_bridge import CvBridge\n"}, "src/navstack/slam/roar_msgs/CMakeLists.txt:9-14": {"file": "src/navstack/slam/roar_msgs/CMakeLists.txt", "lines": "9-14", "start_line": 9, "end_line": 14, "language": "txt", "code": "rosidl_generate_interfaces(${PROJECT_NAME}\n  \"msg/ArucoDetection.msg\"\n  \"msg/ArucoDetectionArray.msg\"\n  DEPENDENCIES std_msgs geometry_msgs\n)\n"}, "src/navstack/navstack_nav2/launch/roar_nav2_only.launch.py:65-261": {"file": "src/navstack/navstack_nav2/launch/roar_nav2_only.launch.py", "lines": "65-261", "start_line": 65, "end_line": 261, "language": "py", "code": "    ieskf_node = Node(\n        package='roar_localization',\n        executable='ieskf_node',\n        name='ieskf_node',\n        output='screen',\n        parameters=[{\n            'frame_id':       'odom',\n            'child_frame_id': 'base_footprint',\n            'publish_tf':          True,       # ieskf owns odom->base_footprint (the fused\n                                                # SLAM pose) so Nav2's TF-based costmap/planner\n                                                # lookups track it instead of diff_drive_\n                                                # controller's raw wheel odometry. Requires\n                                                # enable_odom_tf: false on diff_drive_controller\n                                                # in roar_simulation's diff_controller.yaml —\n                                                # otherwise both nodes broadcast the same edge.\n            'map_frame_id':        'map',\n            'publish_map_to_odom': True,\n            'odom_topic':     '/odom',\n            'aruco_topic':    '/aruco/detections',\n            'aruco_enabled':  True,\n            'aruco_max_distance': 8.0,\n            'aruco_map_path': aruco_map_path,\n            'joint_left':  'wheel_lhs_mid_joint',\n            'joint_right': 'wheel_rhs_mid_joint',\n            'wheel_radius':     0.125,\n            'wheelbase':        0.61,\n            'pulses_per_rev':   201554.0,\n            'max_delta_pulses': 500000.0,\n            'max_vx':           2.0,\n            # BNO055 is mounted on base_link, whose +X is rotated -90deg (yaw)\n            # from the rover's true forward (see base_footprint_joint in\n            # roar_simulation's rover.xacro). Correct it here so the fused\n            # heading (and WIO dead-reckoning) matches true forward motion\n            # instead of running 90deg perpendicular to the ZED position track.\n            'imu_roll_deg':  0.0,\n            'imu_pitch_deg': 0.0,\n            'imu_yaw_deg':   -90.0,\n            'cam_to_base_x': 0.0,\n            'cam_to_base_y': 0.0,\n            'cam_to_base_z': 0.0,\n            'sigma_an':           27.5e-3,\n            'sigma_aw':           18.6e-3,\n            'sigma_ww':           3.3e-5,\n            'sigma_pos':          0.002,\n            'sigma_aruco_base':   0.01,\n            'sigma_aruco_per_m':  0.005,\n            'max_iterations':     10,\n            'epsilon':            1e-6,\n            'wvo_max_jump':    1.0,\n            'wvo_window_size': 1,\n            'wvo_w_wo':        0.0,\n            'wvo_min_fill':    1,\n            'max_omega_z':   1.5,\n            'zed_cov_scale': 0.01,\n            'zupt_enabled': True,\n            'zupt_encoder_speed_threshold':    0.02,\n            'zupt_angular_velocity_threshold': 0.05,\n            'zupt_accel_variance_threshold':   0.05,\n            'zupt_accel_buffer_size':          30,\n            'zupt_min_stationary_duration':    0.5,\n            'zupt_sigma_v':                    0.01,\n            'use_sim_time': True,\n        }],\n        remappings=[\n            ('/imu/data',     '/bno055/data'),\n            ('/joint_states', '/joint_states_updated'),\n        ],\n    )\n\n    # ── Perception stack (LiDAR clustering → /detections/obstacles, ArUco, etc.) ──\n    # Feeds terrain_mapping below via /detections/obstacles.\n    perception = IncludeLaunchDescription(\n        PythonLaunchDescriptionSource(\n            os.path.join(pkg_perception, 'launch', 'perception.launch.py')\n        ),\n        launch_arguments={'use_sim_time': 'true'}.items(),\n    )\n\n    # ── Terrain mapping module ────────────────────────────────────────────────\n    # heightmap_mars_yard.npz is the correct bake for the mars_yard terrain.\n    # Loaded from terrain_mapping's installed share dir (not a path computed\n    # from the workspace source tree) so this launch file works on any\n    # machine/workspace layout after a colcon build.\n    pkg_terrain_mapping = get_package_share_directory('terrain_mapping')\n    heightmap_file = os.path.join(\n        pkg_terrain_mapping, 'working_heightmaps', 'heightmap_mars_yard.npz'\n    )\n\n    terrain_mapping = Node(\n        package='terrain_mapping',\n        executable='terrain_mapping_node',\n        name='terrain_mapping',\n        output='screen',\n        parameters=[{\n            'map_resolution': 0.1,\n            'map_width':  100.0,\n            'map_height': 100.0,\n            'map_origin_x': -50.0,\n            'map_origin_y': -50.0,\n            'heightmap_file': heightmap_file,\n            'occupancy_threshold': 0.3,\n            'obstacle_topic': '/detections/obstacles',\n            'odom_topic':     '/odom',\n            'map_frame':      'map',\n            'publish_rate':   2.0,\n            'use_sim_time':   True,\n        }]\n    )\n\n    # ── Heightmap to Costmap Converter ───────────────────────────────────────\n    # Feeds /terrain_costmap, consumed by DStarPlanner's edgeCost() alongside\n    # its own slope term. heightmap_file above is '' (flat zero base map), so\n    # until a real .npz is supplied here this node runs but has no elevation\n    # variation to derive roughness/steepness from.\n    heightmap_to_costmap_node = Node(\n        package='dstar_navigation',\n        executable='heightmap_to_costmap.py',\n        name='heightmap_to_costmap',\n        output='screen',\n        parameters=[nav_params, {'use_sim_time': True}]\n    )\n\n    # ── Evaluator ─────────────────────────────────────────────────────────────\n    slam_evaluator = Node(\n        package='roar_slam_testing',\n        executable='slam_evaluator',\n        name='slam_evaluator',\n        output='screen',\n        parameters=[{\n            'scenario_file':      scenario_path,\n            'ground_truth_topic': ZED_TOPIC,\n            'odom_topic':         '/odom',\n            'aruco_topic':        '/aruco/detections',\n            'diagnostics_topic':  '/roar/ieskf_diagnostics',\n            'occupancy_topic':    '/active_map/occupancy',\n            'output_dir':         '',     # auto: ~/slam_eval_<timestamp>/\n            'use_sim_time':       True,\n        }]\n    )\n\n    # NOTE: map_server loads a static map from disk (yaml_filename in the\n    # params file). It is currently configured with an empty filename, so it\n    # publishes nothing. Once SLAM is publishing /map, this node is redundant\n    # and can be removed — along with 'map_server' from node_names below.\n    map_server = Node(\n        package='nav2_map_server',\n        executable='map_server',\n        name='map_server',\n        output='screen',\n        parameters=[nav_params, {'use_sim_time': True}]\n    )\n\n    # D* Lite global planner (plugin: nav2_dstar_planner/DStarPlanner)\n    # Blocks until map→odom TF and /map exist.\n    planner = Node(\n        package='nav2_planner',\n        executable='planner_server',\n        name='planner_server',\n        output='screen',\n        parameters=[nav_params, {'use_sim_time': True}]\n    )\n\n    # MPPI local controller (plugin: nav2_mppi_controller::MPPIController)\n    # Publishes /cmd_vel, remapped to the DiffDriveController's input topic.\n    #\n    # NOTE 2026-07-16: cmd_vel_correction_node (a Rz(-90deg) rotation of\n    # linear.x/y, meant to mirror diff_drive_odom_correction_node) was wired\n    # in here and reverted. diff_drive_controller only ever reads\n    # linear.x — it has no lateral DOF. Rotating (linear.x, linear.y) by a\n    # non-180-multiple angle bleeds part or all of linear.x into the ignored\n    # linear.y field; for a pure forward command it zeroed linear.x\n    # entirely, so the robot stopped translating altogether (worse than the\n    # uncorrected behavior it was meant to fix). The underlying wheel-axis\n    # issue this was trying to work around is now fixed at its source (see\n    # ieskf_node's imu_yaw_deg above), so no cmd_vel-side correction is\n    # needed at all.\n    controller = Node(\n        package='nav2_controller',\n        executable='controller_server',\n        name='controller_server',\n        output='screen',\n        parameters=[nav_params, {'use_sim_time': True}],\n        remappings=[('/cmd_vel', '/diff_drive_controller/cmd_vel')]\n    )\n\n    # Recovery behaviors: spin, backup, drive_on_heading, wait\n    # NOTE: previously had no cmd_vel remap at all (defaulted to the\n    # unconnected literal '/cmd_vel' topic — recovery behaviors like\n    # spin/backup were never wired to the robot).\n    behavior_server = Node(\n        package='nav2_behaviors',\n        executable='behavior_server',\n        name='behavior_server',\n        output='screen',\n        parameters=[nav_params, {'use_sim_time': True}],\n        remappings=[('/cmd_vel', '/diff_drive_controller/cmd_vel')]\n    )"}, "src/navigation/referee_engine/referee_engine/score_calculator.py:23-51": {"file": "src/navigation/referee_engine/referee_engine/score_calculator.py", "lines": "23-51", "start_line": 23, "end_line": 51, "language": "py", "code": "class ScoreCalculator:\n    \"\"\"\n    ERC Navigation Task Score Calculator (TRAVERSE SUB-TASK: MAX 300 POINTS)\n\n    Rules Implemented:\n    1. O/NAV-010: Waypoint reached -> MAX(0, round(30 - 6 * d)) where d is edge distance (Max 120 pts total, 30 per wp)\n    2. O/NAV-020: Autonomy bonus -> 25 pts per waypoint reached in autonomous mode (Max 100 pts)\n    3. O/NAV-030: Back to start -> 25 pts if rover center is within 1m of start at finish (requires >=1 wp reached)\n    4. O/NAV-040: Back to start autonomy bonus -> 25 pts if back to start done in autonomous mode\n    5. O/NAV-050: Execution of Traversal Plan -> 6 pts per completed leg following plan (Max 30 pts for 5 legs)\n    6. O/NAV-060: Penalty points return -> -5 per return request\n    7. O/NAV-070 to O/NAV-100: Ignored\n    8. O/NAV-110: Penalty points - only GNSS feed used -> -20% deduction on traverse points\n    \"\"\"\n    def __init__(self, config: ScoreCalculatorConfig = ScoreCalculatorConfig()):\n        self.config = config\n\n    def calculate_edge_distance(self, center_distance: float) -> float:\n        \"\"\"Calculate distance in meters from the edge of the rover's body to the target waypoint.\"\"\"\n        return max(0.0, center_distance - self.config.rover_radius)\n\n    def score_waypoint_reached(self, d_edge: float) -> float:\n        \"\"\"\n        O/NAV-010: Waypoint reached score.\n        MAX(0, round(30 - (6 * d))) where d is edge distance in meters.\n        \"\"\"\n        raw_score = round(30.0 - (6.0 * d_edge))\n        return max(0.0, min(self.config.max_pts_per_waypoint, float(raw_score)))\n"}, "src/start_gui.sh:15-27": {"file": "src/start_gui.sh", "lines": "15-27", "start_line": 15, "end_line": 27, "language": "sh", "code": "source /opt/ros/jazzy/setup.bash\n\nif [ ! -f \"${ROAR_WS}/install/setup.bash\" ]; then\n    echo \"[ROAR] Workspace is not built. Building it now...\"\n    cd \"${ROAR_WS}\"\n    colcon build \\\n        --symlink-install \\\n        --executor parallel \\\n        --allow-overriding nav2_mppi_controller\nfi\n\nsource \"${ROAR_WS}/install/setup.bash\"\nexec python3 \"${SOURCE_ROOT}/navigation/scripts/asu_roar_gui.py\""}, "src/navigation/scripts/asu_roar_gui.py:82-89": {"file": "src/navigation/scripts/asu_roar_gui.py", "lines": "82-89", "start_line": 82, "end_line": 89, "language": "py", "code": "        # Per-item readiness gating: sim -> nav -> referee/evaluators -> waypoints.\n        self.SIM_READY_TIMEOUT_S = 90\n        self.NAV_READY_TIMEOUT_S = 120\n        self.BATCH_READY_POLL_MS = 1500\n        self._batch_generation = 0\n        self._batch_item_ctx = None\n        self._nav_ready = False\n"}, "src/navstack/path-planning/globalPlanner/scripts/batch_waypoint_follower.py:136-162": {"file": "src/navstack/path-planning/globalPlanner/scripts/batch_waypoint_follower.py", "lines": "136-162", "start_line": 136, "end_line": 162, "language": "py", "code": "    # Build final sequence: visit w1 -> w2 -> w3 -> w4 -> return to start_point\n    route = waypoints + [start_point]\n\n    rclpy.init()\n    node = ERCWaypointFollower()\n\n    try:\n        for idx, (x, y) in enumerate(route):\n            is_return = (idx == len(route) - 1)\n            wp_label = \"Return to Start\" if is_return else f\"Waypoint {idx + 1}\"\n            \n            print(f\"\\n==================================================\")\n            print(f\" {wp_label}: Target ({x:.2f}, {y:.2f})\")\n            print(f\"==================================================\")\n            \n            success = node.navigate_to_waypoint(x, y)\n            \n            if success:\n                print(f\"\\n[OK] Rover stopped at {wp_label}.\")\n                if is_return:\n                    print(\"Returned to start safely.\")\n                else:\n                    print(\"Moving to next waypoint automatically...\")\n            else:\n                print(f\"\\n[ERROR] Action failed for {wp_label}. Skipping to next waypoint.\")\n                    \n        print(\"\\nAll waypoints and return sequence completed successfully!\")"}, "src/navigation/referee_engine/referee_engine/score_calculator.py:23-36": {"file": "src/navigation/referee_engine/referee_engine/score_calculator.py", "lines": "23-36", "start_line": 23, "end_line": 36, "language": "py", "code": "class ScoreCalculator:\n    \"\"\"\n    ERC Navigation Task Score Calculator (TRAVERSE SUB-TASK: MAX 300 POINTS)\n\n    Rules Implemented:\n    1. O/NAV-010: Waypoint reached -> MAX(0, round(30 - 6 * d)) where d is edge distance (Max 120 pts total, 30 per wp)\n    2. O/NAV-020: Autonomy bonus -> 25 pts per waypoint reached in autonomous mode (Max 100 pts)\n    3. O/NAV-030: Back to start -> 25 pts if rover center is within 1m of start at finish (requires >=1 wp reached)\n    4. O/NAV-040: Back to start autonomy bonus -> 25 pts if back to start done in autonomous mode\n    5. O/NAV-050: Execution of Traversal Plan -> 6 pts per completed leg following plan (Max 30 pts for 5 legs)\n    6. O/NAV-060: Penalty points return -> -5 per return request\n    7. O/NAV-070 to O/NAV-100: Ignored\n    8. O/NAV-110: Penalty points - only GNSS feed used -> -20% deduction on traverse points\n    \"\"\""}, "src/roar2026/dev_environment/launch_test.sh:20-29": {"file": "src/roar2026/dev_environment/launch_test.sh", "lines": "20-29", "start_line": 20, "end_line": 29, "language": "sh", "code": "case \"$ROVER_CONFIG\" in\n    clean) PKG=\"roar_rover_clean\" ;;\n    noise) PKG=\"roar_rover_noise\" ;;\n    full)  PKG=\"roar_simulation_full\" ;;\n    *)\n        echo \"[ERROR] Unknown rover config: $ROVER_CONFIG\"\n        echo \"        Valid options: clean | noise | full\"\n        exit 1\n        ;;\nesac"}, "src/roar2026/dev_environment/rover/roar_simulation_full/urdf/modules/rover_gazebo.xacro:20-189": {"file": "src/roar2026/dev_environment/rover/roar_simulation_full/urdf/modules/rover_gazebo.xacro", "lines": "20-189", "start_line": 20, "end_line": 189, "language": "xacro", "code": "    <xacro:contact_sensor_gazebo name=\"base_link\" />\n    <xacro:contact_sensor_gazebo name=\"wheel_rhs_front\" />\n    <xacro:contact_sensor_gazebo name=\"wheel_rhs_mid\" />\n    <xacro:contact_sensor_gazebo name=\"wheel_rhs_rear\" />\n    <xacro:contact_sensor_gazebo name=\"wheel_lhs_front\" />\n    <xacro:contact_sensor_gazebo name=\"wheel_lhs_mid\" />\n    <xacro:contact_sensor_gazebo name=\"wheel_lhs_rear\" />\n  </xacro:macro>\n\n  <xacro:macro name=\"contact_sensor_gazebo\" params=\"name\">\n    <gazebo reference=\"${name}\">\n      <sensor name=\"${name}_contact\" type=\"contact\">\n        <always_on>true</always_on>\n        <topic>/rover_contact</topic>\n        <update_rate>50</update_rate>\n        <contact>\n          <collision>${name}_collision</collision>\n        </contact>\n      </sensor>\n    </gazebo>\n  </xacro:macro>\n\n  <xacro:macro name=\"depth_camera_gazebo\" params=\"name\">\n    <gazebo reference=\"${name}_link\">\n      \n      <sensor name=\"${name}_rgb\" type=\"camera\">\n        <always_on>1</always_on>\n        <visualize>false</visualize>\n        <update_rate>5</update_rate>\n        <topic>${name}/image_raw</topic>\n        <camera>\n          <horizontal_fov>1.91986</horizontal_fov> <image><width>640</width><height>360</height></image>\n          <clip><near>0.2</near><far>300</far></clip>\n          <noise>\n            <type>gaussian</type>\n            <mean>0.0</mean>\n            <stddev>0.007</stddev> \n          </noise>\n        </camera>\n      </sensor>\n\n      <sensor name=\"${name}_depth\" type=\"depth_camera\">\n        <always_on>1</always_on>\n        <visualize>false</visualize>\n        <update_rate>5</update_rate>\n        <topic>${name}/depth</topic>\n        <camera>\n          <horizontal_fov>1.91986</horizontal_fov> <image><width>640</width><height>360</height></image>\n          <clip><near>0.2</near><far>20</far></clip>\n          <noise>\n            <type>gaussian</type>\n            <mean>0.0</mean>\n            <stddev>0.01</stddev> \n          </noise>\n        </camera>\n      </sensor>\n      \n    </gazebo>\n  </xacro:macro>\n\n  <xacro:macro name=\"bno055_imu_gazebo\" params=\"name\">\n    <gazebo reference=\"${name}_link\">\n      \n      <sensor name=\"${name}_imu_sensor\" type=\"imu\">\n        <always_on>1</always_on>\n        <update_rate>100</update_rate>\n        <visualize>false</visualize>\n        <topic>${name}/data</topic>\n        <imu>\n          <angular_velocity>\n            <x>\n              <noise type=\"gaussian\">\n                <mean>0.0</mean>\n                <stddev>0.00173</stddev>\n                <bias_mean>0.0175</bias_mean>\n                <bias_stddev>0.001</bias_stddev>\n                <dynamic_bias_stddev>0.0005</dynamic_bias_stddev>\n                <dynamic_bias_correlation_time>400.0</dynamic_bias_correlation_time>\n              </noise>\n            </x>\n            <y>\n              <noise type=\"gaussian\">\n                <mean>0.0</mean>\n                <stddev>0.00173</stddev>\n                <bias_mean>0.0175</bias_mean>\n                <bias_stddev>0.001</bias_stddev>\n                <dynamic_bias_stddev>0.0005</dynamic_bias_stddev>\n                <dynamic_bias_correlation_time>400.0</dynamic_bias_correlation_time>\n              </noise>\n            </y>\n            <z>\n              <noise type=\"gaussian\">\n                <mean>0.0</mean>\n                <stddev>0.00173</stddev>\n                <bias_mean>0.0175</bias_mean>\n                <bias_stddev>0.001</bias_stddev>\n                <dynamic_bias_stddev>0.0005</dynamic_bias_stddev>\n                <dynamic_bias_correlation_time>400.0</dynamic_bias_correlation_time>\n              </noise>\n            </z>\n          </angular_velocity>\n          <linear_acceleration>\n            <x>\n              <noise type=\"gaussian\">\n                <mean>0.0</mean>\n                <stddev>0.0104</stddev>\n                <bias_mean>0.785</bias_mean>\n                <bias_stddev>0.01</bias_stddev>\n                <dynamic_bias_stddev>0.005</dynamic_bias_stddev>\n                <dynamic_bias_correlation_time>400.0</dynamic_bias_correlation_time>\n              </noise>\n            </x>\n            <y>\n              <noise type=\"gaussian\">\n                <mean>0.0</mean>\n                <stddev>0.0104</stddev>\n                <bias_mean>0.785</bias_mean>\n                <bias_stddev>0.01</bias_stddev>\n                <dynamic_bias_stddev>0.005</dynamic_bias_stddev>\n                <dynamic_bias_correlation_time>400.0</dynamic_bias_correlation_time>\n              </noise>\n            </y>\n            <z>\n              <noise type=\"gaussian\">\n                <mean>0.0</mean>\n                <stddev>0.0104</stddev>\n                <bias_mean>0.785</bias_mean>\n                <bias_stddev>0.01</bias_stddev>\n                <dynamic_bias_stddev>0.005</dynamic_bias_stddev>\n                <dynamic_bias_correlation_time>400.0</dynamic_bias_correlation_time>\n              </noise>\n            </z>\n          </linear_acceleration>\n        </imu>\n      </sensor>\n\n      <sensor name=\"${name}_mag_sensor\" type=\"magnetometer\">\n        <always_on>1</always_on>\n        <update_rate>100</update_rate>\n        <visualize>false</visualize>\n        <topic>${name}/mag</topic>\n        <magnetometer>\n          <x>\n            <noise type=\"gaussian\">\n              <mean>0.0</mean>\n              <stddev>1e-06</stddev>\n              <bias_mean>1.5e-05</bias_mean>\n              <bias_stddev>1e-06</bias_stddev>\n            </noise>\n          </x>\n          <y>\n            <noise type=\"gaussian\">\n              <mean>0.0</mean>\n              <stddev>1e-06</stddev>\n              <bias_mean>-1.0e-05</bias_mean>\n              <bias_stddev>1e-06</bias_stddev>\n            </noise>\n          </y>\n          <z>\n            <noise type=\"gaussian\">\n              <mean>0.0</mean>\n              <stddev>1.4e-06</stddev>\n              <bias_mean>0.5e-05</bias_mean>\n              <bias_stddev>1e-06</bias_stddev>\n            </noise>\n          </z>\n        </magnetometer>\n      </sensor>\n\n    </gazebo>"}, "src/roar2026/dev_environment/rover/roar_simulation_full/src/zed_degradation_node.py:154-336": {"file": "src/roar2026/dev_environment/rover/roar_simulation_full/src/zed_degradation_node.py", "lines": "154-336", "start_line": 154, "end_line": 336, "language": "py", "code": "    def get_sun_pixel(self):\n        if self.fx is None or self.sun_pos is None or self.rover_pos is None:\n            return None, None\n\n        try:\n            # 1. World -> Rover (base_footprint)\n            rot_wr = quat_to_rot_matrix(\n                self.rover_quat[0], self.rover_quat[1],\n                self.rover_quat[2], self.rover_quat[3]\n            )\n            p_rs = rot_wr.T @ (self.sun_pos - self.rover_pos)\n\n            # 2. base_footprint -> zed2i_depth_optical_frame (live TF2 with URDF static fallback)\n            p_cam = None\n            if self.tf_buffer is not None:\n                try:\n                    tf_msg = self.tf_buffer.lookup_transform(\n                        'zed2i_depth_optical_frame',\n                        'base_footprint',\n                        rclpy.time.Time()\n                    )\n                    tr = tf_msg.transform.translation\n                    rq = tf_msg.transform.rotation\n                    rot_cb = quat_to_rot_matrix(rq.x, rq.y, rq.z, rq.w)\n                    p_cam = rot_cb @ p_rs + np.array([tr.x, tr.y, tr.z], dtype=np.float64)\n                except Exception:\n                    p_cam = None\n\n            if p_cam is None:\n                # Exact URDF static chain:\n                # base_footprint -> zed2i_link: xyz=(0.35, 0.0, 0.25), rpy=(0, 0, 0)\n                # zed2i_link -> zed2i_depth_optical_frame: rpy=(-pi/2, 0, -pi/2)\n                p_link = p_rs - np.array([0.35, 0.0, 0.25], dtype=np.float64)\n                p_cam = np.array([-p_link[1], -p_link[2], p_link[0]], dtype=np.float64)\n\n            if p_cam[2] > 0.0:\n                u = (self.fx * (p_cam[0] / p_cam[2])) + self.cx\n                v = (self.fy * (p_cam[1] / p_cam[2])) + self.cy\n                return float(u), float(v)\n        except Exception as ex:\n            self.get_logger().warn(f'Sun projection error: {ex}', throttle_duration_sec=5.0)\n\n        return None, None\n\n    def rgb_callback(self, rgb_msg: Image):\n        try:\n            cv_rgb = self.bridge.imgmsg_to_cv2(rgb_msg, desired_encoding='bgr8').copy()\n            h, w, _ = cv_rgb.shape\n\n            # Mars atmospheric dust speckle\n            dust_probs = np.random.uniform(0.0, 1.0, size=(h, w))\n            dust_mask = dust_probs < 0.015\n            cv_rgb[dust_mask] = np.array([80, 120, 180], dtype=np.uint8)\n\n            u, v = self.get_sun_pixel()\n\n            if u is not None and v is not None:\n                glare_radius = 150.0\n                if -glare_radius < u < w + glare_radius and -glare_radius < v < h + glare_radius:\n                    Y, X = np.ogrid[:h, :w]\n                    dist_from_sun = np.sqrt((X - u) ** 2 + (Y - v) ** 2)\n\n                    norm_dist = np.clip(1.0 - (dist_from_sun / glare_radius), 0.0, 1.0)\n                    core = (norm_dist ** 2.5)[..., np.newaxis]\n                    corona = (norm_dist ** 1.4)[..., np.newaxis]\n\n                    # Bright white solar core + warm golden-white lens corona (BGR)\n                    bloom = (\n                        core * np.array([255.0, 255.0, 255.0], dtype=np.float32)\n                        + corona * np.array([90.0, 190.0, 255.0], dtype=np.float32) * 0.65\n                    )\n\n                    cv_rgb_float = cv_rgb.astype(np.float32) + bloom\n\n                    dist_to_center = math.sqrt((u - (w / 2.0)) ** 2 + (v - (h / 2.0)) ** 2)\n                    max_dist = math.sqrt((w / 2.0) ** 2 + (h / 2.0) ** 2)\n\n                    washout_max = float(self.get_parameter('washout_max').value)\n                    global_washout = float(\n                        np.clip(1.0 - (dist_to_center / (max_dist * 1.5)), 0.0, 1.0) * washout_max\n                    )\n\n                    cv_rgb_float = (cv_rgb_float * (1.0 - global_washout)) + (255.0 * global_washout)\n                    cv_rgb = np.clip(cv_rgb_float, 0, 255).astype(np.uint8)\n\n            self.latest_rgb = cv_rgb\n            self.latest_dust_mask = dust_mask\n\n            degraded_rgb_msg = self.bridge.cv2_to_imgmsg(cv_rgb, encoding='bgr8')\n            degraded_rgb_msg.header.stamp = rgb_msg.header.stamp\n            degraded_rgb_msg.header.frame_id = 'zed2i_depth_optical_frame'\n            self.rgb_pub.publish(degraded_rgb_msg)\n\n            if not self._logged_first_frame:\n                self._logged_first_frame = True\n                self.get_logger().info(\n                    f'Publishing /zed2i/image_raw_updated ({w}x{h}), initial sun pixel=({u}, {v})'\n                )\n        except Exception as e:\n            self.get_logger().error(f'Failed to process RGB image: {e}')\n\n    def depth_callback(self, depth_msg: Image):\n        try:\n            cv_depth = self.bridge.imgmsg_to_cv2(depth_msg, desired_encoding='32FC1').copy()\n            h, w = cv_depth.shape\n\n            if self.X_factor is None or self.X_factor.shape != (h, w):\n                self._set_intrinsics(w, h, self.fx, self.fy, w / 2.0, h / 2.0)\n\n            valid_mask = np.isfinite(cv_depth) & (cv_depth > 0.2)\n\n            # Distance-quadratic stereo depth noise\n            z_values = cv_depth[valid_mask]\n            stddev = 0.003 * (z_values ** 2)\n            cv_depth[valid_mask] += np.random.normal(loc=0.0, scale=stddev).astype(np.float32)\n\n            # Mars dust depth dropouts\n            if self.latest_dust_mask is not None and self.latest_dust_mask.shape == (h, w):\n                dust_mask_depth = valid_mask & self.latest_dust_mask\n            else:\n                dust_mask_depth = valid_mask & (np.random.uniform(0.0, 1.0, size=(h, w)) < 0.015)\n            cv_depth[dust_mask_depth] = 0.4\n\n            # Sun glare stereo depth blindness\n            u, v = self.get_sun_pixel()\n            if u is not None and v is not None:\n                glare_radius_depth = 80.0\n                if -glare_radius_depth < u < w + glare_radius_depth and -glare_radius_depth < v < h + glare_radius_depth:\n                    Y, X = np.ogrid[:h, :w]\n                    dist_from_sun = np.sqrt((X - u) ** 2 + (Y - v) ** 2)\n                    cv_depth[dist_from_sun < glare_radius_depth] = np.nan\n\n            degraded_depth_msg = self.bridge.cv2_to_imgmsg(cv_depth, encoding='32FC1')\n            degraded_depth_msg.header.stamp = depth_msg.header.stamp\n            degraded_depth_msg.header.frame_id = 'zed2i_depth_optical_frame'\n            self.depth_pub.publish(degraded_depth_msg)\n\n            vis_img = np.copy(cv_depth)\n            vis_img[~np.isfinite(vis_img)] = 15.0\n            vis_img = np.clip(vis_img, 0.0, 15.0)\n            vis_norm = cv2.normalize(vis_img, None, 0, 255, cv2.NORM_MINMAX, dtype=cv2.CV_8U)\n            colorized_depth = cv2.applyColorMap(vis_norm, cv2.COLORMAP_JET)\n            vis_msg = self.bridge.cv2_to_imgmsg(colorized_depth, encoding='bgr8')\n            vis_msg.header = degraded_depth_msg.header\n            self.depth_vis_pub.publish(vis_msg)\n\n            # Generate PointCloud2\n            X = self.X_factor * cv_depth\n            Y = self.Y_factor * cv_depth\n\n            if self.latest_rgb is not None and self.latest_rgb.shape[:2] == (h, w):\n                rgb_src = self.latest_rgb\n                R_chan = rgb_src[..., 2].astype(np.uint32)\n                G_chan = rgb_src[..., 1].astype(np.uint32)\n                B_chan = rgb_src[..., 0].astype(np.uint32)\n                rgb_packed = ((R_chan << 16) | (G_chan << 8) | B_chan).view(np.float32)\n            else:\n                neutral = np.uint32((200 << 16) | (200 << 8) | 200).view(np.float32)\n                rgb_packed = np.full((h, w), neutral, dtype=np.float32)\n\n            pc_valid = np.isfinite(cv_depth) & (cv_depth > 0.0)\n            points = np.stack(\n                (X[pc_valid], Y[pc_valid], cv_depth[pc_valid], rgb_packed[pc_valid]),\n                axis=-1\n            ).astype(np.float32)\n\n            pc2 = PointCloud2()\n            pc2.header = degraded_depth_msg.header\n            pc2.height = 1\n            pc2.width = len(points)\n            pc2.is_dense = False\n            pc2.is_bigendian = False\n            pc2.fields = [\n                PointField(name='x', offset=0, datatype=PointField.FLOAT32, count=1),\n                PointField(name='y', offset=4, datatype=PointField.FLOAT32, count=1),\n                PointField(name='z', offset=8, datatype=PointField.FLOAT32, count=1),\n                PointField(name='rgb', offset=12, datatype=PointField.FLOAT32, count=1),\n            ]\n            pc2.point_step = 16\n            pc2.row_step = 16 * len(points)\n            pc2.data = points.tobytes()\n\n            self.pc_pub.publish(pc2)"}, "src/roar2026/dev_environment/rover/roar_simulation_full/src/encoder_sim_node.py:31-75": {"file": "src/roar2026/dev_environment/rover/roar_simulation_full/src/encoder_sim_node.py", "lines": "31-75", "start_line": 31, "end_line": 75, "language": "py", "code": "        self.left_joint  = self.declare_parameter('left_joint',  'wheel_lhs_mid_joint').value\n        self.right_joint = self.declare_parameter('right_joint', 'wheel_rhs_mid_joint').value\n\n        # Matches WIOParams::pulses_per_rev default in ieskf_node.cpp (2000.0).\n        # Swap to the real 3531_0-derived value (~201554) once you're ready\n        # to tune for hardware accuracy — keeping the default for now so the\n        # sim matches what the filter already expects out of the box.\n        self.pulses_per_rev = self.declare_parameter('pulses_per_rev', 201554.0).value\n\n        self.sub = self.create_subscription(\n            JointState, '/joint_states', self.joint_state_cb, 10)\n        self.pub = self.create_publisher(\n            JointState, '/joint_states_updated', 10)\n\n        self.get_logger().info(\n            f\"encoder_sim_node up. left={self.left_joint} right={self.right_joint} \"\n            f\"pulses_per_rev={self.pulses_per_rev}\"\n        )\n\n    def joint_state_cb(self, msg: JointState):\n        left_pos = None\n        right_pos = None\n        for name, pos in zip(msg.name, msg.position):\n            if name == self.left_joint:\n                left_pos = pos\n            elif name == self.right_joint:\n                right_pos = pos\n\n        if left_pos is None or right_pos is None:\n            self.get_logger().warn(\n                \"left/right joint not found in /joint_states yet — skipping\",\n                throttle_duration_sec=3.0,\n            )\n            return\n\n        # radians -> simulated pulse count (rounded, so it actually quantizes\n        # like a real encoder instead of passing through a perfect float)\n        left_pulses  = round(left_pos  / (2.0 * math.pi) * self.pulses_per_rev)\n        right_pulses = round(right_pos / (2.0 * math.pi) * self.pulses_per_rev)\n\n        out = JointState()\n        out.header = msg.header\n        out.name = [self.left_joint, self.right_joint]\n        out.position = [float(left_pulses), float(right_pulses)]\n        self.pub.publish(out)"}, "src/navstack/perception/config/perception_params.yaml:31-58": {"file": "src/navstack/perception/config/perception_params.yaml", "lines": "31-58", "start_line": 31, "end_line": 58, "language": "yaml", "code": "    max_distance: 6.0            # [m]  max range to keep (ERC arena ≈5 m radius)\n\n    # ── Stage 1: Voxel-Grid Downsampling ─────────────────────────────────\n    # Reduces point density uniformly.  Smaller → more points, more detail,\n    # more compute.  Must be ≤ smallest rock diameter you care about / 2.\n    # A 0.06 m leaf keeps enough points on a 15 cm rock while halving density.\n    voxel_size: 0.06             # [m]  leaf size\n\n    # ── Stage 2: Statistical Outlier Removal (SOR) ───────────────────────\n    # For each point, compute mean distance to its k nearest neighbours.\n    # If that distance is > mean + std_ratio × σ across all points, remove it.\n    # Effect: kills isolated sensor speckle and flying pixels.\n    # Tuning:\n    #   sor_nb_neighbors ↑  →  stricter (more points removed, safer)\n    #   sor_std_ratio    ↑  →  more lenient (keep more edge points)\n    sor_nb_neighbors: 25         # k nearest neighbours used for mean/std estimate\n    sor_std_ratio: 1.8           # points > 1.8σ from mean are outliers\n    sor_enabled: true\n\n    # ── Stage 3: Radius Outlier Removal (ROR) ────────────────────────────\n    # Remove points that have fewer than ror_min_neighbors within ror_radius.\n    # Effect: removes isolated reflections that survive SOR.\n    # Tuning:\n    #   ror_radius       ↑  →  larger search ball (keeps more lone points)\n    #   ror_min_neighbors ↑  →  stricter (removes more isolated points)\n    ror_radius: 0.12             # [m]  search sphere radius\n    ror_min_neighbors: 6         # min neighbours inside sphere to keep point\n    ror_enabled: true"}, "src/navstack/perception/perception_module/lidar_cluster_node.py:336-486": {"file": "src/navstack/perception/perception_module/lidar_cluster_node.py", "lines": "336-486", "start_line": 336, "end_line": 486, "language": "py", "code": "    def _remove_planes_slope_aware(self, pcd, p) -> o3d.geometry.PointCloud:\n        \"\"\"\n        Iteratively finds and removes dominant planes, but ONLY if the plane:\n          (a) has >= plane_min_inliers points (small planes = rock faces → keep)\n          (b) its normal tilts <= ground_max_tilt_deg from vertical (ZED Y axis)\n              → near-vertical walls / rock faces are NEVER removed\n          (c) its centroid depth (Z) is within [gnd_min_z, gnd_max_z]\n              → prevents accidentally removing a floating rock cluster\n\n        This is the key improvement over the old all-planes-stripped approach:\n        a ramp at 30° is removed; a near-vertical boulder face at 80° is kept.\n        \"\"\"\n        cos_limit = math.cos(math.radians(float(p['gnd_tilt'])))\n        current   = pcd\n\n        for i in range(int(p['plane_iters'])):\n            if len(current.points) < 20:\n                break\n\n            try:\n                plane_model, inliers = current.segment_plane(\n                    distance_threshold=float(p['gnd_thresh']),\n                    ransac_n=3,\n                    num_iterations=200\n                )\n            except Exception:\n                break\n\n            if len(inliers) < int(p['plane_inliers']):\n                # Too few inliers → this is a small feature (rock), not ground. Stop.\n                self.get_logger().debug(\n                    f'RANSAC iter {i}: {len(inliers)} inliers < {p[\"plane_inliers\"]}, stopping.'\n                )\n                break\n\n            # Compute cosine between plane normal and gravity (Y axis)\n            normal = np.array(plane_model[:3], dtype=np.float64)\n            normal /= np.linalg.norm(normal) + 1e-9\n            cos_with_gravity = abs(float(np.dot(normal, _GRAVITY)))\n\n            # Compute centroid depth (Z = forward in ZED frame)\n            pts_arr = np.asarray(current.points)\n            centroid_z = float(np.mean(pts_arr[inliers, 2]))\n\n            # Check centroid depth is in valid ground range\n            depth_ok = p['gnd_min_z'] <= centroid_z <= p['gnd_max_z']\n\n            # Remove the plane only if it is \"ground-like\"\n            if cos_with_gravity >= cos_limit and depth_ok:\n                axis = ['X', 'Y', 'Z'][int(np.argmax(np.abs(normal)))]\n                self.get_logger().debug(\n                    f'RANSAC iter {i}: removed {len(inliers)} pts  '\n                    f'normal≈{normal.round(2)}  dominant={axis}  '\n                    f'tilt_ok  centroid_z={centroid_z:.2f}'\n                )\n                current = current.select_by_index(inliers, invert=True)\n            else:\n                # This plane is too steep (rock face) or at wrong depth — stop.\n                self.get_logger().debug(\n                    f'RANSAC iter {i}: KEPT {len(inliers)} pts  '\n                    f'cos_grav={cos_with_gravity:.2f} < {cos_limit:.2f} '\n                    f'or depth_ok={depth_ok}. Stopping.'\n                )\n                break\n\n        return current\n\n    # ────────────────────────────────────────────────────────────────────────\n    # Stage 4b: Surface-normal roughness filter\n    # ────────────────────────────────────────────────────────────────────────\n\n    def _roughness_filter(self, pcd, p) -> o3d.geometry.PointCloud:\n        \"\"\"\n        Computes surface normals for every point and measures local roughness\n        (curvature / normal variance) in the neighbourhood.\n\n        Algorithm:\n          1. Estimate normals using PCA in a sphere of radius normal_search_radius.\n          2. For each point i, gather its neighbours within the same radius.\n          3. Compute the mean normal of those neighbours.\n          4. Roughness score = mean angular deviation of neighbours from the mean normal.\n             High score → points are on a sharp edge or irregular surface (ROCK).\n             Low score  → points are on a flat/smooth surface (SLOPE/GROUND).\n          5. Drop points with roughness < min_roughness_score.\n\n        GPU acceleration: step 1 (normal estimation) uses open3d.core CUDA\n        tensors when use_gpu=true; steps 2-5 use NumPy on CPU (normal variance\n        computation is memory-bound, not compute-bound, so CPU is adequate).\n        \"\"\"\n        if len(pcd.points) < 10:\n            return pcd\n\n        radius = float(p['norm_radius'])\n        thresh = float(p['roughness'])\n\n        if self._use_gpu:\n            # Estimate normals on GPU via the Tensor API, then bring back to CPU\n            try:\n                pcd_t = o3d.t.geometry.PointCloud.from_legacy(pcd)\n                pcd_t = pcd_t.to(self._gpu_device)\n                pcd_t.estimate_normals(\n                    o3d.core.SizeVector([0, 30]),          # min 0, max 30 neighbours\n                    radius=radius\n                )\n                normals = pcd_t.point.normals.cpu().numpy()\n            except Exception:\n                # GPU path failed (geometry API unstable) → fall back to CPU\n                pcd.estimate_normals(\n                    search_param=o3d.geometry.KDTreeSearchParamRadius(radius)\n                )\n                normals = np.asarray(pcd.normals)\n        else:\n            pcd.estimate_normals(\n                search_param=o3d.geometry.KDTreeSearchParamRadius(radius)\n            )\n            normals = np.asarray(pcd.normals)\n\n        if normals.shape[0] == 0:\n            return pcd\n\n        # Normalise (PCA can return non-unit normals in edge cases)\n        norms_len = np.linalg.norm(normals, axis=1, keepdims=True) + 1e-9\n        normals  /= norms_len\n\n        # Build KD-tree on CPU for neighbourhood queries\n        pts_arr = np.asarray(pcd.points)\n        kdtree  = o3d.geometry.KDTreeFlann(pcd)\n\n        roughness_scores = np.zeros(len(pts_arr), dtype=np.float32)\n\n        for j in range(len(pts_arr)):\n            [k, nb_idx, _] = kdtree.search_radius_vector_3d(pts_arr[j], radius)\n            if k < 3:\n                # Too few neighbours → treat as isolated point, keep it\n                roughness_scores[j] = 1.0\n                continue\n            nb_normals  = normals[nb_idx, :]\n            mean_normal = nb_normals.mean(axis=0)\n            mn_len      = np.linalg.norm(mean_normal) + 1e-9\n            mean_normal /= mn_len\n            # Dot product of each neighbour normal with the mean normal\n            dots         = np.clip(nb_normals @ mean_normal, -1.0, 1.0)\n            # Angular variance: 1 - mean(|dot|) = 0 for flat, ~1 for chaotic\n            roughness_scores[j] = float(1.0 - np.mean(np.abs(dots)))\n\n        # Keep only points that are rough enough to be obstacles\n        keep_mask = roughness_scores >= thresh\n        if keep_mask.sum() == 0:\n            return pcd  # fallback: keep all (avoid empty cloud)\n\n        return pcd.select_by_index(np.where(keep_mask)[0])"}, "src/navstack/perception/config/perception_params.yaml:120-155": {"file": "src/navstack/perception/config/perception_params.yaml", "lines": "120-155", "start_line": 120, "end_line": 155, "language": "yaml", "code": "    cluster_tolerance: 0.25      # [m]  DBSCAN epsilon — neighbour search radius\n    min_cluster_size: 15         # min points for a cluster to be an obstacle\n    max_cluster_size: 3000       # max points — larger = residual ground plane\n\n    # ── Stage 6: Bounding-Box Shape Filter ───────────────────────────────\n    # After clustering, reject clusters whose axis-aligned bounding box is\n    # implausible for a rock.\n    # ZED camera frame: X = right (lateral), Y = down (vertical), Z = forward.\n    #\n    # A sharp ERC rock is roughly 0.15–0.8 m across and 0.05–0.5 m tall.\n    # Set limits conservatively: too tight → miss rocks; too loose → false positives.\n    min_bbox_x: 0.08             # [m]  min lateral width\n    max_bbox_x: 2.0              # [m]  max lateral width   (wider → likely residual ground)\n    min_bbox_y: 0.04             # [m]  min vertical height (≥ 4 cm rock sticking up)\n    max_bbox_y: 1.5              # [m]  max vertical height\n    min_bbox_z: 0.08             # [m]  min depth\n    max_bbox_z: 2.0              # [m]  max depth\n\n    # ── Stage 6 (cont.): Distance & Height Centre Filters ────────────────\n    # Cluster centre must be within these 3-D distance and Y-axis bounds.\n    min_cluster_distance: 0.4    # [m]  ignore clusters too close (sensor blind spot)\n    max_cluster_distance: 6.0    # [m]  ignore clusters too far\n\n    # ZED frame: Y=down (positive = below camera), Y=negative = above camera.\n    # Rocks on the ground have centre Y ≈ 0 to +0.5 m.\n    # Reject clusters whose centre is too high above (overhead objects) or\n    # too low (ghost returns below ground, sensor artefacts).\n    min_center_y: -0.5           # [m]  ignore clusters well above camera (not ground rocks)\n    max_center_y:  1.5           # [m]  ignore clusters very far below camera\n\n    # ── Stage 6 (cont.): Aspect-Ratio Filter ────────────────────────────\n    # A flat slab (ramp remnant) will have bbox_z >> bbox_y.\n    # A sharp rock will be more cube-like.  The filter rejects any cluster\n    # whose depth-to-height ratio exceeds max_depth_height_ratio.\n    # 0.0 disables the filter.\n    max_depth_height_ratio: 6.0  # drop clusters that are very flat slabs"}, "src/navstack/perception/perception_module/obstacle_publisher_node.py:83-220": {"file": "src/navstack/perception/perception_module/obstacle_publisher_node.py", "lines": "83-220", "start_line": 83, "end_line": 220, "language": "py", "code": "    def callback(self, msg: Detection3DArray):\n        max_base_h   = self.get_parameter('max_obstacle_base_height').value\n        min_conf     = self.get_parameter('min_confidence').value\n        source_frame = self.get_parameter('source_frame').value\n        merge_radius = self.get_parameter('merge_radius').value\n        ema_alpha    = self.get_parameter('ema_alpha').value\n\n        world_frame  = self.get_parameter('world_frame').value\n\n        # Use native TF2 to perfectly resolve the 6-frame tree offsets\n        try:\n            tf_stamped = self.tf_buffer.lookup_transform(\n                world_frame,   # target frame\n                source_frame,  # source frame (where the detections are)\n                rclpy.time.Time(), # get the latest available\n                timeout=rclpy.duration.Duration(seconds=0.2)\n            )\n        except Exception as e:\n            self.get_logger().warn(\n                f'Waiting for TF tree to link {source_frame} to {world_frame}...',\n                throttle_duration_sec=5.0,\n            )\n            return\n\n        now = time.time()\n        self.latest_stamp = msg.header.stamp\n\n        for det in msg.detections:\n            # Confidence filter (min_conf=0.0 by default — accept all LiDAR clusters)\n            score    = det.results[0].hypothesis.score    if det.results else 1.0\n            class_id = det.results[0].hypothesis.class_id if det.results else 'obstacle'\n            if score < min_conf:\n                continue\n\n            # Height filter — evaluated in camera frame (Z is UP)\n            bottom_z_cam = det.bbox.center.position.z - det.bbox.size.z / 2.0\n            if bottom_z_cam > max_base_h:\n                continue\n\n            # Distance filter — 3D distance from camera origin in camera frame\n            cx = det.bbox.center.position.x\n            cy = det.bbox.center.position.y\n            cz = det.bbox.center.position.z\n            dist_cam = math.sqrt(cx*cx + cy*cy + cz*cz)\n            if dist_cam > self.get_parameter('max_detection_distance').value:\n                continue\n\n            # Transform obstacle centre to world frame\n            pt_cam        = PointStamped()\n            pt_cam.header = msg.header\n            pt_cam.point  = det.bbox.center.position\n            try:\n                pt_world = tf2_geometry_msgs.do_transform_point(pt_cam, tf_stamped)\n            except Exception as e:\n                self.get_logger().warn(f'Transform failed: {e}')\n                continue\n\n            # Build world-frame detection\n            out_det = Detection3D()\n            out_det.header.frame_id       = world_frame\n            out_det.header.stamp          = msg.header.stamp\n            out_det.bbox.center.position.x = pt_world.point.x\n            out_det.bbox.center.position.y = pt_world.point.y\n            out_det.bbox.center.position.z = pt_world.point.z\n            out_det.bbox.center.orientation.w = 1.0\n            out_det.bbox.size.x = det.bbox.size.x\n            out_det.bbox.size.y = det.bbox.size.y\n            out_det.bbox.size.z = det.bbox.size.z\n            hyp = ObjectHypothesisWithPose()\n            hyp.hypothesis.class_id = class_id\n            hyp.hypothesis.score    = score\n            out_det.results.append(hyp)\n\n            # Merge into obstacle map: if a known obstacle is within merge_radius, update it;\n            # otherwise add a new entry\n            merged = False\n            for entry in self.obstacle_map.values():\n                existing = entry['detection']\n                dx = existing.bbox.center.position.x - pt_world.point.x\n                dy = existing.bbox.center.position.y - pt_world.point.y\n                dz = existing.bbox.center.position.z - pt_world.point.z\n                if math.sqrt(dx*dx + dy*dy + dz*dz) < merge_radius:\n                    # Update in place with EMA (Exponential Moving Average) to eliminate jitter\n                    existing.bbox.center.position.x = (1 - ema_alpha) * existing.bbox.center.position.x + ema_alpha * out_det.bbox.center.position.x\n                    existing.bbox.center.position.y = (1 - ema_alpha) * existing.bbox.center.position.y + ema_alpha * out_det.bbox.center.position.y\n                    existing.bbox.center.position.z = (1 - ema_alpha) * existing.bbox.center.position.z + ema_alpha * out_det.bbox.center.position.z\n                    \n                    existing.bbox.size.x = (1 - ema_alpha) * existing.bbox.size.x + ema_alpha * out_det.bbox.size.x\n                    existing.bbox.size.y = (1 - ema_alpha) * existing.bbox.size.y + ema_alpha * out_det.bbox.size.y\n                    existing.bbox.size.z = (1 - ema_alpha) * existing.bbox.size.z + ema_alpha * out_det.bbox.size.z\n                    \n                    # Keep highest confidence score\n                    if out_det.results and existing.results:\n                        existing.results[0].hypothesis.score = max(existing.results[0].hypothesis.score, out_det.results[0].hypothesis.score)\n\n                    entry['last_seen']  = now\n                    merged = True\n                    break\n\n            if not merged:\n                if len(self.obstacle_map) >= self.get_parameter('max_obstacles').value:\n                    # Map is full — drop the lowest-confidence entry to make room\n                    oldest_key = min(\n                        self.obstacle_map,\n                        key=lambda k: self.obstacle_map[k]['detection'].results[0].hypothesis.score\n                        if self.obstacle_map[k]['detection'].results else 0.0\n                    )\n                    del self.obstacle_map[oldest_key]\n\n                self.obstacle_map[self._next_id] = {\n                    'detection':  out_det,\n                    'last_seen':  now,\n                    'color_idx':  self._next_id,  # fixed forever — colour won't change\n                }\n                self._next_id += 1\n\n        # Forget stale obstacles\n        self._forget_old(now)\n\n    # ── Periodic publisher ────────────────────────────────────────────────────\n\n    def _publish_map(self):\n        \"\"\"Called by timer — publishes the full accumulated obstacle array.\"\"\"\n        if not self.obstacle_map:\n            return\n\n        world_frame = next(iter(self.obstacle_map.values()))['detection'].header.frame_id\n\n        out = Detection3DArray()\n        out.header.stamp    = self.latest_stamp if self.latest_stamp else self.get_clock().now().to_msg()\n        out.header.frame_id = world_frame\n\n        for entry in self.obstacle_map.values():\n            out.detections.append(entry['detection'])\n\n        self.obstacle_pub.publish(out)\n        # Pass the full map (with color info) to the marker builder\n        self._publish_markers(self.obstacle_map)"}, "src/navstack/perception/perception_module/aruco_detector_node.py:210-266": {"file": "src/navstack/perception/perception_module/aruco_detector_node.py", "lines": "210-266", "start_line": 210, "end_line": 266, "language": "py", "code": "        if ids is not None:\n            rvecs, tvecs = self.tracker.estimate_poses(corners, self.marker_size, K, dist)\n\n            if self.visualize and rvecs:\n                cv_img = cv_img.copy()\n                cv2.aruco.drawDetectedMarkers(cv_img, corners, ids)\n                for rv, tv in zip(rvecs, tvecs):\n                    cv2.drawFrameAxes(cv_img, K, dist, rv, tv, self.marker_size * 0.5)\n\n            for i, (marker_id_arr, rvec, tvec) in enumerate(zip(ids, rvecs, tvecs)):\n                marker_id = int(marker_id_arr[0])\n                rvec_flat = rvec.flatten()\n                tvec_flat = tvec.flatten()\n\n                # ── Convert rvec → rotation matrix → quaternion ───────\n                rot_mat, _ = cv2.Rodrigues(rvec_flat)\n                quat = R.from_matrix(rot_mat).as_quat()  # [x, y, z, w]\n\n                # ── Detection3D ───────────────────────────────────────\n                det3d = Detection3D()\n                det3d.header = image_msg.header\n\n                det3d.bbox.center.position.x    = float(tvec_flat[0])\n                det3d.bbox.center.position.y    = float(tvec_flat[1])\n                det3d.bbox.center.position.z    = float(tvec_flat[2])\n                det3d.bbox.center.orientation.x = float(quat[0])\n                det3d.bbox.center.orientation.y = float(quat[1])\n                det3d.bbox.center.orientation.z = float(quat[2])\n                det3d.bbox.center.orientation.w = float(quat[3])\n                det3d.bbox.size.x = self.marker_size\n                det3d.bbox.size.y = self.marker_size\n                det3d.bbox.size.z = 0.02  # 2 cm \"thickness\" for the flat board\n\n                hyp = ObjectHypothesisWithPose()\n                hyp.hypothesis.class_id = f'aruco_{marker_id}'\n                hyp.hypothesis.score    = 1.0\n                det3d.results.append(hyp)\n                det3d_array.detections.append(det3d)\n\n                # ── PoseArray entry ───────────────────────────────────\n                p = Pose()\n                p.position.x    = float(tvec_flat[0])\n                p.position.y    = float(tvec_flat[1])\n                p.position.z    = float(tvec_flat[2])\n                p.orientation.x = float(quat[0])\n                p.orientation.y = float(quat[1])\n                p.orientation.z = float(quat[2])\n                p.orientation.w = float(quat[3])\n                pose_array.poses.append(p)\n\n                # ── SLAM Message entry ────────────────────────────────\n                slam_det = ArucoDetection()\n                slam_det.id = marker_id\n                slam_det.pose_in_camera = p\n                slam_det.distance = float(np.linalg.norm(tvec_flat))\n                slam_array.detections.append(slam_det)\n"}, "src/navstack/slam/roar_localization/src/wio.cpp:41-155": {"file": "src/navstack/slam/roar_localization/src/wio.cpp", "lines": "41-155", "start_line": 41, "end_line": 155, "language": "cpp", "code": "WIOOutput WIO::compute(double      pulses_L,\n                       double      pulses_R,\n                       const Quat& q_imu,\n                       double      dt)\n{\n    WIOOutput out;\n    out.valid = true;\n    out.v_L   = 0.0;    // default: zero slip on invalid / first call\n    out.v_R   = 0.0;\n\n    // ── Step 1: Encoder deltas ────────────────────────────────────────────────\n    const double delta_L = pulses_L - prev_pulses_L_;\n    const double delta_R = pulses_R - prev_pulses_R_;\n\n    // On the very first call we have no previous state.\n    // Return a zero-motion output so the filter starts cleanly.\n    if (first_call_) {\n        prev_pulses_L_ = pulses_L;\n        prev_pulses_R_ = pulses_R;\n        first_call_    = false;\n\n        out.R        = quat_to_rot(q_imu);\n        out.vx       = 0.0;\n        out.dp_world = Vec3::Zero();\n        Vec3 euler   = quat_to_euler(q_imu);\n        out.yaw      = euler(2);\n        out.pitch    = euler(1);\n        prev_yaw_    = out.yaw;\n        return out;\n    }\n\n    // ── Step 2: Spike rejection ───────────────────────────────────────────────\n    // If a single step has an implausible pulse count the encoder missed an\n    // interrupt or a wire glitched. Output zero motion; do NOT advance counts.\n    if (std::abs(delta_L) > params_.max_delta_pulses ||\n        std::abs(delta_R) > params_.max_delta_pulses)\n    {\n        out.valid    = false;\n        out.R        = quat_to_rot(q_imu);\n        out.vx       = 0.0;\n        out.dp_world = Vec3::Zero();\n        Vec3 euler   = quat_to_euler(q_imu);\n        out.yaw      = euler(2);\n        out.pitch    = euler(1);\n        // Do NOT update prev_pulses on a spike.\n        return out;\n    }\n\n    // ── Step 3: Pulses → individual wheel speeds ──────────────────────────────\n    //   one full revolution = pulses_per_rev counts = 2π × wheel_radius metres\n    //\n    // NOTE on encoder format:\n    //   - If your driver publishes RADIANS: set pulses_per_rev = 2π (6.2832).\n    //     Then metres_per_pulse = 2π×r / 2π = r, and\n    //     speed = delta_rad × r / dt — exactly correct.\n    //   - If your driver publishes RAW COUNTS: set pulses_per_rev to your\n    //     encoder's actual PPR × quadrature_factor.\n    const double metres_per_pulse = (2.0 * M_PI * params_.wheel_radius)\n                                    / params_.pulses_per_rev;\n\n    const double v_L = (delta_L * metres_per_pulse) / dt;\n    const double v_R = (delta_R * metres_per_pulse) / dt;\n\n    // Average forward speed — yaw comes from BNO055, not from the differential\n    // (v_R - v_L), because differential speed is unreliable on rough terrain.\n    const double vx = 0.5 * (v_L + v_R);\n\n    // Speed sanity check: reject if above physical maximum.\n    if (std::abs(vx) > params_.max_vx) {\n        out.valid    = false;\n        out.R        = quat_to_rot(q_imu);\n        out.vx       = 0.0;\n        out.dp_world = Vec3::Zero();\n        Vec3 euler   = quat_to_euler(q_imu);\n        out.yaw      = euler(2);\n        out.pitch    = euler(1);\n        prev_pulses_L_ = pulses_L;\n        prev_pulses_R_ = pulses_R;\n        return out;\n    }\n\n    // Reading was valid. Update stored counts.\n    prev_pulses_L_ = pulses_L;\n    prev_pulses_R_ = pulses_R;\n\n    // ── Step 4: BNO055 quaternion → R, Euler ─────────────────────────────────\n    const Mat3 R     = quat_to_rot(q_imu);\n    const Vec3 euler = rot_to_euler(R);\n    const double pitch = euler(1);\n    const double yaw   = euler(2);\n\n    // ── Step 5: Mid-point yaw integration ────────────────────────────────────\n    // Halves the integration error when the rover is turning.\n    const double d_yaw   = wrap_angle(yaw - prev_yaw_);\n    const double avg_yaw = prev_yaw_ + 0.5 * d_yaw;\n    prev_yaw_ = yaw;\n\n    // ── Step 6: Dead-reckoning dp in world frame ──────────────────────────────\n    // dp_z is non-zero on slopes.\n    const double dp_x = vx * std::cos(avg_yaw) * dt;\n    const double dp_y = vx * std::sin(avg_yaw) * dt;\n    const double dp_z = vx * std::sin(pitch)   * dt;\n\n    // ── Pack output ───────────────────────────────────────────────────────────\n    out.R        = R;\n    out.vx       = vx;\n    out.v_L      = v_L;   // ← NEW: left wheel speed for slip ratio\n    out.v_R      = v_R;   // ← NEW: right wheel speed for slip ratio\n    out.dp_world = Vec3(dp_x, dp_y, dp_z);\n    out.yaw      = yaw;\n    out.pitch    = pitch;\n    out.valid    = true;\n\n    return out;\n}"}, "src/navstack/slam/roar_localization/src/ieskf.cpp:105-140": {"file": "src/navstack/slam/roar_localization/src/ieskf.cpp", "lines": "105-140", "start_line": 105, "end_line": 140, "language": "cpp", "code": "void IESKF::predict(const Vec3& a_m,\n                    const Vec3& /*omega_m*/,\n                    const Mat3& R,\n                    double      /*vx*/,\n                    const Vec3& dp_world,\n                    double      dt,\n                    double      k_Q)\n{\n    if (dt <= 0.0) return;\n\n    const Vec3 a_c = a_m - state_.b_a;\n\n    // Nominal state propagation (exact, nonlinear)\n    state_.p += dp_world;          // position via WIO dead-reckoning\n    state_.v += R * a_c * dt;      // velocity via corrected accel (world frame)\n\n    // ── Physical sanity clamp ─────────────────────────────────────────────\n    // Bound the velocity to what the vehicle can physically do. A single\n    // garbage accel sample can otherwise blow the velocity up and send the\n    // position estimate flying (observed under Gazebo RTF stutter; the same\n    // guard protects the real rover from IMU glitches).\n    const double v_norm = state_.v.norm();\n    if (v_norm > params_.max_velocity) {\n        state_.v *= (params_.max_velocity / v_norm);\n    }\n\n    // b_a, b_w stay constant (random walk — only update step modifies them)\n    // Orientation: not propagated (BNO055 owns it)\n\n    // Error-state covariance propagation\n    const StateMat Fx     = buildFx(R, dt);\n    const StateMat FiQiFi = buildFiQiFi(dt, k_Q);\n\n    P_ = Fx * P_ * Fx.transpose() + FiQiFi;\n    P_ = 0.5 * (P_ + P_.transpose());   // enforce symmetry\n}"}, "src/navstack/slam/roar_localization/include/roar_localization/fuzzy_utils.hpp:304-538": {"file": "src/navstack/slam/roar_localization/include/roar_localization/fuzzy_utils.hpp", "lines": "304-538", "start_line": 304, "end_line": 538, "language": "hpp", "code": "class WOFIS\n{\npublic:\n    explicit WOFIS(const WOFISParams& params = WOFISParams{})\n        : params_(params)\n    {\n        buildFIS();\n    }\n\n    // Evaluate k_Q.\n    // slip_ratio   ∈ [0, 1]  — clamped internally\n    // omega_z_norm ∈ [0, 1]  — |ω_z| / max_omega_z\n    // vx_norm      ∈ [0, 1]  — vx / max_vx\n    double evaluate(double slip_ratio,\n                    double omega_z_norm,\n                    double vx_norm) const\n    {\n        slip_ratio   = std::clamp(slip_ratio,   0.0, 1.0);\n        omega_z_norm = std::clamp(omega_z_norm, 0.0, 1.0);\n        vx_norm      = std::clamp(vx_norm,      0.0, 1.0);\n\n        return fis_.evaluate({slip_ratio, omega_z_norm, vx_norm},\n                             params_.k_Q_min);\n    }\n\n    const WOFISParams& getParams() const { return params_; }\n    const SugenoFIS&   getFIS()    const { return fis_; }\n\nprivate:\n    void buildFIS()\n    {\n        // Copy thresholds to local constants for lambda-capture safety\n        const double sl  = params_.slip_low_upper;\n        const double sm  = params_.slip_med_peak;\n        const double sh  = params_.slip_high_lower;\n        const double ol  = params_.omega_low_upper;\n        const double om  = params_.omega_med_peak;\n        const double oh  = params_.omega_high_lower;\n        const double vl  = params_.vx_low_upper;\n        const double vm  = params_.vx_med_peak;\n        const double vh  = params_.vx_high_lower;\n\n        const double Kn  = params_.k_Q_min;\n        const double Kx  = params_.k_Q_max;\n        const double Km  = 0.5 * (Kn + Kx);   // midpoint\n\n        // ── Input 0: slip_ratio ───────────────────────────────────────────────\n        // Index 0 = LOW, 1 = MEDIUM, 2 = HIGH\n        fis_.addInput({\n            MembershipFunc::makeLeft    (0.0, sl),          // 0: LOW\n            MembershipFunc::makeTriangle(0.0, sm, sh + 0.05), // 1: MEDIUM\n            MembershipFunc::makeRight   (sl,  1.0)          // 2: HIGH\n        });\n\n        // ── Input 1: omega_z_norm ─────────────────────────────────────────────\n        // Index 0 = LOW, 1 = MEDIUM, 2 = HIGH\n        fis_.addInput({\n            MembershipFunc::makeLeft    (0.0, ol),           // 0: LOW\n            MembershipFunc::makeTriangle(0.0, om, 1.0),      // 1: MEDIUM\n            MembershipFunc::makeRight   (oh,  1.0)           // 2: HIGH\n        });\n\n        // ── Input 2: vx_norm ──────────────────────────────────────────────────\n        // Index 0 = LOW, 1 = MEDIUM, 2 = HIGH\n        fis_.addInput({\n            MembershipFunc::makeLeft    (0.0, vl),           // 0: LOW\n            MembershipFunc::makeTriangle(0.0, vm, 1.0),      // 1: MEDIUM\n            MembershipFunc::makeRight   (vh,  1.0)           // 2: HIGH\n        });\n\n        // ── Rules ─────────────────────────────────────────────────────────────\n        // Antecedents: [slip_idx, omega_idx, vx_idx]   (-1 = don't care)\n        //\n        // Rule 1: Heavy slip → always inflate (regardless of omega, vx)\n        fis_.addRule({{2, -1, -1}, Kx});\n\n        // Rule 2: Partial slip + aggressive turning → near-max inflate\n        fis_.addRule({{1, 2, -1}, Kx * 0.85});\n\n        // Rule 3: Partial slip + high speed → moderate-high inflate\n        fis_.addRule({{1, -1, 2}, Km + (Kx - Km) * 0.40});\n\n        // Rule 4: Clean + fast turn → moderate inflate (preemptive)\n        fis_.addRule({{0, 2, -1}, Km});\n\n        // Rule 5: Partial slip + moderate turn → moderate inflate\n        fis_.addRule({{1, 1, -1}, Km});\n\n        // Rule 6: Clean + moderate turn → small inflate\n        fis_.addRule({{0, 1, -1}, Kn + (Km - Kn) * 0.5});\n\n        // Rule 7: Partial slip + slow + straight → small inflate\n        fis_.addRule({{1, 0, 0}, Kn + (Km - Kn) * 0.6});\n\n        // Rule 8: Clean + slow + straight → no inflation (ideal conditions)\n        fis_.addRule({{0, 0, 0}, Kn});\n\n        // Rule 9: Clean + fast + straight → tiny inflate (speed alone adds uncertainty)\n        fis_.addRule({{0, 0, 2}, Kn + (Km - Kn) * 0.3});\n\n        // Rule 10: Clean + moderate speed + gentle turn\n        fis_.addRule({{0, 1, 1}, Kn + (Km - Kn) * 0.4});\n    }\n\n    WOFISParams params_;\n    SugenoFIS   fis_;\n};\n\n// ═════════════════════════════════════════════════════════════════════════════\n// VO-FIS — Visual-Odometry Fuzzy Inference System\n// ═════════════════════════════════════════════════════════════════════════════\n//\n// WHAT IT DOES:\n//   Monitors ZED2i tracking quality and inflates the observation noise V\n//   when the camera is struggling, so the Kalman filter relies more on\n//   the encoder dead-reckoning and less on the unreliable visual measurement.\n//\n// PHYSICAL INTUITION:\n//   V = σ_pos² × k_V × I₃. Larger V → smaller Kalman gain K → the ZED\n//   measurement pulls the state estimate less. When dust, glare, textureless\n//   terrain, or fast motion degrade tracking, inflating V prevents a corrupted\n//   ZED reading from snapping the rover's estimated position to a wrong place.\n//\n// INPUTS:\n//   zed_confidence ∈ [0, 100]\n//     Derived from ZED SDK pose covariance:\n//       confidence = 100 × exp(−trace(P_pos) / cov_scale)\n//     High = ZED tracking is accurate. Low = ZED is struggling.\n//\n//   jump_ratio ∈ [0, 5]\n//     = |dp_VO| / (|dp_WO| + ε)\n//     Ratio of the visual delta to the encoder dead-reckoning delta.\n//     Near 1.0 = ZED and encoders agree. >> 1.0 = ZED is drifting.\n//     This is computed inside WVO and returned in WVOOutput.jump_ratio.\n//\n// OUTPUT:\n//   k_V ∈ [k_V_min, k_V_max]   (multiplier for observation noise V)\n//\n// RULE SUMMARY (9 rules — full 3×3 grid):\n//   conf=HIGH  + jump=CONSISTENT  → k_V = MIN   (fully trust ZED)\n//   conf=HIGH  + jump=DIVERGING   → k_V = MIN×8%  (SDK confident but VO drifting slightly)\n//   conf=HIGH  + jump=UNRELIABLE  → k_V = 25%   (SDK confident but jumps too big — suspect)\n//   conf=MED   + jump=CONSISTENT  → k_V = 10%   (moderate confidence, clean jump)\n//   conf=MED   + jump=DIVERGING   → k_V = 30%   (moderate confidence, VO drifting)\n//   conf=MED   + jump=UNRELIABLE  → k_V = 60%   (moderate confidence + bad jump)\n//   conf=LOW   + jump=CONSISTENT  → k_V = 25%   (poor SDK confidence alone is enough)\n//   conf=LOW   + jump=DIVERGING   → k_V = 70%   (ZED is clearly unreliable)\n//   conf=LOW   + jump=UNRELIABLE  → k_V = MAX   (maximum distrust: ignore ZED)\n// ═════════════════════════════════════════════════════════════════════════════\n\nstruct VOFISParams\n{\n    // Output range\n    double k_V_min = 1.0;     // fully trust ZED\n    double k_V_max = 100.0;   // completely distrust ZED\n\n    // ZED confidence membership parameters (universe [0, 100])\n    double conf_low_upper   = 40.0;   // confidence fully \"Low\"  below this\n    double conf_med_peak    = 55.0;   // \"Medium\" confidence peaks here\n    double conf_high_lower  = 65.0;   // confidence fully \"High\" above this\n\n    // jump_ratio membership parameters (universe [0, 5])\n    double jump_cons_upper  = 1.5;    // jump is \"Consistent\" below this\n    double jump_div_peak    = 2.5;    // \"Diverging\" peaks here\n    double jump_unrel_lower = 3.0;    // jump is \"Unreliable\" above this\n};\n\nclass VOFIS\n{\npublic:\n    explicit VOFIS(const VOFISParams& params = VOFISParams{})\n        : params_(params)\n    {\n        buildFIS();\n    }\n\n    // Evaluate k_V.\n    // zed_confidence ∈ [0, 100]  — clamped internally\n    // jump_ratio     ∈ [0, 5]    — clamped internally\n    double evaluate(double zed_confidence, double jump_ratio) const\n    {\n        zed_confidence = std::clamp(zed_confidence, 0.0, 100.0);\n        jump_ratio     = std::clamp(jump_ratio,     0.0,   5.0);\n\n        return fis_.evaluate({zed_confidence, jump_ratio}, params_.k_V_max);\n    }\n\n    const VOFISParams& getParams() const { return params_; }\n    const SugenoFIS&   getFIS()    const { return fis_; }\n\nprivate:\n    void buildFIS()\n    {\n        const double cl   = params_.conf_low_upper;\n        const double cm   = params_.conf_med_peak;\n        const double ch   = params_.conf_high_lower;\n        const double jc   = params_.jump_cons_upper;\n        const double jd   = params_.jump_div_peak;\n        const double ju   = params_.jump_unrel_lower;\n\n        const double Kn   = params_.k_V_min;\n        const double Kx   = params_.k_V_max;\n        const double span = Kx - Kn;\n\n        // ── Input 0: zed_confidence [0, 100] ─────────────────────────────────\n        // Index 0 = LOW, 1 = MEDIUM, 2 = HIGH\n        fis_.addInput({\n            MembershipFunc::makeLeft    (0.0, cl),          // 0: LOW\n            MembershipFunc::makeTriangle(0.0, cm, 100.0),   // 1: MEDIUM\n            MembershipFunc::makeRight   (ch,  100.0)        // 2: HIGH\n        });\n\n        // ── Input 1: jump_ratio [0, 5] ────────────────────────────────────────\n        // Index 0 = CONSISTENT, 1 = DIVERGING, 2 = UNRELIABLE\n        fis_.addInput({\n            MembershipFunc::makeLeft    (0.0, jc),          // 0: CONSISTENT\n            MembershipFunc::makeTriangle(1.0, jd, 5.0),     // 1: DIVERGING\n            MembershipFunc::makeRight   (ju,  5.0)          // 2: UNRELIABLE\n        });\n\n        // ── Rules [conf_idx, jump_idx] ────────────────────────────────────────\n        fis_.addRule({{2, 0}, Kn});                 // HIGH conf + CONSISTENT\n        fis_.addRule({{2, 1}, Kn + span * 0.08});  // HIGH conf + DIVERGING\n        fis_.addRule({{2, 2}, Kn + span * 0.25});  // HIGH conf + UNRELIABLE\n        fis_.addRule({{1, 0}, Kn + span * 0.10});  // MED  conf + CONSISTENT\n        fis_.addRule({{1, 1}, Kn + span * 0.30});  // MED  conf + DIVERGING\n        fis_.addRule({{1, 2}, Kn + span * 0.60});  // MED  conf + UNRELIABLE\n        fis_.addRule({{0, 0}, Kn + span * 0.25});  // LOW  conf + CONSISTENT\n        fis_.addRule({{0, 1}, Kn + span * 0.70});  // LOW  conf + DIVERGING\n        fis_.addRule({{0, 2}, Kx});                 // LOW  conf + UNRELIABLE\n    }\n\n    VOFISParams params_;\n    SugenoFIS   fis_;\n};"}, "src/navstack/slam/roar_localization/src/wvo.cpp:43-108": {"file": "src/navstack/slam/roar_localization/src/wvo.cpp", "lines": "43-108", "start_line": 43, "end_line": 108, "language": "cpp", "code": "WVOOutput WVO::compute(const Vec3& p_zed, const Vec3& dp_wo)\n{\n    WVOOutput out;\n    out.valid      = true;\n    out.ready      = false;\n    out.jump_ratio = 0.0;   // default for first call\n\n    // ── First call: seed from ZED pose ───────────────────────────────────────\n    if (first_call_) {\n        prev_p_zed_ = p_zed;\n        p_wvo_      = p_zed;\n        first_call_ = false;\n        out.z = p_wvo_;\n        return out;\n    }\n\n    // ── Stage 1: Outlier rejection ────────────────────────────────────────────\n    const Vec3   dp_VO     = p_zed - prev_p_zed_;\n    const double jump_dist = dp_VO.norm();\n\n    // Compute jump_ratio regardless of acceptance/rejection.\n    // Use 1e-3 epsilon to avoid division by zero when dp_wo is tiny.\n    const double dp_wo_norm    = dp_wo.norm();\n    const double jump_ratio_raw = jump_dist / (dp_wo_norm + 1e-3);\n    out.jump_ratio = std::min(jump_ratio_raw, 5.0);   // clamp to VO-FIS universe [0,5]\n\n    if (jump_dist > params_.max_jump) {\n        // ZED lost visual tracking (dust, glare, fast motion).\n        // Do NOT update p_wvo_ — coast on the last good position.\n        // Advance prev_p_zed_ so the next good frame diffs correctly.\n        prev_p_zed_    = p_zed;\n        out.valid      = false;\n        out.jump_ratio = 5.0;    // maximum distrust for VO-FIS\n        out.z          = p_wvo_; // return last good estimate\n        return out;\n    }\n\n    // Accepted frame. Advance stored previous pose.\n    prev_p_zed_ = p_zed;\n\n    // ── Stage 2: WO + VO blend ────────────────────────────────────────────────\n    // The blend anchors the VO delta to the encoder scale. If ZED is slowly\n    // drifting but the jump is below max_jump, the WO component limits how far\n    // p_wvo_ can move from the encoder estimate.\n    // dp_wo is Vec3::Zero() when encoders are unavailable — the blend reduces\n    // to pure VO in that case.\n    const Vec3 dp_blend = params_.w_wo * dp_wo\n                        + (1.0 - params_.w_wo) * dp_VO;\n    p_wvo_ += dp_blend;\n\n    // ── Stage 3: Sliding window mean filter ───────────────────────────────────\n    window_.push_back(p_wvo_);\n\n    while (static_cast<int>(window_.size()) > params_.window_size) {\n        window_.pop_front();\n    }\n\n    Vec3 z_mean = Vec3::Zero();\n    for (const Vec3& pos : window_) z_mean += pos;\n    z_mean /= static_cast<double>(window_.size());\n\n    out.ready = (static_cast<int>(window_.size()) >= params_.min_window_fill);\n    out.z     = z_mean;\n\n    return out;\n}"}, "src/navstack/slam/roar_localization/src/ieskf_node.cpp:345-360": {"file": "src/navstack/slam/roar_localization/src/ieskf_node.cpp", "lines": "345-360", "start_line": 345, "end_line": 360, "language": "cpp", "code": "    if (zupt_enabled_ && wio_out.valid) {\n        zupt_->update(wio_out.v_L, wio_out.v_R, omega_m.z(), a_m, now.seconds());\n        if (zupt_->isStationary()) {\n            // Inject v=0 measurement. Logged sparingly to avoid spam.\n            filter_->updateVelocity(Vec3::Zero(), zupt_->getParams().sigma_v_zupt);\n            diag_zupt_fired_++;\n            RCLCPP_DEBUG_THROTTLE(get_logger(), *get_clock(), 2000,\n                \"ZUPT fired (accel_var=%.4f)\",\n                zupt_->currentAccelVariance());\n        }\n    }\n\n    // ── Publish ──────────────────────────────────────────────────────────────\n    publishOdometry(now);\n    if (publish_tf_) publishTF(now);\n"}, "src/navstack/path-planning/globalPlanner/scripts/heightmap_to_costmap.py:144-229": {"file": "src/navstack/path-planning/globalPlanner/scripts/heightmap_to_costmap.py", "lines": "144-229", "start_line": 144, "end_line": 229, "language": "py", "code": "        # ─── Step 2: Compute terrain derivatives ────────────────────────\n        h_blur = cv2.GaussianBlur(h_meters, (3, 3), 0)\n\n        # 1st derivative (steepness) via Sobel\n        sobel_x = cv2.Sobel(h_blur, cv2.CV_32F, 1, 0, ksize=3)\n        sobel_y = cv2.Sobel(h_blur, cv2.CV_32F, 0, 1, ksize=3)\n        steepness = np.sqrt(sobel_x ** 2 + sobel_y ** 2)\n\n        # 2nd derivative (roughness) via Laplacian\n        roughness = np.abs(cv2.Laplacian(h_blur, cv2.CV_32F))\n\n        # Normalize to 0-99 (100 is reserved for lethal)\n        norm_steep = np.clip((steepness / self.max_slope) * 99.0, 0, 99)\n        norm_rough = np.clip((roughness / self.max_roughness) * 99.0, 0, 99)\n\n        # Merge with configurable weights\n        terrain_cost = np.clip(\n            norm_steep * self.steep_w + norm_rough * self.rough_w, 0, 99)\n\n        # ─── Step 3: Detect lethal cells from heightmap ─────────────────\n        # Steep slopes → lethal\n        steep_lethal = steepness > self.max_slope\n\n        # Height diffs (cliffs) → lethal (3x3 max-min filter)\n        kernel_3x3 = np.ones((3, 3), np.uint8)\n        max_h = cv2.dilate(h_blur, kernel_3x3)\n        min_h = cv2.erode(h_blur, kernel_3x3)\n        diff_lethal = (max_h - min_h) > self.max_h_diff\n\n        lethal_mask = (steep_lethal | diff_lethal) & valid_hm\n\n        # ─── Step 4: Inflation layer ────────────────────────────────────\n        # Build binary lethal image for distance transform\n        lethal_binary = lethal_mask.astype(np.uint8)  # 1 = lethal, 0 = free\n\n        # Distance transform: compute distance from each cell to nearest lethal\n        # cv2.distanceTransform needs inverted input (0 = obstacle)\n        dist_map = cv2.distanceTransform(\n            (1 - lethal_binary), cv2.DIST_L2, 5) * res  # convert to meters\n\n        # Inscribed inflation: cells within inscribed_radius → also lethal\n        inscribed_mask = dist_map < self.inscribed_radius\n\n        # Gradual inflation: exponential decay between inscribed and inflation radius\n        # inflation_cost = 99 * exp(-scaling * (dist - inscribed_radius) / (inflation_radius - inscribed_radius))\n        inflation_cost = np.zeros_like(dist_map, dtype=np.float64)\n        inflation_band = (dist_map >= self.inscribed_radius) & (dist_map < self.inflation_radius)\n        if self.inflation_radius > self.inscribed_radius:\n            normalized_dist = (dist_map[inflation_band] - self.inscribed_radius) / \\\n                              (self.inflation_radius - self.inscribed_radius)\n            inflation_cost[inflation_band] = 99.0 * np.exp(-self.inflation_scaling * normalized_dist)\n\n        # ─── Step 5: Combine everything ─────────────────────────────────\n        # Start with terrain cost as base\n        out = terrain_cost.copy()\n\n        # Overlay inflation cost (take max of terrain and inflation)\n        out = np.maximum(out, inflation_cost)\n\n        # Mark lethal cells (original + inscribed inflation)\n        all_lethal = lethal_mask | inscribed_mask\n        out[all_lethal] = 100\n\n        # Mark unknown cells\n        hm_unknown = ~valid_hm\n        out[hm_unknown] = -1\n\n        # Clamp non-lethal, non-unknown to [0, 99]\n        free_mask = ~all_lethal & valid_hm\n        out[free_mask] = np.clip(out[free_mask], 0, 99)\n\n        out = out.astype(np.int8)\n\n        # ─── Step 6: Dilate unknown regions ─────────────────────────────\n        unknown_mask = (out == -1).astype(np.uint8)\n        if np.any(unknown_mask):\n            dilated = cv2.dilate(unknown_mask, kernel_3x3, iterations=2).astype(bool)\n            out[dilated] = -1\n\n        # ─── Step 7: Publish ────────────────────────────────────────────\n        out_msg = OccupancyGrid()\n        out_msg.header = hm_msg.header\n        out_msg.info = hm_msg.info\n        out_msg.data = out.flatten().tolist()\n        self.pub.publish(out_msg)\n"}, "src/navstack/navstack_nav2/config/roar_nav2_sim.yaml:46-63": {"file": "src/navstack/navstack_nav2/config/roar_nav2_sim.yaml", "lines": "46-63", "start_line": 46, "end_line": 63, "language": "yaml", "code": "heightmap_to_costmap:\n  ros__parameters:\n    use_sim_time: true\n    heightmap_topic: \"/active_map/heightmap\"\n    heightmap_range_topic: \"/active_map/heightmap_range\"\n    unified_costmap_topic: \"/unified_costmap\"\n    occupancy_heightmap_scale: 0.015      # Fallback scale if heightmap_range not received\n    MAX_SAFE_SLOPE: 1.20                  # Allows rover to climb steeper slopes (dz/dx = 1.20)\n    MAX_SAFE_ROUGHNESS: 0.50              # Roughness threshold\n    steepness_weight: 0.50                # Weight of slope in terrain difficulty cost (0-99)\n    roughness_weight: 0.10                # Weight of roughness in terrain difficulty cost (0-99)\n    max_traversable_height_diff: 0.45     # Height step > 0.45m = lethal (allows climbing higher terrain)\n    publish_rate: 1.0                     # Fused costmap publish rate (Hz)\n    # ── Inflation Layer ──────────────────────────────────────────────\n    inscribed_radius: 0.25                # 0.25m inscribed radius (rover safety margin)\n    inflation_radius: 0.40                # 0.40m inflation radius for soft repulsion\n    inflation_cost_scaling: 3.0           # Exponential decay factor\n"}, "src/navstack/navstack_nav2/launch/roar_nav2_only.launch.py:219-289": {"file": "src/navstack/navstack_nav2/launch/roar_nav2_only.launch.py", "lines": "219-289", "start_line": 219, "end_line": 289, "language": "py", "code": "    planner = Node(\n        package='nav2_planner',\n        executable='planner_server',\n        name='planner_server',\n        output='screen',\n        parameters=[nav_params, {'use_sim_time': True}]\n    )\n\n    # MPPI local controller (plugin: nav2_mppi_controller::MPPIController)\n    # Publishes /cmd_vel, remapped to the DiffDriveController's input topic.\n    #\n    # NOTE 2026-07-16: cmd_vel_correction_node (a Rz(-90deg) rotation of\n    # linear.x/y, meant to mirror diff_drive_odom_correction_node) was wired\n    # in here and reverted. diff_drive_controller only ever reads\n    # linear.x — it has no lateral DOF. Rotating (linear.x, linear.y) by a\n    # non-180-multiple angle bleeds part or all of linear.x into the ignored\n    # linear.y field; for a pure forward command it zeroed linear.x\n    # entirely, so the robot stopped translating altogether (worse than the\n    # uncorrected behavior it was meant to fix). The underlying wheel-axis\n    # issue this was trying to work around is now fixed at its source (see\n    # ieskf_node's imu_yaw_deg above), so no cmd_vel-side correction is\n    # needed at all.\n    controller = Node(\n        package='nav2_controller',\n        executable='controller_server',\n        name='controller_server',\n        output='screen',\n        parameters=[nav_params, {'use_sim_time': True}],\n        remappings=[('/cmd_vel', '/diff_drive_controller/cmd_vel')]\n    )\n\n    # Recovery behaviors: spin, backup, drive_on_heading, wait\n    # NOTE: previously had no cmd_vel remap at all (defaulted to the\n    # unconnected literal '/cmd_vel' topic — recovery behaviors like\n    # spin/backup were never wired to the robot).\n    behavior_server = Node(\n        package='nav2_behaviors',\n        executable='behavior_server',\n        name='behavior_server',\n        output='screen',\n        parameters=[nav_params, {'use_sim_time': True}],\n        remappings=[('/cmd_vel', '/diff_drive_controller/cmd_vel')]\n    )\n\n    # Behavior tree orchestrator — exposes the /navigate_to_pose action\n    bt_navigator = Node(\n        package='nav2_bt_navigator',\n        executable='bt_navigator',\n        name='bt_navigator',\n        output='screen',\n        parameters=[nav_params, {'use_sim_time': True}]\n    )\n\n    lifecycle = Node(\n        package='nav2_lifecycle_manager',\n        executable='lifecycle_manager',\n        name='lifecycle_manager_navigation',\n        output='screen',\n        parameters=[{\n            'use_sim_time': True,\n            'autostart': True,\n            'bond_timeout': 0.0,\n            'node_names': [\n                'map_server',\n                'planner_server',\n                'controller_server',\n                'behavior_server',\n                'bt_navigator',\n            ]\n        }]\n    )"}, "src/navstack/navstack_nav2/config/roar_nav2_sim.yaml:1-14": {"file": "src/navstack/navstack_nav2/config/roar_nav2_sim.yaml", "lines": "1-14", "start_line": 1, "end_line": 14, "language": "yaml", "code": "bt_navigator:\n  ros__parameters:\n    use_sim_time: true\n    global_frame: map\n    robot_base_frame: base_footprint\n    odom_topic: /odom\n    bt_loop_duration: 10\n    default_server_timeout: 20\n    navigators: [\"navigate_to_pose\"]\n    navigate_to_pose:\n      plugin: \"nav2_bt_navigator::NavigateToPoseNavigator\"\n    default_nav_to_pose_bt_xml: \"/opt/ros/jazzy/share/nav2_bt_navigator/behavior_trees/navigate_to_pose_w_replanning_and_recovery.xml\"\n    default_nav_through_poses_bt_xml: \"/opt/ros/jazzy/share/nav2_bt_navigator/behavior_trees/navigate_through_poses_w_replanning_and_recovery.xml\"\n"}, "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp:203-281": {"file": "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp", "lines": "203-281", "start_line": 203, "end_line": 281, "language": "cpp", "code": "    // 2. Snap Goal Pose using BFS up to 5.0m radius if it is in collision\n    unsigned int snapped_goal = toIndex(goal_x, goal_y);\n    if (!isCellValid(static_cast<int>(goal_x), static_cast<int>(goal_y))) {\n      RCLCPP_WARN(logger_, \"Goal pose (%d, %d) is invalid! Searching for closest valid cell within 5.0m...\", goal_x, goal_y);\n      bool fallback_found = false;\n      double best_dist = kInf;\n      unsigned int best_idx = snapped_goal;\n\n      std::queue<unsigned int> q;\n      std::unordered_set<unsigned int> visited_fallback;\n      q.push(snapped_goal);\n      visited_fallback.insert(snapped_goal);\n\n      while (!q.empty()) {\n        unsigned int curr = q.front();\n        q.pop();\n\n        auto [cx, cy] = toXY(curr);\n        double dist = std::hypot(static_cast<double>(cx) - static_cast<double>(goal_x),\n                                 static_cast<double>(cy) - static_cast<double>(goal_y)) * resolution_;\n        if (dist > 5.0) continue;\n\n        if (isCellValid(static_cast<int>(cx), static_cast<int>(cy))) {\n          if (dist < best_dist) {\n            best_dist = dist;\n            best_idx = curr;\n            fallback_found = true;\n            break;\n          }\n        }\n\n        // Add neighbors to BFS queue\n        for (int dx = -1; dx <= 1; ++dx) {\n          for (int dy = -1; dy <= 1; ++dy) {\n            if (dx == 0 && dy == 0) continue;\n            int nx = static_cast<int>(cx) + dx;\n            int ny = static_cast<int>(cy) + dy;\n            if (nx >= 0 && ny >= 0 && nx < static_cast<int>(width_) && ny < static_cast<int>(height_)) {\n              unsigned int nidx = toIndex(static_cast<unsigned int>(nx), static_cast<unsigned int>(ny));\n              if (visited_fallback.count(nidx) == 0) {\n                visited_fallback.insert(nidx);\n                q.push(nidx);\n              }\n            }\n          }\n        }\n      }\n\n      if (fallback_found) {\n        RCLCPP_INFO(logger_, \"Fallback valid cell found at (%d, %d) with distance %.2fm\", \n                    best_idx % width_, best_idx / width_, best_dist);\n        snapped_goal = best_idx;\n      } else {\n        RCLCPP_WARN(logger_, \"No valid fallback cell found within 5.0m radius of goal!\");\n        return plan; // Returns empty path (failure)\n      }\n    }\n\n    const unsigned int new_start = snapped_start;\n    const unsigned int new_goal  = snapped_goal;\n    const unsigned char* current_costs = costmap_data_.data();\n\n    if (enable_clearance_field_ && clearance_m_.size() == current_map_size)\n      computeClearanceField(current_costs, current_map_size);\n\n    const bool goal_changed = (new_goal != goal_idx_);\n    const bool start_changed = (new_start != start_idx_);\n    const bool can_incremental = enable_incremental_updates_ &&\n                                 !goal_changed &&\n                                 last_costs_.size() == current_map_size;\n\n    if (goal_changed) {\n      // Goal changed: full re-initialization required\n      start_idx_ = new_start;\n      goal_idx_  = new_goal;\n      last_start_idx_ = start_idx_;\n      initializePlannerState();\n      computeShortestPath();\n    }"}, "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp:698-717": {"file": "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp", "lines": "698-717", "start_line": 698, "end_line": 717, "language": "cpp", "code": "  double edgeCost(unsigned int from_idx, unsigned int to_idx) const noexcept {\n    const auto [fx, fy] = toXY(from_idx);\n    const auto [tx, ty] = toXY(to_idx);\n    const double dist = std::hypot(static_cast<double>(fx) - static_cast<double>(tx), static_cast<double>(fy) - static_cast<double>(ty));\n    const unsigned char cost = costmap_data_[to_idx];\n    if (cost == NO_INFORMATION) return dist * unknown_traversal_cost_;\n\n    // Clearance field: exponential decay from lethal obstacles (Dijkstra-based)\n    double clearance_field_term = 0.0;\n    if (enable_clearance_field_ && clearance_field_weight_ > 0.0 && to_idx < clearance_m_.size()) {\n      const double c_m = std::max(0.0, static_cast<double>(clearance_m_[to_idx]));\n      clearance_field_term = clearance_field_weight_ * std::exp(-c_m / clearance_decay_distance_);\n    }\n\n    // Terrain cost: non-lethal cells carry terrain difficulty (0-252 from unified costmap)\n    const double normalized_terrain = std::max(0.0, std::min(1.0, static_cast<double>(cost) / 252.0));\n    const double terrain_term = terrain_weight_ * normalized_terrain * normalized_terrain;\n\n    return dist * (1.0 + clearance_field_term + terrain_term);\n  }"}, "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp:282-300": {"file": "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp", "lines": "282-300", "start_line": 282, "end_line": 300, "language": "cpp", "code": "    else if (can_incremental) {\n      // D* Lite km_ accumulation: compensate for robot movement\n      if (start_changed) {\n        km_ += heuristic(last_start_idx_, new_start);\n        start_idx_ = new_start;\n        last_start_idx_ = start_idx_;\n      }\n\n      // Diff costmap and update changed vertices\n      for (size_t i = 0; i < current_map_size; ++i) {\n        if (last_costs_[i] == current_costs[i]) continue;\n        const unsigned int idx = static_cast<unsigned int>(i);\n        updateVertex(idx);\n        const NeighborList nbrs = getNeighbors(idx);\n        for (int k = 0; k < nbrs.count; ++k)\n          updateVertex(nbrs.indices[k]);\n      }\n      computeShortestPath();\n    }"}, "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp:574-639": {"file": "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp", "lines": "574-639", "start_line": 574, "end_line": 639, "language": "cpp", "code": "  void computeShortestPath()\n  {\n    auto t_start = std::chrono::steady_clock::now();\n    size_t expansions = 0;\n\n    while (!open_list_.empty()) {\n      const Key start_key = calculateKey(start_idx_);\n      if (!keyLess(topKey(), start_key) && std::fabs(g_[start_idx_] - rhs_[start_idx_]) <= kEps)\n        break;\n\n      QueueItem top = open_list_.top();\n      open_list_.pop();\n\n      if (!in_open_[top.idx]) continue;\n      if (!keyEqual(top.key, open_key_[top.idx])) continue;\n\n      const Key new_key = calculateKey(top.idx);\n      if (keyLess(top.key, new_key)) {\n        open_list_.push({new_key, top.idx});\n        open_key_[top.idx] = new_key;\n        continue;\n      }\n\n      ++expansions;\n      in_open_[top.idx] = false;\n      const double g_u   = g_[top.idx];\n      const double rhs_u = rhs_[top.idx];\n\n      if (g_u > rhs_u) {\n        g_[top.idx] = rhs_u;\n        const NeighborList preds = getNeighbors(top.idx);\n        for (int i = 0; i < preds.count; ++i) updateVertex(preds.indices[i]);\n      } else {\n        g_[top.idx] = kInf;\n        updateVertex(top.idx);\n        const NeighborList preds = getNeighbors(top.idx);\n        for (int i = 0; i < preds.count; ++i) updateVertex(preds.indices[i]);\n      }\n    }\n\n    auto t_end = std::chrono::steady_clock::now();\n    double elapsed_ms = std::chrono::duration<double, std::milli>(t_end - t_start).count();\n    RCLCPP_INFO(logger_, \"computeShortestPath: %.2f ms, %zu expansions\", elapsed_ms, expansions);\n  }\n\n  void updateVertex(unsigned int idx)\n  {\n    if (idx != goal_idx_) {\n      const NeighborList succs = getNeighbors(idx);\n      double best_rhs = kInf;\n      for (int i = 0; i < succs.count; ++i) {\n        const double g_s = g_[succs.indices[i]];\n        if (std::isfinite(g_s))\n          best_rhs = std::min(best_rhs, edgeCost(idx, succs.indices[i]) + g_s);\n      }\n      rhs_[idx] = best_rhs;\n    }\n\n    in_open_[idx] = false;\n    if (std::fabs(g_[idx] - rhs_[idx]) > kEps) {\n      const Key key = calculateKey(idx);\n      open_list_.push({key, idx});\n      in_open_[idx]  = true;\n      open_key_[idx] = key;\n    }\n  }"}, "src/navstack/navstack_nav2/config/roar_nav2_sim.yaml:82-180": {"file": "src/navstack/navstack_nav2/config/roar_nav2_sim.yaml", "lines": "82-180", "start_line": 82, "end_line": 180, "language": "yaml", "code": "    FollowPath:\n      plugin: \"nav2_mppi_controller::MPPIController\"\n      time_steps: 56\n      model_dt: 0.05\n      batch_size: 2000\n      vx_std: 0.35\n      vy_std: 0.0\n      wz_std: 0.6\n      vx_max: 0.7\n      vx_min: 0.0\n      wz_max: 1.2\n      iteration_count: 2\n      prune_distance: 3.5\n      transform_tolerance: 0.35\n      temperature: 0.25\n      gamma: 0.015\n      motion_model: \"DiffDrive\"\n      visualize: true\n      reset_period: 1.0\n      regenerate_noises: false\n      TrajectoryVisualizer:\n        trajectory_step: 5\n        time_step: 3\n      critics: [\"ConstraintCritic\", \"GoalCritic\", \"GoalAngleCritic\", \"ObstaclesCritic\", \"PathAlignCritic\", \"PathFollowCritic\", \"PathAngleCritic\", \"PreferForwardCritic\"]\n      ConstraintCritic:\n        enabled: true\n        cost_power: 1\n        cost_weight: 4.0\n      GoalCritic:\n        enabled: true\n        cost_power: 1\n        cost_weight: 8.0\n        threshold_to_consider: 1.0\n      GoalAngleCritic:\n        enabled: true\n        cost_power: 1\n        cost_weight: 4.0\n        threshold_to_consider: 0.5\n      PreferForwardCritic:\n        enabled: true\n        cost_power: 1\n        cost_weight: 15.0\n        threshold_to_consider: 0.5\n      ObstaclesCritic:\n        enabled: true\n        cost_power: 1\n        repulsion_weight: 5.0\n        critical_weight: 50.0\n        consider_footprint: true\n        collision_cost: 100000.0\n        collision_margin_distance: 0.5\n        near_goal_distance: 0.8\n      PathAlignCritic:\n        enabled: true\n        cost_power: 1\n        cost_weight: 3.0\n        max_path_occupancy_ratio: 0.95\n        trajectory_point_step: 4\n        threshold_to_consider: 0.5\n        offset_from_furthest: 15\n        use_path_orientations: false\n      PathFollowCritic:\n        enabled: true\n        cost_power: 1\n        cost_weight: 10.0\n        offset_from_furthest: 15\n        threshold_to_consider: 1.0\n      PathAngleCritic:\n        enabled: true\n        cost_power: 1\n        cost_weight: 2.0\n        offset_from_furthest: 4\n        threshold_to_consider: 0.35\n        max_angle_to_furthest: 1.5\n\nlocal_costmap:\n  local_costmap:\n    ros__parameters:\n      use_sim_time: true\n      update_frequency: 5.0\n      publish_frequency: 2.0\n      global_frame: odom\n      robot_base_frame: base_footprint\n      rolling_window: true\n      width: 8\n      height: 8\n      origin_x: -4.0\n      origin_y: -4.0\n      resolution: 0.05\n      footprint: \"[[0.39, 0.40], [0.39, -0.40], [-0.39, -0.40], [-0.39, 0.40]]\"\n      plugins: [\"static_layer\", \"inflation_layer\"]\n      static_layer:\n        plugin: \"nav2_costmap_2d::StaticLayer\"\n        map_topic: \"/unified_costmap\"\n        map_subscribe_transient_local: true\n      inflation_layer:\n        plugin: \"nav2_costmap_2d::InflationLayer\"\n        cost_scaling_factor: 2.0\n        inflation_radius: 1.2"}, "src/navstack/control/nav2_mppi_controller/src/optimizer.cpp:134-162": {"file": "src/navstack/control/nav2_mppi_controller/src/optimizer.cpp", "lines": "134-162", "start_line": 134, "end_line": 162, "language": "cpp", "code": "geometry_msgs::msg::TwistStamped Optimizer::evalControl(\n  const geometry_msgs::msg::PoseStamped & robot_pose,\n  const geometry_msgs::msg::Twist & robot_speed,\n  const nav_msgs::msg::Path & plan, nav2_core::GoalChecker * goal_checker)\n{\n  prepare(robot_pose, robot_speed, plan, goal_checker);\n\n  do {\n    optimize();\n  } while (fallback(critics_data_.fail_flag));\n\n  utils::savitskyGolayFilter(control_sequence_, control_history_, settings_);\n  auto control = getControlFromSequenceAsTwist(plan.header.stamp);\n\n  if (settings_.shift_control_sequence) {\n    shiftControlSequence();\n  }\n\n  return control;\n}\n\nvoid Optimizer::optimize()\n{\n  for (size_t i = 0; i < settings_.iteration_count; ++i) {\n    generateNoisedTrajectories();\n    critic_manager_.evalTrajectoriesScores(critics_data_);\n    updateControlSequence();\n  }\n}"}, "src/navigation/scripts/asu_roar_gui.py:928-1007": {"file": "src/navigation/scripts/asu_roar_gui.py", "lines": "928-1007", "start_line": 928, "end_line": 1007, "language": "py", "code": "            for w in range(w_from, w_to + 1):\n                costmap_path = os.path.join(self.mission_ws, f\"missions/mission_{w}/assets/costmap.npz\")\n                c = np.load(costmap_path)\n                res, ox, oy = float(c['resolution']), float(c['origin_x']), float(c['origin_y'])\n\n                for wp_index in selected_indices:\n                    mission_id = f\"batch_{len(self.batch_queue) + 1}_w{w}_wp{wp_index}\"\n                    wp_str = f\"wp{wp_index:02d}\"\n                    wp_file = os.path.join(self.mission_ws, f\"missions/mission_{w}/waypoints/{wp_str}/{wp_str}.npy\")\n                    if not os.path.exists(wp_file):\n                        wp_str = f\"wp{wp_index}\"\n                        wp_file = os.path.join(self.mission_ws, f\"missions/mission_{w}/waypoints/{wp_str}/{wp_str}.npy\")\n\n                    if os.path.exists(wp_file):\n                        waypoints_m = []\n                        wp_data = np.load(wp_file)\n                        for col, row in wp_data:\n                            x = round(ox + col * res, 3)\n                            y = round(oy + row * res, 3)\n                            waypoints_m.extend([x, y])\n\n                        iterations = self.spin_iterations.value()\n                        for iter_idx in range(iterations):\n                            mission_id = f\"batch_{len(self.batch_queue) + 1}_w{w}_wp{wp_index}_iter{iter_idx+1}\"\n                            self._save_gui_mission(waypoints_m, override_dir=mission_id)\n                            self.batch_queue.append((w, mission_id, [wp_index], waypoints_m))\n                            self.batch_list_widget.addItem(f\"[{mission_id}] World {w} | WP: {wp_index}\")\n                    else:\n                        print(f\"Waypoint {wp_index} for World {w} not found. Skipping.\")\n                \n        except Exception as e:\n            QMessageBox.critical(self, \"Error\", f\"<font color='white'>Failed to add to batch:<br>{str(e)}</font>\")\n            \n    def remove_selected_batch(self):\n        current_row = self.batch_list_widget.currentRow()\n        if current_row >= 0:\n            self.batch_list_widget.takeItem(current_row)\n            self.batch_queue.pop(current_row)\n\n    def _save_gui_mission(self, waypoints_m, override_dir=None):\n        try:\n            target_name = override_dir if override_dir else \"gui_mission\"\n            mission_dir = os.path.join(self.referee_inputs_dir, target_name)\n            os.makedirs(mission_dir, exist_ok=True)\n\n            pairs = [(waypoints_m[i], waypoints_m[i + 1]) for i in range(0, len(waypoints_m), 2)]\n            wp_array = np.array([[x, y, 1.0] for x, y in pairs], dtype=float)\n            np.save(os.path.join(mission_dir, \"wp_gui.npy\"), wp_array)\n\n            all_pts = [(0.0, 0.0)] + pairs\n            segments = []\n            for i in range(len(pairs)):\n                seg_start = all_pts[i]\n                seg_end   = all_pts[i + 1]\n                segments.append([list(seg_start), list(seg_end)])\n            path_array = np.array(segments, dtype=float)\n            np.save(os.path.join(mission_dir, \"optimal_path.npy\"), path_array)\n\n            self.current_gui_mission = target_name\n\n        except Exception as e:\n            QMessageBox.warning(self, \"Warning\", f\"<font color='white'>Could not save mission array:<br>{str(e)}</font>\")\n\n    def update_yaml(self, waypoints_list):\n        with open(self.yaml_path, 'r') as f:\n            lines = f.readlines()\n        new_lines = []\n        in_waypoints_block = False\n        for line in lines:\n            if line.strip().startswith(\"waypoints: [\"):\n                new_lines.append(f\"      waypoints: [{', '.join(map(str, waypoints_list))}]\\n\")\n                if \"]\" not in line:\n                    in_waypoints_block = True\n            elif in_waypoints_block:\n                if \"]\" in line:\n                    in_waypoints_block = False\n            else:\n                new_lines.append(line)\n        with open(self.yaml_path, 'w') as f:\n            f.writelines(new_lines)"}, "src/navstack/navstack_nav2/config/roar_nav2_sim.yaml:77-81": {"file": "src/navstack/navstack_nav2/config/roar_nav2_sim.yaml", "lines": "77-81", "start_line": 77, "end_line": 81, "language": "yaml", "code": "    general_goal_checker:\n      plugin: \"nav2_controller::SimpleGoalChecker\"\n      xy_goal_tolerance: 0.45\n      yaw_goal_tolerance: 0.2\n      stateful: true"}, "src/navstack/path-planning/globalPlanner/scripts/erc_waypoint_follower.py:151-166": {"file": "src/navstack/path-planning/globalPlanner/scripts/erc_waypoint_follower.py", "lines": "151-166", "start_line": 151, "end_line": 166, "language": "py", "code": "            success = node.navigate_to_waypoint(x, y)\n\n            if success:\n                print(f\"\\n[OK] Rover stopped at {wp_label}.\")\n                if is_return:\n                    print(\"Returned to start safely.\")\n                else:\n                    input(\">>> Press [Enter] once the judge approves moving to the next waypoint...\")\n            else:\n                print(f\"\\n[ERROR] Action failed for {wp_label}.\")\n                choice = input(\">>> Type 'skip' to skip to next waypoint, or press [Enter] to retry: \")\n                if choice.strip().lower() == 'skip':\n                    continue\n                else:\n                    route.insert(idx + 1, (x, y))\n"}, "src/navigation/scripts/asu_roar_gui.py:77-81": {"file": "src/navigation/scripts/asu_roar_gui.py", "lines": "77-81", "start_line": 77, "end_line": 81, "language": "py", "code": "        self.BATCH_ITEM_TIMEOUT_MS = 20 * 60 * 1000\n        self.batch_timeout_timer = QTimer(self)\n        self.batch_timeout_timer.setSingleShot(True)\n        self.batch_timeout_timer.timeout.connect(self._on_batch_item_timeout)\n"}, "src/navstack/path-planning/globalPlanner/scripts/batch_waypoint_follower.py:136-163": {"file": "src/navstack/path-planning/globalPlanner/scripts/batch_waypoint_follower.py", "lines": "136-163", "start_line": 136, "end_line": 163, "language": "py", "code": "    # Build final sequence: visit w1 -> w2 -> w3 -> w4 -> return to start_point\n    route = waypoints + [start_point]\n\n    rclpy.init()\n    node = ERCWaypointFollower()\n\n    try:\n        for idx, (x, y) in enumerate(route):\n            is_return = (idx == len(route) - 1)\n            wp_label = \"Return to Start\" if is_return else f\"Waypoint {idx + 1}\"\n            \n            print(f\"\\n==================================================\")\n            print(f\" {wp_label}: Target ({x:.2f}, {y:.2f})\")\n            print(f\"==================================================\")\n            \n            success = node.navigate_to_waypoint(x, y)\n            \n            if success:\n                print(f\"\\n[OK] Rover stopped at {wp_label}.\")\n                if is_return:\n                    print(\"Returned to start safely.\")\n                else:\n                    print(\"Moving to next waypoint automatically...\")\n            else:\n                print(f\"\\n[ERROR] Action failed for {wp_label}. Skipping to next waypoint.\")\n                    \n        print(\"\\nAll waypoints and return sequence completed successfully!\")\n        "}, "src/navigation/scripts/asu_roar_gui.py:1212-1231": {"file": "src/navigation/scripts/asu_roar_gui.py", "lines": "1212-1231", "start_line": 1212, "end_line": 1231, "language": "py", "code": "        kills = \"pkill -2 -f ros2; pkill -2 -f gz; pkill -2 -f ruby; pkill -2 -f rviz2; pkill -2 -f nav2\"\n        wp_cmd = (\\\n            f\"cd {self.ws_root} && source /opt/ros/jazzy/setup.bash && \" \\\n            f\"source install/setup.bash && \" \\\n            f\"python3 {self.nav_ws}/path-planning/globalPlanner/scripts/batch_waypoint_follower.py --params {self.yaml_path} ; \"\n            f\"echo 'Waypoints finished. Tearing down batch item...' ; sleep 2 ; {kills}\"\n        )\n\n        self.batch_process = QProcess(self)\n        self.batch_process.finished.connect(lambda: self._on_batch_process_finished(generation))\n        self.batch_process.start(\"gnome-terminal\", [\"--wait\", \"--title\", f\"BATCH WPTS: {mission_id}\", \"--\", \"bash\", \"-c\", wp_cmd])\n\n    def _on_batch_process_finished(self, generation):\n        if generation != self._batch_generation:\n            return  # stale — this item was already aborted/skipped\n        self.batch_timeout_timer.stop()\n        self._compile_master_report(self.current_gui_mission)\n        self.completed_batch_count += 1\n        self.kill_all_nodes(show_msg=False) # Guarantee all leftover terminals and nodes are wiped!\n        self._process_next_batch_item()"}, "src/navigation/referee_engine/referee_engine/collision_monitor_node.py:24-95": {"file": "src/navigation/referee_engine/referee_engine/collision_monitor_node.py", "lines": "24-95", "start_line": 24, "end_line": 95, "language": "py", "code": "        # Build mapping from Entity Name (e.g., 'Rock_1') to Mesh ID\n        self.entity_to_mesh = {}\n        if obstacle_gt and os.path.exists(obstacle_gt):\n            try:\n                data = np.load(obstacle_gt, allow_pickle=True)\n                for d in data:\n                    self.entity_to_mesh[d['name']] = d['mesh_id']\n                self.get_logger().info(f\"Loaded {len(self.entity_to_mesh)} rock mesh mappings from {obstacle_gt}\")\n            except Exception as e:\n                self.get_logger().error(f\"Failed to load obstacle_data.npy: {e}\")\n\n        # Non-collidable meshes as requested by the user\n        self.safe_meshes = {5, 6, 7, 8, 9}\n\n        sensors = [\n            ('base_footprint', 'base_link_contact'),\n            ('wheel_rhs_front', 'wheel_rhs_front_contact'),\n            ('wheel_rhs_mid', 'wheel_rhs_mid_contact'),\n            ('wheel_rhs_rear', 'wheel_rhs_rear_contact'),\n            ('wheel_lhs_front', 'wheel_lhs_front_contact'),\n            ('wheel_lhs_mid', 'wheel_lhs_mid_contact'),\n            ('wheel_lhs_rear', 'wheel_lhs_rear_contact'),\n        ]\n\n        self.subs = []\n        for link, sensor in sensors:\n            topic = f'/world/{world_name}/model/{model_name}/link/{link}/sensor/{sensor}/contact'\n            sub = self.create_subscription(\n                Contacts,\n                topic,\n                self.contact_callback,\n                10\n            )\n            self.subs.append(sub)\n            self.get_logger().info(f\"Subscribed to contact topic: {topic}\")\n\n        # Timer to reset the flag if no contacts have been received recently\n        self.timer = self.create_timer(0.5, self.timer_callback)\n        self.last_contact_time = self.get_clock().now()\n        self.is_colliding = False\n\n    def contact_callback(self, msg: Contacts):\n        if not msg.contacts:\n            return\n\n        for contact in msg.contacts:\n            c1 = contact.collision1.name\n            c2 = contact.collision2.name\n            \n            # Find the obstacle name (e.g., \"Rock_5::link::collision\")\n            obstacle_name = c2 if \"roar_rover\" in c1 else c1\n            \n            if \"Rock_\" in obstacle_name:\n                # Extract the base entity name (e.g., \"Rock_5\")\n                entity_name = obstacle_name.split(\"::\")[0]\n                \n                # Look up the mesh_id for this entity\n                mesh_id = self.entity_to_mesh.get(entity_name, -1)\n                \n                if mesh_id in self.safe_meshes:\n                    # It's one of the non-collidable meshes (4,5,6,7,9), ignore it!\n                    continue\n\n            # If we get here, it's a valid fatal collision (collidable rock, wall, etc.)\n            self.is_colliding = True\n            self.last_contact_time = self.get_clock().now()\n            \n            flag_msg = Bool()\n            flag_msg.data = True\n            self.pub.publish(flag_msg)\n            return  # Trigger alarm immediately\n"}, "src/navigation/referee_engine/referee_engine/critical_rule_enforcer.py:28-45": {"file": "src/navigation/referee_engine/referee_engine/critical_rule_enforcer.py", "lines": "28-45", "start_line": 28, "end_line": 45, "language": "py", "code": "    def evaluate_terminal_state(self, current_x, current_y, elapsed_time, waypoints_remaining, is_completed=False):\n        xmin, xmax, ymin, ymax = self.bounds\n\n        # Fatal collisions or out-of-boundary -> score becomes 0 immediately\n        if self.collision_detected:\n            return \"KILL\", \"Terminal: Collision Detected (Score -> 0).\", True\n\n        if not (xmin <= current_x <= xmax and ymin <= current_y <= ymax) or self.halt_triggered:\n            return \"KILL\", \"Terminal: Out of Boundary (Score -> 0).\", True\n\n        # Timeout at 20 minutes (1200s) -> score is displayed up to timeout\n        if elapsed_time > self.timeout_secs:\n            return \"TIMEOUT\", \"Terminal: Mission Time Limit Exceeded (Score displayed).\", False\n\n        if is_completed:\n            return \"SUCCESS\", \"Terminal: Mission Completed.\", False\n\n        return \"RUNNING\", \"State: Nominal\", False"}, "src/navigation/referee_engine/referee_engine/referee_core_node.py:175-187": {"file": "src/navigation/referee_engine/referee_engine/referee_core_node.py", "lines": "175-187", "start_line": 175, "end_line": 187, "language": "py", "code": "    def _clock_callback(self, msg: Clock):\n        t = msg.clock.sec + (msg.clock.nanosec * 1e-9)\n        if self.sim_start_time is None:\n            self.sim_start_time = t\n            self.last_clock_time = t\n            self.total_waiting_time = 0.0\n\n        if self.tracker.state.name == \"WAITING_FOR_COMMAND\":\n            self.total_waiting_time += (t - self.last_clock_time)\n\n        self.current_sim_time = (t - self.sim_start_time) - self.total_waiting_time\n        self.last_clock_time = t\n"}, "src/navigation/referee_engine/referee_engine/waypoint_tracker.py:141-174": {"file": "src/navigation/referee_engine/referee_engine/waypoint_tracker.py", "lines": "141-174", "start_line": 141, "end_line": 174, "language": "py", "code": "        if self._current_index < len(self.waypoints):\n            target = self.waypoints[self._current_index]\n            dist_to_target = self.euclidean(current_pose, (target.x, target.y))\n\n            # Accept waypoint if within acceptance radius AND stopped (< 0.05 m/s)\n            if dist_to_target <= target.acceptance_radius and current_speed < 0.05:\n                stop_pos = current_pose\n                if target.id in self._pending_overrides:\n                    rx, ry, dist_err = self._pending_overrides.pop(target.id)\n                    stop_pos = (rx, ry)\n                    dist_to_target = dist_err\n\n                edge_dist = max(0.0, dist_to_target - self.rover_radius)\n                record = {\n                    \"id\": target.id,\n                    \"timestamp\": current_sim_time,\n                    \"d_center\": dist_to_target,\n                    \"d_edge\": edge_dist,\n                    \"positional_error\": dist_to_target,\n                    \"stop_pose\": stop_pos,\n                    \"is_autonomous\": is_autonomous,\n                    \"reached\": True,\n                    \"status\": \"REACHED\",\n                }\n                self._waypoint_records.append(record)\n                self._current_index += 1\n\n                # Enter WAITING_FOR_COMMAND to pause timer while rover is parked\n                if self._current_index < len(self.waypoints):\n                    self._state = MissionState.WAITING_FOR_COMMAND\n                else:\n                    # Finished all waypoints, targeting back to start\n                    self._state = MissionState.IN_PROGRESS\n"}, "src/navigation/referee_engine/referee_engine/score_calculator.py:40-51": {"file": "src/navigation/referee_engine/referee_engine/score_calculator.py", "lines": "40-51", "start_line": 40, "end_line": 51, "language": "py", "code": "    def calculate_edge_distance(self, center_distance: float) -> float:\n        \"\"\"Calculate distance in meters from the edge of the rover's body to the target waypoint.\"\"\"\n        return max(0.0, center_distance - self.config.rover_radius)\n\n    def score_waypoint_reached(self, d_edge: float) -> float:\n        \"\"\"\n        O/NAV-010: Waypoint reached score.\n        MAX(0, round(30 - (6 * d))) where d is edge distance in meters.\n        \"\"\"\n        raw_score = round(30.0 - (6.0 * d_edge))\n        return max(0.0, min(self.config.max_pts_per_waypoint, float(raw_score)))\n"}, "src/navigation/referee_engine/referee_engine/score_calculator.py:86-183": {"file": "src/navigation/referee_engine/referee_engine/score_calculator.py", "lines": "86-183", "start_line": 86, "end_line": 183, "language": "py", "code": "        # 1. O/NAV-010 & O/NAV-020: Waypoint Scores\n        nav_010_total = 0.0\n        nav_020_total = 0.0\n        successful_waypoints_count = 0\n\n        processed_wp_details = []\n        for wp in waypoint_details:\n            d_center = wp.get(\"d_center\", wp.get(\"dmin\", 0.0))\n            d_edge = self.calculate_edge_distance(d_center)\n            is_auto = wp.get(\"is_autonomous\", True)\n            is_reached = wp.get(\"reached\", True) and wp.get(\"status\", \"REACHED\") != \"FAILED\"\n\n            if is_reached:\n                wp_score_010 = self.score_waypoint_reached(d_edge)\n                wp_score_020 = self.config.autonomy_bonus_per_waypoint if is_auto else 0.0\n                successful_waypoints_count += 1\n            else:\n                wp_score_010 = 0.0\n                wp_score_020 = 0.0\n\n            nav_010_total += wp_score_010\n            nav_020_total += wp_score_020\n\n            processed_wp_details.append({\n                \"id\": wp.get(\"id\", \"WP\"),\n                \"timestamp\": wp.get(\"timestamp\", 0.0),\n                \"d_center\": d_center,\n                \"d_edge\": d_edge,\n                \"positional_error\": d_center,\n                \"score_010\": wp_score_010,\n                \"score_020\": wp_score_020,\n                \"total_score\": wp_score_010 + wp_score_020,\n                \"is_autonomous\": is_auto,\n                \"reached\": is_reached,\n                \"status\": wp.get(\"status\", \"REACHED\" if is_reached else \"FAILED\"),\n                \"stop_pose\": wp.get(\"stop_pose\", (0.0, 0.0)),\n            })\n\n        # Cap sub-totals according to ERC rules\n        nav_010_total = min(120.0, nav_010_total)\n        nav_020_total = min(100.0, nav_020_total)\n\n        # 2. O/NAV-030 & O/NAV-040: Back to Start Scores\n        nav_030_total = 0.0\n        nav_040_total = 0.0\n\n        if back_to_start_detail is not None and successful_waypoints_count >= 1:\n            dist_start = back_to_start_detail.get(\"d_center\", back_to_start_detail.get(\"dist_to_start\", 999.0))\n            is_auto_start = back_to_start_detail.get(\"is_autonomous\", True)\n\n            if dist_start <= 1.0:\n                nav_030_total = self.config.back_to_start_reward\n                if is_auto_start:\n                    nav_040_total = self.config.back_to_start_autonomy_reward\n\n        # 3. O/NAV-050: Execution of Traversal Plan (6 pts per completed leg, max 30 pts for 5 legs)\n        legs_completed = successful_waypoints_count\n        if back_to_start_detail is not None and back_to_start_detail.get(\"d_center\", 999.0) <= 1.0:\n            legs_completed += 1\n        nav_050_total = min(30.0, legs_completed * self.config.traversal_plan_score_per_leg)\n\n        # 4. O/NAV-060: Return Penalties (-5 per return request)\n        nav_060_total = -1.0 * (num_return_requests * self.config.return_penalty_per_req)\n\n        # Raw traverse score sum\n        raw_traverse_score = (\n            nav_010_total\n            + nav_020_total\n            + nav_030_total\n            + nav_040_total\n            + nav_050_total\n            + nav_060_total\n        )\n\n        # 5. O/NAV-110: Only GNSS feed used -> 20% penalty on total traverse score\n        traverse_score = max(0.0, raw_traverse_score)\n        if only_gnss_used:\n            traverse_score *= 0.80\n\n        traverse_score = min(300.0, max(0.0, traverse_score))\n\n        return {\n            \"traverse_score\": float(traverse_score),\n            \"droning_score\": 0.0,\n            \"final_score\": float(traverse_score),\n            \"max_possible_score\": 300.0,\n            \"nav_010_waypoint_reached\": float(nav_010_total),\n            \"nav_020_autonomy_bonus\": float(nav_020_total),\n            \"nav_030_back_to_start\": float(nav_030_total),\n            \"nav_040_back_to_start_autonomy\": float(nav_040_total),\n            \"nav_050_traversal_plan\": float(nav_050_total),\n            \"nav_060_return_penalty\": float(nav_060_total),\n            \"nav_110_gnss_penalty_applied\": only_gnss_used,\n            \"waypoint_details\": processed_wp_details,\n            \"back_to_start_detail\": back_to_start_detail,\n            \"is_fatal\": False,\n            \"elapsed_time_sec\": elapsed_time,\n        }"}, "src/navigation/referee_engine/launch/roar_full_evaluation.launch.py:160-284": {"file": "src/navigation/referee_engine/launch/roar_full_evaluation.launch.py", "lines": "160-284", "start_line": 160, "end_line": 284, "language": "py", "code": "    if enable_slam in ('true', '1', 'yes'):\n        nodes.append(LogInfo(msg=\"[ROAR EVAL] SLAM evaluator ENABLED\"))\n\n        slam_gt_topic = '/zed2i/zed_node/pose_with_covariance'\n        slam_odom_topic = '/odom'\n\n        nodes.append(Node(\n            package='roar_slam_benchmark',\n            executable='slam_evaluator',\n            name='slam_evaluator',\n            output='screen',\n            parameters=[{\n                'output_dir': SLAM_REPORT,\n                'ground_truth_topic': slam_gt_topic,\n                'odom_topic': slam_odom_topic\n            }],\n        ))\n\n    # ── 5. Perception Benchmark ──────────────────────────────────────────────\n    if enable_percept in ('true', '1', 'yes'):\n        nodes.append(LogInfo(msg=\"[ROAR EVAL] Perception benchmark ENABLED\"))\n        try:\n            percept_share  = get_package_share_directory('roar_perception_testing')\n            percept_config = os.path.join(\n                percept_share,\n                'config',\n                'perception_benchmark.yaml'\n            )\n\n            aruco_gt = os.path.join(\n                mission_assets,\n                'aruco_data.yaml'\n            )\n\n            percept_outdir = os.path.join(\n                EVAL_WS,\n                'reports',\n                'perception'\n            )\n\n            os.makedirs(\n                percept_outdir,\n                exist_ok=True\n            )\n\n            nodes.append(LogInfo(\n                msg=(\n                    f\"[ROAR EVAL] Perception world={world_name} \"\n                    f\"obstacle_gt={obstacle_gt} \"\n                    f\"aruco_gt={aruco_gt}\"\n                )\n            ))\n\n            nodes.append(Node(\n                package='roar_perception_testing',\n                executable='perception_reader_node',\n                name='perception_reader_node',\n                output='screen',\n                parameters=[percept_config],\n            ))\n            nodes.append(Node(\n                package='roar_perception_testing',\n                executable='perception_tf_node',\n                name='perception_tf_node',\n                output='screen',\n                parameters=[percept_config],\n            ))\n            nodes.append(Node(\n                package='roar_perception_testing',\n                executable='perception_benchmark_node',\n                name='perception_benchmark_node',\n                output='screen',\n                parameters=[\n                    percept_config,\n                    {\n                        'output_directory': percept_outdir,\n                        'world_name': world_name,\n                        'ground_truth_path': obstacle_gt,\n                        'aruco_ground_truth_path': aruco_gt,\n                    }\n                ],\n            ))\n        except Exception as e:\n            nodes.append(LogInfo(msg=f\"[ROAR EVAL] WARNING: roar_perception_testing not found: {e}\"))\n\n    # ── 6. Adaptive Pure Pursuit Controller ──────────────────────────────────\n    if enable_pursuit in ('true', '1', 'yes'):\n        nodes.append(LogInfo(msg=\"[ROAR EVAL] Adaptive Pure Pursuit ENABLED\"))\n\n        try:\n            pursuit_share  = get_package_share_directory('adaptive_pure_pursuit')\n            pursuit_config = os.path.join(pursuit_share, 'config', 'params.yaml')\n            pursuit_report = os.path.join(EVAL_WS, 'reports', 'pursuit')\n            os.makedirs(pursuit_report, exist_ok=True)\n\n            odom_topic_name = '/odometry/filtered'\n\n            nodes.append(Node(\n                package='adaptive_pure_pursuit',\n                executable='adaptiveLd_fixed',\n                name='adaptive_pure_pursuit_controller',\n                output='screen',\n                parameters=[pursuit_config],\n            ))\n            nodes.append(Node(\n                package='adaptive_pure_pursuit',\n                executable='control_monitor',\n                name='pursuit_control_monitor',\n                output='screen',\n                parameters=[{\n                    'csv_output_path':              os.path.join(pursuit_report, 'controller_metrics.csv'),\n                    'plot_output_path':             os.path.join(pursuit_report, 'controller_metrics.png'),\n                    'publish_rate_hz':              50.0,\n                    'overshoot_threshold_m':        0.2,\n                    'velocity_limit_m_s':           1.0,\n                    'angular_velocity_limit_rad_s': 1.5,\n                    'path_topic':                   '/path',\n                    'odom_topic':                   odom_topic_name,\n                    'cmd_topic':                    '/cmd_vel',\n                    'case_topic':                   '/testing/current_case',\n                }],\n            ))\n        except Exception as e:\n            nodes.append(LogInfo(msg=f\"[ROAR EVAL] WARNING: adaptive_pure_pursuit not found: {e}\"))\n"}, "src/navigation/scripts/asu_roar_gui.py:1263-1358": {"file": "src/navigation/scripts/asu_roar_gui.py", "lines": "1263-1358", "start_line": 1263, "end_line": 1358, "language": "py", "code": "    def _compile_master_report(self, mission_id):\n        import numpy as np\n        import os\n        import glob\n        ctx = self._batch_item_ctx\n        if not ctx: return\n        \n        # Read the stats from run_summary.npy\n        summary_file = os.path.join(self.workspace_root, \"reports\", \"referee\", \"run_summary.npy\")\n        if not os.path.exists(summary_file): return\n        \n        try:\n            data = np.load(summary_file, allow_pickle=True).item()\n        except:\n            return\n            \n        status = data.get('terminal_status', 'UNKNOWN')\n        score = data.get('final_score', 0.0)\n        \n        test_name = f\"World {ctx['world_num']} WP {ctx['wp_indices'][0]}\" if 'wp_indices' in ctx else f\"World {ctx['world_num']} {mission_id}\"\n        w_name = f\"World {ctx['world_num']}\"\n        wp_name = f\"WP {ctx['wp_indices'][0]}\" if 'wp_indices' in ctx else \"Unknown\"\n        \n        if test_name not in self.batch_aggregated_results:\n            self.batch_aggregated_results[test_name] = {'w': w_name, 'wp': wp_name, 'iterations': 0, 'passed': 0, 'failed_collision': 0, 'timeout': 0, 'scores': [], 'reports': []}\n            \n        stats = self.batch_aggregated_results[test_name]\n        stats['iterations'] += 1\n        stats['scores'].append(score)\n        if status == 'SUCCESS': stats['passed'] += 1\n        elif status == 'COLLISION': stats['failed_collision'] += 1\n        elif status in ['TIMEOUT', 'KILL']: stats['timeout'] += 1\n        else: stats['timeout'] += 1 # Any other abort\n        \n        # Find the latest generated HTML report that is NOT live\n        referee_dir = os.path.join(self.workspace_root, \"reports\", \"referee\")\n        htmls = [f for f in glob.glob(os.path.join(referee_dir, \"*.html\")) if \"Live\" not in f]\n        htmls.sort(key=os.path.getmtime, reverse=True)\n        if htmls:\n            stats['reports'].append(htmls[0])\n        else:\n            stats['reports'].append(\"#\")\n        \n        master_html_path = os.path.join(self.workspace_root, f\"reports/master_report_batch.html\")\n        os.makedirs(os.path.join(self.workspace_root, \"reports\"), exist_ok=True)\n        \n        html = \"<html><head><style>body { font-family: sans-serif; background: #0B0B0D; color: #F2F2F2; padding: 20px; } table { width: 100%; border-collapse: collapse; margin-top: 10px; margin-bottom: 30px;} th, td { border: 1px solid #333; padding: 10px; text-align: center; } th { background: #1a1a1a; color: #E10600; } h2 { color: #00D9FF; border-bottom: 1px solid #333; padding-bottom: 10px; } a { text-decoration: none; font-weight: bold; } a:hover { text-decoration: underline; }</style></head><body>\"\n        html += \"<h1 style='color: #E10600;'>ASU ROAR Master Batch Evaluation Report</h1>\"\n        \n        # Table 1: Test Details\n        html += \"<h2>Test Details</h2><table><tr><th>Test Name</th><th>Iterations</th><th>Passed</th><th>Failed (Collision)</th><th>Timeout</th><th>Average Score</th><th>Evaluation Reports</th></tr>\"\n        for t_name, t_stats in self.batch_aggregated_results.items():\n            avg_score = sum(t_stats['scores']) / len(t_stats['scores']) if t_stats['scores'] else 0\n            \n            links = []\n            for i, rep in enumerate(t_stats['reports']):\n                if rep != \"#\":\n                    links.append(f\"<a href='file://{rep}' target='_blank' style='color:#00D9FF;'>[Iter {i+1}]</a>\")\n            links_str = \" \".join(links) if links else \"None\"\n            \n            html += f\"<tr><td>{t_name}</td><td>{t_stats['iterations']}</td><td>{t_stats['passed']}</td><td>{t_stats['failed_collision']}</td><td>{t_stats['timeout']}</td><td>{avg_score:.2f}</td><td>{links_str}</td></tr>\"\n        html += \"</table>\"\n        \n        # Table 2: Benchmarking Per World\n        world_aggs = {}\n        for t_name, t_stats in self.batch_aggregated_results.items():\n            w = t_stats['w']\n            wp = t_stats['wp']\n            if w not in world_aggs:\n                world_aggs[w] = {'passed': 0, 'total': 0, 'wps': {}}\n            world_aggs[w]['passed'] += t_stats['passed']\n            world_aggs[w]['total'] += t_stats['iterations']\n            \n            if wp not in world_aggs[w]['wps']:\n                world_aggs[w]['wps'][wp] = {'passed': 0, 'total': 0}\n            world_aggs[w]['wps'][wp]['passed'] += t_stats['passed']\n            world_aggs[w]['wps'][wp]['total'] += t_stats['iterations']\n\n        html += \"<h2>Benchmarking Overview (Per World)</h2><table><tr><th>World Name</th><th>Overall Success Rate</th><th>Top Waypoint</th><th>Lowest Waypoint</th></tr>\"\n        for w, w_stats in world_aggs.items():\n            overall_sr = (w_stats['passed'] / w_stats['total'] * 100) if w_stats['total'] else 0\n            \n            top_wp = max(w_stats['wps'].items(), key=lambda x: x[1]['passed']/x[1]['total'] if x[1]['total'] else -1, default=(None, None))\n            low_wp = min(w_stats['wps'].items(), key=lambda x: x[1]['passed']/x[1]['total'] if x[1]['total'] else 2, default=(None, None))\n            \n            top_str = f\"{top_wp[0]} ({(top_wp[1]['passed']/top_wp[1]['total']*100):.1f}%)\" if top_wp[0] else \"N/A\"\n            low_str = f\"{low_wp[0]} ({(low_wp[1]['passed']/low_wp[1]['total']*100):.1f}%)\" if low_wp[0] else \"N/A\"\n            \n            html += f\"<tr><td>{w}</td><td>{overall_sr:.1f}%</td><td>{top_str}</td><td>{low_str}</td></tr>\"\n        html += \"</table></body></html>\"\n        \n        with open(master_html_path, \"w\") as f:\n            f.write(html)\n        \n        print(f\"Master batch report updated: {master_html_path}\")\n"}, "src/roar2026/dev_environment/launch_test.sh:116-121": {"file": "src/roar2026/dev_environment/launch_test.sh", "lines": "116-121", "start_line": 116, "end_line": 121, "language": "sh", "code": "# Launch — pass world file and initial spawn pose to launch file\nif [ \"$USE_RVIZ\" = \"rviz\" ]; then\n    ros2 launch \"$PKG\" basic_rover.launch.py world_file:=\"$WORLD_FILE\" start_rviz:=true spawn_x:=\"$SPAWN_X\" spawn_y:=\"$SPAWN_Y\" headless:=\"$HEADLESS\"\nelse\n    ros2 launch \"$PKG\" basic_rover.launch.py world_file:=\"$WORLD_FILE\" spawn_x:=\"$SPAWN_X\" spawn_y:=\"$SPAWN_Y\" headless:=\"$HEADLESS\"\nfi"}, "src/navigation/scripts/asu_roar_gui.py:1133-1148": {"file": "src/navigation/scripts/asu_roar_gui.py", "lines": "1133-1148", "start_line": 1133, "end_line": 1148, "language": "py", "code": "    def _batch_wait_for_sim_ready(self, generation, elapsed):\n        if generation != self._batch_generation:\n            return  # item was aborted/skipped while waiting\n\n        if self.sim_ready:\n            self._batch_launch_nav(generation)\n            return\n\n        if elapsed >= self.SIM_READY_TIMEOUT_S:\n            self._batch_abort_item(\"simulation never became ready\")\n            return\n\n        QTimer.singleShot(\n            self.BATCH_READY_POLL_MS,\n            lambda: self._batch_wait_for_sim_ready(generation, elapsed + self.BATCH_READY_POLL_MS / 1000)\n        )"}, "src/navstack/perception/perception_module/lidar_cluster_node.py:148-203": {"file": "src/navstack/perception/perception_module/lidar_cluster_node.py", "lines": "148-203", "start_line": 148, "end_line": 203, "language": "py", "code": "    def listener_callback(self, msg: PointCloud2):\n        # Read all params fresh each call → ros2 param set takes effect live\n        p = self._read_params()\n\n        # ── Stage 0: GPU-accelerated ROI distance mask ───────────────────\n        points, colors = self._pc2_to_numpy_rgb(msg)\n        if points.shape[0] == 0:\n            return\n\n        if self._use_gpu:\n            # Upload to GPU, compute squared norms, threshold, download mask\n            pts_t  = o3c.Tensor(points, dtype=o3c.float32, device=self._gpu_device)\n            sq     = (pts_t * pts_t).sum(1)                     # Nx1 squared distances\n            mask_t = sq < float(p['max_dist'] ** 2)             # boolean mask on GPU\n            mask   = mask_t.cpu().numpy().astype(bool)\n        else:\n            mask = np.linalg.norm(points, axis=1) < p['max_dist']\n\n        points = points[mask]\n        colors = colors[mask]\n        if points.shape[0] == 0:\n            return\n\n        # Wrap in Open3D legacy PointCloud for the rest of the pipeline\n        pcd = o3d.geometry.PointCloud()\n        pcd.points = o3d.utility.Vector3dVector(points)\n        pcd.colors = o3d.utility.Vector3dVector(colors)\n\n        # ── Stage 1: Voxel-grid downsampling ────────────────────────────\n        pcd = pcd.voxel_down_sample(voxel_size=p['voxel_size'])\n        if len(pcd.points) < 10:\n            return\n\n        # ── Stage 2: Statistical Outlier Removal (SOR) ──────────────────\n        # Removes per-point speckle by comparing each point's mean\n        # neighbour distance to the global mean±σ across all points.\n        if p['sor_en'] and len(pcd.points) >= p['sor_k']:\n            pcd, _ = pcd.remove_statistical_outlier(\n                nb_neighbors=int(p['sor_k']),\n                std_ratio=float(p['sor_std'])\n            )\n            if len(pcd.points) < 5:\n                return\n\n        # ── Stage 3: Radius Outlier Removal (ROR) ───────────────────────\n        # Removes isolated points (sensor reflections) that survive SOR.\n        if p['ror_en'] and len(pcd.points) >= p['ror_n']:\n            pcd, _ = pcd.remove_radius_outlier(\n                nb_points=int(p['ror_n']),\n                radius=float(p['ror_r'])\n            )\n            if len(pcd.points) < 5:\n                return\n\n        # Publish clean cloud (with ground, for debugging in RViz)\n        self.filtered_pub.publish(self._pcd_to_pc2_rgb(pcd, msg.header))"}, "src/navstack/perception/perception_module/lidar_cluster_node.py:205-293": {"file": "src/navstack/perception/perception_module/lidar_cluster_node.py", "lines": "205-293", "start_line": 205, "end_line": 293, "language": "py", "code": "        # ── Stage 4: Slope-aware iterative RANSAC plane removal ─────────\n        # Strips ground + ramps while PRESERVING steep rock faces.\n        pcd_ng = self._remove_planes_slope_aware(pcd, p)\n        if pcd_ng is None or len(pcd_ng.points) == 0:\n            return\n\n        # ── Stage 4b: Surface-normal roughness filter ────────────────────\n        # Removes any remaining smooth-slope points; keeps only rough/sharp rock points.\n        if p['roughness_en']:\n            pcd_ng = self._roughness_filter(pcd_ng, p)\n            if pcd_ng is None or len(pcd_ng.points) < 5:\n                return\n\n        self.no_ground_pub.publish(self._pcd_to_pc2_rgb(pcd_ng, msg.header))\n\n        # ── Stage 5: DBSCAN clustering ───────────────────────────────────\n        # Groups surviving points into candidate obstacle clusters.\n        labels = np.array(\n            pcd_ng.cluster_dbscan(\n                eps=p['cluster_tol'],\n                min_points=p['min_cluster'],\n                print_progress=False\n            )\n        )\n\n        # Build message containers\n        detections     = Detection3DArray(header=msg.header)\n        raw_detections = Detection3DArray(header=msg.header)\n        slam_detections = ObstacleDetectionArray(header=msg.header)\n\n        max_label = int(labels.max()) if labels.size > 0 else -1\n\n        for i in range(max_label + 1):\n            idx = np.where(labels == i)[0]\n            if len(idx) < p['min_cluster'] or len(idx) > p['max_cluster']:\n                continue  # DBSCAN already filters by min, but max is our extra gate\n\n            cluster_pcd = pcd_ng.select_by_index(idx)\n            aabb   = cluster_pcd.get_axis_aligned_bounding_box()\n            center = aabb.get_center()\n            extent = aabb.get_extent()\n            sx, sy, sz = float(extent[0]), float(extent[1]), float(extent[2])\n            cx, cy, cz = float(center[0]), float(center[1]), float(center[2])\n\n            # Assemble Detection3D (shared by raw + filtered arrays)\n            det = self._make_detection3d(msg.header, center, extent, i)\n            raw_detections.detections.append(det)\n\n            # ── Stage 6: Bounding-box shape filter ──────────────────────\n            if not (p['min_bx'] <= sx <= p['max_bx'] and\n                    p['min_by'] <= sy <= p['max_by'] and\n                    p['min_bz'] <= sz <= p['max_bz']):\n                self.get_logger().debug(\n                    f'Cluster {i} rejected by bbox: x={sx:.2f} y={sy:.2f} z={sz:.2f}'\n                )\n                continue\n\n            # ── Stage 6: Aspect-ratio filter (flat slab rejection) ───────\n            # A ramp remnant is wide+deep but not tall.  Rocks are chunkier.\n            if p['max_dr'] > 0 and sy > 1e-3 and (sz / sy) > p['max_dr']:\n                self.get_logger().debug(\n                    f'Cluster {i} rejected by depth/height={sz/sy:.1f} > {p[\"max_dr\"]}'\n                )\n                continue\n\n            # ── Stage 6: Distance filter ─────────────────────────────────\n            cl_dist = float(np.linalg.norm([cx, cy, cz]))\n            if cl_dist < p['min_cdist'] or cl_dist > p['max_cdist']:\n                continue\n\n            # ── Stage 6: Centre-height (Y-axis) filter ───────────────────\n            # ZED Y=down; positive Y = below camera (on ground level).\n            # Rocks sit near Y=0..+0.5; reject clusters above or far below.\n            if cy < p['min_cy'] or cy > p['max_cy']:\n                continue\n\n            detections.detections.append(det)\n\n            # Build SLAM-format obstacle\n            slam_obs = ObstacleDetection()\n            slam_obs.position   = Point(x=cx, y=cy, z=cz)\n            slam_obs.dimensions = Vector3(x=sx, y=sy, z=sz)\n            slam_detections.detections.append(slam_obs)\n\n        # Publish\n        self.raw_cluster_pub.publish(raw_detections)\n        self.cluster_pub.publish(detections)\n        self.slam_pub.publish(slam_detections)\n        self._publish_markers(detections, msg.header)"}, "src/navstack/perception/perception_module/obstacle_publisher_node.py:130-201": {"file": "src/navstack/perception/perception_module/obstacle_publisher_node.py", "lines": "130-201", "start_line": 130, "end_line": 201, "language": "py", "code": "            # Transform obstacle centre to world frame\n            pt_cam        = PointStamped()\n            pt_cam.header = msg.header\n            pt_cam.point  = det.bbox.center.position\n            try:\n                pt_world = tf2_geometry_msgs.do_transform_point(pt_cam, tf_stamped)\n            except Exception as e:\n                self.get_logger().warn(f'Transform failed: {e}')\n                continue\n\n            # Build world-frame detection\n            out_det = Detection3D()\n            out_det.header.frame_id       = world_frame\n            out_det.header.stamp          = msg.header.stamp\n            out_det.bbox.center.position.x = pt_world.point.x\n            out_det.bbox.center.position.y = pt_world.point.y\n            out_det.bbox.center.position.z = pt_world.point.z\n            out_det.bbox.center.orientation.w = 1.0\n            out_det.bbox.size.x = det.bbox.size.x\n            out_det.bbox.size.y = det.bbox.size.y\n            out_det.bbox.size.z = det.bbox.size.z\n            hyp = ObjectHypothesisWithPose()\n            hyp.hypothesis.class_id = class_id\n            hyp.hypothesis.score    = score\n            out_det.results.append(hyp)\n\n            # Merge into obstacle map: if a known obstacle is within merge_radius, update it;\n            # otherwise add a new entry\n            merged = False\n            for entry in self.obstacle_map.values():\n                existing = entry['detection']\n                dx = existing.bbox.center.position.x - pt_world.point.x\n                dy = existing.bbox.center.position.y - pt_world.point.y\n                dz = existing.bbox.center.position.z - pt_world.point.z\n                if math.sqrt(dx*dx + dy*dy + dz*dz) < merge_radius:\n                    # Update in place with EMA (Exponential Moving Average) to eliminate jitter\n                    existing.bbox.center.position.x = (1 - ema_alpha) * existing.bbox.center.position.x + ema_alpha * out_det.bbox.center.position.x\n                    existing.bbox.center.position.y = (1 - ema_alpha) * existing.bbox.center.position.y + ema_alpha * out_det.bbox.center.position.y\n                    existing.bbox.center.position.z = (1 - ema_alpha) * existing.bbox.center.position.z + ema_alpha * out_det.bbox.center.position.z\n                    \n                    existing.bbox.size.x = (1 - ema_alpha) * existing.bbox.size.x + ema_alpha * out_det.bbox.size.x\n                    existing.bbox.size.y = (1 - ema_alpha) * existing.bbox.size.y + ema_alpha * out_det.bbox.size.y\n                    existing.bbox.size.z = (1 - ema_alpha) * existing.bbox.size.z + ema_alpha * out_det.bbox.size.z\n                    \n                    # Keep highest confidence score\n                    if out_det.results and existing.results:\n                        existing.results[0].hypothesis.score = max(existing.results[0].hypothesis.score, out_det.results[0].hypothesis.score)\n\n                    entry['last_seen']  = now\n                    merged = True\n                    break\n\n            if not merged:\n                if len(self.obstacle_map) >= self.get_parameter('max_obstacles').value:\n                    # Map is full — drop the lowest-confidence entry to make room\n                    oldest_key = min(\n                        self.obstacle_map,\n                        key=lambda k: self.obstacle_map[k]['detection'].results[0].hypothesis.score\n                        if self.obstacle_map[k]['detection'].results else 0.0\n                    )\n                    del self.obstacle_map[oldest_key]\n\n                self.obstacle_map[self._next_id] = {\n                    'detection':  out_det,\n                    'last_seen':  now,\n                    'color_idx':  self._next_id,  # fixed forever — colour won't change\n                }\n                self._next_id += 1\n\n        # Forget stale obstacles\n        self._forget_old(now)\n"}, "src/navstack/slam/roar_localization/src/ieskf_node.cpp:295-360": {"file": "src/navstack/slam/roar_localization/src/ieskf_node.cpp", "lines": "295-360", "start_line": 295, "end_line": 360, "language": "cpp", "code": "    // ── WIO ───────────────────────────────────────────────────────────────────\n    const double pulses_L = encoder_ready_ ? encoder_left_  : 0.0;\n    const double pulses_R = encoder_ready_ ? encoder_right_ : 0.0;\n    WIOOutput wio_out = wio_->compute(pulses_L, pulses_R, q_body, dt);\n\n    // ── Update WVO dead-reckoning accumulator with failure tracking ──────────\n    if (wio_out.valid) {\n        accumulated_dp_wo_ += wio_out.dp_world;\n        wio_fail_count_ = 0;\n    } else {\n        wio_fail_count_++;\n        if (wio_fail_count_ >= kMaxWioFails) {\n            accumulated_dp_wo_ = Vec3::Zero();\n            wio_fail_count_    = 0;\n            RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 1000,\n                \"WIO: %d consecutive encoder failures — resetting dp accumulator\",\n                kMaxWioFails);\n        }\n    }\n\n    // ── WO-FIS: compute k_Q ──────────────────────────────────────────────────\n    double k_Q = 1.0;\n    if (wio_out.valid) {\n        const double slip_ratio   =\n            fuzzy::computeSlipRatio(wio_out.v_L, wio_out.v_R);\n        const double omega_z_norm =\n            std::min(std::abs(omega_m.z()) / max_omega_z_, 1.0);\n        const double vx_norm      =\n            std::min(std::abs(wio_out.vx) / max_vx_, 1.0);\n        k_Q = wo_fis_.evaluate(slip_ratio, omega_z_norm, vx_norm);\n    } else {\n        const double omega_z_norm =\n            std::min(std::abs(omega_m.z()) / max_omega_z_, 1.0);\n        k_Q = wo_fis_.evaluate(0.0, omega_z_norm, 0.0);\n    }\n\n    // ── IESKF predict ────────────────────────────────────────────────────────\n    if (wio_out.valid) {\n        filter_->predict(a_m, omega_m, wio_out.R, wio_out.vx,\n                         wio_out.dp_world, dt, k_Q);\n    } else {\n        const Mat3 R_fb = quat_to_rot(q_body);\n        filter_->predict(a_m, omega_m, R_fb, 0.0, Vec3::Zero(), dt, k_Q);\n    }\n\n    diag_last_k_Q_ = k_Q;\n\n    // ── ZUPT ─────────────────────────────────────────────────────────────────\n    // Feed the detector with the latest readings. If all conditions held for\n    // long enough, fire a zero-velocity update.\n    if (zupt_enabled_ && wio_out.valid) {\n        zupt_->update(wio_out.v_L, wio_out.v_R, omega_m.z(), a_m, now.seconds());\n        if (zupt_->isStationary()) {\n            // Inject v=0 measurement. Logged sparingly to avoid spam.\n            filter_->updateVelocity(Vec3::Zero(), zupt_->getParams().sigma_v_zupt);\n            diag_zupt_fired_++;\n            RCLCPP_DEBUG_THROTTLE(get_logger(), *get_clock(), 2000,\n                \"ZUPT fired (accel_var=%.4f)\",\n                zupt_->currentAccelVariance());\n        }\n    }\n\n    // ── Publish ──────────────────────────────────────────────────────────────\n    publishOdometry(now);\n    if (publish_tf_) publishTF(now);\n"}, "src/navstack/path-planning/globalPlanner/scripts/heightmap_to_costmap.py:122-229": {"file": "src/navstack/path-planning/globalPlanner/scripts/heightmap_to_costmap.py", "lines": "122-229", "start_line": 122, "end_line": 229, "language": "py", "code": "        # ─── Step 1: Decode heightmap to meters ─────────────────────────\n        hm_data = np.array(hm_msg.data, dtype=np.float32).reshape((H_h, H_w))\n        valid_hm = (hm_data != -1)\n        h_meters = np.zeros_like(hm_data, dtype=np.float32)\n\n        if self.hm_range is not None:\n            h_min, h_range = self.hm_range\n            h_meters[valid_hm] = h_min + (hm_data[valid_hm] / 100.0) * h_range\n        else:\n            h_meters[valid_hm] = hm_data[valid_hm] * self.hm_scale\n\n        # Guard against all-invalid heightmap (NaN poisoning)\n        if np.any(valid_hm):\n            h_meters[~valid_hm] = np.mean(h_meters[valid_hm])\n        else:\n            out_msg = OccupancyGrid()\n            out_msg.header = hm_msg.header\n            out_msg.info = hm_msg.info\n            out_msg.data = [-1] * (H_w * H_h)\n            self.pub.publish(out_msg)\n            return\n\n        # ─── Step 2: Compute terrain derivatives ────────────────────────\n        h_blur = cv2.GaussianBlur(h_meters, (3, 3), 0)\n\n        # 1st derivative (steepness) via Sobel\n        sobel_x = cv2.Sobel(h_blur, cv2.CV_32F, 1, 0, ksize=3)\n        sobel_y = cv2.Sobel(h_blur, cv2.CV_32F, 0, 1, ksize=3)\n        steepness = np.sqrt(sobel_x ** 2 + sobel_y ** 2)\n\n        # 2nd derivative (roughness) via Laplacian\n        roughness = np.abs(cv2.Laplacian(h_blur, cv2.CV_32F))\n\n        # Normalize to 0-99 (100 is reserved for lethal)\n        norm_steep = np.clip((steepness / self.max_slope) * 99.0, 0, 99)\n        norm_rough = np.clip((roughness / self.max_roughness) * 99.0, 0, 99)\n\n        # Merge with configurable weights\n        terrain_cost = np.clip(\n            norm_steep * self.steep_w + norm_rough * self.rough_w, 0, 99)\n\n        # ─── Step 3: Detect lethal cells from heightmap ─────────────────\n        # Steep slopes → lethal\n        steep_lethal = steepness > self.max_slope\n\n        # Height diffs (cliffs) → lethal (3x3 max-min filter)\n        kernel_3x3 = np.ones((3, 3), np.uint8)\n        max_h = cv2.dilate(h_blur, kernel_3x3)\n        min_h = cv2.erode(h_blur, kernel_3x3)\n        diff_lethal = (max_h - min_h) > self.max_h_diff\n\n        lethal_mask = (steep_lethal | diff_lethal) & valid_hm\n\n        # ─── Step 4: Inflation layer ────────────────────────────────────\n        # Build binary lethal image for distance transform\n        lethal_binary = lethal_mask.astype(np.uint8)  # 1 = lethal, 0 = free\n\n        # Distance transform: compute distance from each cell to nearest lethal\n        # cv2.distanceTransform needs inverted input (0 = obstacle)\n        dist_map = cv2.distanceTransform(\n            (1 - lethal_binary), cv2.DIST_L2, 5) * res  # convert to meters\n\n        # Inscribed inflation: cells within inscribed_radius → also lethal\n        inscribed_mask = dist_map < self.inscribed_radius\n\n        # Gradual inflation: exponential decay between inscribed and inflation radius\n        # inflation_cost = 99 * exp(-scaling * (dist - inscribed_radius) / (inflation_radius - inscribed_radius))\n        inflation_cost = np.zeros_like(dist_map, dtype=np.float64)\n        inflation_band = (dist_map >= self.inscribed_radius) & (dist_map < self.inflation_radius)\n        if self.inflation_radius > self.inscribed_radius:\n            normalized_dist = (dist_map[inflation_band] - self.inscribed_radius) / \\\n                              (self.inflation_radius - self.inscribed_radius)\n            inflation_cost[inflation_band] = 99.0 * np.exp(-self.inflation_scaling * normalized_dist)\n\n        # ─── Step 5: Combine everything ─────────────────────────────────\n        # Start with terrain cost as base\n        out = terrain_cost.copy()\n\n        # Overlay inflation cost (take max of terrain and inflation)\n        out = np.maximum(out, inflation_cost)\n\n        # Mark lethal cells (original + inscribed inflation)\n        all_lethal = lethal_mask | inscribed_mask\n        out[all_lethal] = 100\n\n        # Mark unknown cells\n        hm_unknown = ~valid_hm\n        out[hm_unknown] = -1\n\n        # Clamp non-lethal, non-unknown to [0, 99]\n        free_mask = ~all_lethal & valid_hm\n        out[free_mask] = np.clip(out[free_mask], 0, 99)\n\n        out = out.astype(np.int8)\n\n        # ─── Step 6: Dilate unknown regions ─────────────────────────────\n        unknown_mask = (out == -1).astype(np.uint8)\n        if np.any(unknown_mask):\n            dilated = cv2.dilate(unknown_mask, kernel_3x3, iterations=2).astype(bool)\n            out[dilated] = -1\n\n        # ─── Step 7: Publish ────────────────────────────────────────────\n        out_msg = OccupancyGrid()\n        out_msg.header = hm_msg.header\n        out_msg.info = hm_msg.info\n        out_msg.data = out.flatten().tolist()\n        self.pub.publish(out_msg)\n"}, "src/navstack/navstack_nav2/launch/roar_nav2_only.launch.py:272-290": {"file": "src/navstack/navstack_nav2/launch/roar_nav2_only.launch.py", "lines": "272-290", "start_line": 272, "end_line": 290, "language": "py", "code": "    lifecycle = Node(\n        package='nav2_lifecycle_manager',\n        executable='lifecycle_manager',\n        name='lifecycle_manager_navigation',\n        output='screen',\n        parameters=[{\n            'use_sim_time': True,\n            'autostart': True,\n            'bond_timeout': 0.0,\n            'node_names': [\n                'map_server',\n                'planner_server',\n                'controller_server',\n                'behavior_server',\n                'bt_navigator',\n            ]\n        }]\n    )\n"}, "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp:261-312": {"file": "src/navstack/path-planning/globalPlanner/src/dstar_planner.cpp", "lines": "261-312", "start_line": 261, "end_line": 312, "language": "cpp", "code": "    const unsigned int new_start = snapped_start;\n    const unsigned int new_goal  = snapped_goal;\n    const unsigned char* current_costs = costmap_data_.data();\n\n    if (enable_clearance_field_ && clearance_m_.size() == current_map_size)\n      computeClearanceField(current_costs, current_map_size);\n\n    const bool goal_changed = (new_goal != goal_idx_);\n    const bool start_changed = (new_start != start_idx_);\n    const bool can_incremental = enable_incremental_updates_ &&\n                                 !goal_changed &&\n                                 last_costs_.size() == current_map_size;\n\n    if (goal_changed) {\n      // Goal changed: full re-initialization required\n      start_idx_ = new_start;\n      goal_idx_  = new_goal;\n      last_start_idx_ = start_idx_;\n      initializePlannerState();\n      computeShortestPath();\n    }\n    else if (can_incremental) {\n      // D* Lite km_ accumulation: compensate for robot movement\n      if (start_changed) {\n        km_ += heuristic(last_start_idx_, new_start);\n        start_idx_ = new_start;\n        last_start_idx_ = start_idx_;\n      }\n\n      // Diff costmap and update changed vertices\n      for (size_t i = 0; i < current_map_size; ++i) {\n        if (last_costs_[i] == current_costs[i]) continue;\n        const unsigned int idx = static_cast<unsigned int>(i);\n        updateVertex(idx);\n        const NeighborList nbrs = getNeighbors(idx);\n        for (int k = 0; k < nbrs.count; ++k)\n          updateVertex(nbrs.indices[k]);\n      }\n      computeShortestPath();\n    }\n    else {\n      start_idx_ = new_start;\n      goal_idx_  = new_goal;\n      last_start_idx_ = start_idx_;\n      initializePlannerState();\n      computeShortestPath();\n    }\n\n    if (!std::isfinite(g_[start_idx_])) {\n      RCLCPP_WARN(logger_, \"No D* Lite path found to goal\");\n      return plan;\n    }"}, "src/navstack/navstack_nav2/config/roar_nav2_sim.yaml:65-106": {"file": "src/navstack/navstack_nav2/config/roar_nav2_sim.yaml", "lines": "65-106", "start_line": 65, "end_line": 106, "language": "yaml", "code": "controller_server:\n  ros__parameters:\n    use_sim_time: true\n    enable_stamped_cmd_vel: true\n    controller_frequency: 20.0\n    controller_plugins: [\"FollowPath\"]\n    goal_checker_plugins: [\"general_goal_checker\"]\n    progress_checker_plugins: [\"progress_checker\"]\n    progress_checker:\n      plugin: \"nav2_controller::SimpleProgressChecker\"\n      required_movement_radius: 0.5\n      movement_time_allowance: 60.0\n    general_goal_checker:\n      plugin: \"nav2_controller::SimpleGoalChecker\"\n      xy_goal_tolerance: 0.45\n      yaw_goal_tolerance: 0.2\n      stateful: true\n    FollowPath:\n      plugin: \"nav2_mppi_controller::MPPIController\"\n      time_steps: 56\n      model_dt: 0.05\n      batch_size: 2000\n      vx_std: 0.35\n      vy_std: 0.0\n      wz_std: 0.6\n      vx_max: 0.7\n      vx_min: 0.0\n      wz_max: 1.2\n      iteration_count: 2\n      prune_distance: 3.5\n      transform_tolerance: 0.35\n      temperature: 0.25\n      gamma: 0.015\n      motion_model: \"DiffDrive\"\n      visualize: true\n      reset_period: 1.0\n      regenerate_noises: false\n      TrajectoryVisualizer:\n        trajectory_step: 5\n        time_step: 3\n      critics: [\"ConstraintCritic\", \"GoalCritic\", \"GoalAngleCritic\", \"ObstaclesCritic\", \"PathAlignCritic\", \"PathFollowCritic\", \"PathAngleCritic\", \"PreferForwardCritic\"]\n      ConstraintCritic:"}, "src/navigation/scripts/asu_roar_gui.py:928-988": {"file": "src/navigation/scripts/asu_roar_gui.py", "lines": "928-988", "start_line": 928, "end_line": 988, "language": "py", "code": "            for w in range(w_from, w_to + 1):\n                costmap_path = os.path.join(self.mission_ws, f\"missions/mission_{w}/assets/costmap.npz\")\n                c = np.load(costmap_path)\n                res, ox, oy = float(c['resolution']), float(c['origin_x']), float(c['origin_y'])\n\n                for wp_index in selected_indices:\n                    mission_id = f\"batch_{len(self.batch_queue) + 1}_w{w}_wp{wp_index}\"\n                    wp_str = f\"wp{wp_index:02d}\"\n                    wp_file = os.path.join(self.mission_ws, f\"missions/mission_{w}/waypoints/{wp_str}/{wp_str}.npy\")\n                    if not os.path.exists(wp_file):\n                        wp_str = f\"wp{wp_index}\"\n                        wp_file = os.path.join(self.mission_ws, f\"missions/mission_{w}/waypoints/{wp_str}/{wp_str}.npy\")\n\n                    if os.path.exists(wp_file):\n                        waypoints_m = []\n                        wp_data = np.load(wp_file)\n                        for col, row in wp_data:\n                            x = round(ox + col * res, 3)\n                            y = round(oy + row * res, 3)\n                            waypoints_m.extend([x, y])\n\n                        iterations = self.spin_iterations.value()\n                        for iter_idx in range(iterations):\n                            mission_id = f\"batch_{len(self.batch_queue) + 1}_w{w}_wp{wp_index}_iter{iter_idx+1}\"\n                            self._save_gui_mission(waypoints_m, override_dir=mission_id)\n                            self.batch_queue.append((w, mission_id, [wp_index], waypoints_m))\n                            self.batch_list_widget.addItem(f\"[{mission_id}] World {w} | WP: {wp_index}\")\n                    else:\n                        print(f\"Waypoint {wp_index} for World {w} not found. Skipping.\")\n                \n        except Exception as e:\n            QMessageBox.critical(self, \"Error\", f\"<font color='white'>Failed to add to batch:<br>{str(e)}</font>\")\n            \n    def remove_selected_batch(self):\n        current_row = self.batch_list_widget.currentRow()\n        if current_row >= 0:\n            self.batch_list_widget.takeItem(current_row)\n            self.batch_queue.pop(current_row)\n\n    def _save_gui_mission(self, waypoints_m, override_dir=None):\n        try:\n            target_name = override_dir if override_dir else \"gui_mission\"\n            mission_dir = os.path.join(self.referee_inputs_dir, target_name)\n            os.makedirs(mission_dir, exist_ok=True)\n\n            pairs = [(waypoints_m[i], waypoints_m[i + 1]) for i in range(0, len(waypoints_m), 2)]\n            wp_array = np.array([[x, y, 1.0] for x, y in pairs], dtype=float)\n            np.save(os.path.join(mission_dir, \"wp_gui.npy\"), wp_array)\n\n            all_pts = [(0.0, 0.0)] + pairs\n            segments = []\n            for i in range(len(pairs)):\n                seg_start = all_pts[i]\n                seg_end   = all_pts[i + 1]\n                segments.append([list(seg_start), list(seg_end)])\n            path_array = np.array(segments, dtype=float)\n            np.save(os.path.join(mission_dir, \"optimal_path.npy\"), path_array)\n\n            self.current_gui_mission = target_name\n\n        except Exception as e:"}, "src/navigation/scripts/asu_roar_gui.py:1210-1231": {"file": "src/navigation/scripts/asu_roar_gui.py", "lines": "1210-1231", "start_line": 1210, "end_line": 1231, "language": "py", "code": "        # 4. Send waypoints — same follower invocation as the \"3. SEND WPTS\" button,\n        # with the same graceful teardown, tracked so we know when the item is done.\n        kills = \"pkill -2 -f ros2; pkill -2 -f gz; pkill -2 -f ruby; pkill -2 -f rviz2; pkill -2 -f nav2\"\n        wp_cmd = (\\\n            f\"cd {self.ws_root} && source /opt/ros/jazzy/setup.bash && \" \\\n            f\"source install/setup.bash && \" \\\n            f\"python3 {self.nav_ws}/path-planning/globalPlanner/scripts/batch_waypoint_follower.py --params {self.yaml_path} ; \"\n            f\"echo 'Waypoints finished. Tearing down batch item...' ; sleep 2 ; {kills}\"\n        )\n\n        self.batch_process = QProcess(self)\n        self.batch_process.finished.connect(lambda: self._on_batch_process_finished(generation))\n        self.batch_process.start(\"gnome-terminal\", [\"--wait\", \"--title\", f\"BATCH WPTS: {mission_id}\", \"--\", \"bash\", \"-c\", wp_cmd])\n\n    def _on_batch_process_finished(self, generation):\n        if generation != self._batch_generation:\n            return  # stale — this item was already aborted/skipped\n        self.batch_timeout_timer.stop()\n        self._compile_master_report(self.current_gui_mission)\n        self.completed_batch_count += 1\n        self.kill_all_nodes(show_msg=False) # Guarantee all leftover terminals and nodes are wiped!\n        self._process_next_batch_item()"}, "src/navigation/referee_engine/referee_engine/referee_core_node.py:260-299": {"file": "src/navigation/referee_engine/referee_engine/referee_core_node.py", "lines": "260-299", "start_line": 260, "end_line": 299, "language": "py", "code": "    def _evaluation_loop(self):\n        if self.run_finished:\n            return\n\n        waypoints_remaining = len(self.tracker.waypoints) - self.tracker.waypoints_completed\n        is_completed = (self.tracker.state.name == \"COMPLETED\")\n\n        status, msg_log, is_fatal = self.safety_engine.evaluate_terminal_state(\n            self.current_x,\n            self.current_y,\n            self.current_sim_time,\n            waypoints_remaining,\n            is_completed=is_completed\n        )\n\n        # Periodically compute current score and persist summary\n        score_dict = self.score_engine.final_score(\n            waypoint_details=self.tracker.waypoint_records,\n            back_to_start_detail=self.tracker.back_to_start_record,\n            num_return_requests=self.tracker.num_returns,\n            only_gnss_used=self.only_gnss_used,\n            elapsed_time=self.current_sim_time,\n            is_fatal=is_fatal\n        )\n        score_dict[\"terminal_status\"] = status\n        score_dict[\"is_final\"] = is_completed or is_fatal or (status in [\"KILL\", \"TIMEOUT\", \"SUCCESS\"])\n        score_dict[\"t_min_computed_sec\"] = float(self.t_min_computed)\n        score_dict[\"t_max_computed_sec\"] = float(self.t_max_computed)\n        score_dict[\"minimum_time_sec\"] = float(self.minimum_time)\n        score_dict[\"maximum_time_sec\"] = float(self.maximum_time)\n        score_dict[\"ideal_distance_m\"] = float(self.total_ideal_distance)\n        score_dict[\"actual_distance_m\"] = float(self.tracker.actual_distance)\n\n        # Save summary continuously so file exists at all times\n        self._save_summary_file(score_dict)\n\n        if is_fatal or status in [\"KILL\", \"TIMEOUT\", \"SUCCESS\"] or is_completed:\n            self._conclude_run(status=status, is_fatal=is_fatal)\n            return\n"}, "src/navigation/referee_engine/referee_engine/waypoint_tracker.py:140-194": {"file": "src/navigation/referee_engine/referee_engine/waypoint_tracker.py", "lines": "140-194", "start_line": 140, "end_line": 194, "language": "py", "code": "        # 1. Waypoint checking\n        if self._current_index < len(self.waypoints):\n            target = self.waypoints[self._current_index]\n            dist_to_target = self.euclidean(current_pose, (target.x, target.y))\n\n            # Accept waypoint if within acceptance radius AND stopped (< 0.05 m/s)\n            if dist_to_target <= target.acceptance_radius and current_speed < 0.05:\n                stop_pos = current_pose\n                if target.id in self._pending_overrides:\n                    rx, ry, dist_err = self._pending_overrides.pop(target.id)\n                    stop_pos = (rx, ry)\n                    dist_to_target = dist_err\n\n                edge_dist = max(0.0, dist_to_target - self.rover_radius)\n                record = {\n                    \"id\": target.id,\n                    \"timestamp\": current_sim_time,\n                    \"d_center\": dist_to_target,\n                    \"d_edge\": edge_dist,\n                    \"positional_error\": dist_to_target,\n                    \"stop_pose\": stop_pos,\n                    \"is_autonomous\": is_autonomous,\n                    \"reached\": True,\n                    \"status\": \"REACHED\",\n                }\n                self._waypoint_records.append(record)\n                self._current_index += 1\n\n                # Enter WAITING_FOR_COMMAND to pause timer while rover is parked\n                if self._current_index < len(self.waypoints):\n                    self._state = MissionState.WAITING_FOR_COMMAND\n                else:\n                    # Finished all waypoints, targeting back to start\n                    self._state = MissionState.IN_PROGRESS\n\n        # 2. Back-to-start checking (after all waypoints reached)\n        elif self._current_index == len(self.waypoints):\n            dist_to_start = self.euclidean(current_pose, self.start_pose)\n            if dist_to_start <= 1.0 and current_speed < 0.05:\n                stop_pos = current_pose\n                if \"START\" in self._pending_overrides or \"RETURN\" in self._pending_overrides:\n                    ov_key = \"START\" if \"START\" in self._pending_overrides else \"RETURN\"\n                    rx, ry, dist_err = self._pending_overrides.pop(ov_key)\n                    stop_pos = (rx, ry)\n                    dist_to_start = dist_err\n\n                self._back_to_start_record = {\n                    \"timestamp\": current_sim_time,\n                    \"d_center\": dist_to_start,\n                    \"positional_error\": dist_to_start,\n                    \"stop_pose\": stop_pos,\n                    \"is_autonomous\": is_autonomous,\n                }\n                self._state = MissionState.COMPLETED\n"}, "src/navigation/referee_engine/referee_engine/score_calculator.py:86-166": {"file": "src/navigation/referee_engine/referee_engine/score_calculator.py", "lines": "86-166", "start_line": 86, "end_line": 166, "language": "py", "code": "        # 1. O/NAV-010 & O/NAV-020: Waypoint Scores\n        nav_010_total = 0.0\n        nav_020_total = 0.0\n        successful_waypoints_count = 0\n\n        processed_wp_details = []\n        for wp in waypoint_details:\n            d_center = wp.get(\"d_center\", wp.get(\"dmin\", 0.0))\n            d_edge = self.calculate_edge_distance(d_center)\n            is_auto = wp.get(\"is_autonomous\", True)\n            is_reached = wp.get(\"reached\", True) and wp.get(\"status\", \"REACHED\") != \"FAILED\"\n\n            if is_reached:\n                wp_score_010 = self.score_waypoint_reached(d_edge)\n                wp_score_020 = self.config.autonomy_bonus_per_waypoint if is_auto else 0.0\n                successful_waypoints_count += 1\n            else:\n                wp_score_010 = 0.0\n                wp_score_020 = 0.0\n\n            nav_010_total += wp_score_010\n            nav_020_total += wp_score_020\n\n            processed_wp_details.append({\n                \"id\": wp.get(\"id\", \"WP\"),\n                \"timestamp\": wp.get(\"timestamp\", 0.0),\n                \"d_center\": d_center,\n                \"d_edge\": d_edge,\n                \"positional_error\": d_center,\n                \"score_010\": wp_score_010,\n                \"score_020\": wp_score_020,\n                \"total_score\": wp_score_010 + wp_score_020,\n                \"is_autonomous\": is_auto,\n                \"reached\": is_reached,\n                \"status\": wp.get(\"status\", \"REACHED\" if is_reached else \"FAILED\"),\n                \"stop_pose\": wp.get(\"stop_pose\", (0.0, 0.0)),\n            })\n\n        # Cap sub-totals according to ERC rules\n        nav_010_total = min(120.0, nav_010_total)\n        nav_020_total = min(100.0, nav_020_total)\n\n        # 2. O/NAV-030 & O/NAV-040: Back to Start Scores\n        nav_030_total = 0.0\n        nav_040_total = 0.0\n\n        if back_to_start_detail is not None and successful_waypoints_count >= 1:\n            dist_start = back_to_start_detail.get(\"d_center\", back_to_start_detail.get(\"dist_to_start\", 999.0))\n            is_auto_start = back_to_start_detail.get(\"is_autonomous\", True)\n\n            if dist_start <= 1.0:\n                nav_030_total = self.config.back_to_start_reward\n                if is_auto_start:\n                    nav_040_total = self.config.back_to_start_autonomy_reward\n\n        # 3. O/NAV-050: Execution of Traversal Plan (6 pts per completed leg, max 30 pts for 5 legs)\n        legs_completed = successful_waypoints_count\n        if back_to_start_detail is not None and back_to_start_detail.get(\"d_center\", 999.0) <= 1.0:\n            legs_completed += 1\n        nav_050_total = min(30.0, legs_completed * self.config.traversal_plan_score_per_leg)\n\n        # 4. O/NAV-060: Return Penalties (-5 per return request)\n        nav_060_total = -1.0 * (num_return_requests * self.config.return_penalty_per_req)\n\n        # Raw traverse score sum\n        raw_traverse_score = (\n            nav_010_total\n            + nav_020_total\n            + nav_030_total\n            + nav_040_total\n            + nav_050_total\n            + nav_060_total\n        )\n\n        # 5. O/NAV-110: Only GNSS feed used -> 20% penalty on total traverse score\n        traverse_score = max(0.0, raw_traverse_score)\n        if only_gnss_used:\n            traverse_score *= 0.80\n\n        traverse_score = min(300.0, max(0.0, traverse_score))\n"}}};
